--
-- Table structure for table `boq_items`
--

CREATE TABLE `boq_items` (
  `id` int(10) UNSIGNED NOT NULL,
  `project_id` int(10) UNSIGNED NOT NULL,
  `section` varchar(150) NOT NULL,
  `item_no` varchar(20) NOT NULL,
  `description` text NOT NULL,
  `unit` varchar(30) NOT NULL,
  `quantity` decimal(12,3) DEFAULT 0.000,
  `rate` decimal(12,2) DEFAULT 0.00,
  `amount` decimal(15,2) DEFAULT 0.00,
  `certified_qty` decimal(12,3) DEFAULT 0.000,
  `paid_qty` decimal(12,3) DEFAULT 0.000,
  `status` varchar(40) DEFAULT 'active',
  `review_status` varchar(30) NOT NULL DEFAULT 'pending',
  `risk_status` varchar(30) NOT NULL DEFAULT 'normal',
  `manager_note` text DEFAULT NULL,
  `last_reviewed_by` int(10) UNSIGNED DEFAULT NULL,
  `last_reviewed_at` datetime DEFAULT NULL,
  `certified_updated_by` int(10) UNSIGNED DEFAULT NULL,
  `paid_updated_by` int(10) UNSIGNED DEFAULT NULL,
  `updated_by` int(10) UNSIGNED DEFAULT NULL,
  `last_certified_at` datetime DEFAULT NULL,
  `last_paid_at` datetime DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

