(7, 1, 271, 'section', 'ecitizen_cta', '{\"id\":271,\"page_id\":1,\"section_key\":\"ecitizen_cta\",\"label\":\"Application CTA\",\"section_type\":\"home_cta\",\"sort_order\":50,\"editor_mode\":\"home_cta\",\"is_visible\":1,\"is_locked\":1,\"content_json\":\"{\\\"background_image\\\":\\\"uploads/site-photos/maili-tatu-2.jpg\\\",\\\"logo_image\\\":\\\"uploads/logos/BomaYanguLogo.png\\\",\\\"eyebrow\\\":\\\"Boma Yangu - eCitizen\\\",\\\"title\\\":\\\"Your Home.\\\\nApplied Online.\\\",\\\"subtitle\\\":\\\"Register on the national Boma Yangu portal via eCitizen, save your deposit, and choose your preferred constituency in Trans-Nzoia County.\\\",\\\"primary_label\\\":\\\"Apply via eCitizen\\\",\\\"primary_url\\\":\\\"https://ecitizen.go.ke\\\",\\\"secondary_label\\\":\\\"About the programme\\\",\\\"secondary_url\\\":\\\"about.php\\\",\\\"step_1_icon\\\":\\\"fa-user-plus\\\",\\\"step_1_title\\\":\\\"Create eCitizen Account\\\",\\\"step_1_body\\\":\\\"Register at ecitizen.go.ke with your National ID or Passport.\\\",\\\"step_2_icon\\\":\\\"fa-house-circle-check\\\",\\\"step_2_title\\\":\\\"Register on Boma Yangu\\\",\\\"step_2_body\\\":\\\"Complete your housing application profile on the portal.\\\",\\\"step_3_icon\\\":\\\"fa-piggy-bank\\\",\\\"step_3_title\\\":\\\"Save Your Deposit\\\",\\\"step_3_body\\\":\\\"Min. KES 1,000/month to the Boma Yangu savings account.\\\",\\\"step_4_icon\\\":\\\"fa-map-location-dot\\\",\\\"step_4_title\\\":\\\"Select Trans-Nzoia\\\",\\\"step_4_body\\\":\\\"Choose your preferred constituency as your allocation preference.\\\"}\",\"updated_by\":null,\"updated_at\":\"2026-05-28 11:44:41\"}', 1, '2026-05-28 17:58:59'),
(8, 1, 270, 'section', 'ground_reports', '{\"id\":270,\"page_id\":1,\"section_key\":\"ground_reports\",\"label\":\"From the Ground Block\",\"section_type\":\"dynamic_news\",\"sort_order\":40,\"editor_mode\":\"dynamic_news\",\"is_visible\":1,\"is_locked\":1,\"content_json\":\"{\\\"title\\\":\\\"From the Ground\\\",\\\"subtitle\\\":\\\"Project milestones, tender notices, and official clearances - directly from Trans-Nzoia County AHP sites.\\\",\\\"button_label\\\":\\\"All Reports\\\",\\\"button_url\\\":\\\"news.php\\\",\\\"alerts_title\\\":\\\"Latest Alerts\\\",\\\"feature_count\\\":\\\"1\\\",\\\"compact_count\\\":\\\"2\\\",\\\"alert_count\\\":\\\"6\\\",\\\"empty_title\\\":\\\"Reports will appear here\\\",\\\"empty_text\\\":\\\"Published news and alerts will populate this live section.\\\"}\",\"updated_by\":null,\"updated_at\":\"2026-05-28 11:44:41\"}', 1, '2026-05-28 17:59:04'),
