(48, 3, 'source_snapshot', 'Frontend Source Snapshot', 'source', 0, 'reference', 1, 0, '{\"source_file\":\"projects.php\",\"meta\":{\"pageTitle\":\"All Projects | Trans-Nzoia County Affordable Housing Tracker\",\"pageDescription\":\"Browse all affordable housing projects in Trans-Nzoia County ???????? real-time construction progress, contractor details and unit counts across all 5 constituencies.\",\"pageKeywords\":\"Trans-Nzoia affordable housing projects, AHP Kenya, Maili Tatu estate, Matunda estate, Saboti housing, Cherangany housing\",\"canonicalUrl\":\"https://housing.transnzoia.go.ke/projects.php\",\"activePage\":\"projects\"},\"headings\":[{\"level\":1,\"text\":\"Housing ProjectsDirectory\"},{\"level\":3,\"text\":\"No projects found\"}],\"sections\":[{\"order\":1,\"id\":\"\",\"class\":\"page-hero page-hero--projects\",\"aria_label\":\"Projects directory\",\"labelled_by\":\"\"},{\"order\":2,\"id\":\"\",\"class\":\"projects-main\",\"aria_label\":\"Project listings\",\"labelled_by\":\"\"}],\"images\":[{\"src\":\"uploads/gallery/maili-tatu-2.jpg\",\"alt\":\"\",\"loading\":\"eager\"}],\"links\":[{\"href\":\"index.php\",\"text\":\"Home\"}],\"html_snapshot\":\"???<?php\\n$basePath = \'\';\\n$activePage = \'projects\';\\n$pageTitle = \'All Projects | Trans-Nzoia County Affordable Housing Tracker\';\\n$pageDescription = \'Browse all affordable housing projects in Trans-Nzoia County ???????? real-time construction progress, contractor details and unit counts across all 5 constituencies.\';\\n$pageKeywords = \'Trans-Nzoia affordable housing projects, AHP Kenya, Maili Tatu estate, Matunda estate, Saboti housing, Cherangany housing\';\\n$pageAuthor = \'Trans-Nzoia County Government ???????? Department of Land, Housing & Physical Planning\';\\n$pageRobots = \'index, follow\';\\n$themeColor = \'#163300\';\\n$canonicalUrl = \'https://housing.transnzoia.go.ke/projects.php\';\\n$pageStyles = [\\n  \'assets/css/global.css\',\\n  \'assets/css/pages/projects.css\'\\n];\\n$pageScripts = [\\n  \'assets/js/global.js\',\\n  \'assets/js/data.js\',\\n  \'assets/js/pages/projects.js\'\\n];\\n$headMeta = [\\n  \'<meta property=\\\"og:title\\\" content=\\\"All Projects ???????? Trans-Nzoia AHP Tracker\\\">\',\\n  \'<meta property=\\\"og:description\\\" content=\\\"Browse all 8 affordable housing projects across Trans-Nzoia County\\\\\'s 5 constituencies with real-time progress tracking.\\\">\',\\n  \'<meta property=\\\"og:type\\\" content=\\\"website\\\">\',\\n  \'<meta property=\\\"og:url\\\" content=\\\"https://housing.transnzoia.go.ke/projects.php\\\">\',\\n  \'<meta property=\\\"og:image\\\" content=\\\"uploads/gallery/maili-tatu-1.jpg\\\">\',\\n  \'<meta property=\\\"og:locale\\\" content=\\\"en_KE\\\">\',\\n  \'<meta property=\\\"og:site_name\\\" content=\\\"Trans-Nzoia AHP Tracker\\\">\',\\n  \'<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\">\',\\n  \'<meta name=\\\"twitter:title\\\" content=\\\"All Projects ???????? Trans-Nzoia AHP Tracker\\\">\',\\n  \'<meta name=\\\"twitter:description\\\" content=\\\"Real-time construction tracking for all 8 affordable housing projects in Trans-Nzoia County, Kenya.\\\">\',\\n  \'<meta name=\\\"twitter:image\\\" content=\\\"uploads/gallery/maili-tatu-1.jpg\\\">\'\\n];\\ninclude __DIR__ . \\\"/app/partials/\\\" . \'head.php\';\\n?>\\n<body>\\n<?php include __DIR__ . \\\"/app/partials/\\\" . \'cursor.php\'; ?>\\n<?php include __DIR__ . \\\"/app/partials/\\\" . \'skip-link.php\'; ?>\\n<?php include __DIR__ . \\\"/app/partials/\\\" . \'navbar.php\'; ?><main id=\\\"main-content\\\">\\r\\n\\r\\n    <!-- ===== PAGE HERO ===== -->\\r\\n    <section class=\\\"page-hero page-hero--projects\\\" aria-label=\\\"Projects directory\\\">\\r\\n      <div class=\\\"page-hero-bg\\\" aria-hidden=\\\"true\\\">\\r\\n        <img src=\\\"uploads/gallery/maili-tatu-2.jpg\\\" alt=\\\"\\\" loading=\\\"eager\\\" onerror=\\\"this.style.display=\'none\'\\\">\\r\\n        <div class=\\\"page-hero-overlay\\\"></div>\