(138, 2, 'faq_teaser', 'FAQ Teaser', 'about_faq', 70, 'about_faq', 1, 1, '{\"eyebrow\": \"Common Questions\", \"title\": \"Frequently Asked Questions\", \"subtitle\": \"Quick answers to the most common questions about the programme.\", \"display_count\": \"4\", \"link_label\": \"Read all frequently asked questions\", \"link_url\": \"faq.php\", \"empty_text\": \"Published FAQ records will appear here after they are added in the backend.\"}', 1, '2026-06-29 20:04:37'),
(139, 2, 'leadership_contact', 'Leadership & Contact', 'about_leadership', 80, 'about_leadership', 1, 1, '{\"eyebrow\": \"National Programme Leadership\", \"title\": \"Programme Leadership\", \"subtitle\": \"This is a national government initiative delivered through the State Department of Housing & Urban Development. The Trans-Nzoia field office coordinates local programme delivery and public support.\", \"link_label\": \"Meet the full leadership team\", \"link_url\": \"leadership.php\", \"contact_title\": \"Get In Touch\", \"contact_intro\": \"Have a question about the programme or your application? Reach the housing department directly.\", \"contact_button_label\": \"Send a Message\", \"contact_button_url\": \"contact.php\", \"office_hours\": \"Monday - Friday, 8:00 AM - 5:00 PM\", \"empty_role\": \"Leadership registry\", \"empty_title\": \"No leadership records published yet\", \"empty_text\": \"Published leadership records will appear here after they are added in the backend.\"}', 1, '2026-06-29 20:04:37'),
(140, 2, 'apply_cta', 'Apply CTA', 'about_cta', 90, 'about_cta', 1, 1, '{\"title\":\"Ready to Apply for Affordable Housing in Trans-Nzoia?\",\"subtitle\":\"Register on the national Boma Yangu portal, save your monthly deposit and select Trans-Nzoia as your allocation preference to join the housing ballot.\",\"primary_label\":\"Apply on Boma Yangu\",\"primary_url\":\"https://bomayangu.go.ke\",\"secondary_label\":\"View All Projects\",\"secondary_url\":\"projects.php\"}', 1, '2026-05-28 11:38:11'),
