(355, 1, 'current_frontend_snapshot', 'Home - Current Frontend Snapshot', 'frontend_snapshot', 1, 'json', 1, 1, '{\"page_slug\":\"home\",\"page_label\":\"Home\",\"file_path\":\"index.php\",\"source_hash\":\"0d0ca10795744b7d0c9ce048e2aad25883b661d97a2268ce5c02437df8674e67\",\"title\":\"Trans-Nzoia County Constituency Map\",\"meta_description\":\"\",\"headings\":[{\"level\":3,\"text\":\"How to Apply\"},{\"level\":2,\"text\":\"\\\" class=\\\"section-title\\\">\"}],\"links\":[{\"href\":\"<?= Security::e(CmsLoader::text($hero,\",\"text\":\"\\\" class=\\\"btn btn-lg btn-white\\\"> \\\" aria-hidden=\\\"true\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($hero,\",\"text\":\"\\\" class=\\\"btn btn-lg btn-outline-white\\\"> \\\" aria-hidden=\\\"true\\\">\"},{\"href\":\"news-article.php?id=<?= Security::e($item[\",\"text\":\"\\\" class=\\\"nas-headline\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($cta,\",\"text\":\"\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ecitizen-btn-main\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($cta,\",\"text\":\"\\\" class=\\\"ecitizen-btn-ghost\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($content,\",\"text\":\"\\\" class=\\\"btn btn-outline\\\">\"},{\"href\":\"project-detail.php?id=<?= Security::e($project[\",\"text\":\"\\\" class=\\\"btn btn-primary btn-sm\\\">View Details\"},{\"href\":\"https://ecitizen.go.ke\",\"text\":\"Apply on eCitizen\"},{\"href\":\"news-article.php?id=<?= Security::e($item[\",\"text\":\"\\\" class=\\\"news-read-link\\\">Read full report\"}],\"images\":[{\"src\":\"\",\"alt\":\"\"},{\"src\":\"\",\"alt\":\"\"},{\"src\":\"\",\"alt\":\"\"},{\"src\":\"\",\"alt\":\"\"},{\"src\":\"\",\"alt\":\"\"}],\"forms\":[],\"cms_keys\":[\"home_hero\",\"featured_projects\",\"constituency_coverage\",\"ground_reports\",\"ecitizen_cta\"],\"text_content\":\"\'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>> \\\" class=\\\"btn btn-lg btn-white\\\"> \\\" aria-hidden=\\\"true\\\"> \\\" class=\\\"btn btn-lg btn-outline-white\\\"> \\\" aria-hidden=\\\"true\\\"> Trans-Nzoia County Constituency Map \\\" data-name=\\\" \\\" data-projects=\\\" \\\" data-status=\\\" 0 ? \'active\' : \'planning\') ?>\\\" data-units=\\\" \\\" data-pct=\\\" \\\" data-link=\\\"constituency-detail.php?id= \\\" tabindex=\\\"0\\\" role=\\\"button\\\" aria-label=\\\" \\\"> \\\" class=\\\"map-path\\\"/> \\\" y=\\\" \\\"> N Constituencies Active Projects + Units Planned \\\"> \\\" class=\\\"nas-headline\\\"> \\\"> \\\"this.style.display=\'none\'\\\"]) ?>> \\\"this.style.display=\'none\'\\\"]) ?>> \\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ecitizen-btn-main\\\"> \\\" class=\\\"ecitizen-btn-ghost\\\"> How to Apply \\\" aria-hidden=\\\"true\\\"> \\\" data-suffix=\\\" \\\" aria-label=\\\" \\\">0 \\\" class=\\\"section-title\\\"> \\\" class=\\\"btn btn-outline\\\"> \\\"this.parentElement.classList.add(\'ptc-img-fallback\')\\\"]) ?>> \\\"> Units % Complete Est. Delivery \\\" aria-valuemin=\\\"0\\\" aria-valuemax=\\\"100\\\" aria-label=\\\"Construction % complete\\\"> \\\"> % Completed \\\" class=\\\"btn btn-primary btn-sm\\\">View Details Apply on eCitizen \\\"> \\\"this.parentElement.classList.add(\'news-img-fallback\')\\\"]) ?>> \\\"> \\\"> \\\" class=\\\"news-read-link\\\">Read full report <?php }\",\"raw_source\":\"<?php\\nrequire_once __DIR__ . \'/app/core/bootstrap.php\';\\n\\n$basePath = \'\';\\n$activePage = \'home\';\\n$homePage = CmsLoader::page(\'home\');\\n$projectStats = Project::stats();\\n$featuredProjects = Project::withRelations([\'featured\' => \'1\'], 3);\\nif (!$featuredProjects) {\\n    $featuredProjects = Project::withRelations([], 3);\\n}\\n$constituencies = Constituency::withProjectCounts();\\n$newsItems = home_news_items(9);\\n\\n$hero = CmsLoader::content($homePage, \'home_hero\', home_defaults(\'home_hero\'));\\n$featured = CmsLoader::content($homePage, \'featured_projects\', home_defaults(\'featured_projects\'));\\n$coverage = CmsLoader::content($homePage, \'constituency_coverage\', home_defaults(\'constituency_coverage\'));\\n$reports = CmsLoader::content($homePage, \'ground_reports\', home_defaults(\'ground_reports\'));\\n$cta = CmsLoader::content($homePage, \'ecitizen_cta\', home_defaults(\'ecitizen_cta\'));\\n\\n$pageTitle = (string)($homePage[\'seo_title\'] ?? \'Trans-Nzoia County | Affordable Housing Project Tracker\');\\n$pageDescription = (string)($homePage[\'seo_description\'] ?? \'Trans-Nzoia County Affordable Housing Project Tracker - real-time monitoring of housing construction delivery.\');\\n$pageKeywords = (string)($homePage[\'seo_keywords\'] ?? \'Trans-Nzoia affordable housing, AHP Kenya, county housing tracker\');\\n$pageAuthor = \'Trans-Nzoia County Government - Department of Land, Housing & Physical Planning\';\\n$pageRobots = \'index, follow\';\\n$themeColor = \'#163300\';\\n$canonicalUrl = (string)($homePage[\'canonical_url\'] ?? \'https://housing.transnzoia.go.ke/\');\\n$heroImage = CmsLoader::text($hero, \'background_image\', (string)($homePage[\'hero_image\'] ?? \'uploads/heroes/hero-main.jpg\'));\\n$pageStyles = [\\n    \'assets/css/global.css\',\\n    \'assets/css/pages/index.css\',\\n];\\n$pageScripts = [\\n    \'assets/js/global.js\',\\n    \'assets/js/pages/index.js\',\\n];\\n$headMeta = [\\n    \'<meta name=\\\"geo.region\\\" content=\\\"KE-36\\\">\',\\n    \'<meta name=\\\"geo.placename\\\" content=\\\"Trans-Nzoia County, Kenya\\\">\',\\n    \'<meta property=\\\"og:title\\\" content=\\\"\' . Security::e($pageTitle) . \'\\\">\',\\n    \'<meta property=\\\"og:description\\\" content=\\\"\' . Security::e($pageDescription) . \'\\\">\',\\n    \'<meta property=\\\"og:type\\\" content=\\\"website\\\">\',\\n    \'<meta property=\\\"og:url\\\" content=\\\"\' . Security::e($canonicalUrl) . \'\\\">\',\\n    \'<meta property=\\\"og:image\\\" content=\\\"\' . Security::e($heroImage) . \'\\\">\',\\n    \'<meta property=\\\"og:locale\\\" content=\\\"en_KE\\\">\',\\n    \'<meta property=\\\"og:site_name\\\" content=\\\"Trans-Nzoia AHP Tracker\\\">\',\\n    \'<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\">\',\\n    \'<meta name=\\\"twitter:title\\\" content=\\\"\' . Security::e($pageTitle) . \'\\\">\',\\n    \'<meta name=\\\"twitter:description\\\" content=\\\"\' . Security::e($pageDescription) . \'\\\">\',\\n    \'<meta name=\\\"twitter:image\\\" content=\\\"\' . Security::e($heroImage) . \'\\\">\',\\n];\\ninclude __DIR__ . \'/app/partials/head.php\';\\n?>\\n<body>\\n<?php include __DIR__ . \'/app/partials/cursor.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/skip-link.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/navbar.php\'; ?>\\n<main id=\\\"main-content\\\">\\n\\n<?php if (CmsLoader::visible($homePage, \'home_hero\')): ?>\\n  <section class=\\\"tracker-hero\\\" aria-label=\\\"Programme overview\\\">\\n    <div class=\\\"tracker-hero-bg\\\">\\n      <img <?= public_image_attrs($heroImage, CmsLoader::text($hero, \'background_alt\', \'Affordable housing construction site in Trans-Nzoia County, Kenya\'), [\'loading\' => \'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>>\\n      <div class=\\\"tracker-hero-overlay\\\" aria-hidden=\\\"true\\\"></div>\\n    </div>\\n    <div class=\\\"container tracker-hero-content\\\">\\n      <div class=\\\"tracker-hero-inner\\\">\\n        <div class=\\\"programme-badge\\\" role=\\\"status\\\">\\n          <span class=\\\"programme-badge-dot\\\" aria-hidden=\\\"true\\\"></span>\\n          <?= Security::e(CmsLoader::text($hero, \'eyebrow\', \'Ongoing Projects - Trans-Nzoia County\')) ?>\\n        </div>\\n        <h1 class=\\\"tracker-hero-title\\\"><?= nl2br(Security::e(CmsLoader::text($hero, \'title\', \\\"Affordable Housing\\\\nProject Tracker\\\")), false) ?></h1>\\n        <p class=\\\"tracker-hero-subtitle\\\"><?= Security::e(CmsLoader::text($hero, \'subtitle\', \'Transparent, real-time monitoring of housing construction delivery across all five constituencies of Trans-Nzoia County.\')) ?></p>\\n        <div class=\\\"tracker-hero-cta\\\">\\n          <a href=\\\"<?= Security::e(CmsLoader::text($hero, \'primary_url\', \'projects.php\')) ?>\\\" class=\\\"btn btn-lg btn-white\\\">\\n            <i class=\\\"fa-solid <?= Security::e(CmsLoader::text($hero, \'primary_icon\', \'fa-table-cells-large\')) ?>\\\" aria-hidden=\\\"true\\\"></i>\\n            <?= Security::e(CmsLoader::text($hero, \'primary_label\', \'View All Projects\')) ?>\\n          </a>\\n          <a href=\\\"<?= Security::e(CmsLoader::text($hero, \'secondary_url\', \'constituencies.php\')) ?>\\\" class=\\\"btn btn-lg btn-outline-white\\\">\\n            <i class=\\\"fa-solid <?= Security::e(CmsLoader::text($hero, \'secondary_icon\', \'fa-map-location-dot\')) ?>\\\" aria-hidden=\\\"true\\\"></i>\\n            <?= Security::e(CmsLoader::text($hero, \'secondary_label\', \'By Constituency\')) ?>\\n          </a>\\n        </div>\\n      </div>\\n\\n<?php if (CmsLoader::bool($hero, \'show_kpis\', true)): ?>\\n      <div class=\\\"hero-kpi-strip\\\" role=\\\"region\\\" aria-label=\\\"Programme key metrics\\\">\\n        <?php home_kpi(\'Active Projects\', (int)($projectStats[\'active_projects\'] ?? 0)); ?>\\n        <div class=\\\"hero-kpi-divider\\\" aria-hidden=\\\"true\\\"></div>\\n        <?php home_kpi(\'Units Under Construction\', (int)($projectStats[\'total_units\'] ?? 0), \'+\'); ?>\\n        <div class=\\\"hero-kpi-divider\\\" aria-hidden=\\\"true\\\"></div>\\n        <?php home_kpi(\'Constituencies Covered\', count($constituencies)); ?>\\n        <div class=\\\"hero-kpi-divider\\\" aria-hidden=\\\"true\\\"></div>\\n        <?php home_kpi(\'Avg. Completion\', (int)round((float)($projectStats[\'avg_completion\'] ?? 0)), \'%\'); ?>\\n      </div>\\n<?php endif; ?>\\n    </div>\\n  </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($homePage, \'featured_projects\')): ?>\\n  <section class=\\\"section projects-section\\\" id=\\\"featured-projects\\\" aria-labelledby=\\\"projects-heading\\\">\\n    <div class=\\\"container\\\">\\n      <?php home_section_header(\'projects-heading\', $featured, \'Featured Projects\', \'Track ongoing affordable housing construction across Trans-Nzoia County.\', \'Full Portfolio\', \'projects.php\'); ?>\\n      <div class=\\\"project-cards-grid stagger-children\\\">\\n<?php foreach (array_slice($featuredProjects, 0, max(1, (int)($featured[\'display_count\'] ?? 3))) as $project): ?>\\n        <?php home_project_card($project); ?>\\n<?php endforeach; ?>\\n<?php if (!$featuredProjects): ?>\\n        <div class=\\\"empty-state\\\">\\n          <strong><?= Security::e(CmsLoader::text($featured, \'empty_title\', \'Featured projects will appear here\')) ?></strong>\\n          <p><?= Security::e(CmsLoader::text($featured, \'empty_text\', \'Mark projects as featured in the project editor to populate this section.\')) ?></p>\\n        </div>\\n<?php endif; ?>\\n      </div>\\n    </div>\\n  </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($homePage, \'constituency_coverage\')): ?>\\n  <section class=\\\"section map-section\\\" aria-labelledby=\\\"map-heading\\\">\\n    <div class=\\\"container\\\">\\n      <?php home_section_header(\'map-heading\', $coverage, \'Coverage by Constituency\', \'All five constituencies are part of the Trans-Nzoia AHP.\', \'All Constituencies\', \'constituencies.php\'); ?>\\n      <div class=\\\"map-interactive-wrap\\\">\\n        <div class=\\\"map-canvas-wrap\\\">\\n          <svg viewBox=\\\"0 0 480 400\\\" class=\\\"county-map\\\" role=\\\"img\\\" aria-label=\\\"Interactive map of Trans-Nzoia County showing five constituencies\\\">\\n            <title>Trans-Nzoia County Constituency Map</title>\\n            <defs><filter id=\\\"mapGlow\\\"><feGaussianBlur stdDeviation=\\\"3\\\" result=\\\"blur\\\"/><feMerge><feMergeNode in=\\\"blur\\\"/><feMergeNode in=\\\"SourceGraphic\\\"/></feMerge></filter></defs>\\n<?php foreach (home_map_shapes() as $slug => $shape): ?>\\n            <?php $c = home_constituency($constituencies, $slug); $projects = (int)($c[\'live_project_count\'] ?? 0); $pct = (int)round((float)($c[\'live_avg_completion\'] ?? 0)); ?>\\n            <g class=\\\"map-constituency\\\" data-id=\\\"<?= Security::e($slug) ?>\\\" data-name=\\\"<?= Security::e($c[\'name\'] ?? $shape[\'name\']) ?>\\\" data-projects=\\\"<?= $projects ?>\\\" data-status=\\\"<?= Security::e($pct > 0 ? \'active\' : \'planning\') ?>\\\" data-units=\\\"<?= (int)($c[\'live_total_units\'] ?? 0) ?>\\\" data-pct=\\\"<?= $pct ?>\\\" data-link=\\\"constituency-detail.php?id=<?= Security::e($slug) ?>\\\" tabindex=\\\"0\\\" role=\\\"button\\\" aria-label=\\\"<?= Security::e(($c[\'name\'] ?? $shape[\'name\']) . \' - \' . $projects . \' projects\') ?>\\\">\\n              <path d=\\\"<?= Security::e($shape[\'path\']) ?>\\\" class=\\\"map-path\\\"/>\\n              <text class=\\\"map-label\\\" x=\\\"<?= Security::e($shape[\'x\']) ?>\\\" y=\\\"<?= Security::e($shape[\'y\']) ?>\\\"><?= Security::e($c[\'name\'] ?? $shape[\'name\']) ?></text>\\n            </g>\\n<?php endforeach; ?>\\n            <g class=\\\"map-sites\\\" aria-hidden=\\\"true\\\">\\n              <circle class=\\\"map-site-dot site-active\\\" cx=\\\"178\\\" cy=\\\"255\\\" r=\\\"6\\\"/><circle class=\\\"map-site-pulse\\\" cx=\\\"178\\\" cy=\\\"255\\\" r=\\\"6\\\"/>\\n              <circle class=\\\"map-site-dot site-active\\\" cx=\\\"304\\\" cy=\\\"125\\\" r=\\\"6\\\"/><circle class=\\\"map-site-pulse\\\" cx=\\\"304\\\" cy=\\\"125\\\" r=\\\"6\\\"/>\\n              <circle class=\\\"map-site-dot site-planning\\\" cx=\\\"88\\\" cy=\\\"82\\\" r=\\\"5\\\"/>\\n            </g>\\n          </svg>\\n          <div class=\\\"map-compass\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid fa-location-crosshairs\\\"></i><span>N</span></div>\\n          <div class=\\\"map-legend\\\" aria-hidden=\\\"true\\\">\\n            <span class=\\\"map-legend-item\\\"><span class=\\\"map-legend-dot map-legend-active\\\"></span><?= Security::e(CmsLoader::text($coverage, \'legend_active\', \'Active\')) ?></span>\\n            <span class=\\\"map-legend-item\\\"><span class=\\\"map-legend-dot map-legend-plan\\\"></span><?= Security::e(CmsLoader::text($coverage, \'legend_planning\', \'Planning\')) ?></span>\\n            <span class=\\\"map-legend-item\\\"><i class=\\\"fa-solid fa-location-dot\\\" style=\\\"color:var(--lime-muted);font-size:11px\\\"></i> <?= Security::e(CmsLoader::text($coverage, \'legend_site\', \'Project site\')) ?></span>\\n          </div>\\n        </div>\\n        <aside class=\\\"map-side-panel\\\" id=\\\"mapPanel\\\" aria-live=\\\"polite\\\">\\n          <div class=\\\"map-panel-default\\\" id=\\\"mapPanelDefault\\\">\\n            <i class=\\\"fa-solid fa-map-location-dot map-panel-icon\\\" aria-hidden=\\\"true\\\"></i>\\n            <p class=\\\"map-panel-hint\\\"><?= Security::e(CmsLoader::text($coverage, \'panel_hint\', \'Click a constituency on the map to see project data\')) ?></p>\\n            <div class=\\\"map-panel-overview\\\">\\n              <div class=\\\"map-ov-item\\\"><span class=\\\"map-ov-val\\\"><?= Security::e(format_number(count($constituencies))) ?></span><span class=\\\"map-ov-lbl\\\">Constituencies</span></div>\\n              <div class=\\\"map-ov-item\\\"><span class=\\\"map-ov-val\\\"><?= Security::e(format_number((int)($projectStats[\'active_projects\'] ?? 0))) ?></span><span class=\\\"map-ov-lbl\\\">Active Projects</span></div>\\n              <div class=\\\"map-ov-item\\\"><span class=\\\"map-ov-val\\\"><?= Security::e(format_number((int)($projectStats[\'total_units\'] ?? 0))) ?>+</span><span class=\\\"map-ov-lbl\\\">Units Planned</span></div>\\n            </div>\\n          </div>\\n          <div class=\\\"map-panel-detail\\\" id=\\\"mapPanelDetail\\\"></div>\\n        </aside>\\n      </div>\\n    </div>\\n  </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($homePage, \'ground_reports\')): ?>\\n  <section class=\\\"section news-section\\\" aria-labelledby=\\\"news-heading\\\">\\n    <div class=\\\"container\\\">\\n      <?php home_section_header(\'news-heading\', $reports, \'From the Ground\', \'Project milestones, tender notices, and official clearances.\', \'All Reports\', \'news.php\'); ?>\\n      <div class=\\\"news-asymmetric\\\">\\n<?php if ($newsItems): ?>\\n        <?php home_news_card($newsItems[0], true); ?>\\n        <div class=\\\"news-stack\\\">\\n<?php foreach (array_slice($newsItems, 1, max(0, (int)($reports[\'compact_count\'] ?? 2))) as $item): ?>\\n          <?php home_news_card($item, false); ?>\\n<?php endforeach; ?>\\n        </div>\\n        <aside class=\\\"news-alerts-sidebar\\\" aria-label=\\\"Latest programme alerts\\\">\\n          <div class=\\\"nas-header\\\"><i class=\\\"fa-solid fa-bolt nas-icon\\\" aria-hidden=\\\"true\\\"></i><span class=\\\"nas-title\\\"><?= Security::e(CmsLoader::text($reports, \'alerts_title\', \'Latest Alerts\')) ?></span></div>\\n          <ul class=\\\"nas-list\\\">\\n<?php foreach (array_slice($newsItems, 0, max(1, (int)($reports[\'alert_count\'] ?? 6))) as $index => $item): ?>\\n            <li class=\\\"nas-item <?= $index === 0 ? \'nas-item--urgent\' : \'\' ?>\\\">\\n              <span class=\\\"nas-dot\\\" aria-hidden=\\\"true\\\"></span>\\n              <div class=\\\"nas-content\\\">\\n                <span class=\\\"nas-tag\\\"><?= Security::e($item[\'category_name\'] ?? \'Report\') ?></span>\\n                <a href=\\\"news-article.php?id=<?= Security::e($item[\'slug\']) ?>\\\" class=\\\"nas-headline\\\"><?= Security::e($item[\'title\']) ?></a>\\n                <time class=\\\"nas-time\\\" datetime=\\\"<?= Security::e(substr((string)$item[\'published_at\'], 0, 10)) ?>\\\"><?= Security::e(format_date($item[\'published_at\'] ?? null, \'d M Y\')) ?></time>\\n              </div>\\n            </li>\\n<?php endforeach; ?>\\n          </ul>\\n        </aside>\\n<?php else: ?>\\n        <div class=\\\"empty-state\\\">\\n          <strong><?= Security::e(CmsLoader::text($reports, \'empty_title\', \'Reports will appear here\')) ?></strong>\\n          <p><?= Security::e(CmsLoader::text($reports, \'empty_text\', \'Published news and alerts will populate this live section.\')) ?></p>\\n        </div>\\n<?php endif; ?>\\n      </div>\\n    </div>\\n  </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($homePage, \'ecitizen_cta\')): ?>\\n  <section class=\\\"ecitizen-cta\\\" aria-labelledby=\\\"ecitizen-heading\\\">\\n    <div class=\\\"ecitizen-cta-bg\\\" aria-hidden=\\\"true\\\">\\n      <img <?= public_image_attrs(CmsLoader::text($cta, \'background_image\', \'uploads/site-photos/maili-tatu-2.jpg\'), \'\', [\'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>>\\n      <div class=\\\"ecitizen-cta-overlay\\\"></div>\\n    </div>\\n    <div class=\\\"container\\\">\\n      <div class=\\\"ecitizen-inner fade-up\\\">\\n        <div class=\\\"ecitizen-left\\\">\\n          <div class=\\\"ecitizen-eyebrow\\\">\\n            <img <?= public_image_attrs(CmsLoader::text($cta, \'logo_image\', \'uploads/logos/BomaYanguLogo.png\'), \'Boma Yangu\', [\'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>>\\n            <span><?= Security::e(CmsLoader::text($cta, \'eyebrow\', \'Boma Yangu - eCitizen\')) ?></span>\\n          </div>\\n          <h2 id=\\\"ecitizen-heading\\\" class=\\\"ecitizen-headline\\\"><?= nl2br(Security::e(CmsLoader::text($cta, \'title\', \\\"Your Home.\\\\nApplied Online.\\\")), false) ?></h2>\\n          <p class=\\\"ecitizen-sub\\\"><?= Security::e(CmsLoader::text($cta, \'subtitle\', \'Register on the national Boma Yangu portal via eCitizen.\')) ?></p>\\n          <div class=\\\"ecitizen-actions\\\">\\n            <a href=\\\"<?= Security::e(CmsLoader::text($cta, \'primary_url\', \'https://ecitizen.go.ke\')) ?>\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ecitizen-btn-main\\\">\\n              <?= Security::e(CmsLoader::text($cta, \'primary_label\', \'Apply via eCitizen\')) ?> <i class=\\\"fa-solid fa-arrow-up-right-from-square\\\" aria-hidden=\\\"true\\\"></i>\\n            </a>\\n            <a href=\\\"<?= Security::e(CmsLoader::text($cta, \'secondary_url\', \'about.php\')) ?>\\\" class=\\\"ecitizen-btn-ghost\\\">\\n              <?= Security::e(CmsLoader::text($cta, \'secondary_label\', \'About the programme\')) ?> <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i>\\n            </a>\\n          </div>\\n        </div>\\n        <div class=\\\"ecitizen-steps\\\" aria-label=\\\"How to apply via eCitizen\\\">\\n          <h3 class=\\\"ecitizen-steps-title\\\"><i class=\\\"fa-solid fa-list-check\\\" aria-hidden=\\\"true\\\"></i> How to Apply</h3>\\n          <div class=\\\"ecitizen-steps-grid\\\">\\n<?php for ($i = 1; $i <= 4; $i++): ?>\\n            <div class=\\\"ecitizen-step-card\\\">\\n              <div class=\\\"ecitizen-step-icon-wrap\\\">\\n                <i class=\\\"fa-solid <?= Security::e(CmsLoader::text($cta, \\\"step_{$i}_icon\\\", \'fa-circle-check\')) ?>\\\" aria-hidden=\\\"true\\\"></i>\\n                <span class=\\\"ecitizen-step-num\\\"><?= str_pad((string)$i, 2, \'0\', STR_PAD_LEFT) ?></span>\\n              </div>\\n              <strong><?= Security::e(CmsLoader::text($cta, \\\"step_{$i}_title\\\", \'Application step\')) ?></strong>\\n              <p><?= Security::e(CmsLoader::text($cta, \\\"step_{$i}_body\\\", \'Complete this step to continue.\')) ?></p>\\n            </div>\\n<?php endfor; ?>\\n          </div>\\n        </div>\\n      </div>\\n    </div>\\n  </section>\\n<?php endif; ?>\\n\\n</main>\\n\\n<?php include __DIR__ . \'/app/partials/footer.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/back-to-top.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/mobile-menu.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/scripts.php\'; ?>\\n</body>\\n</html>\\n\\n<?php\\nfunction home_defaults(string $key): array\\n{\\n    return match ($key) {\\n        \'home_hero\' => [\\n            \'eyebrow\' => \'Ongoing Projects - Trans-Nzoia County\',\\n            \'title\' => \\\"Affordable Housing\\\\nProject Tracker\\\",\\n            \'subtitle\' => \'Transparent, real-time monitoring of housing construction delivery across all five constituencies of Trans-Nzoia County.\',\\n            \'background_image\' => \'uploads/heroes/hero-main.jpg\',\\n            \'background_alt\' => \'Affordable housing construction site in Trans-Nzoia County, Kenya\',\\n            \'primary_label\' => \'View All Projects\',\\n            \'primary_url\' => \'projects.php\',\\n            \'primary_icon\' => \'fa-table-cells-large\',\\n            \'secondary_label\' => \'By Constituency\',\\n            \'secondary_url\' => \'constituencies.php\',\\n            \'secondary_icon\' => \'fa-map-location-dot\',\\n            \'show_kpis\' => \'1\',\\n        ],\\n        \'featured_projects\' => [\'title\' => \'Featured Projects\', \'subtitle\' => \'Track ongoing affordable housing construction across Trans-Nzoia County.\', \'button_label\' => \'Full Portfolio\', \'button_url\' => \'projects.php\'],\\n        \'constituency_coverage\' => [\'title\' => \'Coverage by Constituency\', \'subtitle\' => \'All five constituencies are part of the Trans-Nzoia AHP.\', \'button_label\' => \'All Constituencies\', \'button_url\' => \'constituencies.php\'],\\n        \'ground_reports\' => [\'title\' => \'From the Ground\', \'subtitle\' => \'Project milestones, tender notices, and official clearances.\', \'button_label\' => \'All Reports\', \'button_url\' => \'news.php\', \'alerts_title\' => \'Latest Alerts\'],\\n        \'ecitizen_cta\' => [\'title\' => \\\"Your Home.\\\\nApplied Online.\\\", \'subtitle\' => \'Register on the national Boma Yangu portal via eCitizen.\', \'primary_label\' => \'Apply via eCitizen\', \'primary_url\' => \'https://ecitizen.go.ke\'],\\n        default => [],\\n    };\\n}\\n\\nfunction home_kpi(string $label, int $value, string $suffix = \'\'): void\\n{\\n    ?>\\n    <div class=\\\"hero-kpi-item\\\">\\n      <span class=\\\"hero-kpi-number\\\" data-count=\\\"<?= $value ?>\\\" data-suffix=\\\"<?= Security::e($suffix) ?>\\\" aria-label=\\\"<?= Security::e(format_number($value) . $suffix . \' \' . $label) ?>\\\">0</span>\\n      <span class=\\\"hero-kpi-label\\\"><?= Security::e($label) ?></span>\\n    </div>\\n    <?php\\n}\\n\\nfunction home_section_header(string $id, array $content, string $fallbackTitle, string $fallbackSubtitle, string $fallbackButton, string $fallbackUrl): void\\n{\\n    ?>\\n    <div class=\\\"split-section-header fade-up\\\">\\n      <div class=\\\"split-section-left\\\">\\n        <span class=\\\"accent-line\\\"></span>\\n        <h2 id=\\\"<?= Security::e($id) ?>\\\" class=\\\"section-title\\\"><?= Security::e(CmsLoader::text($content, \'title\', $fallbackTitle)) ?></h2>\\n        <p class=\\\"section-subtitle\\\" style=\\\"margin-bottom:0\\\"><?= Security::e(CmsLoader::text($content, \'subtitle\', $fallbackSubtitle)) ?></p>\\n      </div>\\n      <div class=\\\"split-section-right\\\">\\n        <a href=\\\"<?= Security::e(CmsLoader::text($content, \'button_url\', $fallbackUrl)) ?>\\\" class=\\\"btn btn-outline\\\">\\n          <?= Security::e(CmsLoader::text($content, \'button_label\', $fallbackButton)) ?> <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i>\\n        </a>\\n      </div>\\n    </div>\\n    <?php\\n}\\n\\nfunction home_project_card(array $project): void\\n{\\n    $image = home_project_image($project);\\n    $status = status_label($project[\'status\'] ?? \'planning\');\\n    $pct = (int)($project[\'pct_complete\'] ?? 0);\\n    ?>\\n    <article class=\\\"ptc\\\">\\n      <div class=\\\"ptc-image\\\">\\n        <img <?= public_image_attrs($image, ($project[\'name\'] ?? \'Project\') . \' construction site\', [\'onerror\' => \\\"this.parentElement.classList.add(\'ptc-img-fallback\')\\\"]) ?>>\\n        <div class=\\\"ptc-image-overlay\\\" aria-hidden=\\\"true\\\"></div>\\n        <div class=\\\"ptc-badges\\\">\\n          <span class=\\\"badge <?= ($project[\'status\'] ?? \'\') === \'active\' ? \'badge-ongoing\' : \'badge-warning\' ?>\\\"><?= Security::e($status) ?></span>\\n          <span class=\\\"ptc-category-tag\\\"><?= Security::e($project[\'category_name\'] ?? \'AHP\') ?></span>\\n        </div>\\n      </div>\\n      <div class=\\\"ptc-body\\\">\\n        <div class=\\\"ptc-location\\\"><i class=\\\"fa-solid fa-location-dot\\\" aria-hidden=\\\"true\\\"></i> <?= Security::e(($project[\'constituency_name\'] ?? \'Trans-Nzoia\') . \' Constituency - \' . ($project[\'ward_name\'] ?? $project[\'location_label\'] ?? \'\')) ?></div>\\n        <h3 class=\\\"ptc-title\\\"><?= Security::e($project[\'name\'] ?? \'Project\') ?></h3>\\n        <div class=\\\"ptc-stats-row\\\">\\n          <div class=\\\"ptc-stat\\\"><span class=\\\"ptc-stat-val\\\"><?= Security::e(format_number((int)($project[\'units\'] ?? 0))) ?></span><span class=\\\"ptc-stat-lbl\\\">Units</span></div>\\n          <div class=\\\"ptc-stat-sep\\\" aria-hidden=\\\"true\\\"></div>\\n          <div class=\\\"ptc-stat\\\"><span class=\\\"ptc-stat-val ptc-stat-pct\\\"><?= $pct ?>%</span><span class=\\\"ptc-stat-lbl\\\">Complete</span></div>\\n          <div class=\\\"ptc-stat-sep\\\" aria-hidden=\\\"true\\\"></div>\\n          <div class=\\\"ptc-stat\\\"><span class=\\\"ptc-stat-val\\\"><?= Security::e(home_delivery_year($project[\'est_delivery\'] ?? null)) ?></span><span class=\\\"ptc-stat-lbl\\\">Est. Delivery</span></div>\\n        </div>\\n        <div class=\\\"ptc-progress\\\" role=\\\"progressbar\\\" aria-valuenow=\\\"<?= $pct ?>\\\" aria-valuemin=\\\"0\\\" aria-valuemax=\\\"100\\\" aria-label=\\\"Construction <?= $pct ?>% complete\\\">\\n          <div class=\\\"ptc-progress-track\\\"><div class=\\\"ptc-progress-fill\\\" data-progress=\\\"<?= $pct ?>\\\"></div></div>\\n          <span class=\\\"ptc-progress-label\\\"><?= $pct ?>% Completed</span>\\n        </div>\\n        <div class=\\\"ptc-actions\\\">\\n          <a href=\\\"project-detail.php?id=<?= Security::e($project[\'slug\'] ?? \'\') ?>\\\" class=\\\"btn btn-primary btn-sm\\\">View Details</a>\\n          <a href=\\\"https://ecitizen.go.ke\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"btn btn-outline btn-sm\\\">Apply on eCitizen <i class=\\\"fa-solid fa-arrow-up-right-from-square\\\" aria-hidden=\\\"true\\\"></i></a>\\n        </div>\\n      </div>\\n    </article>\\n    <?php\\n}\\n\\nfunction home_project_image(array $project): string\\n{\\n    if (!empty($project[\'hero_image\'])) {\\n        return (string)$project[\'hero_image\'];\\n    }\\n\\n    $images = json_decode((string)($project[\'images_json\'] ?? \'\'), true);\\n    return is_array($images) && !empty($images[0]) ? (string)$images[0] : \'uploads/heroes/hero-main.jpg\';\\n}\\n\\nfunction home_delivery_year(mixed $date): string\\n{\\n    if (!$date) {\\n        return \'TBD\';\\n    }\\n\\n    $timestamp = strtotime((string)$date);\\n    return $timestamp ? date(\'Y\', $timestamp) : (string)$date;\\n}\\n\\nfunction home_constituency(array $rows, string $slug): array\\n{\\n    foreach ($rows as $row) {\\n        if (($row[\'slug\'] ?? \'\') === $slug) {\\n            return $row;\\n        }\\n    }\\n\\n    return [];\\n}\\n\\nfunction home_map_shapes(): array\\n{\\n    return [\\n        \'endebess\' => [\'name\' => \'Endebess\', \'path\' => \'M 20,20 L 220,20 L 220,180 L 120,200 L 20,160 Z\', \'x\' => \'112\', \'y\' => \'98\'],\\n        \'cherangany\' => [\'name\' => \'Cherangany\', \'path\' => \'M 220,20 L 460,20 L 460,230 L 260,230 L 220,180 Z\', \'x\' => \'348\', \'y\' => \'112\'],\\n        \'kiminini\' => [\'name\' => \'Kiminini\', \'path\' => \'M 20,160 L 120,200 L 120,380 L 20,380 Z\', \'x\' => \'62\', \'y\' => \'290\'],\\n        \'saboti\' => [\'name\' => \'Saboti\', \'path\' => \'M 120,200 L 220,180 L 260,230 L 260,380 L 120,380 Z\', \'x\' => \'186\', \'y\' => \'305\'],\\n        \'kwanza\' => [\'name\' => \'Kwanza\', \'path\' => \'M 260,230 L 460,230 L 460,380 L 260,380 Z\', \'x\' => \'362\', \'y\' => \'310\'],\\n    ];\\n}\\n\\nfunction home_news_items(int $limit): array\\n{\\n    try {\\n        return Database::fetchAll(\\\"\\n            SELECT na.*, nc.name AS category_name, nc.slug AS category_slug, ml.path AS image_path\\n            FROM news_articles na\\n            LEFT JOIN news_categories nc ON nc.id = na.category_id\\n            LEFT JOIN media_library ml ON ml.id = na.featured_image_id\\n            WHERE na.status = \'published\'\\n            ORDER BY COALESCE(na.published_at, na.created_at) DESC, na.id DESC\\n            LIMIT {$limit}\\n        \\\");\\n    } catch (Throwable $e) {\\n        return [];\\n    }\\n}\\n\\nfunction home_news_card(array $item, bool $feature): void\\n{\\n    $image = (string)($item[\'image_path\'] ?? \'uploads/news/modern-market.jpg\');\\n    $class = $feature ? \'news-card news-card--feature\' : \'news-card news-card--compact\';\\n    ?>\\n    <article class=\\\"<?= $class ?>\\\">\\n      <div class=\\\"news-card-img\\\">\\n        <img <?= public_image_attrs($image, $item[\'title\'] ?? \'Programme report\', [\'onerror\' => \\\"this.parentElement.classList.add(\'news-img-fallback\')\\\"]) ?>>\\n        <span class=\\\"news-cat-badge news-cat-milestone\\\"><i class=\\\"fa-solid fa-flag-checkered\\\" aria-hidden=\\\"true\\\"></i> <?= Security::e($item[\'category_name\'] ?? \'Report\') ?></span>\\n      </div>\\n      <div class=\\\"news-card-body\\\">\\n        <time class=\\\"news-date\\\" datetime=\\\"<?= Security::e(substr((string)($item[\'published_at\'] ?? $item[\'created_at\'] ?? \'\'), 0, 10)) ?>\\\"><i class=\\\"fa-regular fa-calendar\\\" aria-hidden=\\\"true\\\"></i> <?= Security::e(format_date($item[\'published_at\'] ?? $item[\'created_at\'] ?? null, \'d M Y\')) ?></time>\\n        <h3 class=\\\"news-card-title\\\"><?= Security::e($item[\'title\'] ?? \'Programme report\') ?></h3>\\n        <p class=\\\"news-card-text <?= $feature ? \'\' : \'line-clamp-2\' ?>\\\"><?= Security::e($item[\'excerpt\'] ?? \'\') ?></p>\\n<?php if ($feature): ?>\\n        <a href=\\\"news-article.php?id=<?= Security::e($item[\'slug\'] ?? \'\') ?>\\\" class=\\\"news-read-link\\\">Read full report <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i></a>\\n<?php endif; ?>\\n      </div>\\n    </article>\\n    <?php\\n}\\n\",\"note\":\"Snapshot of the current public frontend file. Frontend rendering has not been changed yet.\"}', NULL, '2026-06-24 18:05:13');
INSERT INTO `cms_sections` (`id`, `page_id`, `section_key`, `label`, `section_type`, `sort_order`, `editor_mode`, `is_visible`, `is_locked`, `content_json`, `updated_by`, `updated_at`) VALUES
(356, 2, 'current_frontend_snapshot', 'About - Current Frontend Snapshot', 'frontend_snapshot', 1, 'json', 1, 1, '{\"page_slug\":\"about\",\"page_label\":\"About\",\"file_path\":\"about.php\",\"source_hash\":\"0fbe9e275b5cfb7f10c736d6c8f40d3edfafeeea8cd82c961ad50908c220bb0b\",\"title\":\"\",\"meta_description\":\"\",\"headings\":[],\"links\":[{\"href\":\"index.php\",\"text\":\"Home\"},{\"href\":\"<?= Security::e(CmsLoader::text($hero,\",\"text\":\"\\\" class=\\\"ab-btn-lime\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($hero,\",\"text\":\"\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-btn-outline\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($overview,\",\"text\":\"\\\" class=\\\"ab-text-link\\\">\"},{\"href\":\"<?= Security::e($row[\",\"text\":\"\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">\"},{\"href\":\"<?= Security::e($card[\",\"text\":\"\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-legal-link\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($faqTeaser,\",\"text\":\"\\\" class=\\\"ab-text-link\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($leadership,\",\"text\":\"\\\" class=\\\"ab-text-link\\\" style=\\\"margin-top:var(--space-6);display:inline-flex;align-items:center;gap:var(--space-2)\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($leadership,\",\"text\":\"\\\" class=\\\"ab-contact-cta\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($applyCta,\",\"text\":\"\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-btn-lime\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($applyCta,\",\"text\":\"\\\" class=\\\"ab-btn-outline-dark\\\">\"},{\"href\":\"<?= Security::e($href) ?>\",\"text\":\"\"}],\"images\":[{\"src\":\"\",\"alt\":\"\"}],\"forms\":[],\"cms_keys\":[\"about_hero\",\"programme_overview\",\"core_commitments\",\"programme_history\",\"legal_framework\",\"partners_teaser\",\"faq_teaser\",\"leadership_contact\",\"apply_cta\"],\"text_content\":\"\'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>> Home About \\\" class=\\\"ab-btn-lime\\\"> \\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-btn-outline\\\"> \\\" class=\\\"ab-text-link\\\"> \\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\"> \\\"> \\\"> \\\"> \\\"> \\\" aria-hidden=\\\"true\\\"> \\\"> \\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-legal-link\\\"> \\\"> \\\" id=\\\"faq-trigger- \\\"> \\\" role=\\\"region\\\" aria-labelledby=\\\"faq-trigger- \\\"> \\\" class=\\\"ab-text-link\\\"> \\\"> \\\" class=\\\"ab-text-link\\\" style=\\\"margin-top:var(--space-6);display:inline-flex;align-items:center;gap:var(--space-2)\\\"> \\\" class=\\\"ab-contact-cta\\\"> \\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-btn-lime\\\"> \\\" class=\\\"ab-btn-outline-dark\\\"> ab-kpi-icon\\\" aria-hidden=\\\"true\\\"> \\\" > \\\"> \\\"> <?php }\",\"raw_source\":\"<?php\\nrequire_once __DIR__ . \'/app/core/bootstrap.php\';\\n\\n$basePath = \'\';\\n$activePage = \'about\';\\n$aboutPage = CmsLoader::page(\'about\');\\n$projectStats = Project::stats();\\n$constituencies = Constituency::withProjectCounts();\\n\\n$hero = CmsLoader::content($aboutPage, \'about_hero\', about_defaults(\'about_hero\'));\\n$overview = CmsLoader::content($aboutPage, \'programme_overview\', about_defaults(\'programme_overview\'));\\n$pillars = CmsLoader::content($aboutPage, \'core_commitments\', about_defaults(\'core_commitments\'));\\n$history = CmsLoader::content($aboutPage, \'programme_history\', about_defaults(\'programme_history\'));\\n$legal = CmsLoader::content($aboutPage, \'legal_framework\', about_defaults(\'legal_framework\'));\\n$partners = CmsLoader::content($aboutPage, \'partners_teaser\', about_defaults(\'partners_teaser\'));\\n$faqTeaser = CmsLoader::content($aboutPage, \'faq_teaser\', about_defaults(\'faq_teaser\'));\\n$leadership = CmsLoader::content($aboutPage, \'leadership_contact\', about_defaults(\'leadership_contact\'));\\n$applyCta = CmsLoader::content($aboutPage, \'apply_cta\', about_defaults(\'apply_cta\'));\\n\\n$pageTitle = (string)($aboutPage[\'seo_title\'] ?? \'About the Programme | Trans-Nzoia AHP Tracker\');\\n$pageDescription = (string)($aboutPage[\'seo_description\'] ?? \'Learn about the Trans-Nzoia County Affordable Housing Programme - mandate, partners, legal framework and how to apply.\');\\n$pageKeywords = (string)($aboutPage[\'seo_keywords\'] ?? \'Trans-Nzoia affordable housing, AHP Kenya, housing programme, Boma Yangu, county housing policy\');\\n$pageAuthor = \'Trans-Nzoia County Government - Department of Land, Housing & Physical Planning\';\\n$pageRobots = \'index, follow\';\\n$themeColor = \'#163300\';\\n$canonicalUrl = (string)($aboutPage[\'canonical_url\'] ?? \'https://housing.transnzoia.go.ke/about.php\');\\n$heroImage = CmsLoader::text($hero, \'background_image\', (string)($aboutPage[\'hero_image\'] ?? \'uploads/gallery/maili-tatu-2.jpg\'));\\n$pageStyles = [\\n    \'assets/css/global.css\',\\n    \'assets/css/pages/about.css\',\\n];\\n$pageScripts = [\\n    \'assets/js/global.js\',\\n    \'assets/js/pages/about.js\',\\n];\\n$headMeta = [\\n    \'<meta name=\\\"geo.region\\\" content=\\\"KE-36\\\">\',\\n    \'<meta name=\\\"geo.placename\\\" content=\\\"Trans-Nzoia County, Kenya\\\">\',\\n    \'<meta property=\\\"og:title\\\" content=\\\"\' . Security::e($pageTitle) . \'\\\">\',\\n    \'<meta property=\\\"og:description\\\" content=\\\"\' . Security::e($pageDescription) . \'\\\">\',\\n    \'<meta property=\\\"og:type\\\" content=\\\"website\\\">\',\\n    \'<meta property=\\\"og:url\\\" content=\\\"\' . Security::e($canonicalUrl) . \'\\\">\',\\n    \'<meta property=\\\"og:image\\\" content=\\\"\' . Security::e($heroImage) . \'\\\">\',\\n    \'<meta property=\\\"og:locale\\\" content=\\\"en_KE\\\">\',\\n    \'<meta property=\\\"og:site_name\\\" content=\\\"Trans-Nzoia AHP Tracker\\\">\',\\n    \'<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\">\',\\n    \'<meta name=\\\"twitter:title\\\" content=\\\"\' . Security::e($pageTitle) . \'\\\">\',\\n    \'<meta name=\\\"twitter:description\\\" content=\\\"\' . Security::e($pageDescription) . \'\\\">\',\\n    \'<meta name=\\\"twitter:image\\\" content=\\\"\' . Security::e($heroImage) . \'\\\">\',\\n];\\ninclude __DIR__ . \'/app/partials/head.php\';\\n?>\\n<body>\\n<?php include __DIR__ . \'/app/partials/cursor.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/skip-link.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/navbar.php\'; ?>\\n<main id=\\\"main-content\\\">\\n\\n<?php if (CmsLoader::visible($aboutPage, \'about_hero\')): ?>\\n    <section class=\\\"ab-hero\\\" aria-label=\\\"About the programme\\\">\\n      <div class=\\\"ab-hero-bg\\\" aria-hidden=\\\"true\\\">\\n        <img <?= public_image_attrs($heroImage, CmsLoader::text($hero, \'background_alt\', \'Affordable housing construction works in Trans-Nzoia County\'), [\'loading\' => \'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>>\\n        <div class=\\\"ab-hero-overlay\\\"></div>\\n      </div>\\n      <div class=\\\"container\\\">\\n        <nav class=\\\"breadcrumb\\\" aria-label=\\\"Breadcrumb\\\">\\n          <a href=\\\"index.php\\\" class=\\\"breadcrumb-link\\\">Home</a>\\n          <span class=\\\"breadcrumb-sep\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid fa-chevron-right\\\"></i></span>\\n          <span class=\\\"breadcrumb-current\\\" aria-current=\\\"page\\\">About</span>\\n        </nav>\\n        <div class=\\\"ab-hero-body\\\">\\n          <div class=\\\"ab-hero-eyebrow\\\">\\n            <i class=\\\"fa-solid fa-circle-info\\\" aria-hidden=\\\"true\\\"></i>\\n            <?= Security::e(CmsLoader::text($hero, \'eyebrow\', \'National Affordable Housing Programme - Trans-Nzoia County\')) ?>\\n          </div>\\n          <h1 class=\\\"ab-hero-title\\\"><?= nl2br(Security::e(CmsLoader::text($hero, \'title\', \'Delivering Affordable Homes for Trans-Nzoia County Residents\')), false) ?></h1>\\n          <p class=\\\"ab-hero-desc\\\"><?= Security::e(CmsLoader::text($hero, \'subtitle\', \'A government-led initiative to provide quality, subsidised housing to low-to-middle-income earners across all five constituencies - tracked transparently for every resident.\')) ?></p>\\n          <div class=\\\"ab-hero-ctas\\\">\\n            <a href=\\\"<?= Security::e(CmsLoader::text($hero, \'primary_url\', \'projects.php\')) ?>\\\" class=\\\"ab-btn-lime\\\">\\n              <i class=\\\"fa-solid fa-building-columns\\\" aria-hidden=\\\"true\\\"></i> <?= Security::e(CmsLoader::text($hero, \'primary_label\', \'View All Projects\')) ?>\\n            </a>\\n            <a href=\\\"<?= Security::e(CmsLoader::text($hero, \'secondary_url\', \'https://bomayangu.go.ke\')) ?>\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-btn-outline\\\">\\n              <?= Security::e(CmsLoader::text($hero, \'secondary_label\', \'Apply on Boma Yangu\')) ?> <i class=\\\"fa-solid fa-arrow-up-right-from-square\\\" aria-hidden=\\\"true\\\"></i>\\n            </a>\\n          </div>\\n        </div>\\n        <div class=\\\"ab-hero-kpis\\\" aria-label=\\\"Programme key figures\\\">\\n          <?php about_kpi(\'fa-map-location-dot\', count($constituencies), \'Constituencies\'); ?>\\n          <?php about_kpi(\'fa-building-columns\', (int)($projectStats[\'total_projects\'] ?? 0), \'Projects\'); ?>\\n          <?php about_kpi(\'fa-house-chimney\', (int)($projectStats[\'total_units\'] ?? 0), \'Units Planned\'); ?>\\n          <?php about_kpi(\'fa-calendar-days\', CmsLoader::text($hero, \'launch_year\', \'2024\'), CmsLoader::text($hero, \'launch_label\', \'Programme Launch\')); ?>\\n        </div>\\n      </div>\\n    </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($aboutPage, \'programme_overview\')): ?>\\n    <section class=\\\"ab-overview fade-up\\\" aria-label=\\\"Programme overview\\\">\\n      <div class=\\\"container\\\">\\n        <div class=\\\"ab-overview-inner\\\">\\n          <div class=\\\"ab-overview-copy\\\">\\n            <div class=\\\"ab-section-eyebrow\\\"><?= Security::e(CmsLoader::text($overview, \'eyebrow\', \'Programme Overview\')) ?></div>\\n            <h2 class=\\\"ab-section-title\\\"><?= Security::e(CmsLoader::text($overview, \'title\', \'What Is the Affordable Housing Programme?\')) ?></h2>\\n            <p class=\\\"ab-overview-lead\\\"><?= Security::e(CmsLoader::text($overview, \'lead\', about_defaults(\'programme_overview\')[\'lead\'])) ?></p>\\n            <?php about_paragraph($overview, \'body_1\'); ?>\\n            <?php about_paragraph($overview, \'body_2\'); ?>\\n            <a href=\\\"<?= Security::e(CmsLoader::text($overview, \'link_url\', \'projects.php\')) ?>\\\" class=\\\"ab-text-link\\\">\\n              <?= Security::e(CmsLoader::text($overview, \'link_label\', \'Explore all active projects\')) ?> <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i>\\n            </a>\\n          </div>\\n          <div class=\\\"ab-snapshot\\\">\\n            <div class=\\\"ab-snapshot-header\\\">\\n              <i class=\\\"fa-solid fa-chart-pie\\\" aria-hidden=\\\"true\\\"></i>\\n              <?= Security::e(CmsLoader::text($overview, \'snapshot_title\', \'Programme at a Glance\')) ?>\\n            </div>\\n            <ul class=\\\"ab-snapshot-list\\\">\\n              <?php foreach (about_series($overview, \'glance\', 6, [\'label\', \'value\', \'url\']) as $row): ?>\\n                <?php if (($row[\'label\'] ?? \'\') !== \'\' || ($row[\'value\'] ?? \'\') !== \'\'): ?>\\n              <li>\\n                <span class=\\\"ab-snap-label\\\"><?= Security::e($row[\'label\'] ?? \'\') ?></span>\\n                <span class=\\\"ab-snap-value\\\">\\n                  <?php if (!empty($row[\'url\'])): ?>\\n                    <a href=\\\"<?= Security::e($row[\'url\']) ?>\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\"><?= Security::e($row[\'value\'] ?? \'\') ?> <i class=\\\"fa-solid fa-arrow-up-right-from-square\\\" style=\\\"font-size:9px\\\"></i></a>\\n                  <?php else: ?>\\n                    <?= Security::e($row[\'value\'] ?? \'\') ?>\\n                  <?php endif; ?>\\n                </span>\\n              </li>\\n                <?php endif; ?>\\n              <?php endforeach; ?>\\n            </ul>\\n          </div>\\n        </div>\\n      </div>\\n    </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($aboutPage, \'core_commitments\')): ?>\\n    <section class=\\\"ab-pillars fade-up\\\" aria-label=\\\"Programme pillars\\\">\\n      <div class=\\\"container\\\">\\n        <div class=\\\"ab-pillars-header\\\">\\n          <div class=\\\"ab-section-eyebrow ab-section-eyebrow--light\\\"><?= Security::e(CmsLoader::text($pillars, \'eyebrow\', \'Our Pillars\')) ?></div>\\n          <h2 class=\\\"ab-section-title ab-section-title--light\\\"><?= Security::e(CmsLoader::text($pillars, \'title\', \'Built on Four Core Commitments\')) ?></h2>\\n          <p class=\\\"ab-section-sub ab-section-sub--light\\\"><?= Security::e(CmsLoader::text($pillars, \'subtitle\', \'Every decision, project and process is guided by four foundational principles.\')) ?></p>\\n        </div>\\n        <div class=\\\"ab-pillars-grid\\\">\\n          <?php foreach (about_series($pillars, \'pillar\', 4, [\'icon\', \'title\', \'body\']) as $pillar): ?>\\n            <?php if (($pillar[\'title\'] ?? \'\') !== \'\'): ?>\\n          <div class=\\\"ab-pillar-card\\\">\\n            <div class=\\\"ab-pillar-icon-wrap\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid <?= Security::e(about_icon($pillar[\'icon\'] ?? \'fa-circle-check\')) ?>\\\"></i></div>\\n            <h3 class=\\\"ab-pillar-title\\\"><?= Security::e($pillar[\'title\']) ?></h3>\\n            <p class=\\\"ab-pillar-desc\\\"><?= Security::e($pillar[\'body\'] ?? \'\') ?></p>\\n          </div>\\n            <?php endif; ?>\\n          <?php endforeach; ?>\\n        </div>\\n      </div>\\n    </section>\\n\\n    <div class=\\\"ab-stats-strip\\\" aria-label=\\\"Programme statistics\\\">\\n      <div class=\\\"container\\\">\\n        <div class=\\\"ab-stats-inner\\\">\\n          <?php about_stat((string)count($constituencies), \'Constituencies\'); ?>\\n          <div class=\\\"ab-stat-divider\\\" aria-hidden=\\\"true\\\"></div>\\n          <?php about_stat((string)(int)($projectStats[\'total_projects\'] ?? 0), \'Projects\'); ?>\\n          <div class=\\\"ab-stat-divider\\\" aria-hidden=\\\"true\\\"></div>\\n          <?php about_stat((string)(int)($projectStats[\'total_units\'] ?? 0), \'Units Planned\'); ?>\\n          <div class=\\\"ab-stat-divider\\\" aria-hidden=\\\"true\\\"></div>\\n          <?php about_stat(CmsLoader::text($pillars, \'families_target\', \'8650\'), \'Families to Benefit\'); ?>\\n          <div class=\\\"ab-stat-divider\\\" aria-hidden=\\\"true\\\"></div>\\n          <?php about_stat(CmsLoader::text($hero, \'launch_year\', \'2024\'), \'Year Launched\', true); ?>\\n        </div>\\n      </div>\\n    </div>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($aboutPage, \'programme_history\')): ?>\\n    <section class=\\\"ab-timeline fade-up\\\" aria-label=\\\"Programme timeline\\\">\\n      <div class=\\\"container\\\">\\n        <div class=\\\"ab-timeline-header\\\">\\n          <div class=\\\"ab-section-eyebrow ab-section-eyebrow--light\\\"><?= Security::e(CmsLoader::text($history, \'eyebrow\', \'Programme History\')) ?></div>\\n          <h2 class=\\\"ab-section-title ab-section-title--light\\\"><?= Security::e(CmsLoader::text($history, \'title\', \'From Announcement to Active Construction\')) ?></h2>\\n          <p class=\\\"ab-section-sub ab-section-sub--light\\\"><?= Security::e(CmsLoader::text($history, \'subtitle\', \'A chronological record of how affordable housing came to life in Trans-Nzoia County.\')) ?></p>\\n        </div>\\n        <ol class=\\\"ab-tl-track\\\">\\n          <?php foreach (about_series($history, \'item\', 6, [\'period\', \'icon\', \'title\', \'body\', \'status\']) as $item): ?>\\n            <?php if (($item[\'title\'] ?? \'\') !== \'\'): ?>\\n          <li class=\\\"ab-tl-item <?= Security::e(about_timeline_class($item[\'status\'] ?? \'\')) ?>\\\">\\n            <span class=\\\"ab-tl-year\\\"><?= Security::e($item[\'period\'] ?? \'\') ?></span>\\n            <div class=\\\"ab-tl-node\\\" aria-hidden=\\\"true\\\">\\n              <div class=\\\"ab-tl-dot\\\"><i class=\\\"fa-solid <?= Security::e(about_icon($item[\'icon\'] ?? \'fa-circle\')) ?>\\\"></i></div>\\n              <div class=\\\"ab-tl-connector\\\"></div>\\n            </div>\\n            <div class=\\\"ab-tl-content\\\">\\n              <h3 class=\\\"ab-tl-title\\\"><?= Security::e($item[\'title\']) ?></h3>\\n              <p class=\\\"ab-tl-desc\\\"><?= Security::e($item[\'body\'] ?? \'\') ?></p>\\n              <span class=\\\"ab-tl-badge <?= Security::e(about_timeline_badge_class($item[\'status\'] ?? \'\')) ?>\\\"><i class=\\\"fa-solid <?= Security::e(about_timeline_icon($item[\'status\'] ?? \'\')) ?>\\\" aria-hidden=\\\"true\\\"></i> <?= Security::e($item[\'status\'] ?: \'Upcoming\') ?></span>\\n            </div>\\n          </li>\\n            <?php endif; ?>\\n          <?php endforeach; ?>\\n        </ol>\\n      </div>\\n    </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($aboutPage, \'legal_framework\')): ?>\\n    <section class=\\\"ab-legal fade-up\\\" aria-label=\\\"Legal and regulatory framework\\\">\\n      <div class=\\\"container\\\">\\n        <div class=\\\"ab-legal-header\\\">\\n          <div class=\\\"ab-section-eyebrow\\\"><?= Security::e(CmsLoader::text($legal, \'eyebrow\', \'Legal Framework\')) ?></div>\\n          <h2 class=\\\"ab-section-title\\\"><?= Security::e(CmsLoader::text($legal, \'title\', \'Backed by Law & Policy\')) ?></h2>\\n          <p class=\\\"ab-section-sub\\\"><?= Security::e(CmsLoader::text($legal, \'subtitle\', \'A robust legal and regulatory framework ensures compliance, accountability and environmental responsibility across every project site.\')) ?></p>\\n        </div>\\n        <div class=\\\"ab-legal-grid\\\">\\n          <?php foreach (about_series($legal, \'card\', 6, [\'icon\', \'title\', \'body\', \'link_label\', \'url\']) as $card): ?>\\n            <?php if (($card[\'title\'] ?? \'\') !== \'\'): ?>\\n          <div class=\\\"ab-legal-card\\\">\\n            <div class=\\\"ab-legal-icon\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid <?= Security::e(about_icon($card[\'icon\'] ?? \'fa-book\')) ?>\\\"></i></div>\\n            <h3 class=\\\"ab-legal-title\\\"><?= Security::e($card[\'title\']) ?></h3>\\n            <p class=\\\"ab-legal-desc\\\"><?= Security::e($card[\'body\'] ?? \'\') ?></p>\\n            <?php if (!empty($card[\'url\'])): ?>\\n            <a href=\\\"<?= Security::e($card[\'url\']) ?>\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-legal-link\\\"><?= Security::e($card[\'link_label\'] ?: \'Read more\') ?> <i class=\\\"fa-solid fa-arrow-up-right-from-square\\\" aria-hidden=\\\"true\\\"></i></a>\\n            <?php endif; ?>\\n          </div>\\n            <?php endif; ?>\\n          <?php endforeach; ?>\\n        </div>\\n      </div>\\n    </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($aboutPage, \'partners_teaser\')): ?>\\n    <section class=\\\"ab-partners fade-up\\\" aria-label=\\\"Implementing partners\\\">\\n      <div class=\\\"container\\\">\\n        <div class=\\\"ab-partners-header\\\">\\n          <div class=\\\"ab-section-eyebrow ab-section-eyebrow--light\\\"><?= Security::e(CmsLoader::text($partners, \'eyebrow\', \'Partners\')) ?></div>\\n          <h2 class=\\\"ab-section-title ab-section-title--light\\\"><?= Security::e(CmsLoader::text($partners, \'title\', \'Implementing Partners & Stakeholders\')) ?></h2>\\n          <p class=\\\"ab-section-sub ab-section-sub--light\\\"><?= Security::e(CmsLoader::text($partners, \'subtitle\', \'Delivered through collaboration between national and county government agencies, financial institutions and regulatory bodies.\')) ?></p>\\n        </div>\\n        <div class=\\\"ab-partners-grid\\\">\\n          <?php foreach (about_partner_rows((int)($partners[\'display_count\'] ?? 5)) as $partner): ?>\\n          <div class=\\\"ab-partner-card\\\">\\n            <div class=\\\"ab-partner-icon\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid <?= Security::e(about_icon($partner[\'icon\'] ?? \'fa-handshake\')) ?>\\\"></i></div>\\n            <h3 class=\\\"ab-partner-name\\\"><?= Security::e($partner[\'name\']) ?></h3>\\n            <p class=\\\"ab-partner-role\\\"><?= Security::e($partner[\'description\']) ?></p>\\n          </div>\\n          <?php endforeach; ?>\\n        </div>\\n      </div>\\n    </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($aboutPage, \'faq_teaser\')): ?>\\n    <section class=\\\"ab-faq fade-up\\\" aria-label=\\\"Frequently asked questions\\\">\\n      <div class=\\\"container\\\">\\n        <div class=\\\"ab-faq-wrap\\\">\\n          <div class=\\\"ab-faq-header\\\">\\n            <div class=\\\"ab-section-eyebrow\\\"><?= Security::e(CmsLoader::text($faqTeaser, \'eyebrow\', \'Common Questions\')) ?></div>\\n            <h2 class=\\\"ab-section-title\\\"><?= Security::e(CmsLoader::text($faqTeaser, \'title\', \'Frequently Asked Questions\')) ?></h2>\\n            <p class=\\\"ab-section-sub\\\"><?= Security::e(CmsLoader::text($faqTeaser, \'subtitle\', \'Quick answers to the most common questions about the programme.\')) ?></p>\\n          </div>\\n          <div class=\\\"ab-faq-list\\\">\\n            <?php foreach (about_faq_rows((int)($faqTeaser[\'display_count\'] ?? 4)) as $index => $faq): ?>\\n            <div class=\\\"ab-faq-item\\\">\\n              <button class=\\\"ab-faq-trigger\\\" aria-expanded=\\\"false\\\" aria-controls=\\\"faq-<?= (int)$index + 1 ?>\\\" id=\\\"faq-trigger-<?= (int)$index + 1 ?>\\\">\\n                <span><?= Security::e($faq[\'question\']) ?></span>\\n                <i class=\\\"fa-solid fa-chevron-down ab-faq-chevron\\\" aria-hidden=\\\"true\\\"></i>\\n              </button>\\n              <div class=\\\"ab-faq-body\\\" id=\\\"faq-<?= (int)$index + 1 ?>\\\" role=\\\"region\\\" aria-labelledby=\\\"faq-trigger-<?= (int)$index + 1 ?>\\\">\\n                <p><?= Security::e($faq[\'answer\']) ?></p>\\n              </div>\\n            </div>\\n            <?php endforeach; ?>\\n          </div>\\n          <div class=\\\"ab-faq-footer\\\">\\n            <a href=\\\"<?= Security::e(CmsLoader::text($faqTeaser, \'link_url\', \'faq.php\')) ?>\\\" class=\\\"ab-text-link\\\">\\n              <?= Security::e(CmsLoader::text($faqTeaser, \'link_label\', \'Read all frequently asked questions\')) ?> <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i>\\n            </a>\\n          </div>\\n        </div>\\n      </div>\\n    </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($aboutPage, \'leadership_contact\')): ?>\\n    <section class=\\\"ab-leadership fade-up\\\" aria-label=\\\"Programme leadership and contact\\\">\\n      <div class=\\\"container\\\">\\n        <div class=\\\"ab-leadership-inner\\\">\\n          <div class=\\\"ab-leadership-col\\\">\\n            <div class=\\\"ab-section-eyebrow\\\"><?= Security::e(CmsLoader::text($leadership, \'eyebrow\', \'National Programme Leadership\')) ?></div>\\n            <h2 class=\\\"ab-section-title\\\"><?= Security::e(CmsLoader::text($leadership, \'title\', \'Programme Leadership\')) ?></h2>\\n            <p class=\\\"ab-leadership-sub\\\"><?= Security::e(CmsLoader::text($leadership, \'subtitle\', about_defaults(\'leadership_contact\')[\'subtitle\'])) ?></p>\\n            <div class=\\\"ab-leaders-grid\\\">\\n              <?php foreach (about_leadership_rows() as $leader): ?>\\n              <div class=\\\"ab-leader-card\\\">\\n                <div class=\\\"ab-leader-avatar\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid <?= Security::e(about_icon($leader[\'icon\'] ?? \'fa-user-tie\')) ?>\\\"></i></div>\\n                <div class=\\\"ab-leader-info\\\">\\n                  <span class=\\\"ab-leader-role\\\"><?= Security::e($leader[\'title\']) ?></span>\\n                  <h3 class=\\\"ab-leader-name\\\"><?= Security::e($leader[\'name\']) ?></h3>\\n                  <span class=\\\"ab-leader-dept\\\"><?= Security::e($leader[\'organisation\']) ?></span>\\n                </div>\\n              </div>\\n              <?php endforeach; ?>\\n            </div>\\n            <a href=\\\"<?= Security::e(CmsLoader::text($leadership, \'link_url\', \'leadership.php\')) ?>\\\" class=\\\"ab-text-link\\\" style=\\\"margin-top:var(--space-6);display:inline-flex;align-items:center;gap:var(--space-2)\\\">\\n              <?= Security::e(CmsLoader::text($leadership, \'link_label\', \'Meet the full leadership team\')) ?> <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i>\\n            </a>\\n          </div>\\n          <div class=\\\"ab-contact-col\\\">\\n            <div class=\\\"ab-contact-card\\\">\\n              <div class=\\\"ab-contact-header\\\">\\n                <div class=\\\"ab-contact-header-icon\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid fa-envelope-open-text\\\"></i></div>\\n                <h3><?= Security::e(CmsLoader::text($leadership, \'contact_title\', \'Get In Touch\')) ?></h3>\\n                <p><?= Security::e(CmsLoader::text($leadership, \'contact_intro\', \'Have a question about the programme or your application? Reach the housing department directly.\')) ?></p>\\n              </div>\\n              <ul class=\\\"ab-contact-list\\\">\\n                <?php about_contact_item(\'fa-location-dot\', \'Physical Address\', (string)(CmsLoader::setting(\'contact_address\') ?? \'Trans-Nzoia County Government Offices, Kitale\')); ?>\\n                <?php about_contact_item(\'fa-phone\', \'Phone\', (string)(CmsLoader::setting(\'contact_phone\') ?? \'+254 53 000 0000\'), \'tel:\'); ?>\\n                <?php about_contact_item(\'fa-envelope\', \'Email\', (string)(CmsLoader::setting(\'contact_email\') ?? \'housing@transnzoia.go.ke\'), \'mailto:\'); ?>\\n                <?php about_contact_item(\'fa-clock\', \'Office Hours\', CmsLoader::text($leadership, \'office_hours\', \'Monday - Friday, 8:00 AM - 5:00 PM\')); ?>\\n              </ul>\\n              <a href=\\\"<?= Security::e(CmsLoader::text($leadership, \'contact_button_url\', \'contact.php\')) ?>\\\" class=\\\"ab-contact-cta\\\">\\n                <?= Security::e(CmsLoader::text($leadership, \'contact_button_label\', \'Send a Message\')) ?> <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i>\\n              </a>\\n            </div>\\n          </div>\\n        </div>\\n      </div>\\n    </section>\\n<?php endif; ?>\\n\\n</main>\\n\\n<?php if (CmsLoader::visible($aboutPage, \'apply_cta\')): ?>\\n  <div class=\\\"ab-apply-banner\\\" role=\\\"complementary\\\" aria-label=\\\"Apply for affordable housing\\\">\\n    <div class=\\\"container\\\">\\n      <div class=\\\"ab-apply-inner\\\">\\n        <div class=\\\"ab-apply-icon\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid fa-house-circle-check\\\"></i></div>\\n        <div class=\\\"ab-apply-copy\\\">\\n          <h3 class=\\\"ab-apply-title\\\"><?= Security::e(CmsLoader::text($applyCta, \'title\', \'Ready to Apply for Affordable Housing in Trans-Nzoia?\')) ?></h3>\\n          <p class=\\\"ab-apply-sub\\\"><?= Security::e(CmsLoader::text($applyCta, \'subtitle\', \'Register on the national Boma Yangu portal, save your monthly deposit and select Trans-Nzoia as your allocation preference to join the housing ballot.\')) ?></p>\\n        </div>\\n        <div class=\\\"ab-apply-ctas\\\">\\n          <a href=\\\"<?= Security::e(CmsLoader::text($applyCta, \'primary_url\', \'https://bomayangu.go.ke\')) ?>\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-btn-lime\\\">\\n            <i class=\\\"fa-solid fa-arrow-up-right-from-square\\\" aria-hidden=\\\"true\\\"></i> <?= Security::e(CmsLoader::text($applyCta, \'primary_label\', \'Apply on Boma Yangu\')) ?>\\n          </a>\\n          <a href=\\\"<?= Security::e(CmsLoader::text($applyCta, \'secondary_url\', \'projects.php\')) ?>\\\" class=\\\"ab-btn-outline-dark\\\">\\n            <?= Security::e(CmsLoader::text($applyCta, \'secondary_label\', \'View All Projects\')) ?> <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i>\\n          </a>\\n        </div>\\n      </div>\\n    </div>\\n  </div>\\n<?php endif; ?>\\n\\n<?php include __DIR__ . \'/app/partials/footer.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/back-to-top.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/mobile-menu.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/scripts.php\'; ?>\\n</body>\\n</html>\\n\\n<?php\\nfunction about_defaults(string $section): array\\n{\\n    $defaults = [\\n        \'about_hero\' => [\\n            \'background_image\' => \'uploads/gallery/maili-tatu-2.jpg\',\\n            \'background_alt\' => \'Affordable housing construction works in Trans-Nzoia County\',\\n            \'eyebrow\' => \'National Affordable Housing Programme - Trans-Nzoia County\',\\n            \'title\' => \'Delivering Affordable Homes for Trans-Nzoia County Residents\',\\n            \'subtitle\' => \'A government-led initiative to provide quality, subsidised housing to low-to-middle-income earners across all five constituencies - tracked transparently for every resident.\',\\n            \'primary_label\' => \'View All Projects\',\\n            \'primary_url\' => \'projects.php\',\\n            \'secondary_label\' => \'Apply on Boma Yangu\',\\n            \'secondary_url\' => \'https://bomayangu.go.ke\',\\n            \'launch_year\' => \'2024\',\\n            \'launch_label\' => \'Programme Launch\',\\n        ],\\n        \'programme_overview\' => [\\n            \'lead\' => \\\"The National Affordable Housing Programme (AHP) is a flagship initiative of the Kenya Kwanza Administration, aimed at bridging the nation\'s housing deficit by delivering quality, affordable units to low-to-middle-income earners.\\\",\\n            \'body_1\' => \'In Trans-Nzoia County, the programme is implemented jointly by the State Department of Housing & Urban Development and the Trans-Nzoia County Government - Department of Land, Housing & Physical Planning. Projects span all five constituencies.\',\\n            \'body_2\' => \'Units are allocated exclusively through the Boma Yangu Portal, using a transparent ballot to ensure equitable access for all registered applicants across Trans-Nzoia County.\',\\n        ],\\n        \'core_commitments\' => [],\\n        \'programme_history\' => [],\\n        \'legal_framework\' => [],\\n        \'partners_teaser\' => [],\\n        \'faq_teaser\' => [],\\n        \'leadership_contact\' => [\\n            \'subtitle\' => \'This is a national government initiative delivered through the State Department of Housing & Urban Development. The Trans-Nzoia field office coordinates local programme delivery and public support.\',\\n        ],\\n        \'apply_cta\' => [],\\n    ];\\n\\n    return $defaults[$section] ?? [];\\n}\\n\\nfunction about_kpi(string $icon, string|int|float $value, string $label): void\\n{\\n    ?>\\n    <div class=\\\"ab-kpi\\\">\\n      <i class=\\\"fa-solid <?= Security::e($icon) ?> ab-kpi-icon\\\" aria-hidden=\\\"true\\\"></i>\\n      <span class=\\\"ab-kpi-val\\\"><?= Security::e(is_numeric($value) ? format_number($value) : (string)$value) ?></span>\\n      <span class=\\\"ab-kpi-lbl\\\"><?= Security::e($label) ?></span>\\n    </div>\\n    <?php\\n}\\n\\nfunction about_stat(string $value, string $label, bool $static = false): void\\n{\\n    $numeric = preg_replace(\'/[^0-9.]/\', \'\', $value);\\n    ?>\\n    <div class=\\\"ab-stat-item\\\">\\n      <span class=\\\"ab-stat-val<?= $static ? \' ab-stat-static\' : \'\' ?>\\\"<?= !$static && $numeric !== \'\' ? \' data-target=\\\"\' . Security::e($numeric) . \'\\\"\' : \'\' ?>><?= Security::e($static ? $value : \'0\') ?></span>\\n      <span class=\\\"ab-stat-lbl\\\"><?= Security::e($label) ?></span>\\n    </div>\\n    <?php\\n}\\n\\nfunction about_paragraph(array $content, string $key): void\\n{\\n    $text = trim((string)($content[$key] ?? \'\'));\\n    if ($text === \'\') {\\n        return;\\n    }\\n    echo \'<p class=\\\"ab-overview-body\\\">\' . Security::e($text) . \'</p>\';\\n}\\n\\nfunction about_series(array $content, string $prefix, int $count, array $keys): array\\n{\\n    $rows = [];\\n    for ($i = 1; $i <= $count; $i++) {\\n        $row = [];\\n        foreach ($keys as $key) {\\n            $row[$key] = trim((string)($content[$prefix . \'_\' . $i . \'_\' . $key] ?? \'\'));\\n        }\\n        $rows[] = $row;\\n    }\\n\\n    return $rows;\\n}\\n\\nfunction about_icon(string $icon): string\\n{\\n    $icon = trim($icon);\\n    if ($icon === \'\') {\\n        return \'fa-circle-check\';\\n    }\\n    return preg_match(\'/^fa-[a-z0-9-]+$/\', $icon) ? $icon : \'fa-circle-check\';\\n}\\n\\nfunction about_timeline_class(string $status): string\\n{\\n    $status = strtolower($status);\\n    if (str_contains($status, \'progress\')) {\\n        return \'ab-tl-current\';\\n    }\\n    if (str_contains($status, \'complete\') || str_contains($status, \'done\')) {\\n        return \'ab-tl-done\';\\n    }\\n    return \'\';\\n}\\n\\nfunction about_timeline_badge_class(string $status): string\\n{\\n    $status = strtolower($status);\\n    if (str_contains($status, \'progress\')) {\\n        return \'ab-tl-badge--current\';\\n    }\\n    if (str_contains($status, \'complete\') || str_contains($status, \'done\')) {\\n        return \'ab-tl-badge--done\';\\n    }\\n    return \'\';\\n}\\n\\nfunction about_timeline_icon(string $status): string\\n{\\n    $status = strtolower($status);\\n    if (str_contains($status, \'progress\')) {\\n        return \'fa-rotate\';\\n    }\\n    if (str_contains($status, \'complete\') || str_contains($status, \'done\')) {\\n        return \'fa-check\';\\n    }\\n    return \'fa-clock\';\\n}\\n\\nfunction about_partner_rows(int $limit): array\\n{\\n    try {\\n        $rows = Database::fetchAll(\\n            \'SELECT organisation, role, description, category\\n             FROM stakeholders\\n             WHERE is_visible = 1\\n             ORDER BY sort_order ASC, id ASC\\n             LIMIT \' . max(1, $limit)\\n        );\\n    } catch (Throwable $e) {\\n        $rows = [];\\n    }\\n\\n    if ($rows) {\\n        return array_map(static function (array $row): array {\\n            return [\\n                \'icon\' => match (strtolower((string)($row[\'category\'] ?? \'\'))) {\\n                    \'government\' => \'fa-building-columns\',\\n                    \'finance\', \'financial\' => \'fa-hand-holding-dollar\',\\n                    \'regulator\', \'regulatory\' => \'fa-helmet-safety\',\\n                    default => \'fa-handshake\',\\n                },\\n                \'name\' => (string)($row[\'organisation\'] ?? \'\'),\\n                \'description\' => (string)($row[\'description\'] ?: ($row[\'role\'] ?? \'Programme partner\')),\\n            ];\\n        }, $rows);\\n    }\\n\\n    return [\\n        [\'icon\' => \'fa-building-columns\', \'name\' => \'State Dept. of Housing\', \'description\' => \'Lead implementing agency for project oversight, contractor management and national housing policy direction.\'],\\n        [\'icon\' => \'fa-landmark-flag\', \'name\' => \'Trans-Nzoia County Government\', \'description\' => \'Land allocation, community engagement, site coordination and county-level programme support.\'],\\n        [\'icon\' => \'fa-hand-holding-dollar\', \'name\' => \'Kenya Mortgage Refinance Company\', \'description\' => \'Long-term mortgage financing that supports affordable repayments for eligible beneficiaries.\'],\\n        [\'icon\' => \'fa-house-circle-check\', \'name\' => \'Boma Yangu Portal\', \'description\' => \'National beneficiary registration, savings tracking and transparent unit allocation ballot.\'],\\n        [\'icon\' => \'fa-helmet-safety\', \'name\' => \'National Construction Authority\', \'description\' => \'Contractor registration, site inspection compliance and occupational safety oversight.\'],\\n    ];\\n}\\n\\nfunction about_faq_rows(int $limit): array\\n{\\n    try {\\n        $rows = Database::fetchAll(\\n            \'SELECT question, answer\\n             FROM faq_items\\n             WHERE is_visible = 1\\n             ORDER BY sort_order ASC, id ASC\\n             LIMIT \' . max(1, $limit)\\n        );\\n    } catch (Throwable $e) {\\n        $rows = [];\\n    }\\n\\n    return $rows ?: [\\n        [\'question\' => \'What is the Affordable Housing Programme?\', \'answer\' => \'The Affordable Housing Programme is a government initiative to deliver subsidised homes for low-to-middle-income earners.\'],\\n        [\'question\' => \'Who qualifies to apply for a unit?\', \'answer\' => \'Eligible Kenyan citizens can apply through the Boma Yangu portal and follow the national allocation process.\'],\\n        [\'question\' => \'How are units allocated?\', \'answer\' => \'Units are allocated through the official Boma Yangu process using transparent eligibility and ballot controls.\'],\\n        [\'question\' => \'Where can I apply?\', \'answer\' => \'Applications are submitted through the national Boma Yangu portal.\'],\\n    ];\\n}\\n\\nfunction about_leadership_rows(): array\\n{\\n    try {\\n        $rows = Database::fetchAll(\\n            \'SELECT name, title, organisation\\n             FROM leadership_profiles\\n             WHERE is_visible = 1\\n             ORDER BY sort_order ASC, id ASC\\n             LIMIT 2\'\\n        );\\n    } catch (Throwable $e) {\\n        $rows = [];\\n    }\\n\\n    if ($rows) {\\n        return array_map(static fn (array $row): array => [\\n            \'icon\' => \'fa-user-tie\',\\n            \'name\' => (string)($row[\'name\'] ?? \'\'),\\n            \'title\' => (string)($row[\'title\'] ?? \'Programme Leadership\'),\\n            \'organisation\' => (string)($row[\'organisation\'] ?? \'\'),\\n        ], $rows);\\n    }\\n\\n    return [\\n        [\'icon\' => \'fa-user-tie\', \'title\' => \'County Director\', \'name\' => \'Moses Owuor\', \'organisation\' => \'State Dept. of Housing & Urban Development - Trans-Nzoia Representative\'],\\n        [\'icon\' => \'fa-building-columns\', \'title\' => \'Lead National Agency\', \'name\' => \'State Dept. of Housing & Urban Development\', \'organisation\' => \'Ministry of Lands, Housing & Urban Development - National Government\'],\\n    ];\\n}\\n\\nfunction about_contact_item(string $icon, string $label, string $value, string $scheme = \'\'): void\\n{\\n    $value = trim($value);\\n    if ($value === \'\') {\\n        return;\\n    }\\n\\n    $href = \'\';\\n    if ($scheme === \'tel:\') {\\n        $href = \'tel:\' . preg_replace(\'/[^0-9+]/\', \'\', $value);\\n    } elseif ($scheme === \'mailto:\') {\\n        $href = \'mailto:\' . $value;\\n    }\\n    ?>\\n    <li>\\n      <div class=\\\"ab-contact-icon\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid <?= Security::e($icon) ?>\\\"></i></div>\\n      <div>\\n        <strong><?= Security::e($label) ?></strong>\\n        <span>\\n          <?php if ($href !== \'\'): ?>\\n            <a href=\\\"<?= Security::e($href) ?>\\\"><?= Security::e($value) ?></a>\\n          <?php else: ?>\\n            <?= nl2br(Security::e($value), false) ?>\\n          <?php endif; ?>\\n        </span>\\n      </div>\\n    </li>\\n    <?php\\n}\\n\",\"note\":\"Snapshot of the current public frontend file. Frontend rendering has not been changed yet.\"}', NULL, '2026-06-24 18:05:14');
INSERT INTO `cms_sections` (`id`, `page_id`, `section_key`, `label`, `section_type`, `sort_order`, `editor_mode`, `is_visible`, `is_locked`, `content_json`, `updated_by`, `updated_at`) VALUES
(357, 3, 'current_frontend_snapshot', 'Projects - Current Frontend Snapshot', 'frontend_snapshot', 1, 'json', 1, 1, '{\"page_slug\":\"projects\",\"page_label\":\"Projects\",\"file_path\":\"projects.php\",\"source_hash\":\"1e80d1ef233bc965ea612d77c0e302efbad806b641ad9f3ae1454c9c05620d93\",\"title\":\"\",\"meta_description\":\"\",\"headings\":[{\"level\":2,\"text\":\"Projects Across Trans-Nzoia\"},{\"level\":2,\"text\":\"Where Work Is Happening\"}],\"links\":[{\"href\":\"index.php\",\"text\":\"Home\"},{\"href\":\"constituencies.php\",\"text\":\"View constituencies\"},{\"href\":\"constituency-detail.php?id=<?= $e(rawurlencode($constituencySlug)) ?>\",\"text\":\"projects units % complete\"},{\"href\":\"project-detail.php?id=<?= $e(rawurlencode((string)($project[\",\"text\":\"\\\" class=\\\"proj-cta\\\" aria-label=\\\"View details for \\\">\"}],\"images\":[{\"src\":\"\",\"alt\":\"\"},{\"src\":\"\",\"alt\":\"\"}],\"forms\":[],\"cms_keys\":[\"projects_hero\",\"projects_filters\",\"projects_listing\"],\"text_content\":\"\'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>> Home All Projects County Coverage Projects Across Trans-Nzoia Browse active and planned housing works by constituency, progress and unit count. 0 ? \' has-projects\' : \'\' ?>\\\"> \\\"> \\\" y=\\\" \\\"> \\\" y=\\\" \\\"> Constituency Snapshot Where Work Is Happening View constituencies \\\" class=\\\"pcv-card\\\"> projects units % complete \\\" placeholder=\\\" \\\" aria-label=\\\"Search projects by name or location\\\"> \\\" type=\\\"button\\\" data-filter-status=\\\"all\\\"> \\\" type=\\\"button\\\" data-filter-status=\\\"active\\\"> \\\" type=\\\"button\\\" data-filter-status=\\\"planning\\\"> \\\" type=\\\"button\\\" data-filter-con=\\\"all\\\"> \\\" type=\\\"button\\\" data-filter-con=\\\" \\\"> \\\" type=\\\"button\\\" data-filter-category=\\\"all\\\"> \\\" type=\\\"button\\\" data-filter-category=\\\" \\\"> > > > > > \\\" data-results-prefix=\\\" \\\" data-project-single=\\\" \\\" data-project-plural=\\\" \\\" data-units-label=\\\" \\\" data-complete-label=\\\" \\\" data-view-label=\\\" \\\" data-pagination-showing=\\\" \\\" data-pagination-of=\\\" \\\"> ms\\\" data-status=\\\" \\\" data-constituency=\\\" \\\" data-category=\\\" \\\" data-name=\\\" \\\" data-units=\\\" \\\" data-pct=\\\" \\\" data-search=\\\" \\\"> \\\"this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\'\\\"]) ?>> \\\" aria-label=\\\"Status: \\\"> % \\\" aria-valuemin=\\\"0\\\" aria-valuemax=\\\"100\\\" aria-label=\\\" % complete\\\"> \\\"> \\\"> \\\" class=\\\"proj-cta\\\" aria-label=\\\"View details for \\\">\",\"raw_source\":\"<?php\\nrequire_once __DIR__ . \'/app/core/bootstrap.php\';\\n\\n$basePath = \'\';\\n$activePage = \'projects\';\\n$cmsPage = CmsLoader::publicPage(\'projects\');\\n\\n$hero = CmsLoader::content($cmsPage, \'projects_hero\', [\\n    \'background_image\' => \'uploads/gallery/maili-tatu-2.jpg\',\\n    \'background_alt\' => \'Affordable housing construction site in Trans-Nzoia County\',\\n    \'eyebrow\' => \'AHP Projects\',\\n    \'title_plain\' => \'Housing Projects\',\\n    \'title_highlight\' => \'Directory\',\\n    \'subtitle\' => \'Track every affordable housing project across Trans-Nzoia County - construction progress, contractor details, timelines and unit counts in real time.\',\\n    \'total_projects_label\' => \'Total Projects\',\\n    \'units_label\' => \'Units Planned\',\\n    \'active_label\' => \'Active\',\\n    \'constituencies_label\' => \'Constituencies\',\\n]);\\n$filters = CmsLoader::content($cmsPage, \'projects_filters\', [\\n    \'search_placeholder\' => \'Search projects...\',\\n    \'status_label\' => \'Status:\',\\n    \'all_label\' => \'All\',\\n    \'active_label\' => \'Active\',\\n    \'planning_label\' => \'Planning\',\\n    \'category_label\' => \'Category:\',\\n    \'constituency_label\' => \'Constituency:\',\\n    \'sort_label\' => \'Sort:\',\\n    \'sort_completion_desc\' => \'Completion high to low\',\\n    \'sort_completion_asc\' => \'Completion low to high\',\\n    \'sort_units_desc\' => \'Most units\',\\n    \'sort_name_asc\' => \'Name A-Z\',\\n    \'reset_label\' => \'Clear filters\',\\n]);\\n$listing = CmsLoader::content($cmsPage, \'projects_listing\', [\\n    \'results_prefix\' => \'Showing\',\\n    \'project_single\' => \'project\',\\n    \'project_plural\' => \'projects\',\\n    \'units_label\' => \'Units\',\\n    \'complete_label\' => \'Complete\',\\n    \'view_label\' => \'View Project\',\\n    \'pagination_showing_label\' => \'Showing\',\\n    \'pagination_of_label\' => \'of\',\\n    \'empty_title\' => \'No projects found\',\\n    \'empty_text\' => \'Try adjusting your filters or search term.\',\\n    \'empty_reset_label\' => \'Clear all filters\',\\n]);\\n\\n$initialFilters = [\\n    \'q\' => Security::cleanString((string)($_GET[\'search\'] ?? $_GET[\'q\'] ?? \'\')),\\n    \'status\' => Security::cleanString((string)($_GET[\'status\'] ?? \'\')),\\n    \'constituency\' => Security::cleanString((string)($_GET[\'constituency\'] ?? \'\')),\\n    \'category\' => Security::cleanString((string)($_GET[\'category\'] ?? \'\')),\\n    \'sort\' => Security::cleanString((string)($_GET[\'sort\'] ?? \'pct-desc\')),\\n];\\nforeach ([\'status\', \'constituency\', \'category\'] as $filterKey) {\\n    if (strtolower($initialFilters[$filterKey]) === \'all\') {\\n        $initialFilters[$filterKey] = \'\';\\n    }\\n}\\n$initialFilters[\'status\'] = in_array($initialFilters[\'status\'], [\'active\', \'planning\', \'completed\', \'on_hold\', \'stalled\'], true)\\n    ? $initialFilters[\'status\']\\n    : \'\';\\n$initialFilters[\'sort\'] = in_array($initialFilters[\'sort\'], [\'pct-desc\', \'pct-asc\', \'units-desc\', \'name-asc\', \'updated-desc\'], true)\\n    ? $initialFilters[\'sort\']\\n    : \'pct-desc\';\\n$hasInitialFilters = $initialFilters[\'q\'] !== \'\'\\n    || $initialFilters[\'status\'] !== \'\'\\n    || $initialFilters[\'constituency\'] !== \'\'\\n    || $initialFilters[\'category\'] !== \'\'\\n    || $initialFilters[\'sort\'] !== \'pct-desc\';\\n\\n$projects = Project::publicListing($initialFilters);\\n$constituencies = Project::publicConstituencies();\\n$categories = Project::publicCategories();\\n$projectStats = Project::publicStats($initialFilters);\\n$coverageConstituencies = class_exists(\'Constituency\') ? Constituency::publicList() : [];\\n$featuredProjects = array_slice($projects, 0, 3);\\n\\n$totalProjects = (int)($projectStats[\'total_projects\'] ?? count($projects));\\n$totalUnits = (int)($projectStats[\'total_units\'] ?? 0);\\n$activeProjects = (int)($projectStats[\'active_projects\'] ?? 0);\\n$coveredConstituencies = (int)($projectStats[\'constituencies\'] ?? 0);\\n$publicPayload = public_page_payload(\'projects\', [\\n    \'projects\' => $projects,\\n    \'constituencies\' => $constituencies,\\n    \'coverage_constituencies\' => $coverageConstituencies,\\n    \'featured_projects\' => $featuredProjects,\\n    \'categories\' => $categories,\\n    \'stats\' => $projectStats,\\n], [\\n    \'title\' => \'All Projects\',\\n    \'description\' => \'Browse affordable housing projects across Trans-Nzoia County.\',\\n]);\\n\\n$pageTitle = $cmsPage[\'seo_title\'] ?? \'All Projects | Trans-Nzoia County Affordable Housing Tracker\';\\n$pageDescription = $cmsPage[\'seo_description\'] ?? \'Browse all affordable housing projects in Trans-Nzoia County with live construction progress, contractor details and unit counts across all 5 constituencies.\';\\n$pageKeywords = $cmsPage[\'seo_keywords\'] ?? \'Trans-Nzoia affordable housing projects, AHP Kenya, Maili Tatu estate, Matunda estate, Saboti housing, Cherangany housing\';\\n$pageAuthor = \'Trans-Nzoia County Government - Department of Land, Housing & Physical Planning\';\\n$pageRobots = \'index, follow\';\\n$themeColor = \'#163300\';\\n$canonicalUrl = $cmsPage[\'canonical_url\'] ?? \'https://housing.transnzoia.go.ke/projects.php\';\\n$pageStyles = [\\n    \'assets/css/global.css\',\\n    \'assets/css/pages/projects.css\',\\n];\\n$pageScripts = [\\n    \'assets/js/global.js\',\\n    \'assets/js/pages/projects.js\',\\n];\\n\\n$e = static fn (mixed $value): string => Security::e($value);\\n$text = static fn (array $content, string $key, string $default = \'\'): string => CmsLoader::text($content, $key, $default);\\n$asset = static function (?string $path): string {\\n    $path = trim((string)$path);\\n    if ($path === \'\') {\\n        return \'\';\\n    }\\n    return preg_match(\'#^https?://#i\', $path) ? $path : $path;\\n};\\n$statusLabel = static function (string $status): string {\\n    return match ($status) {\\n        \'active\' => \'Active\',\\n        \'completed\' => \'Completed\',\\n        \'stalled\' => \'Stalled\',\\n        \'on_hold\' => \'On Hold\',\\n        \'cancelled\' => \'Cancelled\',\\n        default => \'Planning\',\\n    };\\n};\\n$publicStatus = static function (string $status): string {\\n    return $status === \'active\' || $status === \'completed\' ? \'active\' : \'planning\';\\n};\\n$isActiveFilter = static fn (string $current, string $value): string => $current === $value ? \' is-active\' : \'\';\\n$isSelected = static fn (string $current, string $value): string => $current === $value ? \' selected\' : \'\';\\n\\n$headMeta = [\\n    \'<meta property=\\\"og:title\\\" content=\\\"\' . $e($pageTitle) . \'\\\">\',\\n    \'<meta property=\\\"og:description\\\" content=\\\"\' . $e($pageDescription) . \'\\\">\',\\n    \'<meta property=\\\"og:type\\\" content=\\\"website\\\">\',\\n    \'<meta property=\\\"og:url\\\" content=\\\"\' . $e($canonicalUrl) . \'\\\">\',\\n    \'<meta property=\\\"og:image\\\" content=\\\"\' . $e($asset((string)($hero[\'background_image\'] ?? \'uploads/gallery/maili-tatu-2.jpg\'))) . \'\\\">\',\\n    \'<meta property=\\\"og:locale\\\" content=\\\"en_KE\\\">\',\\n    \'<meta property=\\\"og:site_name\\\" content=\\\"Trans-Nzoia AHP Tracker\\\">\',\\n    \'<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\">\',\\n    \'<meta name=\\\"twitter:title\\\" content=\\\"\' . $e($pageTitle) . \'\\\">\',\\n    \'<meta name=\\\"twitter:description\\\" content=\\\"\' . $e($pageDescription) . \'\\\">\',\\n    \'<meta name=\\\"twitter:image\\\" content=\\\"\' . $e($asset((string)($hero[\'background_image\'] ?? \'uploads/gallery/maili-tatu-2.jpg\'))) . \'\\\">\',\\n];\\n\\ninclude __DIR__ . \'/app/partials/head.php\';\\n?>\\n<body>\\n<?php include __DIR__ . \'/app/partials/cursor.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/skip-link.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/navbar.php\'; ?>\\n<main id=\\\"main-content\\\">\\n\\n    <section class=\\\"page-hero page-hero--projects\\\" aria-label=\\\"Projects directory\\\">\\n      <div class=\\\"page-hero-bg\\\" aria-hidden=\\\"true\\\">\\n        <?php $heroImage = $asset((string)($hero[\'background_image\'] ?? \'uploads/gallery/maili-tatu-2.jpg\')); ?>\\n        <?php if ($heroImage !== \'\'): ?>\\n          <img <?= public_image_attrs($heroImage, $text($hero, \'background_alt\', \'\'), [\'loading\' => \'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>>\\n        <?php endif; ?>\\n        <div class=\\\"page-hero-overlay\\\"></div>\\n      </div>\\n      <div class=\\\"container\\\">\\n        <nav class=\\\"breadcrumb\\\" aria-label=\\\"Breadcrumb\\\">\\n          <a href=\\\"index.php\\\" class=\\\"breadcrumb-link\\\">Home</a>\\n          <i class=\\\"fa-solid fa-chevron-right breadcrumb-sep\\\" aria-hidden=\\\"true\\\"></i>\\n          <span class=\\\"breadcrumb-current\\\">All Projects</span>\\n        </nav>\\n        <div class=\\\"page-hero-body\\\">\\n          <div class=\\\"page-hero-eyebrow\\\">\\n            <span class=\\\"page-hero-tag\\\"><i class=\\\"fa-solid fa-building-columns\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($hero, \'eyebrow\', \'AHP Projects\')) ?></span>\\n          </div>\\n          <h1 class=\\\"page-hero-title\\\"><?= $e($text($hero, \'title_plain\', \'Housing Projects\')) ?><br><span class=\\\"text-lime\\\"><?= $e($text($hero, \'title_highlight\', \'Directory\')) ?></span></h1>\\n          <p class=\\\"page-hero-sub\\\"><?= $e($text($hero, \'subtitle\', \'Track every affordable housing project across Trans-Nzoia County - construction progress, contractor details, timelines and unit counts in real time.\')) ?></p>\\n        </div>\\n        <div class=\\\"projects-hero-stats\\\" role=\\\"region\\\" aria-label=\\\"Programme statistics\\\">\\n          <div class=\\\"phs-item\\\">\\n            <span class=\\\"phs-val\\\" id=\\\"statTotalProjects\\\"><?= $e(format_number($totalProjects)) ?></span>\\n            <span class=\\\"phs-lbl\\\"><?= $e($text($hero, \'total_projects_label\', \'Total Projects\')) ?></span>\\n          </div>\\n          <div class=\\\"phs-divider\\\" aria-hidden=\\\"true\\\"></div>\\n          <div class=\\\"phs-item\\\">\\n            <span class=\\\"phs-val\\\" id=\\\"statTotalUnits\\\"><?= $e(format_number($totalUnits)) ?></span>\\n            <span class=\\\"phs-lbl\\\"><?= $e($text($hero, \'units_label\', \'Units Planned\')) ?></span>\\n          </div>\\n          <div class=\\\"phs-divider\\\" aria-hidden=\\\"true\\\"></div>\\n          <div class=\\\"phs-item\\\">\\n            <span class=\\\"phs-val\\\" id=\\\"statActiveProjects\\\"><?= $e(format_number($activeProjects)) ?></span>\\n            <span class=\\\"phs-lbl\\\"><?= $e($text($hero, \'active_label\', \'Active\')) ?></span>\\n          </div>\\n          <div class=\\\"phs-divider\\\" aria-hidden=\\\"true\\\"></div>\\n          <div class=\\\"phs-item\\\">\\n            <span class=\\\"phs-val\\\" id=\\\"statConstituencies\\\"><?= $e(format_number($coveredConstituencies)) ?></span>\\n            <span class=\\\"phs-lbl\\\"><?= $e($text($hero, \'constituencies_label\', \'Constituencies\')) ?></span>\\n          </div>\\n        </div>\\n      </div>\\n    </section>\\n\\n    <section class=\\\"projects-coverage-section\\\" aria-label=\\\"Project coverage summary\\\">\\n      <div class=\\\"container\\\">\\n        <div class=\\\"projects-coverage-grid\\\">\\n          <div class=\\\"projects-coverage-map\\\">\\n            <div class=\\\"pcv-section-label\\\">County Coverage</div>\\n            <h2 class=\\\"pcv-title\\\">Projects Across Trans-Nzoia</h2>\\n            <p class=\\\"pcv-subtitle\\\">Browse active and planned housing works by constituency, progress and unit count.</p>\\n            <div class=\\\"pcv-map-wrap\\\" aria-label=\\\"Trans-Nzoia constituencies map\\\">\\n              <svg viewBox=\\\"0 0 480 400\\\" xmlns=\\\"http://www.w3.org/2000/svg\\\" role=\\\"img\\\" aria-label=\\\"Public project coverage map\\\">\\n<?php foreach (Constituency::mapShapes() as $slug => $shape): ?>\\n<?php\\n    $coverageItem = null;\\n    foreach ($coverageConstituencies as $candidate) {\\n        if ((string)$candidate[\'slug\'] === $slug) {\\n            $coverageItem = $candidate;\\n            break;\\n        }\\n    }\\n    $coverageName = $coverageItem[\'name\'] ?? ucwords($slug);\\n    $coverageCount = (int)($coverageItem[\'projectCount\'] ?? 0);\\n?>\\n                <g class=\\\"pcv-map-region<?= $coverageCount > 0 ? \' has-projects\' : \'\' ?>\\\">\\n                  <path d=\\\"<?= $e($shape[\'path\']) ?>\\\"></path>\\n                  <text x=\\\"<?= (int)$shape[\'label_x\'] ?>\\\" y=\\\"<?= (int)$shape[\'label_y\'] ?>\\\"><?= $e($coverageName) ?></text>\\n                  <text class=\\\"pcv-map-sub\\\" x=\\\"<?= (int)$shape[\'label_x\'] ?>\\\" y=\\\"<?= (int)$shape[\'sub_y\'] ?>\\\"><?= $e($coverageCount . \' \' . ($coverageCount === 1 ? \'project\' : \'projects\')) ?></text>\\n                </g>\\n<?php endforeach; ?>\\n              </svg>\\n            </div>\\n          </div>\\n          <div class=\\\"projects-coverage-list\\\">\\n            <div class=\\\"pcv-list-head\\\">\\n              <div>\\n                <div class=\\\"pcv-section-label\\\">Constituency Snapshot</div>\\n                <h2 class=\\\"pcv-title\\\">Where Work Is Happening</h2>\\n              </div>\\n              <a href=\\\"constituencies.php\\\" class=\\\"pcv-link\\\">View constituencies <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i></a>\\n            </div>\\n            <div class=\\\"pcv-constituency-cards\\\">\\n<?php foreach ($coverageConstituencies as $item): ?>\\n              <?php $constituencySlug = (string)$item[\'slug\']; ?>\\n              <a href=\\\"constituency-detail.php?id=<?= $e(rawurlencode($constituencySlug)) ?>\\\" class=\\\"pcv-card\\\">\\n                <div>\\n                  <h3><?= $e($item[\'name\']) ?></h3>\\n                  <p><?= $e(implode(\' / \', array_slice($item[\'wards\'], 0, 3))) ?></p>\\n                </div>\\n                <div class=\\\"pcv-card-stats\\\">\\n                  <span><strong><?= $e((string)$item[\'projectCount\']) ?></strong> projects</span>\\n                  <span><strong><?= $e(format_number((int)$item[\'totalUnits\'])) ?></strong> units</span>\\n                  <span><strong><?= $e((string)$item[\'avgCompletion\']) ?>%</strong> complete</span>\\n                </div>\\n              </a>\\n<?php endforeach; ?>\\n            </div>\\n          </div>\\n        </div>\\n      </div>\\n    </section>\\n\\n    <section class=\\\"projects-main\\\" aria-label=\\\"Project listings\\\">\\n      <div class=\\\"container\\\">\\n        <div class=\\\"projects-filter-bar\\\" role=\\\"search\\\" aria-label=\\\"Filter projects\\\">\\n          <div class=\\\"pfb-search-wrap\\\">\\n            <i class=\\\"fa-solid fa-magnifying-glass pfb-search-icon\\\" aria-hidden=\\\"true\\\"></i>\\n            <input type=\\\"search\\\" class=\\\"pfb-search-input\\\" id=\\\"projectSearch\\\" value=\\\"<?= $e($initialFilters[\'q\']) ?>\\\" placeholder=\\\"<?= $e($text($filters, \'search_placeholder\', \'Search projects...\')) ?>\\\" aria-label=\\\"Search projects by name or location\\\">\\n          </div>\\n          <div class=\\\"pfb-filters\\\" role=\\\"group\\\" aria-label=\\\"Filter by status\\\">\\n            <span class=\\\"pfb-label\\\"><?= $e($text($filters, \'status_label\', \'Status:\')) ?></span>\\n            <button class=\\\"pfb-chip<?= $initialFilters[\'status\'] === \'\' ? \' is-active\' : \'\' ?>\\\" type=\\\"button\\\" data-filter-status=\\\"all\\\"><?= $e($text($filters, \'all_label\', \'All\')) ?></button>\\n            <button class=\\\"pfb-chip<?= $isActiveFilter($initialFilters[\'status\'], \'active\') ?>\\\" type=\\\"button\\\" data-filter-status=\\\"active\\\">\\n              <span class=\\\"pfb-chip-dot pfb-chip-dot--active\\\" aria-hidden=\\\"true\\\"></span><?= $e($text($filters, \'active_label\', \'Active\')) ?>\\n            </button>\\n            <button class=\\\"pfb-chip<?= $isActiveFilter($initialFilters[\'status\'], \'planning\') ?>\\\" type=\\\"button\\\" data-filter-status=\\\"planning\\\">\\n              <span class=\\\"pfb-chip-dot pfb-chip-dot--planning\\\" aria-hidden=\\\"true\\\"></span><?= $e($text($filters, \'planning_label\', \'Planning\')) ?>\\n            </button>\\n          </div>\\n          <div class=\\\"pfb-filters\\\" role=\\\"group\\\" aria-label=\\\"Filter by constituency\\\">\\n            <span class=\\\"pfb-label\\\"><?= $e($text($filters, \'constituency_label\', \'Constituency:\')) ?></span>\\n            <button class=\\\"pfb-chip<?= $initialFilters[\'constituency\'] === \'\' ? \' is-active\' : \'\' ?>\\\" type=\\\"button\\\" data-filter-con=\\\"all\\\"><?= $e($text($filters, \'all_label\', \'All\')) ?></button>\\n<?php foreach ($constituencies as $constituency): ?>\\n            <button class=\\\"pfb-chip<?= $isActiveFilter($initialFilters[\'constituency\'], (string)$constituency[\'slug\']) ?>\\\" type=\\\"button\\\" data-filter-con=\\\"<?= $e($constituency[\'slug\']) ?>\\\"><?= $e($constituency[\'name\']) ?></button>\\n<?php endforeach; ?>\\n          </div>\\n<?php if ($categories): ?>\\n          <div class=\\\"pfb-filters\\\" role=\\\"group\\\" aria-label=\\\"Filter by project category\\\">\\n            <span class=\\\"pfb-label\\\"><?= $e($text($filters, \'category_label\', \'Category:\')) ?></span>\\n            <button class=\\\"pfb-chip<?= $initialFilters[\'category\'] === \'\' ? \' is-active\' : \'\' ?>\\\" type=\\\"button\\\" data-filter-category=\\\"all\\\"><?= $e($text($filters, \'all_label\', \'All\')) ?></button>\\n<?php foreach ($categories as $category): ?>\\n            <button class=\\\"pfb-chip<?= $isActiveFilter($initialFilters[\'category\'], (string)$category[\'slug\']) ?>\\\" type=\\\"button\\\" data-filter-category=\\\"<?= $e($category[\'slug\']) ?>\\\"><?= $e($category[\'name\']) ?></button>\\n<?php endforeach; ?>\\n          </div>\\n<?php endif; ?>\\n          <div class=\\\"pfb-sort-wrap\\\">\\n            <label for=\\\"projectSort\\\" class=\\\"pfb-label\\\"><?= $e($text($filters, \'sort_label\', \'Sort:\')) ?></label>\\n            <select id=\\\"projectSort\\\" class=\\\"pfb-sort-select\\\" aria-label=\\\"Sort projects\\\">\\n              <option value=\\\"pct-desc\\\"<?= $isSelected($initialFilters[\'sort\'], \'pct-desc\') ?>><?= $e($text($filters, \'sort_completion_desc\', \'Completion high to low\')) ?></option>\\n              <option value=\\\"pct-asc\\\"<?= $isSelected($initialFilters[\'sort\'], \'pct-asc\') ?>><?= $e($text($filters, \'sort_completion_asc\', \'Completion low to high\')) ?></option>\\n              <option value=\\\"units-desc\\\"<?= $isSelected($initialFilters[\'sort\'], \'units-desc\') ?>><?= $e($text($filters, \'sort_units_desc\', \'Most units\')) ?></option>\\n              <option value=\\\"name-asc\\\"<?= $isSelected($initialFilters[\'sort\'], \'name-asc\') ?>><?= $e($text($filters, \'sort_name_asc\', \'Name A-Z\')) ?></option>\\n            </select>\\n          </div>\\n        </div>\\n\\n        <div class=\\\"projects-results-meta\\\" aria-live=\\\"polite\\\" aria-atomic=\\\"true\\\">\\n          <span id=\\\"resultsCount\\\"><?= $e($text($listing, \'results_prefix\', \'Showing\')) ?> <?= $e(format_number($totalProjects)) ?> <?= $e($totalProjects === 1 ? $text($listing, \'project_single\', \'project\') : $text($listing, \'project_plural\', \'projects\')) ?></span>\\n          <button class=\\\"pfb-reset\\\" type=\\\"button\\\" id=\\\"resetFilters\\\"<?= $hasInitialFilters ? \'\' : \' hidden\' ?>>\\n            <i class=\\\"fa-solid fa-xmark\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($filters, \'reset_label\', \'Clear filters\')) ?>\\n          </button>\\n        </div>\\n\\n        <div class=\\\"projects-grid\\\"\\n             id=\\\"projectsGrid\\\"\\n             role=\\\"list\\\"\\n             data-api-url=\\\"<?= $e(public_url(\'api/public/projects.php\')) ?>\\\"\\n             data-results-prefix=\\\"<?= $e($text($listing, \'results_prefix\', \'Showing\')) ?>\\\"\\n             data-project-single=\\\"<?= $e($text($listing, \'project_single\', \'project\')) ?>\\\"\\n             data-project-plural=\\\"<?= $e($text($listing, \'project_plural\', \'projects\')) ?>\\\"\\n             data-units-label=\\\"<?= $e($text($listing, \'units_label\', \'Units\')) ?>\\\"\\n             data-complete-label=\\\"<?= $e($text($listing, \'complete_label\', \'Complete\')) ?>\\\"\\n             data-view-label=\\\"<?= $e($text($listing, \'view_label\', \'View Project\')) ?>\\\"\\n             data-pagination-showing=\\\"<?= $e($text($listing, \'pagination_showing_label\', \'Showing\')) ?>\\\"\\n             data-pagination-of=\\\"<?= $e($text($listing, \'pagination_of_label\', \'of\')) ?>\\\">\\n<?php foreach ($projects as $index => $project): ?>\\n          <?php\\n            $status = (string)($project[\'status\'] ?? \'planning\');\\n            $displayStatus = $publicStatus($status);\\n            $pct = max(0, min(100, (int)($project[\'pct_complete\'] ?? 0)));\\n            $image = $asset((string)($project[\'hero_image\'] ?? \'\'));\\n            $name = (string)($project[\'name\'] ?? \'Project\');\\n            $search = strtolower(trim(implode(\' \', [\\n                $name,\\n                $project[\'constituency_name\'] ?? \'\',\\n                $project[\'ward_name\'] ?? \'\',\\n                $project[\'contractor_name\'] ?? \'\',\\n                $project[\'current_milestone\'] ?? \'\',\\n            ])));\\n          ?>\\n          <article class=\\\"proj-card is-visible\\\"\\n                   role=\\\"listitem\\\"\\n                   style=\\\"animation-delay:<?= (int)($index % 6) * 55 ?>ms\\\"\\n                   data-status=\\\"<?= $e($displayStatus) ?>\\\"\\n                   data-constituency=\\\"<?= $e($project[\'constituency_slug\'] ?? \'\') ?>\\\"\\n                   data-category=\\\"<?= $e($project[\'category_slug\'] ?? \'\') ?>\\\"\\n                   data-name=\\\"<?= $e(strtolower($name)) ?>\\\"\\n                   data-units=\\\"<?= (int)($project[\'units\'] ?? 0) ?>\\\"\\n                   data-pct=\\\"<?= $pct ?>\\\"\\n                   data-search=\\\"<?= $e($search) ?>\\\">\\n            <div class=\\\"proj-card-img\\\">\\n<?php if ($image !== \'\'): ?>\\n              <img <?= public_image_attrs($image, $name, [\'onerror\' => \\\"this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\'\\\"]) ?>>\\n              <div class=\\\"proj-card-img-placeholder\\\" style=\\\"display:none\\\"><i class=\\\"fa-solid fa-building\\\" aria-hidden=\\\"true\\\"></i></div>\\n<?php else: ?>\\n              <div class=\\\"proj-card-img-placeholder\\\"><i class=\\\"fa-solid fa-building\\\" aria-hidden=\\\"true\\\"></i></div>\\n<?php endif; ?>\\n              <span class=\\\"proj-status-badge proj-status-badge--<?= $e($displayStatus) ?>\\\" aria-label=\\\"Status: <?= $e($statusLabel($status)) ?>\\\"><?= $e($statusLabel($status)) ?></span>\\n              <span class=\\\"proj-con-tag\\\"><?= $e($project[\'constituency_name\'] ?? \'\') ?></span>\\n            </div>\\n            <div class=\\\"proj-card-body\\\">\\n              <div class=\\\"proj-card-meta\\\">\\n                <span class=\\\"proj-ward\\\"><?= $e($project[\'ward_name\'] ?? $project[\'location_label\'] ?? \'\') ?></span>\\n              </div>\\n              <h3 class=\\\"proj-card-title\\\"><?= $e($name) ?></h3>\\n              <div class=\\\"proj-card-stats\\\">\\n                <div class=\\\"proj-stat\\\">\\n                  <span class=\\\"proj-stat-val\\\"><?= $e(format_number((int)($project[\'units\'] ?? 0))) ?></span>\\n                  <span class=\\\"proj-stat-lbl\\\"><?= $e($text($listing, \'units_label\', \'Units\')) ?></span>\\n                </div>\\n                <div class=\\\"proj-stat\\\">\\n                  <span class=\\\"proj-stat-val\\\"><?= $pct ?>%</span>\\n                  <span class=\\\"proj-stat-lbl\\\"><?= $e($text($listing, \'complete_label\', \'Complete\')) ?></span>\\n                </div>\\n              </div>\\n              <div class=\\\"proj-progress\\\" role=\\\"progressbar\\\" aria-valuenow=\\\"<?= $pct ?>\\\" aria-valuemin=\\\"0\\\" aria-valuemax=\\\"100\\\" aria-label=\\\"<?= $pct ?>% complete\\\">\\n                <div class=\\\"proj-progress-fill\\\" data-target=\\\"<?= $pct ?>\\\"></div>\\n              </div>\\n              <div class=\\\"proj-milestone\\\">\\n                <i class=\\\"fa-solid fa-hard-hat\\\" aria-hidden=\\\"true\\\"></i>\\n                <span><?= $e($project[\'current_milestone\'] ?? \'Project details pending\') ?></span>\\n              </div>\\n              <div class=\\\"proj-card-footer\\\">\\n                <span class=\\\"proj-contractor\\\" title=\\\"<?= $e($project[\'contractor_name\'] ?? \'\') ?>\\\"><?= $e($project[\'contractor_name\'] ?? \'\') ?></span>\\n                <a href=\\\"project-detail.php?id=<?= $e(rawurlencode((string)($project[\'slug\'] ?? \'\'))) ?>\\\" class=\\\"proj-cta\\\" aria-label=\\\"View details for <?= $e($name) ?>\\\">\\n                  <?= $e($text($listing, \'view_label\', \'View Project\')) ?> <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i>\\n                </a>\\n              </div>\\n            </div>\\n          </article>\\n<?php endforeach; ?>\\n        </div>\\n\\n        <nav class=\\\"projects-pagination\\\" id=\\\"projectsPagination\\\" aria-label=\\\"Project pages\\\" hidden></nav>\\n\\n        <div class=\\\"projects-empty\\\" id=\\\"projectsEmpty\\\" hidden aria-live=\\\"polite\\\">\\n          <div class=\\\"projects-empty-icon\\\" aria-hidden=\\\"true\\\">\\n            <i class=\\\"fa-solid fa-building-circle-xmark\\\"></i>\\n          </div>\\n          <h3><?= $e($text($listing, \'empty_title\', \'No projects found\')) ?></h3>\\n          <p><?= $e($text($listing, \'empty_text\', \'Try adjusting your filters or search term.\')) ?></p>\\n          <button class=\\\"btn btn-primary\\\" type=\\\"button\\\" id=\\\"emptyReset\\\"><?= $e($text($listing, \'empty_reset_label\', \'Clear all filters\')) ?></button>\\n        </div>\\n      </div>\\n    </section>\\n\\n  </main>\\n\\n<?php include __DIR__ . \'/app/partials/footer.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/back-to-top.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/mobile-menu.php\'; ?>\\n<?= public_json_script(\'ahp-page-data\', $publicPayload) ?>\\n<?php include __DIR__ . \'/app/partials/scripts.php\'; ?>\\n</body>\\n</html>\\n\",\"note\":\"Snapshot of the current public frontend file. Frontend rendering has not been changed yet.\"}', NULL, '2026-06-24 18:05:14');
INSERT INTO `cms_sections` (`id`, `page_id`, `section_key`, `label`, `section_type`, `sort_order`, `editor_mode`, `is_visible`, `is_locked`, `content_json`, `updated_by`, `updated_at`) VALUES
(358, 4, 'current_frontend_snapshot', 'Project Detail - Current Frontend Snapshot', 'frontend_snapshot', 1, 'json', 1, 1, '{\"page_slug\":\"project-detail\",\"page_label\":\"Project Detail\",\"file_path\":\"project-detail.php\",\"source_hash\":\"043ddeba617c3a34432e2158455771392e66989b02467645901504decb989e73\",\"title\":\"\",\"meta_description\":\"\",\"headings\":[],\"links\":[{\"href\":\"projects.php\",\"text\":\"\"},{\"href\":\"index.php\",\"text\":\"Home\"},{\"href\":\"projects.php\",\"text\":\"\"},{\"href\":\"<?= $e($text($applyCta,\",\"text\":\"\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"pd-apply-btn\\\">\"},{\"href\":\"constituency-detail.php?id=<?= $e(rawurlencode($constituencySlug)) ?>\",\"text\":\"\"},{\"href\":\"projects.php?constituency=<?= $e(rawurlencode($constituencySlug)) ?>\",\"text\":\"\"},{\"href\":\"projects.php\",\"text\":\"\"},{\"href\":\"project-detail.php?id=<?= $e(rawurlencode((string)$related[\",\"text\":\"\\\" class=\\\"pd-related-project\\\"> /\"}],\"images\":[{\"src\":\"\",\"alt\":\"\"},{\"src\":\"\",\"alt\":\"\"}],\"forms\":[],\"cms_keys\":[\"project_detail_labels\",\"project_detail_overview\",\"project_detail_sidebar\",\"project_detail_apply_cta\",\"project_detail_not_found\"],\"text_content\":\"\'eager\', \'fetchpriority\' => \'high\']) ?>> Home \\\"> \\\" aria-hidden=\\\"true\\\"> % \\\" style=\\\"width:0%\\\"> \\\"> : % \\\" aria-valuemin=\\\"0\\\" aria-valuemax=\\\"100\\\" aria-label=\\\" % construction complete\\\"> \\\"> \\\"> CURRENT \\\" type=\\\"button\\\" data-gallery-index=\\\" \\\" data-gallery-src=\\\" \\\" data-gallery-alt=\\\" \\\" aria-label=\\\"View photo \\\"> $index === 0 ? \'eager\' : \'lazy\', \'fetchpriority\' => $index === 0 ? \'high\' : \'auto\']) ?>> \\\"> \\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"pd-apply-btn\\\"> \\\" class=\\\"pd-related-link\\\"> \\\" class=\\\"pd-related-link\\\"> \\\" class=\\\"pd-related-project\\\"> /\",\"raw_source\":\"<?php\\nrequire_once __DIR__ . \'/app/core/bootstrap.php\';\\n\\n$basePath = \'\';\\n$activePage = \'projects\';\\n$cmsPage = CmsLoader::publicPage(\'project-detail\');\\n$labels = CmsLoader::content($cmsPage, \'project_detail_labels\', []);\\n$overview = CmsLoader::content($cmsPage, \'project_detail_overview\', []);\\n$sidebar = CmsLoader::content($cmsPage, \'project_detail_sidebar\', []);\\n$applyCta = CmsLoader::content($cmsPage, \'project_detail_apply_cta\', []);\\n$notFound = CmsLoader::content($cmsPage, \'project_detail_not_found\', []);\\n$text = static fn (array $content, string $key, string $default = \'\'): string => CmsLoader::text($content, $key, $default);\\n$e = static fn (mixed $value): string => Security::e($value);\\n\\n$lookup = trim((string)($_GET[\'id\'] ?? $_GET[\'slug\'] ?? \'\'));\\n$project = $lookup !== \'\' ? Project::publicDetail($lookup) : null;\\n$isFound = is_array($project);\\n\\nif (!$isFound) {\\n    http_response_code(404);\\n}\\n\\nif (!function_exists(\'pd_asset_url\')) {\\n    function pd_asset_url(?string $path): string\\n    {\\n        $path = trim((string)$path);\\n        if ($path === \'\') {\\n            return \'\';\\n        }\\n        if (preg_match(\'#^(?:[a-z][a-z0-9+.-]*:)?//#i\', $path) || str_starts_with($path, \'data:\')) {\\n            return $path;\\n        }\\n        return Url::asset($path);\\n    }\\n}\\n\\nif (!function_exists(\'pd_images\')) {\\n    function pd_images(array $project): array\\n    {\\n        $images = [];\\n        $hero = trim((string)($project[\'hero_image\'] ?? \'\'));\\n        if ($hero !== \'\') {\\n            $images[] = $hero;\\n        }\\n\\n        $decoded = json_decode((string)($project[\'images_json\'] ?? \'[]\'), true);\\n        if (is_array($decoded)) {\\n            foreach ($decoded as $image) {\\n                $image = trim((string)$image);\\n                if ($image !== \'\') {\\n                    $images[] = $image;\\n                }\\n            }\\n        }\\n\\n        $unique = [];\\n        foreach ($images as $image) {\\n            if (!in_array($image, $unique, true)) {\\n                $unique[] = $image;\\n            }\\n        }\\n\\n        return $unique;\\n    }\\n}\\n\\nif (!function_exists(\'pd_quarter_label\')) {\\n    function pd_quarter_label(?string $date, string $fallback = \'\'): string\\n    {\\n        $date = trim((string)$date);\\n        if ($date === \'\' || $date === \'0000-00-00\') {\\n            return $fallback;\\n        }\\n        $timestamp = strtotime($date);\\n        if (!$timestamp) {\\n            return $date;\\n        }\\n        return \'Q\' . (int)ceil((int)date(\'n\', $timestamp) / 3) . \' \' . date(\'Y\', $timestamp);\\n    }\\n}\\n\\nif (!function_exists(\'pd_date_label\')) {\\n    function pd_date_label(?string $date, string $fallback = \'\'): string\\n    {\\n        $date = trim((string)$date);\\n        if ($date === \'\' || $date === \'0000-00-00\') {\\n            return $fallback;\\n        }\\n        $timestamp = strtotime($date);\\n        return $timestamp ? date(\'j M Y\', $timestamp) : $date;\\n    }\\n}\\n\\nif (!function_exists(\'pd_number\')) {\\n    function pd_number(mixed $value): string\\n    {\\n        return number_format((float)$value, 0);\\n    }\\n}\\n\\nif (!function_exists(\'pd_status_class\')) {\\n    function pd_status_class(string $status): string\\n    {\\n        return match ($status) {\\n            \'active\' => \'active\',\\n            \'completed\' => \'completed\',\\n            \'on_hold\', \'stalled\' => \'watch\',\\n            default => \'planning\',\\n        };\\n    }\\n}\\n\\nif (!function_exists(\'pd_status_label\')) {\\n    function pd_status_label(string $status, array $labels): string\\n    {\\n        return match ($status) {\\n            \'active\' => CmsLoader::text($labels, \'active_status_label\', \'Active\'),\\n            \'completed\' => CmsLoader::text($labels, \'completed_status_label\', \'Completed\'),\\n            \'on_hold\', \'stalled\' => CmsLoader::text($labels, \'watch_status_label\', \'On Hold\'),\\n            default => CmsLoader::text($labels, \'planning_status_label\', \'Planning\'),\\n        };\\n    }\\n}\\n\\nif (!function_exists(\'pd_icon_for_status\')) {\\n    function pd_icon_for_status(string $status): string\\n    {\\n        return match ($status) {\\n            \'active\' => \'fa-circle-dot\',\\n            \'completed\' => \'fa-circle-check\',\\n            \'on_hold\', \'stalled\' => \'fa-triangle-exclamation\',\\n            default => \'fa-clock\',\\n        };\\n    }\\n}\\n\\n$images = $isFound ? pd_images($project) : [];\\n$projectName = $isFound ? (string)($project[\'name\'] ?? \'Project Detail\') : $text($notFound, \'title\', \'Project Not Found\');\\n$projectDescription = $isFound\\n    ? trim((string)($project[\'full_description\'] ?? $project[\'description\'] ?? \'\'))\\n    : $text($notFound, \'text\', \\\"The project you\'re looking for doesn\'t exist or the URL is incorrect.\\\");\\n$pageTitle = $isFound\\n    ? $projectName . \' | Trans-Nzoia County Affordable Housing Tracker\'\\n    : $text($notFound, \'title\', \'Project Not Found\') . \' | Trans-Nzoia County Affordable Housing Tracker\';\\n$pageDescription = $isFound && $projectDescription !== \'\'\\n    ? substr(strip_tags($projectDescription), 0, 160)\\n    : ($cmsPage[\'seo_description\'] ?? \'Detailed construction progress, contractor information, milestones and site photos for an affordable housing project in Trans-Nzoia County.\');\\n$pageKeywords = $cmsPage[\'seo_keywords\'] ?? \'Trans-Nzoia AHP project detail, affordable housing Kenya, construction progress\';\\n$pageAuthor = \'Trans-Nzoia County Government - Department of Land, Housing & Physical Planning\';\\n$pageRobots = $isFound ? \'index, follow\' : \'noindex, follow\';\\n$themeColor = \'#163300\';\\n$canonicalUrl = $isFound\\n    ? \'https://housing.transnzoia.go.ke/project-detail.php?id=\' . rawurlencode((string)($project[\'slug\'] ?? $lookup))\\n    : \'https://housing.transnzoia.go.ke/project-detail.php\';\\n$pageStyles = [\\n    \'assets/css/global.css\',\\n    \'assets/css/pages/project-detail.css\',\\n];\\n$pageScripts = [\\n    \'assets/js/global.js\',\\n    \'assets/js/pages/project-detail.js\',\\n];\\n$milestones = [];\\n$programmeSummary = [];\\n$galleryMedia = [];\\n$relatedProjects = [];\\n$publicPayload = public_page_payload(\'project-detail\', [], [\\n    \'title\' => $projectName,\\n    \'description\' => $pageDescription,\\n]);\\nif ($isFound) {\\n    $milestones = Milestone::publicForProject((int)$project[\'id\']);\\n    $programmeSummary = ProgrammeTask::publicSummaryForProject((int)$project[\'id\']);\\n    $galleryMedia = GalleryImage::publicForProject((int)$project[\'id\'], 48);\\n    foreach ($galleryMedia as $galleryItem) {\\n        $image = (string)($galleryItem[\'full_url\'] ?: $galleryItem[\'url\'] ?? \'\');\\n        if ($image !== \'\' && !in_array($image, $images, true)) {\\n            $images[] = $image;\\n        }\\n    }\\n    $relatedProjects = Project::publicRelated($project, 4);\\n    $publicPayload = public_page_payload(\'project-detail\', [\\n        \'project\' => $project,\\n        \'milestones\' => $milestones,\\n        \'programme\' => $programmeSummary,\\n        \'gallery\' => $galleryMedia,\\n        \'related_projects\' => $relatedProjects,\\n    ], [\\n        \'title\' => $projectName,\\n        \'description\' => $pageDescription,\\n    ]);\\n}\\n$heroImage = $images[0] ?? \'\';\\n$headMeta = [\\n    \'<meta property=\\\"og:title\\\" content=\\\"\' . $e($pageTitle) . \'\\\">\',\\n    \'<meta property=\\\"og:type\\\" content=\\\"website\\\">\',\\n    \'<meta property=\\\"og:locale\\\" content=\\\"en_KE\\\">\',\\n    \'<meta property=\\\"og:site_name\\\" content=\\\"Trans-Nzoia AHP Tracker\\\">\',\\n    \'<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\">\',\\n];\\nif ($heroImage !== \'\') {\\n    $headMeta[] = \'<meta property=\\\"og:image\\\" content=\\\"\' . $e(pd_asset_url($heroImage)) . \'\\\">\';\\n}\\n\\ninclude __DIR__ . \'/app/partials/head.php\';\\n?>\\n<body>\\n<?php include __DIR__ . \'/app/partials/cursor.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/skip-link.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/navbar.php\'; ?>\\n<main id=\\\"main-content\\\">\\n\\n<?php if (!$isFound): ?>\\n  <section class=\\\"pd-not-found\\\" id=\\\"pdNotFound\\\">\\n    <div class=\\\"container\\\">\\n      <div class=\\\"pd-not-found-inner\\\">\\n        <i class=\\\"fa-solid fa-building-circle-xmark pd-not-found-icon\\\" aria-hidden=\\\"true\\\"></i>\\n        <h1><?= $e($text($notFound, \'title\', \'Project Not Found\')) ?></h1>\\n        <p><?= $e($text($notFound, \'text\', \\\"The project you\'re looking for doesn\'t exist or the URL is incorrect.\\\")) ?></p>\\n        <a href=\\\"projects.php\\\" class=\\\"btn btn-primary\\\">\\n          <i class=\\\"fa-solid fa-arrow-left\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($notFound, \'button_label\', \'Back to All Projects\')) ?>\\n        </a>\\n      </div>\\n    </div>\\n  </section>\\n<?php else:\\n    $status = (string)($project[\'status\'] ?? \'planning\');\\n    $statusClass = pd_status_class($status);\\n    $statusLabel = pd_status_label($status, $labels);\\n    $pct = max(0, min(100, (int)($project[\'pct_complete\'] ?? 0)));\\n    $units = (int)($project[\'units\'] ?? 0);\\n    $unitsInProgress = (int)round($units * $pct / 100);\\n    $constituencyName = (string)($project[\'constituency_name\'] ?? \'Trans-Nzoia\');\\n    $constituencySlug = (string)($project[\'constituency_slug\'] ?? \'\');\\n    $wardName = trim((string)($project[\'ward_name\'] ?? $project[\'location_label\'] ?? \'\'));\\n    $location = trim(($wardName !== \'\' ? $wardName . \', \' : \'\') . $constituencyName);\\n    $contractor = trim((string)($project[\'contractor_name\'] ?? \'\'));\\n    $siteEngineer = trim((string)($project[\'site_engineer\'] ?? \'\'));\\n    $leadAgency = trim((string)($project[\'lead_agency\'] ?? \'State Dept. of Housing\'));\\n    $funding = trim((string)($project[\'funding_source\'] ?? \'National AHP Fund\'));\\n    $currentMilestone = trim((string)($project[\'current_milestone\'] ?? \'\'));\\n    $startDate = pd_quarter_label($project[\'start_date\'] ?? null);\\n    $deliveryDate = pd_quarter_label($project[\'est_delivery\'] ?? null);\\n    $detailUrl = \'project-detail.php?id=\' . rawurlencode((string)$project[\'slug\']);\\n?>\\n  <section class=\\\"pd-hero\\\" id=\\\"pdHero\\\" aria-label=\\\"Project overview\\\">\\n    <div class=\\\"pd-hero-bg\\\" id=\\\"pdHeroBg\\\" aria-hidden=\\\"true\\\">\\n<?php if ($heroImage !== \'\'): ?>\\n      <img <?= public_image_attrs($heroImage, \'\', [\'loading\' => \'eager\', \'fetchpriority\' => \'high\']) ?>>\\n<?php endif; ?>\\n      <div class=\\\"pd-hero-overlay\\\"></div>\\n    </div>\\n    <div class=\\\"container\\\">\\n      <nav class=\\\"breadcrumb\\\" aria-label=\\\"Breadcrumb\\\">\\n        <a href=\\\"index.php\\\" class=\\\"breadcrumb-link\\\">Home</a>\\n        <i class=\\\"fa-solid fa-chevron-right breadcrumb-sep\\\" aria-hidden=\\\"true\\\"></i>\\n        <a href=\\\"projects.php\\\" class=\\\"breadcrumb-link\\\"><?= $e($text($labels, \'projects_breadcrumb_label\', \'Projects\')) ?></a>\\n        <i class=\\\"fa-solid fa-chevron-right breadcrumb-sep\\\" aria-hidden=\\\"true\\\"></i>\\n        <span class=\\\"breadcrumb-current\\\"><?= $e($projectName) ?></span>\\n      </nav>\\n\\n      <div class=\\\"pd-hero-content\\\" id=\\\"pdHeroContent\\\">\\n        <div class=\\\"pd-hero-badges\\\">\\n          <span class=\\\"pd-badge pd-badge--<?= $e($statusClass) ?>\\\">\\n            <i class=\\\"fa-solid <?= $e(pd_icon_for_status($status)) ?>\\\" aria-hidden=\\\"true\\\"></i> <?= $e($statusLabel) ?>\\n          </span>\\n          <span class=\\\"pd-badge pd-badge--con\\\">\\n            <i class=\\\"fa-solid fa-map-location-dot\\\" aria-hidden=\\\"true\\\"></i> <?= $e($constituencyName) ?>\\n          </span>\\n<?php if ($startDate !== \'\'): ?>\\n          <span class=\\\"pd-badge pd-badge--date\\\"><i class=\\\"fa-solid fa-calendar-days\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($labels, \'started_label\', \'Started\')) ?> <?= $e($startDate) ?></span>\\n<?php endif; ?>\\n<?php if ($deliveryDate !== \'\'): ?>\\n          <span class=\\\"pd-badge pd-badge--date\\\"><i class=\\\"fa-solid fa-flag-checkered\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($labels, \'delivery_label\', \'Est. Delivery\')) ?> <?= $e($deliveryDate) ?></span>\\n<?php endif; ?>\\n        </div>\\n        <h1 class=\\\"pd-hero-title\\\"><?= $e($projectName) ?></h1>\\n        <div class=\\\"pd-hero-meta\\\">\\n<?php if ($location !== \'\'): ?>\\n          <span class=\\\"pd-hero-meta-item\\\"><i class=\\\"fa-solid fa-map-pin\\\" aria-hidden=\\\"true\\\"></i> <?= $e($location) ?></span>\\n<?php endif; ?>\\n<?php if ($currentMilestone !== \'\'): ?>\\n          <span class=\\\"pd-hero-meta-item\\\"><i class=\\\"fa-solid fa-hard-hat\\\" aria-hidden=\\\"true\\\"></i> <?= $e($currentMilestone) ?></span>\\n<?php endif; ?>\\n<?php if ($contractor !== \'\'): ?>\\n          <span class=\\\"pd-hero-meta-item\\\"><i class=\\\"fa-solid fa-person-digging\\\" aria-hidden=\\\"true\\\"></i> <?= $e($contractor) ?></span>\\n<?php endif; ?>\\n        </div>\\n        <div class=\\\"pd-hero-pct-wrap\\\">\\n          <div class=\\\"pd-hero-pct\\\">\\n            <span class=\\\"pd-hero-pct-num\\\"><?= $e($pct) ?><span class=\\\"pd-hero-pct-sign\\\">%</span></span>\\n            <span class=\\\"pd-hero-pct-lbl\\\"><?= $e($text($labels, \'construction_complete_label\', \'Construction Complete\')) ?></span>\\n          </div>\\n          <div class=\\\"pd-hero-pct-bar\\\" aria-hidden=\\\"true\\\">\\n            <div class=\\\"pd-hero-pct-bar-fill\\\" data-target=\\\"<?= $e($pct) ?>\\\" style=\\\"width:0%\\\"></div>\\n          </div>\\n        </div>\\n      </div>\\n    </div>\\n  </section>\\n\\n  <div class=\\\"pd-body\\\" id=\\\"pdBody\\\">\\n    <div class=\\\"container\\\">\\n      <div class=\\\"pd-body-inner\\\">\\n        <div class=\\\"pd-main\\\" id=\\\"pdMain\\\">\\n          <div class=\\\"pd-facts-strip\\\" id=\\\"pdFactsStrip\\\">\\n<?php\\n    $facts = [\\n        [\'fa-house-chimney\', $text($labels, \'units_label\', \'Units Planned\'), pd_number($units)],\\n        [\'fa-map-pin\', $text($labels, \'ward_label\', \'Ward\'), $wardName !== \'\' ? $wardName : \'-\'],\\n        [\'fa-person-digging\', $text($labels, \'contractor_label\', \'Contractor\'), $contractor !== \'\' ? $contractor : \'TBD\'],\\n        [\'fa-coins\', $text($labels, \'funding_label\', \'Funding Source\'), $funding !== \'\' ? $funding : \'-\'],\\n        [\'fa-calendar-plus\', $text($labels, \'start_date_label\', \'Start Date\'), $startDate !== \'\' ? $startDate : \'-\'],\\n        [\'fa-flag-checkered\', $text($labels, \'est_delivery_label\', \'Est. Delivery\'), $deliveryDate !== \'\' ? $deliveryDate : \'-\'],\\n    ];\\n?>\\n<?php foreach ($facts as [$icon, $label, $value]): ?>\\n            <div class=\\\"pd-fact\\\">\\n              <div class=\\\"pd-fact-icon-wrap\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid <?= $e($icon) ?>\\\"></i></div>\\n              <span class=\\\"pd-fact-lbl\\\"><?= $e($label) ?></span>\\n              <span class=\\\"pd-fact-val\\\"><?= $e($value) ?></span>\\n            </div>\\n<?php endforeach; ?>\\n          </div>\\n\\n          <section class=\\\"pd-description pd-card\\\" id=\\\"pdDescription\\\">\\n            <p class=\\\"pd-section-label\\\"><?= $e($text($overview, \'section_label\', \'About This Project\')) ?></p>\\n            <h2 class=\\\"pd-section-title\\\"><?= $e($text($overview, \'title\', \'Project Overview\')) ?></h2>\\n            <p class=\\\"pd-description-text\\\"><?= nl2br($e($projectDescription)) ?></p>\\n            <div class=\\\"pd-desc-meta-strip\\\">\\n<?php if ($leadAgency !== \'\'): ?>\\n              <div class=\\\"pd-desc-meta-item\\\"><i class=\\\"fa-solid fa-building-government\\\" aria-hidden=\\\"true\\\"></i><span><strong><?= $e($text($overview, \'lead_agency_label\', \'Lead Agency\')) ?></strong><?= $e($leadAgency) ?></span></div>\\n<?php endif; ?>\\n<?php if ($siteEngineer !== \'\' && strtolower($siteEngineer) !== \'tbd\'): ?>\\n              <div class=\\\"pd-desc-meta-item\\\"><i class=\\\"fa-solid fa-helmet-safety\\\" aria-hidden=\\\"true\\\"></i><span><strong><?= $e($text($overview, \'site_engineer_label\', \'Site Engineer\')) ?></strong><?= $e($siteEngineer) ?></span></div>\\n<?php endif; ?>\\n<?php if ($funding !== \'\'): ?>\\n              <div class=\\\"pd-desc-meta-item\\\"><i class=\\\"fa-solid fa-coins\\\" aria-hidden=\\\"true\\\"></i><span><strong><?= $e($text($overview, \'funding_label\', \'Funding\')) ?></strong><?= $e($funding) ?></span></div>\\n<?php endif; ?>\\n            </div>\\n<?php if ($currentMilestone !== \'\'): ?>\\n            <div class=\\\"pd-current-milestone\\\">\\n              <i class=\\\"fa-solid fa-hard-hat\\\" aria-hidden=\\\"true\\\"></i>\\n              <span><strong><?= $e($text($overview, \'current_activity_label\', \'Current Activity\')) ?>:</strong> <?= $e($currentMilestone) ?></span>\\n            </div>\\n<?php endif; ?>\\n          </section>\\n\\n          <section class=\\\"pd-progress-section pd-card\\\" id=\\\"pdProgressSection\\\">\\n            <p class=\\\"pd-section-label\\\"><?= $e($text($overview, \'progress_label\', \'Construction Progress\')) ?></p>\\n            <h2 class=\\\"pd-section-title\\\"><?= $e($text($overview, \'progress_title\', \'Live Progress Tracker\')) ?></h2>\\n            <div class=\\\"pd-progress-bar-wrap\\\">\\n              <div class=\\\"pd-progress-meta\\\">\\n                <span class=\\\"pd-progress-lbl\\\"><?= $e($text($overview, \'overall_completion_label\', \'Overall Completion\')) ?></span>\\n                <span class=\\\"pd-progress-pct\\\"><?= $e($pct) ?>%</span>\\n              </div>\\n              <div class=\\\"pd-progress-track\\\" role=\\\"progressbar\\\" aria-valuenow=\\\"<?= $e($pct) ?>\\\" aria-valuemin=\\\"0\\\" aria-valuemax=\\\"100\\\" aria-label=\\\"<?= $e($pct) ?>% construction complete\\\">\\n                <div class=\\\"pd-progress-fill\\\" data-target=\\\"<?= $e($pct) ?>\\\"></div>\\n              </div>\\n              <p class=\\\"pd-progress-note\\\"><i class=\\\"fa-regular fa-clock\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($overview, \'progress_note\', \'Data updated regularly by the Trans-Nzoia County Housing Department.\')) ?></p>\\n            </div>\\n            <div class=\\\"pd-mini-stats\\\">\\n              <div class=\\\"pd-mini-stat\\\"><span class=\\\"pd-mini-stat-val\\\"><?= $e(pd_number($units)) ?></span><span class=\\\"pd-mini-stat-lbl\\\"><?= $e($text($labels, \'units_label\', \'Units Planned\')) ?></span></div>\\n              <div class=\\\"pd-mini-stat\\\"><span class=\\\"pd-mini-stat-val\\\"><?= $e(pd_number($unitsInProgress)) ?></span><span class=\\\"pd-mini-stat-lbl\\\"><?= $e($text($overview, \'units_in_progress_label\', \'Units In Progress\')) ?></span></div>\\n              <div class=\\\"pd-mini-stat\\\"><span class=\\\"pd-mini-stat-val\\\"><?= $e($deliveryDate !== \'\' ? $deliveryDate : \'-\') ?></span><span class=\\\"pd-mini-stat-lbl\\\"><?= $e($text($overview, \'target_delivery_label\', \'Target Delivery\')) ?></span></div>\\n              <div class=\\\"pd-mini-stat\\\"><span class=\\\"pd-mini-stat-val\\\"><?= $e(format_percentage($programmeSummary[\'average_progress\'] ?? $pct)) ?></span><span class=\\\"pd-mini-stat-lbl\\\"><?= $e($text($overview, \'programme_progress_label\', \'Programme Progress\')) ?></span></div>\\n              <div class=\\\"pd-mini-stat\\\"><span class=\\\"pd-mini-stat-val\\\"><?= $e(pd_number($programmeSummary[\'complete\'] ?? 0)) ?></span><span class=\\\"pd-mini-stat-lbl\\\"><?= $e($text($overview, \'completed_tasks_label\', \'Completed Tasks\')) ?></span></div>\\n              <div class=\\\"pd-mini-stat\\\"><span class=\\\"pd-mini-stat-val\\\"><?= $e(pd_number($programmeSummary[\'needs_attention\'] ?? 0)) ?></span><span class=\\\"pd-mini-stat-lbl\\\"><?= $e($text($overview, \'attention_items_label\', \'Needs Attention\')) ?></span></div>\\n            </div>\\n          </section>\\n\\n          <section class=\\\"pd-timeline-section pd-card\\\" id=\\\"pdTimelineSection\\\">\\n            <p class=\\\"pd-section-label\\\"><?= $e($text($overview, \'timeline_label\', \'Key Milestones\')) ?></p>\\n            <h2 class=\\\"pd-section-title\\\"><?= $e($text($overview, \'timeline_title\', \'Construction Timeline\')) ?></h2>\\n<?php if ($milestones): ?>\\n            <div class=\\\"pd-timeline\\\">\\n<?php foreach ($milestones as $milestone):\\n        $milestoneStatus = (string)($milestone[\'status\'] ?? \'pending\');\\n        $itemClass = $milestoneStatus === \'done\' ? \'is-done\' : ($milestoneStatus === \'current\' ? \'is-current\' : \'\');\\n        $milestoneDate = pd_date_label($milestone[\'actual_date\'] ?: ($milestone[\'target_date\'] ?? \'\'), (string)($milestone[\'target_date\'] ?? \'\'));\\n?>\\n              <div class=\\\"pd-tl-item <?= $e($itemClass) ?>\\\">\\n                <div class=\\\"pd-tl-spine\\\" aria-hidden=\\\"true\\\">\\n                  <div class=\\\"pd-tl-dot\\\"><?php if ($milestoneStatus === \'done\'): ?><i class=\\\"fa-solid fa-check\\\" aria-hidden=\\\"true\\\"></i><?php elseif ($milestoneStatus === \'current\'): ?><i class=\\\"fa-solid fa-circle-half-stroke\\\" aria-hidden=\\\"true\\\"></i><?php endif; ?></div>\\n                </div>\\n                <div class=\\\"pd-tl-content\\\">\\n                  <span class=\\\"pd-tl-date\\\"><?= $e($milestoneDate !== \'\' ? $milestoneDate : \'Pending\') ?></span>\\n                  <p class=\\\"pd-tl-label\\\"><?= $e($milestone[\'label\'] ?? \'\') ?><?php if ($milestoneStatus === \'current\'): ?> <span class=\\\"pd-tl-badge\\\">CURRENT</span><?php endif; ?></p>\\n                </div>\\n              </div>\\n<?php endforeach; ?>\\n            </div>\\n<?php else: ?>\\n            <div class=\\\"pd-timeline-empty\\\">\\n              <i class=\\\"fa-solid fa-list-check\\\" aria-hidden=\\\"true\\\"></i>\\n              <p><?= $e($text($overview, \'timeline_empty_text\', \'Milestones will appear after they are added to this project.\')) ?></p>\\n            </div>\\n<?php endif; ?>\\n          </section>\\n\\n          <section class=\\\"pd-gallery-section pd-card\\\" id=\\\"pdGallerySection\\\">\\n            <p class=\\\"pd-section-label\\\"><?= $e($text($overview, \'gallery_label\', \'Site Photography\')) ?></p>\\n            <h2 class=\\\"pd-section-title\\\"><?= $e($text($overview, \'gallery_title\', \'Photo Gallery\')) ?></h2>\\n<?php if ($images): ?>\\n            <div class=\\\"pd-gallery\\\">\\n<?php foreach ($images as $index => $image): ?>\\n<?php if ($index === 1): ?>\\n              <div class=\\\"pd-gallery-grid\\\">\\n<?php endif; ?>\\n              <button class=\\\"<?= $index === 0 ? \'pd-gallery-featured\' : \'pd-gallery-item\' ?>\\\" type=\\\"button\\\" data-gallery-index=\\\"<?= $e($index) ?>\\\" data-gallery-src=\\\"<?= $e(pd_asset_url($image)) ?>\\\" data-gallery-alt=\\\"<?= $e($projectName . \' site photo \' . ($index + 1)) ?>\\\" aria-label=\\\"View photo <?= $e($index + 1) ?>\\\">\\n                <img <?= public_image_attrs($image, $projectName . \' site photo \' . ($index + 1), [\'loading\' => $index === 0 ? \'eager\' : \'lazy\', \'fetchpriority\' => $index === 0 ? \'high\' : \'auto\']) ?>>\\n                <div class=\\\"pd-gallery-item-overlay\\\"><i class=\\\"fa-solid fa-magnifying-glass-plus\\\" aria-hidden=\\\"true\\\"></i></div>\\n              </button>\\n<?php endforeach; ?>\\n<?php if (count($images) > 1): ?>\\n              </div>\\n<?php endif; ?>\\n            </div>\\n<?php else: ?>\\n            <div class=\\\"pd-gallery-empty\\\">\\n              <i class=\\\"fa-solid fa-camera-slash\\\" aria-hidden=\\\"true\\\"></i>\\n              <p><?= $e($text($overview, \'gallery_empty_text\', \'Site photography will be added as construction progresses.\')) ?></p>\\n            </div>\\n<?php endif; ?>\\n          </section>\\n        </div>\\n\\n        <aside class=\\\"pd-sidebar\\\" id=\\\"pdSidebar\\\" aria-label=\\\"Project quick facts\\\">\\n          <div class=\\\"pd-sidebar-card pd-sb-contractor\\\">\\n            <div class=\\\"pd-sb-con-avatar\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid fa-helmet-safety\\\"></i></div>\\n            <div class=\\\"pd-sb-con-info\\\">\\n              <p class=\\\"pd-sidebar-card-title\\\"><?= $e($text($sidebar, \'contractor_title\', \'Contractor\')) ?></p>\\n              <p class=\\\"pd-contractor-name\\\"><?= $e($contractor !== \'\' ? $contractor : \'TBD\') ?></p>\\n              <span class=\\\"pd-contractor-role-badge\\\"><?= $e($text($sidebar, \'contractor_role_label\', \'Principal Contractor\')) ?></span>\\n            </div>\\n<?php if ($leadAgency !== \'\'): ?>\\n            <div class=\\\"pd-sb-agency\\\"><i class=\\\"fa-solid fa-building-government\\\" aria-hidden=\\\"true\\\"></i><span><?= $e($leadAgency) ?></span></div>\\n<?php endif; ?>\\n          </div>\\n\\n          <div class=\\\"pd-sidebar-card\\\">\\n            <p class=\\\"pd-sidebar-card-title\\\"><?= $e($text($sidebar, \'project_info_title\', \'Project Info\')) ?></p>\\n            <div class=\\\"pd-sidebar-list\\\">\\n<?php\\n    $infoRows = [\\n        [$text($sidebar, \'constituency_label\', \'Constituency\'), $constituencySlug !== \'\' ? \'<a href=\\\"constituency-detail.php?id=\' . $e(rawurlencode($constituencySlug)) . \'\\\" class=\\\"pd-sb-link\\\">\' . $e($constituencyName) . \'</a>\' : $e($constituencyName), true],\\n        [$text($labels, \'ward_label\', \'Ward\'), $e($wardName !== \'\' ? $wardName : \'-\') , true],\\n        [$text($sidebar, \'status_label\', \'Status\'), \'<span class=\\\"pd-sb-status pd-sb-status--\' . $e($statusClass) . \'\\\">\' . $e($statusLabel) . \'</span>\', true],\\n        [$text($sidebar, \'target_units_label\', \'Target Units\'), $e(pd_number($units)), true],\\n        [$text($labels, \'start_date_label\', \'Start Date\'), $e($startDate !== \'\' ? $startDate : \'-\'), true],\\n        [$text($labels, \'est_delivery_label\', \'Est. Delivery\'), $e($deliveryDate !== \'\' ? $deliveryDate : \'-\'), true],\\n        [$text($sidebar, \'completion_label\', \'Completion\'), \'<span class=\\\"pd-sb-pct\\\">\' . $e($pct) . \'%</span><div class=\\\"pd-sb-mini-bar\\\"><div class=\\\"pd-sb-mini-fill\\\" style=\\\"width:\' . $e($pct) . \'%\\\"></div></div>\', true],\\n    ];\\n?>\\n<?php foreach ($infoRows as $index => [$label, $value, $raw]): ?>\\n              <div class=\\\"pd-sidebar-row<?= $index % 2 === 1 ? \' is-alt\' : \'\' ?>\\\">\\n                <span class=\\\"pd-sidebar-row-lbl\\\"><?= $e($label) ?></span>\\n                <span class=\\\"pd-sidebar-row-val\\\"><?= $raw ? $value : $e($value) ?></span>\\n              </div>\\n<?php endforeach; ?>\\n            </div>\\n          </div>\\n\\n          <div class=\\\"pd-sidebar-card pd-apply-card\\\">\\n            <div class=\\\"pd-apply-icon-wrap\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid fa-house-chimney-user\\\"></i></div>\\n            <p class=\\\"pd-apply-title\\\"><?= $e($text($applyCta, \'title\', \'Interested in a Unit?\')) ?></p>\\n            <p class=\\\"pd-apply-sub\\\"><?= $e($text($applyCta, \'subtitle\', \'Register on the national Boma Yangu portal to apply for affordable housing in Trans-Nzoia County.\')) ?></p>\\n            <a href=\\\"<?= $e($text($applyCta, \'button_url\', \'https://app.bomayangu.go.ke\')) ?>\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"pd-apply-btn\\\">\\n              <i class=\\\"fa-solid fa-arrow-up-right-from-square\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($applyCta, \'button_label\', \'Apply on Boma Yangu\')) ?>\\n            </a>\\n          </div>\\n\\n          <div class=\\\"pd-sidebar-card\\\">\\n            <p class=\\\"pd-sidebar-card-title\\\"><?= $e($text($sidebar, \'related_title\', \'Related\')) ?></p>\\n            <div class=\\\"pd-related-links\\\">\\n<?php if ($constituencySlug !== \'\'): ?>\\n              <a href=\\\"constituency-detail.php?id=<?= $e(rawurlencode($constituencySlug)) ?>\\\" class=\\\"pd-related-link\\\">\\n                <div class=\\\"pd-related-icon\\\"><i class=\\\"fa-solid fa-map-location-dot\\\" aria-hidden=\\\"true\\\"></i></div>\\n                <span><?= $e($constituencyName . \' \' . $text($sidebar, \'constituency_link_suffix\', \'Constituency\')) ?></span>\\n                <i class=\\\"fa-solid fa-chevron-right pd-related-arrow\\\" aria-hidden=\\\"true\\\"></i>\\n              </a>\\n              <a href=\\\"projects.php?constituency=<?= $e(rawurlencode($constituencySlug)) ?>\\\" class=\\\"pd-related-link\\\">\\n                <div class=\\\"pd-related-icon\\\"><i class=\\\"fa-solid fa-building-columns\\\" aria-hidden=\\\"true\\\"></i></div>\\n                <span><?= $e($text($sidebar, \'all_projects_prefix\', \'All\') . \' \' . $constituencyName . \' Projects\') ?></span>\\n                <i class=\\\"fa-solid fa-chevron-right pd-related-arrow\\\" aria-hidden=\\\"true\\\"></i>\\n              </a>\\n<?php endif; ?>\\n              <a href=\\\"projects.php\\\" class=\\\"pd-related-link\\\">\\n                <div class=\\\"pd-related-icon\\\"><i class=\\\"fa-solid fa-arrow-left\\\" aria-hidden=\\\"true\\\"></i></div>\\n                <span><?= $e($text($sidebar, \'back_projects_label\', \'Back to All Projects\')) ?></span>\\n                <i class=\\\"fa-solid fa-chevron-right pd-related-arrow\\\" aria-hidden=\\\"true\\\"></i>\\n              </a>\\n            </div>\\n          </div>\\n<?php if ($relatedProjects): ?>\\n          <div class=\\\"pd-sidebar-card\\\">\\n            <p class=\\\"pd-sidebar-card-title\\\"><?= $e($text($sidebar, \'nearby_projects_title\', \'Nearby Projects\')) ?></p>\\n            <div class=\\\"pd-related-projects\\\">\\n<?php foreach ($relatedProjects as $related): ?>\\n              <a href=\\\"project-detail.php?id=<?= $e(rawurlencode((string)$related[\'slug\'])) ?>\\\" class=\\\"pd-related-project\\\">\\n                <span class=\\\"pd-related-project-name\\\"><?= $e($related[\'name\']) ?></span>\\n                <span class=\\\"pd-related-project-meta\\\"><?= $e($related[\'constituency_name\']) ?> / <?= $e(format_percentage($related[\'pct_complete\'])) ?></span>\\n              </a>\\n<?php endforeach; ?>\\n            </div>\\n          </div>\\n<?php endif; ?>\\n        </aside>\\n      </div>\\n    </div>\\n  </div>\\n<?php endif; ?>\\n</main>\\n<?php include __DIR__ . \'/app/partials/footer.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/back-to-top.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/mobile-menu.php\'; ?>\\n<?= public_json_script(\'ahp-page-data\', $publicPayload) ?>\\n<?php include __DIR__ . \'/app/partials/scripts.php\'; ?>\\n</body>\\n</html>\\n\",\"note\":\"Snapshot of the current public frontend file. Frontend rendering has not been changed yet.\"}', NULL, '2026-06-24 18:05:14');
INSERT INTO `cms_sections` (`id`, `page_id`, `section_key`, `label`, `section_type`, `sort_order`, `editor_mode`, `is_visible`, `is_locked`, `content_json`, `updated_by`, `updated_at`) VALUES
(359, 5, 'current_frontend_snapshot', 'Constituencies - Current Frontend Snapshot', 'frontend_snapshot', 1, 'json', 1, 1, '{\"page_slug\":\"constituencies\",\"page_label\":\"Constituencies\",\"file_path\":\"constituencies.php\",\"source_hash\":\"f4056c27dcf26fa9bdf27d280fa2acea6e22b34688f68e976d86c48d4fadd2ef\",\"title\":\"\",\"meta_description\":\"\",\"headings\":[],\"links\":[{\"href\":\"index.php\",\"text\":\"Home\"},{\"href\":\"<?= Security::e($item[\",\"text\":\"\\\" class=\\\"con-card-cta\\\" aria-label=\\\"Explore \\\"> Explore\"},{\"href\":\"<?= Security::e(CmsLoader::text($progressCopy,\",\"text\":\"\\\" class=\\\"btn btn-primary\\\">\"},{\"href\":\"<?= Security::e($item[\",\"text\":\"\\\" class=\\\"con-browse-cta\\\"> Explore\"},{\"href\":\"<?= Security::e(CmsLoader::text($ctaCopy,\",\"text\":\"\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"btn btn-lime\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($ctaCopy,\",\"text\":\"\\\" class=\\\"btn btn-outline-light\\\">\"}],\"images\":[{\"src\":\"\",\"alt\":\"\"}],\"forms\":[],\"cms_keys\":[],\"text_content\":\"\'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>> Home Constituencies \\\" tabindex=\\\"0\\\" role=\\\"button\\\" aria-label=\\\" \\\"> \\\" class=\\\"con-path\\\"/> \\\" y=\\\" \\\"> \\\" y=\\\" \\\"> \\\" tabindex=\\\"0\\\" aria-label=\\\"Explore \\\"> residents \\\"> Projects Units Wards Avg. Completion % \\\" aria-valuemin=\\\"0\\\" aria-valuemax=\\\"100\\\"> \\\" style=\\\"width: %\\\"> \\\" class=\\\"con-card-cta\\\" aria-label=\\\"Explore \\\"> Explore \\\" class=\\\"btn btn-primary\\\"> \\\" style=\\\"width: %\\\"> % residents \\\"> Projects Units Wards Avg. Completion % \\\" style=\\\"width: %\\\"> \\\" class=\\\"con-browse-cta\\\"> Explore \\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"btn btn-lime\\\"> \\\" class=\\\"btn btn-outline-light\\\">\",\"raw_source\":\"<?php\\nrequire_once __DIR__ . \'/app/core/bootstrap.php\';\\n\\n$basePath = \'\';\\n$activePage = \'constituencies\';\\n$cmsPage = CmsLoader::publicPage(\'constituencies\');\\n\\nif (!function_exists(\'constituencies_content\')) {\\nfunction constituencies_content(array $page, string $key, array $defaults): array\\n{\\n    return CmsLoader::content($page, $key, $defaults);\\n}\\n}\\n\\nif (!function_exists(\'constituencies_number\')) {\\nfunction constituencies_number(int|float $value): string\\n{\\n    return number_format((float)$value, 0);\\n}\\n}\\n\\nif (!function_exists(\'constituencies_short_number\')) {\\nfunction constituencies_short_number(int|float $value): string\\n{\\n    $value = (float)$value;\\n    if ($value >= 1000000) {\\n        return rtrim(rtrim(number_format($value / 1000000, 1), \'0\'), \'.\') . \'M\';\\n    }\\n    if ($value >= 1000) {\\n        return rtrim(rtrim(number_format($value / 1000, 1), \'0\'), \'.\') . \'K\';\\n    }\\n    return number_format($value, 0);\\n}\\n}\\n\\nif (!function_exists(\'constituencies_plural\')) {\\nfunction constituencies_plural(int $count, string $singular, string $plural): string\\n{\\n    return $count === 1 ? $singular : $plural;\\n}\\n}\\n\\nif (!function_exists(\'constituencies_replace_stats\')) {\\nfunction constituencies_replace_stats(string $text, array $stats): string\\n{\\n    return strtr($text, [\\n        \'{constituencies}\' => (string)$stats[\'constituencies\'],\\n        \'{projects}\' => (string)$stats[\'projects\'],\\n        \'{units}\' => constituencies_number((int)$stats[\'units\']),\\n        \'{residents}\' => constituencies_short_number((int)$stats[\'residents\']),\\n    ]);\\n}\\n}\\n\\n$hero = constituencies_content($cmsPage, \'constituencies_hero\', [\\n    \'background_image\' => \'uploads/gallery/maili-tatu-3.jpg\',\\n    \'background_alt\' => \'Affordable housing construction site in Trans-Nzoia County\',\\n    \'eyebrow\' => \'Coverage Map\',\\n    \'title_prefix\' => \'All\',\\n    \'title_highlight\' => \'5 Constituencies\',\\n    \'subtitle\' => \'Explore how the Affordable Housing Programme reaches every corner of Trans-Nzoia County - from Endebess on the Uganda border to Kwanza in the south.\',\\n    \'constituencies_label\' => \'Constituencies\',\\n    \'projects_label\' => \'Projects\',\\n    \'units_label\' => \'Units Planned\',\\n    \'residents_label\' => \'Residents Served\',\\n]);\\n$mapCopy = constituencies_content($cmsPage, \'constituencies_map\', [\\n    \'title\' => \'Trans-Nzoia County\',\\n    \'subtitle\' => \'Click a constituency to explore its housing projects\',\\n    \'active_label\' => \'Active construction\',\\n    \'planning_label\' => \'Planning stage\',\\n    \'selected_label\' => \'Selected\',\\n    \'empty_text\' => \'Constituency data will appear after projects and wards are added to the registry.\',\\n]);\\n$progressCopy = constituencies_content($cmsPage, \'constituencies_progress\', [\\n    \'title\' => \\\"County-Wide\\\\nProgramme\\\\nProgress\\\",\\n    \'subtitle\' => \'Across all {constituencies} constituencies, the programme is delivering {units} affordable housing units - targeting Kenyans registered on the national Boma Yangu portal.\',\\n    \'button_label\' => \'Browse All Projects\',\\n    \'button_url\' => \'projects.php\',\\n]);\\n$gridCopy = constituencies_content($cmsPage, \'constituencies_grid\', [\\n    \'eyebrow\' => \'Browse by Constituency\',\\n    \'title_prefix\' => \'All\',\\n    \'title_highlight\' => \'5 Constituencies\',\\n    \'sort_label\' => \'Sort:\',\\n    \'default_label\' => \'Default\',\\n    \'progress_label\' => \'Highest Progress\',\\n    \'units_label\' => \'Most Units\',\\n    \'alpha_label\' => \'A - Z\',\\n]);\\n$ctaCopy = constituencies_content($cmsPage, \'constituencies_apply_cta\', [\\n    \'title\' => \'Ready to Apply for Affordable Housing?\',\\n    \'subtitle\' => \'Register on the national Boma Yangu portal to join the Trans-Nzoia County AHP allocation list.\',\\n    \'primary_label\' => \'Apply on Boma Yangu\',\\n    \'primary_url\' => \'https://bomayangu.go.ke\',\\n    \'secondary_label\' => \'View All Projects\',\\n    \'secondary_url\' => \'projects.php\',\\n]);\\n\\n$constituencies = Constituency::publicList();\\n$stats = Constituency::publicStats();\\n$constituenciesBySlug = [];\\nforeach ($constituencies as $item) {\\n    $constituenciesBySlug[$item[\'id\']] = $item;\\n}\\n$clientLabels = [\\n    \'active\' => \'Active\',\\n    \'planning\' => \'Planning\',\\n    \'residents\' => \'residents\',\\n    \'projects\' => CmsLoader::text($hero, \'projects_label\', \'Projects\'),\\n    \'units\' => \'Units\',\\n    \'wards\' => \'Wards\',\\n    \'completion\' => \'Avg. Completion\',\\n    \'explore\' => \'Explore\',\\n    \'previous\' => \'Prev\',\\n    \'next\' => \'Next\',\\n    \'showing\' => \'Showing\',\\n    \'of\' => \'of\',\\n];\\n$pagePayload = public_page_payload(\'constituencies\', [\\n    \'constituencies\' => $constituencies,\\n    \'stats\' => $stats,\\n    \'labels\' => $clientLabels,\\n]);\\n\\n$pageTitle = $cmsPage[\'seo_title\'] ?? \'Constituencies | Trans-Nzoia County Affordable Housing Tracker\';\\n$pageDescription = $cmsPage[\'seo_description\'] ?? \'Explore affordable housing coverage across all 5 constituencies in Trans-Nzoia County - Saboti, Cherangany, Endebess, Kiminini and Kwanza.\';\\n$pageKeywords = $cmsPage[\'seo_keywords\'] ?? \'Trans-Nzoia constituencies, Saboti housing, Cherangany AHP, Endebess housing, Kiminini housing, Kwanza housing\';\\n$pageAuthor = \'Trans-Nzoia County Government - Department of Land, Housing & Physical Planning\';\\n$pageRobots = \'index, follow\';\\n$themeColor = \'#163300\';\\n$canonicalUrl = $cmsPage[\'canonical_url\'] ?? \'https://housing.transnzoia.go.ke/constituencies.php\';\\n$heroImage = CmsLoader::text($hero, \'background_image\', (string)($cmsPage[\'hero_image\'] ?? \'uploads/gallery/maili-tatu-3.jpg\'));\\n$pageStyles = [\'assets/css/global.css\', \'assets/css/pages/constituencies.css\'];\\n$pageScripts = [\'assets/js/global.js\', \'assets/js/pages/constituencies.js\'];\\n$headMeta = [\\n    \'<meta property=\\\"og:title\\\" content=\\\"\' . Security::e($pageTitle) . \'\\\">\',\\n    \'<meta property=\\\"og:description\\\" content=\\\"\' . Security::e($pageDescription) . \'\\\">\',\\n    \'<meta property=\\\"og:type\\\" content=\\\"website\\\">\',\\n    \'<meta property=\\\"og:url\\\" content=\\\"\' . Security::e($canonicalUrl) . \'\\\">\',\\n    \'<meta property=\\\"og:image\\\" content=\\\"\' . Security::e($heroImage) . \'\\\">\',\\n    \'<meta property=\\\"og:locale\\\" content=\\\"en_KE\\\">\',\\n    \'<meta property=\\\"og:site_name\\\" content=\\\"Trans-Nzoia AHP Tracker\\\">\',\\n    \'<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\">\',\\n    \'<meta name=\\\"twitter:title\\\" content=\\\"\' . Security::e($pageTitle) . \'\\\">\',\\n    \'<meta name=\\\"twitter:description\\\" content=\\\"\' . Security::e($pageDescription) . \'\\\">\',\\n    \'<meta name=\\\"twitter:image\\\" content=\\\"\' . Security::e($heroImage) . \'\\\">\',\\n];\\ninclude __DIR__ . \'/app/partials/head.php\';\\n?>\\n<body>\\n<?php include __DIR__ . \'/app/partials/cursor.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/skip-link.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/navbar.php\'; ?><main id=\\\"main-content\\\">\\n\\n    <section class=\\\"page-hero page-hero--constituencies\\\" aria-label=\\\"Constituencies overview\\\">\\n      <div class=\\\"page-hero-bg\\\" aria-hidden=\\\"true\\\">\\n        <img <?= public_image_attrs($heroImage, \'\', [\'loading\' => \'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>>\\n        <div class=\\\"page-hero-overlay\\\"></div>\\n      </div>\\n      <div class=\\\"container\\\">\\n        <nav class=\\\"breadcrumb\\\" aria-label=\\\"Breadcrumb\\\">\\n          <a href=\\\"index.php\\\" class=\\\"breadcrumb-link\\\">Home</a>\\n          <i class=\\\"fa-solid fa-chevron-right breadcrumb-sep\\\" aria-hidden=\\\"true\\\"></i>\\n          <span class=\\\"breadcrumb-current\\\">Constituencies</span>\\n        </nav>\\n        <div class=\\\"page-hero-body\\\">\\n          <div class=\\\"page-hero-eyebrow\\\">\\n            <span class=\\\"page-hero-tag\\\"><i class=\\\"fa-solid fa-map-location-dot\\\" aria-hidden=\\\"true\\\"></i> <?= Security::e(CmsLoader::text($hero, \'eyebrow\', \'Coverage Map\')) ?></span>\\n          </div>\\n          <h1 class=\\\"page-hero-title\\\"><?= Security::e(CmsLoader::text($hero, \'title_prefix\', \'All\')) ?> <span class=\\\"text-lime\\\"><?= Security::e(CmsLoader::text($hero, \'title_highlight\', $stats[\'constituencies\'] . \' Constituencies\')) ?></span></h1>\\n          <p class=\\\"page-hero-sub\\\"><?= Security::e(CmsLoader::text($hero, \'subtitle\', \'Explore how the Affordable Housing Programme reaches every corner of Trans-Nzoia County.\')) ?></p>\\n        </div>\\n        <div class=\\\"projects-hero-stats\\\" role=\\\"region\\\" aria-label=\\\"County-wide statistics\\\">\\n          <div class=\\\"phs-item\\\"><span class=\\\"phs-val\\\"><?= Security::e((string)$stats[\'constituencies\']) ?></span><span class=\\\"phs-lbl\\\"><?= Security::e(CmsLoader::text($hero, \'constituencies_label\', \'Constituencies\')) ?></span></div>\\n          <div class=\\\"phs-divider\\\" aria-hidden=\\\"true\\\"></div>\\n          <div class=\\\"phs-item\\\"><span class=\\\"phs-val\\\"><?= Security::e((string)$stats[\'projects\']) ?></span><span class=\\\"phs-lbl\\\"><?= Security::e(CmsLoader::text($hero, \'projects_label\', \'Projects\')) ?></span></div>\\n          <div class=\\\"phs-divider\\\" aria-hidden=\\\"true\\\"></div>\\n          <div class=\\\"phs-item\\\"><span class=\\\"phs-val\\\"><?= Security::e(constituencies_number($stats[\'units\'])) ?></span><span class=\\\"phs-lbl\\\"><?= Security::e(CmsLoader::text($hero, \'units_label\', \'Units Planned\')) ?></span></div>\\n          <div class=\\\"phs-divider\\\" aria-hidden=\\\"true\\\"></div>\\n          <div class=\\\"phs-item\\\"><span class=\\\"phs-val\\\"><?= Security::e(constituencies_short_number($stats[\'residents\'])) ?></span><span class=\\\"phs-lbl\\\"><?= Security::e(CmsLoader::text($hero, \'residents_label\', \'Residents Served\')) ?></span></div>\\n        </div>\\n      </div>\\n    </section>\\n\\n    <section class=\\\"constituencies-split\\\" aria-label=\\\"Constituency map and listings\\\">\\n      <div class=\\\"constituencies-split-inner\\\">\\n        <div class=\\\"con-map-panel\\\" aria-label=\\\"Interactive constituency map\\\">\\n          <div class=\\\"con-map-sticky\\\">\\n            <div class=\\\"con-map-header\\\">\\n              <h2 class=\\\"con-map-title\\\"><?= Security::e(CmsLoader::text($mapCopy, \'title\', \'Trans-Nzoia County\')) ?></h2>\\n              <p class=\\\"con-map-hint\\\"><?= Security::e(CmsLoader::text($mapCopy, \'subtitle\', \'Click a constituency to explore its housing projects\')) ?></p>\\n            </div>\\n            <div class=\\\"con-map-wrap\\\">\\n              <svg id=\\\"countyMap\\\" viewBox=\\\"0 0 480 400\\\" xmlns=\\\"http://www.w3.org/2000/svg\\\" role=\\\"img\\\" aria-label=\\\"Trans-Nzoia County map showing constituencies\\\">\\n                <defs>\\n                  <filter id=\\\"shadow\\\" x=\\\"-10%\\\" y=\\\"-10%\\\" width=\\\"120%\\\" height=\\\"120%\\\">\\n                    <feDropShadow dx=\\\"0\\\" dy=\\\"2\\\" stdDeviation=\\\"3\\\" flood-color=\\\"rgba(10,31,5,0.25)\\\"/>\\n                  </filter>\\n                </defs>\\n<?php foreach (Constituency::mapShapes() as $slug => $shape): ?>\\n<?php $item = $constituenciesBySlug[$slug] ?? [\'name\' => ucwords($slug), \'projectCount\' => 0, \'avgCompletion\' => 0]; ?>\\n                <g class=\\\"con-path-group\\\" data-id=\\\"<?= Security::e($slug) ?>\\\" tabindex=\\\"0\\\" role=\\\"button\\\" aria-label=\\\"<?= Security::e($item[\'name\'] . \' - \' . $item[\'projectCount\'] . \' \' . constituencies_plural((int)$item[\'projectCount\'], \'project\', \'projects\') . \', \' . $item[\'avgCompletion\'] . \'% average completion\') ?>\\\">\\n                  <path d=\\\"<?= Security::e($shape[\'path\']) ?>\\\" class=\\\"con-path\\\"/>\\n                  <text class=\\\"con-path-label\\\" x=\\\"<?= (int)$shape[\'label_x\'] ?>\\\" y=\\\"<?= (int)$shape[\'label_y\'] ?>\\\"><?= Security::e($item[\'name\']) ?></text>\\n                  <text class=\\\"con-path-sub\\\" x=\\\"<?= (int)$shape[\'label_x\'] ?>\\\" y=\\\"<?= (int)$shape[\'sub_y\'] ?>\\\"><?= Security::e($item[\'projectCount\'] . \' \' . constituencies_plural((int)$item[\'projectCount\'], \'project\', \'projects\')) ?></text>\\n                </g>\\n<?php endforeach; ?>\\n              </svg>\\n            </div>\\n            <div class=\\\"con-map-legend\\\" aria-label=\\\"Map legend\\\">\\n              <div class=\\\"con-legend-item\\\"><span class=\\\"con-legend-dot con-legend-dot--active\\\"></span><span><?= Security::e(CmsLoader::text($mapCopy, \'active_label\', \'Active construction\')) ?></span></div>\\n              <div class=\\\"con-legend-item\\\"><span class=\\\"con-legend-dot con-legend-dot--planning\\\"></span><span><?= Security::e(CmsLoader::text($mapCopy, \'planning_label\', \'Planning stage\')) ?></span></div>\\n              <div class=\\\"con-legend-item\\\"><span class=\\\"con-legend-dot con-legend-dot--selected\\\"></span><span><?= Security::e(CmsLoader::text($mapCopy, \'selected_label\', \'Selected\')) ?></span></div>\\n            </div>\\n          </div>\\n        </div>\\n        <div class=\\\"con-cards-panel\\\" id=\\\"conCardsPanel\\\" aria-label=\\\"Constituency listings\\\">\\n<?php if ($constituencies): ?>\\n<?php foreach ($constituencies as $item): ?>\\n          <article class=\\\"con-card\\\" data-id=\\\"<?= Security::e($item[\'id\']) ?>\\\" tabindex=\\\"0\\\" aria-label=\\\"Explore <?= Security::e($item[\'name\']) ?>\\\">\\n  