INSERT INTO `messages` (`id`, `thread_id`, `sender_id`, `parent_id`, `body`, `created_at`, `edited_at`, `is_deleted`, `deleted_by`, `deleted_at`, `metadata_json`) VALUES
(1, 1, 9, NULL, 'Good morning.\n\nThis is a demo thread to confirm project-scoped messaging is live. Managers can reach county leadership and assigned project teams only.\n\nPlease reply from Message Centre to verify the conversation panel.', '2026-07-11 10:45:29', NULL, 0, NULL, NULL, NULL),
(2, 1, 1, NULL, 'Acknowledged. Message Centre policy is active: non-directors only see staff on shared projects. Super Administrators retain full staff directory access.', '2026-07-11 10:45:29', NULL, 0, NULL, NULL, NULL),
(3, 2, 9, NULL, 'Team,\n\nUse this project channel for site coordination on Bireke ESP Site. Only assigned project staff can participate.\n\nNext: confirm attendance gateway is open tomorrow morning.', '2026-07-11 10:45:30', NULL, 0, NULL, NULL, NULL),
(4, 3, 10, NULL, 'Team,\n\nThis is the project coordination channel for Kiminini Modern Market.\nUse it for site updates, attendance, and IPC walkthrough notes.\nOnly assigned project staff can participate.', '2026-07-11 10:58:12', NULL, 0, NULL, NULL, NULL),
(5, 4, 1, NULL, 'Hello Finance,\n\nThis is a demo thread from county leadership. Use Message Centre for payment and certification discussions with managers and contractors on active projects.', '2026-07-11 10:58:12', NULL, 0, NULL, NULL, NULL),
(6, 4, 13, NULL, 'Noted. Finance will use Message Centre for payment queries and certification follow-ups.', '2026-07-11 10:58:12', NULL, 0, NULL, NULL, NULL),
(7, 5, 10, NULL, 'Good morning,\n\nThis is a demo conversation for Patrick Wekesa.\nManagers can message county leadership and staff on their assigned projects only.\n\nPlease reply here to confirm Message Centre is working for your account.', '2026-07-11 10:58:20', NULL, 0, NULL, NULL, NULL),
(8, 5, 1, NULL, 'Acknowledged, Patrick Wekesa. Message Centre is live. Non-directors only see staff on shared projects; Super Administrators retain the full staff directory.', '2026-07-11 10:58:20', NULL, 0, NULL, NULL, NULL),
(9, 5, 10, NULL, 'Thanks', '2026-07-11 11:06:44', NULL, 0, NULL, NULL, NULL),
(10, 6, 1, NULL, 'Teddy,\n\nThis is a Phase 9 demo thread for document and site report coordination.\nPlease use Message Centre for technical clarifications on assigned projects only.', '2026-07-11 12:51:32', NULL, 0, NULL, NULL, NULL),
(11, 6, 8, NULL, 'Received. Document and site report reviews are active on the consultant portfolio.', '2026-07-11 12:51:32', NULL, 0, NULL, NULL, NULL),
(12, 7, 1, NULL, 'Leadership,\n\nDemo thread for extension of time and variation recommendations.\nPending items are seeded for UAT of consultant contract review.', '2026-07-11 12:51:32', NULL, 0, NULL, NULL, NULL),
(13, 7, 8, NULL, 'Noted. We will track consultant recommendations through the contract pages.', '2026-07-11 12:51:32', NULL, 0, NULL, NULL, NULL),
(14, 8, 8, NULL, 'Team,\n\nPhase 9 demo channel for Maili Tatu Affordable Housing Estate.\nUse for document, material, drawing and contract clarifications.', '2026-07-11 12:51:33', NULL, 0, NULL, NULL, NULL);

