CREATE TABLE `news_articles` (
  `id` int(10) UNSIGNED NOT NULL,
  `post_format` varchar(40) NOT NULL DEFAULT 'article',
  `category_id` int(10) UNSIGNED DEFAULT NULL,
  `author_id` int(10) UNSIGNED NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `excerpt` text DEFAULT NULL,
  `read_time` varchar(50) DEFAULT NULL,
  `body` longtext NOT NULL,
  `featured_image_id` int(10) UNSIGNED DEFAULT NULL,
  `image_caption` varchar(500) DEFAULT NULL,
  `inline_image_id` int(10) UNSIGNED DEFAULT NULL,
  `attachment_id` int(10) UNSIGNED DEFAULT NULL,
  `external_url` varchar(500) DEFAULT NULL,
  `status` enum('draft','published','scheduled','archived') DEFAULT 'draft',
  `is_featured` tinyint(1) DEFAULT 0,
  `is_visible` tinyint(1) NOT NULL DEFAULT 1,
  `show_in_ticker` tinyint(1) NOT NULL DEFAULT 0,
  `ticker_text` varchar(255) DEFAULT NULL,
  `ticker_url` varchar(500) DEFAULT NULL,
  `ticker_expires_at` datetime DEFAULT NULL,
  `ticker_priority` int(11) NOT NULL DEFAULT 0,
  `published_at` datetime DEFAULT NULL,
  `scheduled_for` datetime DEFAULT NULL,
  `views` int(10) UNSIGNED DEFAULT 0,
  `seo_title` varchar(255) DEFAULT NULL,
  `seo_description` text DEFAULT NULL,
  `og_image_id` int(10) UNSIGNED DEFAULT NULL,
  `metadata_json` longtext DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

