INSERT INTO `news_articles` (`id`, `post_format`, `category_id`, `author_id`, `title`, `slug`, `excerpt`, `read_time`, `body`, `featured_image_id`, `image_caption`, `inline_image_id`, `attachment_id`, `external_url`, `status`, `is_featured`, `is_visible`, `show_in_ticker`, `ticker_text`, `ticker_url`, `ticker_expires_at`, `ticker_priority`, `published_at`, `scheduled_for`, `views`, `seo_title`, `seo_description`, `og_image_id`, `metadata_json`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'article', 1, 1, 'Trans-Nzoia AHP Delivers First 200 Units at Maili Tatu Estate - Beneficiaries Receive Keys', 'maili-tatu-first-200-units', 'In a landmark ceremony held at the Maili Tatu Estate in Kitale, Governor George Natembeya presided over the handover of 200 affordable housing units to qualifying beneficiaries. The milestone marks a significant step in the county commitment to delivering dignified, affordable housing to low- and middle-income residents under the national AHP framework.', '6 min read', 'In a landmark ceremony held at the Maili Tatu Estate in Kitale, Governor George Natembeya presided over the handover of 200 affordable housing units to qualifying beneficiaries. The milestone marks a significant step in the county commitment to delivering dignified, affordable housing to low- and middle-income residents under the national AHP framework.', 8, NULL, NULL, NULL, NULL, 'published', 1, 1, 0, NULL, NULL, NULL, 0, '2026-05-15 08:00:00', NULL, 25, 'Trans-Nzoia AHP Delivers First 200 Units at Maili Tatu Estate - Beneficiaries Receive Keys', 'In a landmark ceremony held at the Maili Tatu Estate in Kitale, Governor George Natembeya presided over the handover of 200 affordable housing units to qualifying beneficiaries. The milestone marks a significant step in the county commitment to delivering dignified, affordable housing to low- and middle-income residents under the national AHP framework.', NULL, NULL, '2026-05-26 17:30:02', '2026-07-11 19:25:22', NULL),
(2, 'article', 32, 1, 'Ground-Breaking Ceremony Marks Start of Endebess Phase 2 Construction', 'endebess-phase-2-groundbreaking', 'County officials and community leaders gathered at the Endebess site to officially launch the second phase of the affordable housing project, set to deliver 120 additional units to qualifying residents.', '3 min', 'County officials and community leaders gathered at the Endebess site to officially launch the second phase of the affordable housing project, set to deliver 120 additional units to qualifying residents.', 9, NULL, NULL, NULL, NULL, 'published', 1, 1, 0, NULL, NULL, NULL, 0, '2026-05-10 08:00:00', NULL, 1, 'Ground-Breaking Ceremony Marks Start of Endebess Phase 2 Construction', 'County officials and community leaders gathered at the Endebess site to officially launch the second phase of the affordable housing project, set to deliver 120 additional units to qualifying residents.', NULL, NULL, '2026-05-26 17:30:03', '2026-07-08 17:07:04', NULL),
(3, 'progress_report', 33, 1, 'Cherangany Housing Project Reaches 70% Completion Milestone', 'cherangany-70-percent-completion', 'The Cherangany constituency AHP project has surpassed the 70% completion threshold, with roofing works now underway on the final two residential blocks ahead of the projected Q3 2026 handover date.', '4 min', 'The Cherangany constituency AHP project has surpassed the 70% completion threshold, with roofing works now underway on the final two residential blocks ahead of the projected Q3 2026 handover date.', 10, NULL, NULL, NULL, NULL, 'published', 1, 1, 0, NULL, NULL, NULL, 0, '2026-05-08 08:00:00', NULL, 1, 'Cherangany Housing Project Reaches 70% Completion Milestone', 'The Cherangany constituency AHP project has surpassed the 70% completion threshold, with roofing works now underway on the final two residential blocks ahead of the projected Q3 2026 handover date.', NULL, NULL, '2026-05-26 17:30:03', '2026-06-29 19:26:44', NULL),
(4, 'policy', 34, 1, 'County Receives KSh 1.8 Billion National AHP Allocation for FY 2026/27', 'fy-2026-27-ahp-allocation', 'The National Treasury has confirmed a KSh 1.8 billion disbursement to Trans-Nzoia County under the Affordable Housing Programme for the upcoming financial year, enabling the commencement of three new estate projects.', '5 min', 'The National Treasury has confirmed a KSh 1.8 billion disbursement to Trans-Nzoia County under the Affordable Housing Programme for the upcoming financial year, enabling the commencement of three new estate projects.', 11, NULL, NULL, NULL, NULL, 'published', 1, 1, 0, NULL, NULL, NULL, 0, '2026-05-05 08:00:00', NULL, 1, 'County Receives KSh 1.8 Billion National AHP Allocation for FY 2026/27', 'The National Treasury has confirmed a KSh 1.8 billion disbursement to Trans-Nzoia County under the Affordable Housing Programme for the upcoming financial year, enabling the commencement of three new estate projects.', NULL, NULL, '2026-05-26 17:30:03', '2026-06-29 19:26:44', NULL),
(5, 'article', 35, 1, 'Community Stakeholders Forum Held in Kwanza Sub-County', 'kwanza-community-stakeholders-forum', 'Over 400 residents attended the public participation forum in Kwanza, where the Housing Department presented the beneficiary registration process, eligibility criteria, and construction timelines for the local AHP estate.', '3 min', 'Over 400 residents attended the public participation forum in Kwanza, where the Housing Department presented the beneficiary registration process, eligibility criteria, and construction timelines for the local AHP estate.', 12, NULL, NULL, NULL, NULL, 'published', 0, 1, 0, NULL, NULL, NULL, 0, '2026-05-03 08:00:00', NULL, 0, 'Community Stakeholders Forum Held in Kwanza Sub-County', 'Over 400 residents attended the public participation forum in Kwanza, where the Housing Department presented the beneficiary registration process, eligibility criteria, and construction timelines for the local AHP estate.', NULL, NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03', NULL),
(6, 'announcement', 36, 1, 'Governor Issues Statement on Beneficiary Selection and Allocation Criteria', 'beneficiary-selection-statement', 'The Office of the Governor has released an official statement clarifying the eligibility criteria for affordable housing unit allocation, reaffirming that selection will be transparent, needs-based, and verifiable through public registers.', '2 min', 'The Office of the Governor has released an official statement clarifying the eligibility criteria for affordable housing unit allocation, reaffirming that selection will be transparent, needs-based, and verifiable through public registers.', 13, NULL, NULL, NULL, NULL, 'published', 0, 0, 1, 'Governor Issues Statement on Beneficiary Selection and Allocation Criteria', NULL, NULL, 0, '2026-05-01 08:00:00', NULL, 0, 'Governor Issues Statement on Beneficiary Selection and Allocation Criteria', 'The Office of the Governor has released an official statement clarifying the eligibility criteria for affordable housing unit allocation, reaffirming that selection will be transparent, needs-based, and verifiable through public registers.', NULL, NULL, '2026-05-26 17:30:03', '2026-06-29 18:33:00', NULL),
(7, 'field_report', 37, 1, 'Field Report: Site Visit to Kiminini Social Housing Complex', 'kiminini-site-field-report', 'County housing inspectors conducted a comprehensive site assessment at the Kiminini Social Housing Complex, confirming structural compliance on all four residential blocks and certifying the plumbing installations on Blocks A and B.', '5 min', 'County housing inspectors conducted a comprehensive site assessment at the Kiminini Social Housing Complex, confirming structural compliance on all four residential blocks and certifying the plumbing installations on Blocks A and B.', 14, NULL, NULL, NULL, NULL, 'published', 0, 1, 0, NULL, NULL, NULL, 0, '2026-04-28 08:00:00', NULL, 1, 'Field Report: Site Visit to Kiminini Social Housing Complex', 'County housing inspectors conducted a comprehensive site assessment at the Kiminini Social Housing Complex, confirming structural compliance on all four residential blocks and certifying the plumbing installations on Blocks A and B.', NULL, NULL, '2026-05-26 17:30:03', '2026-06-30 11:46:52', NULL),
(8, 'article', 1, 1, 'National Housing Corporation Signs New Implementation Agreement with Trans-Nzoia County', 'nhc-implementation-agreement', 'The National Housing Corporation and Trans-Nzoia County Government have signed a revised implementation agreement expanding the scope of the AHP programme to include two additional estate sites in Saboti and Kwanza constituencies.', '4 min', 'The National Housing Corporation and Trans-Nzoia County Government have signed a revised implementation agreement expanding the scope of the AHP programme to include two additional estate sites in Saboti and Kwanza constituencies.', 15, NULL, NULL, NULL, NULL, 'published', 0, 1, 0, NULL, NULL, NULL, 0, '2026-04-25 08:00:00', NULL, 0, 'National Housing Corporation Signs New Implementation Agreement with Trans-Nzoia County', 'The National Housing Corporation and Trans-Nzoia County Government have signed a revised implementation agreement expanding the scope of the AHP programme to include two additional estate sites in Saboti and Kwanza constituencies.', NULL, NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03', NULL),
(9, 'article', 35, 1, 'Residents Urged to Register Beneficiary Interest via eCitizen Portal', 'ecitizen-beneficiary-registration', 'The Department of Land, Housing and Physical Planning has called on all eligible Trans-Nzoia residents to formally register their interest for affordable housing units through the government eCitizen online portal before the 30 June 2026 deadline.', '3 min', 'The Department of Land, Housing and Physical Planning has called on all eligible Trans-Nzoia residents to formally register their interest for affordable housing units through the government eCitizen online portal before the 30 June 2026 deadline.', 16, NULL, NULL, NULL, NULL, 'published', 0, 1, 0, NULL, NULL, NULL, 0, '2026-04-22 08:00:00', NULL, 1, 'Residents Urged to Register Beneficiary Interest via eCitizen Portal', 'The Department of Land, Housing and Physical Planning has called on all eligible Trans-Nzoia residents to formally register their interest for affordable housing units through the government eCitizen online portal before the 30 June 2026 deadline.', NULL, NULL, '2026-05-26 17:30:03', '2026-06-29 18:54:49', NULL),
(10, 'policy', 34, 1, 'New Affordable Housing Allocation Policy Framework Released for Public Input', 'allocation-policy-framework', 'The County Assembly Housing Committee has published a draft allocation policy framework for public comment, outlining income bands, household size requirements, and priority scoring for first-time homeowners under the AHP.', '6 min', 'The County Assembly Housing Committee has published a draft allocation policy framework for public comment, outlining income bands, household size requirements, and priority scoring for first-time homeowners under the AHP.', 17, NULL, NULL, NULL, NULL, 'published', 0, 1, 0, NULL, NULL, NULL, 0, '2026-04-18 08:00:00', NULL, 0, 'New Affordable Housing Allocation Policy Framework Released for Public Input', 'The County Assembly Housing Committee has published a draft allocation policy framework for public comment, outlining income bands, household size requirements, and priority scoring for first-time homeowners under the AHP.', NULL, NULL, '2026-05-26 17:30:03', '2026-05-30 13:17:32', NULL),
(11, 'progress_report', 33, 1, 'Saboti Constituency: First 50 Housing Units Ready for Beneficiary Handover', 'saboti-first-50-handover-ready', 'Engineers have issued practical completion certificates for the first 50 units at the Saboti AHP estate following final electrical, plumbing, and structural sign-offs, clearing the way for the formal handover ceremony scheduled for May 2026.', '4 min', 'Engineers have issued practical completion certificates for the first 50 units at the Saboti AHP estate following final electrical, plumbing, and structural sign-offs, clearing the way for the formal handover ceremony scheduled for May 2026.', 18, NULL, NULL, NULL, NULL, 'published', 0, 1, 0, NULL, NULL, NULL, 0, '2026-04-15 08:00:00', NULL, 1, 'Saboti Constituency: First 50 Housing Units Ready for Beneficiary Handover', 'Engineers have issued practical completion certificates for the first 50 units at the Saboti AHP estate following final electrical, plumbing, and structural sign-offs, clearing the way for the formal handover ceremony scheduled for May 2026.', NULL, NULL, '2026-05-26 17:30:03', '2026-07-07 11:46:17', NULL),
(12, 'article', 35, 1, '300 Local Youth Artisans Employed Across Trans-Nzoia AHP Construction Sites', 'local-youth-artisans-employed', 'A county-led youth employment initiative has placed over 300 trained artisans - including masons, carpenters, and electricians - on active AHP construction sites, aligning housing delivery with local economic empowerment goals.', '3 min', 'A county-led youth employment initiative has placed over 300 trained artisans - including masons, carpenters, and electricians - on active AHP construction sites, aligning housing delivery with local economic empowerment goals.', 19, NULL, NULL, NULL, NULL, 'published', 0, 1, 0, NULL, NULL, NULL, 0, '2026-04-12 08:00:00', NULL, 0, '300 Local Youth Artisans Employed Across Trans-Nzoia AHP Construction Sites', 'A county-led youth employment initiative has placed over 300 trained artisans - including masons, carpenters, and electricians - on active AHP construction sites, aligning housing delivery with local economic empowerment goals.', NULL, NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03', NULL),
(13, 'article', 1, 1, 'AHP Programme Update: 1,200 Units Under Active Construction County-Wide', 'programme-update-1200-active-units', 'The latest quarterly programme report confirms that 1,200 affordable housing units are now under active construction across all five constituencies in Trans-Nzoia County, representing a 40% increase on the previous quarter figures.', '5 min', 'The latest quarterly programme report confirms that 1,200 affordable housing units are now under active construction across all five constituencies in Trans-Nzoia County, representing a 40% increase on the previous quarter figures.', 20, NULL, NULL, NULL, NULL, 'published', 0, 1, 0, NULL, NULL, NULL, 0, '2026-04-08 08:00:00', NULL, 0, 'AHP Programme Update: 1,200 Units Under Active Construction County-Wide', 'The latest quarterly programme report confirms that 1,200 affordable housing units are now under active construction across all five constituencies in Trans-Nzoia County, representing a 40% increase on the previous quarter figures.', NULL, NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03', NULL),
(41, 'announcement', 36, 1, 'County Director Confirms June 2026 Project Review Schedule', 'county-director-june-2026-project-review-schedule', 'County project review visits for June 2026 have been confirmed across active affordable housing sites.', '1 min', '<p>County project review visits for June 2026 have been confirmed across active affordable housing sites. Site teams will receive detailed movement plans through the staff portal.</p>', NULL, NULL, NULL, NULL, NULL, 'published', 0, 0, 1, 'County Director Confirms June 2026 Project Review Schedule', NULL, NULL, 0, '2026-06-29 21:18:58', NULL, 0, 'County Director Confirms June 2026 Project Review Schedule', 'Official public announcement for June 2026 project review visits.', NULL, '{\"editor_notes\":\"Demo official public announcement.\"}', '2026-06-29 18:18:58', '2026-06-29 18:33:00', NULL),
(42, 'announcement', 36, 1, 'Beneficiary Verification Desk Opens At Kitale Huduma Centre', 'beneficiary-verification-desk-opens-at-kitale-huduma-centre', 'A beneficiary verification support desk is now available at Kitale Huduma Centre during working hours.', '1 min', '<p>A beneficiary verification support desk is now available at Kitale Huduma Centre during working hours for residents following affordable housing allocation updates.</p>', NULL, NULL, NULL, NULL, NULL, 'published', 0, 0, 1, 'Beneficiary Verification Desk Opens At Kitale Huduma Centre', NULL, NULL, 0, '2026-06-29 20:18:58', NULL, 0, 'Beneficiary Verification Desk Opens At Kitale Huduma Centre', 'Official public announcement for beneficiary verification support.', NULL, '{\"editor_notes\":\"Demo official public announcement.\"}', '2026-06-29 18:18:58', '2026-06-29 18:33:00', NULL),
(43, 'announcement', 36, 1, 'Public Viewing Register Updated For Trans-Nzoia AHP Sites', 'public-viewing-register-updated-for-trans-nzoia-ahp-sites', 'The public viewing register has been updated for active and planning-stage AHP sites.', '1 min', '<p>The public viewing register has been updated for active and planning-stage AHP sites. Residents may review published project information through the official tracker.</p>', NULL, NULL, NULL, NULL, NULL, 'published', 0, 0, 1, 'Public Viewing Register Updated For Trans-Nzoia AHP Sites', NULL, NULL, 0, '2026-06-29 19:18:58', NULL, 0, 'Public Viewing Register Updated For Trans-Nzoia AHP Sites', 'Official public announcement for updated project viewing records.', NULL, '{\"editor_notes\":\"Demo official public announcement.\"}', '2026-06-29 18:18:58', '2026-06-29 18:33:00', NULL),
(44, 'announcement', 36, 1, 'Community Baraza Dates Published For Saboti And Kiminini', 'community-baraza-dates-published-for-saboti-and-kiminini', 'Community baraza dates for Saboti and Kiminini housing updates have been published.', '1 min', '<p>Community baraza dates for Saboti and Kiminini housing updates have been published. Residents should follow official county communication channels for venue details.</p>', NULL, NULL, NULL, NULL, NULL, 'published', 0, 0, 1, 'Community Baraza Dates Published For Saboti And Kiminini', NULL, NULL, 0, '2026-06-29 18:18:58', NULL, 1, 'Community Baraza Dates Published For Saboti And Kiminini', 'Official public announcement for community baraza dates.', NULL, '{\"editor_notes\":\"Demo official public announcement.\"}', '2026-06-29 18:18:58', '2026-06-29 18:33:00', NULL),
(45, 'announcement', 36, 1, 'Affordable Housing Tracker Maintenance Window Announced', 'affordable-housing-tracker-maintenance-window-announced', 'The public tracker will undergo a short maintenance window outside peak hours.', '1 min', '<p>The public tracker will undergo a short maintenance window outside peak hours. Core public project information will remain available immediately after the update.</p>', NULL, NULL, NULL, NULL, NULL, 'published', 0, 0, 1, 'Affordable Housing Tracker Maintenance Window Announced', NULL, NULL, 0, '2026-06-29 17:18:58', NULL, 0, 'Affordable Housing Tracker Maintenance Window Announced', 'Official public announcement for tracker maintenance.', NULL, '{\"editor_notes\":\"Demo official public announcement.\"}', '2026-06-29 18:18:58', '2026-06-29 18:33:00', NULL),
(46, 'announcement', 36, 1, 'Official Progress Note Released For Maili Tatu Estate', 'official-progress-note-released-for-maili-tatu-estate', 'An official progress note has been released for the Maili Tatu Affordable Housing Estate.', '1 min', '<p>An official progress note has been released for the Maili Tatu Affordable Housing Estate. The note summarises current site activity and upcoming public reporting milestones.</p>', NULL, NULL, NULL, NULL, NULL, 'published', 0, 0, 1, 'Official Progress Note Released For Maili Tatu Estate', NULL, NULL, 0, '2026-06-29 16:18:58', NULL, 0, 'Official Progress Note Released For Maili Tatu Estate', 'Official public announcement for Maili Tatu Estate progress.', NULL, '{\"editor_notes\":\"Demo official public announcement.\"}', '2026-06-29 18:18:58', '2026-06-29 18:33:00', NULL);

