(1, 'home', 'Home', 'index.php', '0d0ca10795744b7d0c9ce048e2aad25883b661d97a2268ce5c02437df8674e67', '<?php\nrequire_once __DIR__ . \'/app/core/bootstrap.php\';\n\n$basePath = \'\';\n$activePage = \'home\';\n$homePage = CmsLoader::page(\'home\');\n$projectStats = Project::stats();\n$featuredProjects = Project::withRelations([\'featured\' => \'1\'], 3);\nif (!$featuredProjects) {\n    $featuredProjects = Project::withRelations([], 3);\n}\n$constituencies = Constituency::withProjectCounts();\n$newsItems = home_news_items(9);\n\n$hero = CmsLoader::content($homePage, \'home_hero\', home_defaults(\'home_hero\'));\n$featured = CmsLoader::content($homePage, \'featured_projects\', home_defaults(\'featured_projects\'));\n$coverage = CmsLoader::content($homePage, \'constituency_coverage\', home_defaults(\'constituency_coverage\'));\n$reports = CmsLoader::content($homePage, \'ground_reports\', home_defaults(\'ground_reports\'));\n$cta = CmsLoader::content($homePage, \'ecitizen_cta\', home_defaults(\'ecitizen_cta\'));\n\n$pageTitle = (string)($homePage[\'seo_title\'] ?? \'Trans-Nzoia County | Affordable Housing Project Tracker\');\n$pageDescription = (string)($homePage[\'seo_description\'] ?? \'Trans-Nzoia County Affordable Housing Project Tracker - real-time monitoring of housing construction delivery.\');\n$pageKeywords = (string)($homePage[\'seo_keywords\'] ?? \'Trans-Nzoia affordable housing, AHP Kenya, county housing tracker\');\n$pageAuthor = \'Trans-Nzoia County Government - Department of Land, Housing & Physical Planning\';\n$pageRobots = \'index, follow\';\n$themeColor = \'#163300\';\n$canonicalUrl = (string)($homePage[\'canonical_url\'] ?? \'https://housing.transnzoia.go.ke/\');\n$heroImage = CmsLoader::text($hero, \'background_image\', (string)($homePage[\'hero_image\'] ?? \'uploads/heroes/hero-main.jpg\'));\n$pageStyles = [\n    \'assets/css/global.css\',\n    \'assets/css/pages/index.css\',\n];\n$pageScripts = [\n    \'assets/js/global.js\',\n    \'assets/js/pages/index.js\',\n];\n$headMeta = [\n    \'<meta name=\"geo.region\" content=\"KE-36\">\',\n    \'<meta name=\"geo.placename\" content=\"Trans-Nzoia County, Kenya\">\',\n    \'<meta property=\"og:title\" content=\"\' . Security::e($pageTitle) . \'\">\',\n    \'<meta property=\"og:description\" content=\"\' . Security::e($pageDescription) . \'\">\',\n    \'<meta property=\"og:type\" content=\"website\">\',\n    \'<meta property=\"og:url\" content=\"\' . Security::e($canonicalUrl) . \'\">\',\n    \'<meta property=\"og:image\" content=\"\' . Security::e($heroImage) . \'\">\',\n    \'<meta property=\"og:locale\" content=\"en_KE\">\',\n    \'<meta property=\"og:site_name\" content=\"Trans-Nzoia AHP Tracker\">\',\n    \'<meta name=\"twitter:card\" content=\"summary_large_image\">\',\n    \'<meta name=\"twitter:title\" content=\"\' . Security::e($pageTitle) . \'\">\',\n    \'<meta name=\"twitter:description\" content=\"\' . Security::e($pageDescription) . \'\">\',\n    \'<meta name=\"twitter:image\" content=\"\' . Security::e($heroImage) . \'\">\',\n];\ninclude __DIR__ . \'/app/partials/head.php\';\n?>\n<body>\n<?php include __DIR__ . \'/app/partials/cursor.php\'; ?>\n<?php include __DIR__ . \'/app/partials/skip-link.php\'; ?>\n<?php include __DIR__ . \'/app/partials/navbar.php\'; ?>\n<main id=\"main-content\">\n\n<?php if (CmsLoader::visible($homePage, \'home_hero\')): ?>\n  <section class=\"tracker-hero\" aria-label=\"Programme overview\">\n    <div class=\"tracker-hero-bg\">\n      <img <?= public_image_attrs($heroImage, CmsLoader::text($hero, \'background_alt\', \'Affordable housing construction site in Trans-Nzoia County, Kenya\'), [\'loading\' => \'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \"this.style.display=\'none\'\"]) ?>>\n      <div class=\"tracker-hero-overlay\" aria-hidden=\"true\"></div>\n    </div>\n    <div class=\"container tracker-hero-content\">\n      <div class=\"tracker-hero-inner\">\n        <div class=\"programme-badge\" role=\"status\">\n          <span class=\"programme-badge-dot\" aria-hidden=\"true\"></span>\n          <?= Security::e(CmsLoader::text($hero, \'eyebrow\', \'Ongoing Projects - Trans-Nzoia County\')) ?>\n        </div>\n        <h1 class=\"tracker-hero-title\"><?= nl2br(Security::e(CmsLoader::text($hero, \'title\', \"Affordable Housing\\nProject Tracker\")), false) ?></h1>\n        <p class=\"tracker-hero-subtitle\"><?= Security::e(CmsLoader::text($hero, \'subtitle\', \'Transparent, real-time monitoring of housing construction delivery across all five constituencies of Trans-Nzoia County.\')) ?></p>\n        <div class=\"tracker-hero-cta\">\n          <a href=\"<?= Security::e(CmsLoader::text($hero, \'primary_url\', \'projects.php\')) ?>\" class=\"btn btn-lg btn-white\">\n            <i class=\"fa-solid <?= Security::e(CmsLoader::text($hero, \'primary_icon\', \'fa-table-cells-large\')) ?>\" aria-hidden=\"true\"></i>\n            <?= Security::e(CmsLoader::text($hero, \'primary_label\', \'View All Projects\')) ?>\n          </a>\n          <a href=\"<?= Security::e(CmsLoader::text($hero, \'secondary_url\', \'constituencies.php\')) ?>\" class=\"btn btn-lg btn-outline-white\">\n            <i class=\"fa-solid <?= Security::e(CmsLoader::text($hero, \'secondary_icon\', \'fa-map-location-dot\')) ?>\" aria-hidden=\"true\"></i>\n            <?= Security::e(CmsLoader::text($hero, \'secondary_label\', \'By Constituency\')) ?>\n          </a>\n        </div>\n      </div>\n\n<?php if (CmsLoader::bool($hero, \'show_kpis\', true)): ?>\n      <div class=\"hero-kpi-strip\" role=\"region\" aria-label=\"Programme key metrics\">\n        <?php home_kpi(\'Active Projects\', (int)($projectStats[\'active_projects\'] ?? 0)); ?>\n        <div class=\"hero-kpi-divider\" aria-hidden=\"true\"></div>\n        <?php home_kpi(\'Units Under Construction\', (int)($projectStats[\'total_units\'] ?? 0), \'+\'); ?>\n        <div class=\"hero-kpi-divider\" aria-hidden=\"true\"></div>\n        <?php home_kpi(\'Constituencies Covered\', count($constituencies)); ?>\n        <div class=\"hero-kpi-divider\" aria-hidden=\"true\"></div>\n        <?php home_kpi(\'Avg. Completion\', (int)round((float)($projectStats[\'avg_completion\'] ?? 0)), \'%\'); ?>\n      </div>\n<?php endif; ?>\n    </div>\n  </section>\n<?php endif; ?>\n\n<?php if (CmsLoader::visible($homePage, \'featured_projects\')): ?>\n  <section class=\"section projects-section\" id=\"featured-projects\" aria-labelledby=\"projects-heading\">\n    <div class=\"container\">\n      <?php home_section_header(\'projects-heading\', $featured, \'Featured Projects\', \'Track ongoing affordable housing construction across Trans-Nzoia County.\', \'Full Portfolio\', \'projects.php\'); ?>\n      <div class=\"project-cards-grid stagger-children\">\n<?php foreach (array_slice($featuredProjects, 0, max(1, (int)($featured[\'display_count\'] ?? 3))) as $project): ?>\n        <?php home_project_card($project); ?>\n<?php endforeach; ?>\n<?php if (!$featuredProjects): ?>\n        <div class=\"empty-state\">\n          <strong><?= Security::e(CmsLoader::text($featured, \'empty_title\', \'Featured projects will appear here\')) ?></strong>\n          <p><?= Security::e(CmsLoader::text($featured, \'empty_text\', \'Mark projects as featured in the project editor to populate this section.\')) ?></p>\n        </div>\n<?php endif; ?>\n      </div>\n    </div>\n  </section>\n<?php endif; ?>\n\n<?php if (CmsLoader::visible($homePage, \'constituency_coverage\')): ?>\n  <section class=\"section map-section\" aria-labelledby=\"map-heading\">\n    <div class=\"container\">\n      <?php home_section_header(\'map-heading\', $coverage, \'Coverage by Constituency\', \'All five constituencies are part of the Trans-Nzoia AHP.\', \'All Constituencies\', \'constituencies.php\'); ?>\n      <div class=\"map-interactive-wrap\">\n        <div class=\"map-canvas-wrap\">\n          <svg viewBox=\"0 0 480 400\" class=\"county-map\" role=\"img\" aria-label=\"Interactive map of Trans-Nzoia County showing five constituencies\">\n            <title>Trans-Nzoia County Constituency Map</title>\n            <defs><filter id=\"mapGlow\"><feGaussianBlur stdDeviation=\"3\" result=\"blur\"/><feMerge><feMergeNode in=\"blur\"/><feMergeNode in=\"SourceGraphic\"/></feMerge></filter></defs>\n<?php foreach (home_map_shapes() as $slug => $shape): ?>\n            <?php $c = home_constituency($constituencies, $slug); $projects = (int)($c[\'live_project_count\'] ?? 0); $pct = (int)round((float)($c[\'live_avg_completion\'] ?? 0)); ?>\n            <g class=\"map-constituency\" data-id=\"<?= Security::e($slug) ?>\" data-name=\"<?= Security::e($c[\'name\'] ?? $shape[\'name\']) ?>\" data-projects=\"<?= $projects ?>\" data-status=\"<?= Security::e($pct > 0 ? \'active\' : \'planning\') ?>\" data-units=\"<?= (int)($c[\'live_total_units\'] ?? 0) ?>\" data-pct=\"<?= $pct ?>\" data-link=\"constituency-detail.php?id=<?= Security::e($slug) ?>\" tabindex=\"0\" role=\"button\" aria-label=\"<?= Security::e(($c[\'name\'] ?? $shape[\'name\']) . \' - \' . $projects . \' projects\') ?>\">\n              <path d=\"<?= Security::e($shape[\'path\']) ?>\" class=\"map-path\"/>\n              <text class=\"map-label\" x=\"<?= Security::e($shape[\'x\']) ?>\" y=\"<?= Security::e($shape[\'y\']) ?>\"><?= Security::e($c[\'name\'] ?? $shape[\'name\']) ?></text>\n            </g>\n<?php endforeach; ?>\n            <g class=\"map-sites\" aria-hidden=\"true\">\n              <circle class=\"map-site-dot site-active\" cx=\"178\" cy=\"255\" r=\"6\"/><circle class=\"map-site-pulse\" cx=\"178\" cy=\"255\" r=\"6\"/>\n              <circle class=\"map-site-dot site-active\" cx=\"304\" cy=\"125\" r=\"6\"/><circle class=\"map-site-pulse\" cx=\"304\" cy=\"125\" r=\"6\"/>\n              <circle class=\"map-site-dot site-planning\" cx=\"88\" cy=\"82\" r=\"5\"/>\n            </g>\n          </svg>\n          <div class=\"map-compass\" aria-hidden=\"true\"><i class=\"fa-solid fa-location-crosshairs\"></i><span>N</span></div>\n          <div class=\"map-legend\" aria-hidden=\"true\">\n            <span class=\"map-legend-item\"><span class=\"map-legend-dot map-legend-active\"></span><?= Security::e(CmsLoader::text($coverage, \'legend_active\', \'Active\')) ?></span>\n            <span class=\"map-legend-item\"><span class=\"map-legend-dot map-legend-plan\"></span><?= Security::e(CmsLoader::text($coverage, \'legend_planning\', \'Planning\')) ?></span>\n            <span class=\"map-legend-item\"><i class=\"fa-solid fa-location-dot\" style=\"color:var(--lime-muted);font-size:11px\"></i> <?= Security::e(CmsLoader::text($coverage, \'legend_site\', \'Project site\')) ?></span>\n          </div>\n        </div>\n        <aside class=\"map-side-panel\" id=\"mapPanel\" aria-live=\"polite\">\n          <div class=\"map-panel-default\" id=\"mapPanelDefault\">\n            <i class=\"fa-solid fa-map-location-dot map-panel-icon\" aria-hidden=\"true\"></i>\n            <p class=\"map-panel-hint\"><?= Security::e(CmsLoader::text($coverage, \'panel_hint\', \'Click a constituency on the map to see project data\')) ?></p>\n            <div class=\"map-panel-overview\">\n              <div class=\"map-ov-item\"><span class=\"map-ov-val\"><?= Security::e(format_number(count($constituencies))) ?></span><span class=\"map-ov-lbl\">Constituencies</span></div>\n              <div class=\"map-ov-item\"><span class=\"map-ov-val\"><?= Security::e(format_number((int)($projectStats[\'active_projects\'] ?? 0))) ?></span><span class=\"map-ov-lbl\">Active Projects</span></div>\n              <div class=\"map-ov-item\"><span class=\"map-ov-val\"><?= Security::e(format_number((int)($projectStats[\'total_units\'] ?? 0))) ?>+</span><span class=\"map-ov-lbl\">Units Planned</span></div>\n            </div>\n          </div>\n          <div class=\"map-panel-detail\" id=\"mapPanelDetail\"></div>\n        </aside>\n      </div>\n    </div>\n  </section>\n<?php endif; ?>\n\n<?php if (CmsLoader::visible($homePage, \'ground_reports\')): ?>\n  <section class=\"section news-section\" aria-labelledby=\"news-heading\">\n    <div class=\"container\">\n      <?php home_section_header(\'news-heading\', $reports, \'From the Ground\', \'Project milestones, tender notices, and official clearances.\', \'All Reports\', \'news.php\'); ?>\n      <div class=\"news-asymmetric\">\n<?php if ($newsItems): ?>\n        <?php home_news_card($newsItems[0], true); ?>\n        <div class=\"news-stack\">\n<?php foreach (array_slice($newsItems, 1, max(0, (int)($reports[\'compact_count\'] ?? 2))) as $item): ?>\n          <?php home_news_card($item, false); ?>\n<?php endforeach; ?>\n        </div>\n        <aside class=\"news-alerts-sidebar\" aria-label=\"Latest programme alerts\">\n          <div class=\"nas-header\"><i class=\"fa-solid fa-bolt nas-icon\" aria-hidden=\"true\"></i><span class=\"nas-title\"><?= Security::e(CmsLoader::text($reports, \'alerts_title\', \'Latest Alerts\')) ?></span></div>\n          <ul class=\"nas-list\">\n<?php foreach (array_slice($newsItems, 0, max(1, (int)($reports[\'alert_count\'] ?? 6))) as $index => $item): ?>\n            <li class=\"nas-item <?= $index === 0 ? \'nas-item--urgent\' : \'\' ?>\">\n              <span class=\"nas-dot\" aria-hidden=\"true\"></span>\n              <div class=\"nas-content\">\n                <span class=\"nas-tag\"><?= Security::e($item[\'category_name\'] ?? \'Report\') ?></span>\n                <a href=\"news-article.php?id=<?= Security::e($item[\'slug\']) ?>\" class=\"nas-headline\"><?= Security::e($item[\'title\']) ?></a>\n                <time class=\"nas-time\" datetime=\"<?= Security::e(substr((string)$item[\'published_at\'], 0, 10)) ?>\"><?= Security::e(format_date($item[\'published_at\'] ?? null, \'d M Y\')) ?></time>\n              </div>\n            </li>\n<?php endforeach; ?>\n          </ul>\n        </aside>\n<?php else: ?>\n        <div class=\"empty-state\">\n          <strong><?= Security::e(CmsLoader::text($reports, \'empty_title\', \'Reports will appear here\')) ?></strong>\n          <p><?= Security::e(CmsLoader::text($reports, \'empty_text\', \'Published news and alerts will populate this live section.\')) ?></p>\n        </div>\n<?php endif; ?>\n      </div>\n    </div>\n  </section>\n<?php endif; ?>\n\n<?php if (CmsLoader::visible($homePage, \'ecitizen_cta\')): ?>\n  <section class=\"ecitizen-cta\" aria-labelledby=\"ecitizen-heading\">\n    <div class=\"ecitizen-cta-bg\" aria-hidden=\"true\">\n      <img <?= public_image_attrs(CmsLoader::text($cta, \'background_image\', \'uploads/site-photos/maili-tatu-2.jpg\'), \'\', [\'onerror\' => \"this.style.display=\'none\'\"]) ?>>\n      <div class=\"ecitizen-cta-overlay\"></div>\n    </div>\n    <div class=\"container\">\n      <div class=\"ecitizen-inner fade-up\">\n        <div class=\"ecitizen-left\">\n          <div class=\"ecitizen-eyebrow\">\n            <img <?= public_image_attrs(CmsLoader::text($cta, \'logo_image\', \'uploads/logos/BomaYanguLogo.png\'), \'Boma Yangu\', [\'onerror\' => \"this.style.display=\'none\'\"]) ?>>\n            <span><?= Security::e(CmsLoader::text($cta, \'eyebrow\', \'Boma Yangu - eCitizen\')) ?></span>\n          </div>\n          <h2 id=\"ecitizen-heading\" class=\"ecitizen-headline\"><?= nl2br(Security::e(CmsLoader::text($cta, \'title\', \"Your Home.\\nApplied Online.\")), false) ?></h2>\n          <p class=\"ecitizen-sub\"><?= Security::e(CmsLoader::text($cta, \'subtitle\', \'Register on the national Boma Yangu portal via eCitizen.\')) ?></p>\n          <div class=\"ecitizen-actions\">\n            <a href=\"<?= Security::e(CmsLoader::text($cta, \'primary_url\', \'https://ecitizen.go.ke\')) ?>\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ecitizen-btn-main\">\n              <?= Security::e(CmsLoader::text($cta, \'primary_label\', \'Apply via eCitizen\')) ?> <i class=\"fa-solid fa-arrow-up-right-from-square\" aria-hidden=\"true\"></i>\n            </a>\n            <a href=\"<?= Security::e(CmsLoader::text($cta, \'secondary_url\', \'about.php\')) ?>\" class=\"ecitizen-btn-ghost\">\n              <?= Security::e(CmsLoader::text($cta, \'secondary_label\', \'About the programme\')) ?> <i class=\"fa-solid fa-arrow-right\" aria-hidden=\"true\"></i>\n            </a>\n          </div>\n        </div>\n        <div class=\"ecitizen-steps\" aria-label=\"How to apply via eCitizen\">\n          <h3 class=\"ecitizen-steps-title\"><i class=\"fa-solid fa-list-check\" aria-hidden=\"true\"></i> How to Apply</h3>\n          <div class=\"ecitizen-steps-grid\">\n<?php for ($i = 1; $i <= 4; $i++): ?>\n            <div class=\"ecitizen-step-card\">\n              <div class=\"ecitizen-step-icon-wrap\">\n                <i class=\"fa-solid <?= Security::e(CmsLoader::text($cta, \"step_{$i}_icon\", \'fa-circle-check\')) ?>\" aria-hidden=\"true\"></i>\n                <span class=\"ecitizen-step-num\"><?= str_pad((string)$i, 2, \'0\', STR_PAD_LEFT) ?></span>\n              </div>\n              <strong><?= Security::e(CmsLoader::text($cta, \"step_{$i}_title\", \'Application step\')) ?></strong>\n              <p><?= Security::e(CmsLoader::text($cta, \"step_{$i}_body\", \'Complete this step to continue.\')) ?></p>\n            </div>\n<?php endfor; ?>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n<?php endif; ?>\n\n</main>\n\n<?php include __DIR__ . \'/app/partials/footer.php\'; ?>\n<?php include __DIR__ . \'/app/partials/back-to-top.php\'; ?>\n<?php include __DIR__ . \'/app/partials/mobile-menu.php\'; ?>\n<?php include __DIR__ . \'/app/partials/scripts.php\'; ?>\n</body>\n</html>\n\n<?php\nfunction home_defaults(string $key): array\n{\n    return match ($key) {\n        \'home_hero\' => [\n            \'eyebrow\' => \'Ongoing Projects - Trans-Nzoia County\',\n            \'title\' => \"Affordable Housing\\nProject Tracker\",\n            \'subtitle\' => \'Transparent, real-time monitoring of housing construction delivery across all five constituencies of Trans-Nzoia County.\',\n            \'background_image\' => \'uploads/heroes/hero-main.jpg\',\n            \'background_alt\' => \'Affordable housing construction site in Trans-Nzoia County, Kenya\',\n            \'primary_label\' => \'View All Projects\',\n            \'primary_url\' => \'projects.php\',\n            \'primary_icon\' => \'fa-table-cells-large\',\n            \'secondary_label\' => \'By Constituency\',\n            \'secondary_url\' => \'constituencies.php\',\n            \'secondary_icon\' => \'fa-map-location-dot\',\n            \'show_kpis\' => \'1\',\n        ],\n        \'featured_projects\' => [\'title\' => \'Featured Projects\', \'subtitle\' => \'Track ongoing affordable housing construction across Trans-Nzoia County.\', \'button_label\' => \'Full Portfolio\', \'button_url\' => \'projects.php\'],\n        \'constituency_coverage\' => [\'title\' => \'Coverage by Constituency\', \'subtitle\' => \'All five constituencies are part of the Trans-Nzoia AHP.\', \'button_label\' => \'All Constituencies\', \'button_url\' => \'constituencies.php\'],\n        \'ground_reports\' => [\'title\' => \'From the Ground\', \'subtitle\' => \'Project milestones, tender notices, and official clearances.\', \'button_label\' => \'All Reports\', \'button_url\' => \'news.php\', \'alerts_title\' => \'Latest Alerts\'],\n        \'ecitizen_cta\' => [\'title\' => \"Your Home.\\nApplied Online.\", \'subtitle\' => \'Register on the national Boma Yangu portal via eCitizen.\', \'primary_label\' => \'Apply via eCitizen\', \'primary_url\' => \'https://ecitizen.go.ke\'],\n        default => [],\n    };\n}\n\nfunction home_kpi(string $label, int $value, string $suffix = \'\'): void\n{\n    ?>\n    <div class=\"hero-kpi-item\">\n      <span class=\"hero-kpi-number\" data-count=\"<?= $value ?>\" data-suffix=\"<?= Security::e($suffix) ?>\" aria-label=\"<?= Security::e(format_number($value) . $suffix . \' \' . $label) ?>\">0</span>\n      <span class=\"hero-kpi-label\"><?= Security::e($label) ?></span>\n    </div>\n    <?php\n}\n\nfunction home_section_header(string $id, array $content, string $fallbackTitle, string $fallbackSubtitle, string $fallbackButton, string $fallbackUrl): void\n{\n    ?>\n    <div class=\"split-section-header fade-up\">\n      <div class=\"split-section-left\">\n        <span class=\"accent-line\"></span>\n        <h2 id=\"<?= Security::e($id) ?>\" class=\"section-title\"><?= Security::e(CmsLoader::text($content, \'title\', $fallbackTitle)) ?></h2>\n        <p class=\"section-subtitle\" style=\"margin-bottom:0\"><?= Security::e(CmsLoader::text($content, \'subtitle\', $fallbackSubtitle)) ?></p>\n      </div>\n      <div class=\"split-section-right\">\n        <a href=\"<?= Security::e(CmsLoader::text($content, \'button_url\', $fallbackUrl)) ?>\" class=\"btn btn-outline\">\n          <?= Security::e(CmsLoader::text($content, \'button_label\', $fallbackButton)) ?> <i class=\"fa-solid fa-arrow-right\" aria-hidden=\"true\"></i>\n        </a>\n      </div>\n    </div>\n    <?php\n}\n\nfunction home_project_card(array $project): void\n{\n    $image = home_project_image($project);\n    $status = status_label($project[\'status\'] ?? \'planning\');\n    $pct = (int)($project[\'pct_complete\'] ?? 0);\n    ?>\n    <article class=\"ptc\">\n      <div class=\"ptc-image\">\n        <img <?= public_image_attrs($image, ($project[\'name\'] ?? \'Project\') . \' construction site\', [\'onerror\' => \"this.parentElement.classList.add(\'ptc-img-fallback\')\"]) ?>>\n        <div class=\"ptc-image-overlay\" aria-hidden=\"true\"></div>\n        <div class=\"ptc-badges\">\n          <span class=\"badge <?= ($project[\'status\'] ?? \'\') === \'active\' ? \'badge-ongoing\' : \'badge-warning\' ?>\"><?= Security::e($status) ?></span>\n          <span class=\"ptc-category-tag\"><?= Security::e($project[\'category_name\'] ?? \'AHP\') ?></span>\n        </div>\n      </div>\n      <div class=\"ptc-body\">\n        <div class=\"ptc-location\"><i class=\"fa-solid fa-location-dot\" aria-hidden=\"true\"></i> <?= Security::e(($project[\'constituency_name\'] ?? \'Trans-Nzoia\') . \' Constituency - \' . ($project[\'ward_name\'] ?? $project[\'location_label\'] ?? \'\')) ?></div>\n        <h3 class=\"ptc-title\"><?= Security::e($project[\'name\'] ?? \'Project\') ?></h3>\n        <div class=\"ptc-stats-row\">\n          <div class=\"ptc-stat\"><span class=\"ptc-stat-val\"><?= Security::e(format_number((int)($project[\'units\'] ?? 0))) ?></span><span class=\"ptc-stat-lbl\">Units</span></div>\n          <div class=\"ptc-stat-sep\" aria-hidden=\"true\"></div>\n          <div class=\"ptc-stat\"><span class=\"ptc-stat-val ptc-stat-pct\"><?= $pct ?>%</span><span class=\"ptc-stat-lbl\">Complete</span></div>\n          <div class=\"ptc-stat-sep\" aria-hidden=\"true\"></div>\n          <div class=\"ptc-stat\"><span class=\"ptc-stat-val\"><?= Security::e(home_delivery_year($project[\'est_delivery\'] ?? null)) ?></span><span class=\"ptc-stat-lbl\">Est. Delivery</span></div>\n        </div>\n        <div class=\"ptc-progress\" role=\"progressbar\" aria-valuenow=\"<?= $pct ?>\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-label=\"Construction <?= $pct ?>% complete\">\n          <div class=\"ptc-progress-track\"><div class=\"ptc-progress-fill\" data-progress=\"<?= $pct ?>\"></div></div>\n          <span class=\"ptc-progress-label\"><?= $pct ?>% Completed</span>\n        </div>\n        <div class=\"ptc-actions\">\n          <a href=\"project-detail.php?id=<?= Security::e($project[\'slug\'] ?? \'\') ?>\" class=\"btn btn-primary btn-sm\">View Details</a>\n          <a href=\"https://ecitizen.go.ke\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-outline btn-sm\">Apply on eCitizen <i class=\"fa-solid fa-arrow-up-right-from-square\" aria-hidden=\"true\"></i></a>\n        </div>\n      </div>\n    </article>\n    <?php\n}\n\nfunction home_project_image(array $project): string\n{\n    if (!empty($project[\'hero_image\'])) {\n        return (string)$project[\'hero_image\'];\n    }\n\n    $images = json_decode((string)($project[\'images_json\'] ?? \'\'), true);\n    return is_array($images) && !empty($images[0]) ? (string)$images[0] : \'uploads/heroes/hero-main.jpg\';\n}\n\nfunction home_delivery_year(mixed $date): string\n{\n    if (!$date) {\n        return \'TBD\';\n    }\n\n    $timestamp = strtotime((string)$date);\n    return $timestamp ? date(\'Y\', $timestamp) : (string)$date;\n}\n\nfunction home_constituency(array $rows, string $slug): array\n{\n    foreach ($rows as $row) {\n        if (($row[\'slug\'] ?? \'\') === $slug) {\n            return $row;\n        }\n    }\n\n    return [];\n}\n\nfunction home_map_shapes(): array\n{\n    return [\n        \'endebess\' => [\'name\' => \'Endebess\', \'path\' => \'M 20,20 L 220,20 L 220,180 L 120,200 L 20,160 Z\', \'x\' => \'112\', \'y\' => \'98\'],\n        \'cherangany\' => [\'name\' => \'Cherangany\', \'path\' => \'M 220,20 L 460,20 L 460,230 L 260,230 L 220,180 Z\', \'x\' => \'348\', \'y\' => \'112\'],\n        \'kiminini\' => [\'name\' => \'Kiminini\', \'path\' => \'M 20,160 L 120,200 L 120,380 L 20,380 Z\', \'x\' => \'62\', \'y\' => \'290\'],\n        \'saboti\' => [\'name\' => \'Saboti\', \'path\' => \'M 120,200 L 220,180 L 260,230 L 260,380 L 120,380 Z\', \'x\' => \'186\', \'y\' => \'305\'],\n        \'kwanza\' => [\'name\' => \'Kwanza\', \'path\' => \'M 260,230 L 460,230 L 460,380 L 260,380 Z\', \'x\' => \'362\', \'y\' => \'310\'],\n    ];\n}\n\nfunction home_news_items(int $limit): array\n{\n    try {\n        return Database::fetchAll(\"\n            SELECT na.*, nc.name AS category_name, nc.slug AS category_slug, ml.path AS image_path\n            FROM news_articles na\n            LEFT JOIN news_categories nc ON nc.id = na.category_id\n            LEFT JOIN media_library ml ON ml.id = na.featured_image_id\n            WHERE na.status = \'published\'\n            ORDER BY COALESCE(na.published_at, na.created_at) DESC, na.id DESC\n            LIMIT {$limit}\n        \");\n    } catch (Throwable $e) {\n        return [];\n    }\n}\n\nfunction home_news_card(array $item, bool $feature): void\n{\n    $image = (string)($item[\'image_path\'] ?? \'uploads/news/modern-market.jpg\');\n    $class = $feature ? \'news-card news-card--feature\' : \'news-card news-card--compact\';\n    ?>\n    <article class=\"<?= $class ?>\">\n      <div class=\"news-card-img\">\n        <img <?= public_image_attrs($image, $item[\'title\'] ?? \'Programme report\', [\'onerror\' => \"this.parentElement.classList.add(\'news-img-fallback\')\"]) ?>>\n        <span class=\"news-cat-badge news-cat-milestone\"><i class=\"fa-solid fa-flag-checkered\" aria-hidden=\"true\"></i> <?= Security::e($item[\'category_name\'] ?? \'Report\') ?></span>\n      </div>\n      <div class=\"news-card-body\">\n        <time class=\"news-date\" datetime=\"<?= Security::e(substr((string)($item[\'published_at\'] ?? $item[\'created_at\'] ?? \'\'), 0, 10)) ?>\"><i class=\"fa-regular fa-calendar\" aria-hidden=\"true\"></i> <?= Security::e(format_date($item[\'published_at\'] ?? $item[\'created_at\'] ?? null, \'d M Y\')) ?></time>\n        <h3 class=\"news-card-title\"><?= Security::e($item[\'title\'] ?? \'Programme report\') ?></h3>\n        <p class=\"news-card-text <?= $feature ? \'\' : \'line-clamp-2\' ?>\"><?= Security::e($item[\'excerpt\'] ?? \'\') ?></p>\n<?php if ($feature): ?>\n        <a href=\"news-article.php?id=<?= Security::e($item[\'slug\'] ?? \'\') ?>\" class=\"news-read-link\">Read full report <i class=\"fa-solid fa-arrow-right\" aria-hidden=\"true\"></i></a>\n<?php endif; ?>\n      </div>\n    </article>\n    <?php\n}\n', '\'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \"this.style.display=\'none\'\"]) ?>> \" class=\"btn btn-lg btn-white\"> \" aria-hidden=\"true\"> \" class=\"btn btn-lg btn-outline-white\"> \" aria-hidden=\"true\"> Trans-Nzoia County Constituency Map \" data-name=\" \" data-projects=\" \" data-status=\" 0 ? \'active\' : \'planning\') ?>\" data-units=\" \" data-pct=\" \" data-link=\"constituency-detail.php?id= \" tabindex=\"0\" role=\"button\" aria-label=\" \"> \" class=\"map-path\"/> \" y=\" \"> N Constituencies Active Projects + Units Planned \"> \" class=\"nas-headline\"> \"> \"this.style.display=\'none\'\"]) ?>> \"this.style.display=\'none\'\"]) ?>> \" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ecitizen-btn-main\"> \" class=\"ecitizen-btn-ghost\"> How to Apply \" aria-hidden=\"true\"> \" data-suffix=\" \" aria-label=\" \">0 \" class=\"section-title\"> \" class=\"btn btn-outline\"> \"this.parentElement.classList.add(\'ptc-img-fallback\')\"]) ?>> \"> Units % Complete Est. Delivery \" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-label=\"Construction % complete\"> \"> % Completed \" class=\"btn btn-primary btn-sm\">View Details Apply on eCitizen \"> \"this.parentElement.classList.add(\'news-img-fallback\')\"]) ?>> \"> \"> \" class=\"news-read-link\">Read full report <?php }', '{\"page_slug\":\"home\",\"page_label\":\"Home\",\"file_path\":\"index.php\",\"source_hash\":\"0d0ca10795744b7d0c9ce048e2aad25883b661d97a2268ce5c02437df8674e67\",\"title\":\"Trans-Nzoia County Constituency Map\",\"meta_description\":\"\",\"headings\":[{\"level\":3,\"text\":\"How to Apply\"},{\"level\":2,\"text\":\"\\\" class=\\\"section-title\\\">\"}],\"links\":[{\"href\":\"<?= Security::e(CmsLoader::text($hero,\",\"text\":\"\\\" class=\\\"btn btn-lg btn-white\\\"> \\\" aria-hidden=\\\"true\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($hero,\",\"text\":\"\\\" class=\\\"btn btn-lg btn-outline-white\\\"> \\\" aria-hidden=\\\"true\\\">\"},{\"href\":\"news-article.php?id=<?= Security::e($item[\",\"text\":\"\\\" class=\\\"nas-headline\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($cta,\",\"text\":\"\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ecitizen-btn-main\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($cta,\",\"text\":\"\\\" class=\\\"ecitizen-btn-ghost\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($content,\",\"text\":\"\\\" class=\\\"btn btn-outline\\\">\"},{\"href\":\"project-detail.php?id=<?= Security::e($project[\",\"text\":\"\\\" class=\\\"btn btn-primary btn-sm\\\">View Details\"},{\"href\":\"https://ecitizen.go.ke\",\"text\":\"Apply on eCitizen\"},{\"href\":\"news-article.php?id=<?= Security::e($item[\",\"text\":\"\\\" class=\\\"news-read-link\\\">Read full report\"}],\"images\":[{\"src\":\"\",\"alt\":\"\"},{\"src\":\"\",\"alt\":\"\"},{\"src\":\"\",\"alt\":\"\"},{\"src\":\"\",\"alt\":\"\"},{\"src\":\"\",\"alt\":\"\"}],\"forms\":[],\"cms_keys\":[\"home_hero\",\"featured_projects\",\"constituency_coverage\",\"ground_reports\",\"ecitizen_cta\"],\"text_content\":\"\'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>> \\\" class=\\\"btn btn-lg btn-white\\\"> \\\" aria-hidden=\\\"true\\\"> \\\" class=\\\"btn btn-lg btn-outline-white\\\"> \\\" aria-hidden=\\\"true\\\"> Trans-Nzoia County Constituency Map \\\" data-name=\\\" \\\" data-projects=\\\" \\\" data-status=\\\" 0 ? \'active\' : \'planning\') ?>\\\" data-units=\\\" \\\" data-pct=\\\" \\\" data-link=\\\"constituency-detail.php?id= \\\" tabindex=\\\"0\\\" role=\\\"button\\\" aria-label=\\\" \\\"> \\\" class=\\\"map-path\\\"/> \\\" y=\\\" \\\"> N Constituencies Active Projects + Units Planned \\\"> \\\" class=\\\"nas-headline\\\"> \\\"> \\\"this.style.display=\'none\'\\\"]) ?>> \\\"this.style.display=\'none\'\\\"]) ?>> \\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ecitizen-btn-main\\\"> \\\" class=\\\"ecitizen-btn-ghost\\\"> How to Apply \\\" aria-hidden=\\\"true\\\"> \\\" data-suffix=\\\" \\\" aria-label=\\\" \\\">0 \\\" class=\\\"section-title\\\"> \\\" class=\\\"btn btn-outline\\\"> \\\"this.parentElement.classList.add(\'ptc-img-fallback\')\\\"]) ?>> \\\"> Units % Complete Est. Delivery \\\" aria-valuemin=\\\"0\\\" aria-valuemax=\\\"100\\\" aria-label=\\\"Construction % complete\\\"> \\\"> % Completed \\\" class=\\\"btn btn-primary btn-sm\\\">View Details Apply on eCitizen \\\"> \\\"this.parentElement.classList.add(\'news-img-fallback\')\\\"]) ?>> \\\"> \\\"> \\\" class=\\\"news-read-link\\\">Read full report <?php }\",\"raw_source\":\"<?php\\nrequire_once __DIR__ . \'/app/core/bootstrap.php\';\\n\\n$basePath = \'\';\\n$activePage = \'home\';\\n$homePage = CmsLoader::page(\'home\');\\n$projectStats = Project::stats();\\n$featuredProjects = Project::withRelations([\'featured\' => \'1\'], 3);\\nif (!$featuredProjects) {\\n    $featuredProjects = Project::withRelations([], 3);\\n}\\n$constituencies = Constituency::withProjectCounts();\\n$newsItems = home_news_items(9);\\n\\n$hero = CmsLoader::content($homePage, \'home_hero\', home_defaults(\'home_hero\'));\\n$featured = CmsLoader::content($homePage, \'featured_projects\', home_defaults(\'featured_projects\'));\\n$coverage = CmsLoader::content($homePage, \'constituency_coverage\', home_defaults(\'constituency_coverage\'));\\n$reports = CmsLoader::content($homePage, \'ground_reports\', home_defaults(\'ground_reports\'));\\n$cta = CmsLoader::content($homePage, \'ecitizen_cta\', home_defaults(\'ecitizen_cta\'));\\n\\n$pageTitle = (string)($homePage[\'seo_title\'] ?? \'Trans-Nzoia County | Affordable Housing Project Tracker\');\\n$pageDescription = (string)($homePage[\'seo_description\'] ?? \'Trans-Nzoia County Affordable Housing Project Tracker - real-time monitoring of housing construction delivery.\');\\n$pageKeywords = (string)($homePage[\'seo_keywords\'] ?? \'Trans-Nzoia affordable housing, AHP Kenya, county housing tracker\');\\n$pageAuthor = \'Trans-Nzoia County Government - Department of Land, Housing & Physical Planning\';\\n$pageRobots = \'index, follow\';\\n$themeColor = \'#163300\';\\n$canonicalUrl = (string)($homePage[\'canonical_url\'] ?? \'https://housing.transnzoia.go.ke/\');\\n$heroImage = CmsLoader::text($hero, \'background_image\', (string)($homePage[\'hero_image\'] ?? \'uploads/heroes/hero-main.jpg\'));\\n$pageStyles = [\\n    \'assets/css/global.css\',\\n    \'assets/css/pages/index.css\',\\n];\\n$pageScripts = [\\n    \'assets/js/global.js\',\\n    \'assets/js/pages/index.js\',\\n];\\n$headMeta = [\\n    \'<meta name=\\\"geo.region\\\" content=\\\"KE-36\\\">\',\\n    \'<meta name=\\\"geo.placename\\\" content=\\\"Trans-Nzoia County, Kenya\\\">\',\\n    \'<meta property=\\\"og:title\\\" content=\\\"\' . Security::e($pageTitle) . \'\\\">\',\\n    \'<meta property=\\\"og:description\\\" content=\\\"\' . Security::e($pageDescription) . \'\\\">\',\\n    \'<meta property=\\\"og:type\\\" content=\\\"website\\\">\',\\n    \'<meta property=\\\"og:url\\\" content=\\\"\' . Security::e($canonicalUrl) . \'\\\">\',\\n    \'<meta property=\\\"og:image\\\" content=\\\"\' . Security::e($heroImage) . \'\\\">\',\\n    \'<meta property=\\\"og:locale\\\" content=\\\"en_KE\\\">\',\\n    \'<meta property=\\\"og:site_name\\\" content=\\\"Trans-Nzoia AHP Tracker\\\">\',\\n    \'<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\">\',\\n    \'<meta name=\\\"twitter:title\\\" content=\\\"\' . Security::e($pageTitle) . \'\\\">\',\\n    \'<meta name=\\\"twitter:description\\\" content=\\\"\' . Security::e($pageDescription) . \'\\\">\',\\n    \'<meta name=\\\"twitter:image\\\" content=\\\"\' . Security::e($heroImage) . \'\\\">\',\\n];\\ninclude __DIR__ . \'/app/partials/head.php\';\\n?>\\n<body>\\n<?php include __DIR__ . \'/app/partials/cursor.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/skip-link.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/navbar.php\'; ?>\\n<main id=\\\"main-content\\\">\\n\\n<?php if (CmsLoader::visible($homePage, \'home_hero\')): ?>\\n  <section class=\\\"tracker-hero\\\" aria-label=\\\"Programme overview\\\">\\n    <div class=\\\"tracker-hero-bg\\\">\\n      <img <?= public_image_attrs($heroImage, CmsLoader::text($hero, \'background_alt\', \'Affordable housing construction site in Trans-Nzoia County, Kenya\'), [\'loading\' => \'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>>\\n      <div class=\\\"tracker-hero-overlay\\\" aria-hidden=\\\"true\\\"></div>\\n    </div>\\n    <div class=\\\"container tracker-hero-content\\\">\\n      <div class=\\\"tracker-hero-inner\\\">\\n        <div class=\\\"programme-badge\\\" role=\\\"status\\\">\\n          <span class=\\\"programme-badge-dot\\\" aria-hidden=\\\"true\\\"></span>\\n          <?= Security::e(CmsLoader::text($hero, \'eyebrow\', \'Ongoing Projects - Trans-Nzoia County\')) ?>\\n        </div>\\n        <h1 class=\\\"tracker-hero-title\\\"><?= nl2br(Security::e(CmsLoader::text($hero, \'title\', \\\"Affordable Housing\\\\nProject Tracker\\\")), false) ?></h1>\\n        <p class=\\\"tracker-hero-subtitle\\\"><?= Security::e(CmsLoader::text($hero, \'subtitle\', \'Transparent, real-time monitoring of housing construction delivery across all five constituencies of Trans-Nzoia County.\')) ?></p>\\n        <div class=\\\"tracker-hero-cta\\\">\\n          <a href=\\\"<?= Security::e(CmsLoader::text($hero, \'primary_url\', \'projects.php\')) ?>\\\" class=\\\"btn btn-lg btn-white\\\">\\n            <i class=\\\"fa-solid <?= Security::e(CmsLoader::text($hero, \'primary_icon\', \'fa-table-cells-large\')) ?>\\\" aria-hidden=\\\"true\\\"></i>\\n            <?= Security::e(CmsLoader::text($hero, \'primary_label\', \'View All Projects\')) ?>\\n          </a>\\n          <a href=\\\"<?= Security::e(CmsLoader::text($hero, \'secondary_url\', \'constituencies.php\')) ?>\\\" class=\\\"btn btn-lg btn-outline-white\\\">\\n            <i class=\\\"fa-solid <?= Security::e(CmsLoader::text($hero, \'secondary_icon\', \'fa-map-location-dot\')) ?>\\\" aria-hidden=\\\"true\\\"></i>\\n            <?= Security::e(CmsLoader::text($hero, \'secondary_label\', \'By Constituency\')) ?>\\n          </a>\\n        </div>\\n      </div>\\n\\n<?php if (CmsLoader::bool($hero, \'show_kpis\', true)): ?>\\n      <div class=\\\"hero-kpi-strip\\\" role=\\\"region\\\" aria-label=\\\"Programme key metrics\\\">\\n        <?php home_kpi(\'Active Projects\', (int)($projectStats[\'active_projects\'] ?? 0)); ?>\\n        <div class=\\\"hero-kpi-divider\\\" aria-hidden=\\\"true\\\"></div>\\n        <?php home_kpi(\'Units Under Construction\', (int)($projectStats[\'total_units\'] ?? 0), \'+\'); ?>\\n        <div class=\\\"hero-kpi-divider\\\" aria-hidden=\\\"true\\\"></div>\\n        <?php home_kpi(\'Constituencies Covered\', count($constituencies)); ?>\\n        <div class=\\\"hero-kpi-divider\\\" aria-hidden=\\\"true\\\"></div>\\n        <?php home_kpi(\'Avg. Completion\', (int)round((float)($projectStats[\'avg_completion\'] ?? 0)), \'%\'); ?>\\n      </div>\\n<?php endif; ?>\\n    </div>\\n  </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($homePage, \'featured_projects\')): ?>\\n  <section class=\\\"section projects-section\\\" id=\\\"featured-projects\\\" aria-labelledby=\\\"projects-heading\\\">\\n    <div class=\\\"container\\\">\\n      <?php home_section_header(\'projects-heading\', $featured, \'Featured Projects\', \'Track ongoing affordable housing construction across Trans-Nzoia County.\', \'Full Portfolio\', \'projects.php\'); ?>\\n      <div class=\\\"project-cards-grid stagger-children\\\">\\n<?php foreach (array_slice($featuredProjects, 0, max(1, (int)($featured[\'display_count\'] ?? 3))) as $project): ?>\\n        <?php home_project_card($project); ?>\\n<?php endforeach; ?>\\n<?php if (!$featuredProjects): ?>\\n        <div class=\\\"empty-state\\\">\\n          <strong><?= Security::e(CmsLoader::text($featured, \'empty_title\', \'Featured projects will appear here\')) ?></strong>\\n          <p><?= Security::e(CmsLoader::text($featured, \'empty_text\', \'Mark projects as featured in the project editor to populate this section.\')) ?></p>\\n        </div>\\n<?php endif; ?>\\n      </div>\\n    </div>\\n  </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($homePage, \'constituency_coverage\')): ?>\\n  <section class=\\\"section map-section\\\" aria-labelledby=\\\"map-heading\\\">\\n    <div class=\\\"container\\\">\\n      <?php home_section_header(\'map-heading\', $coverage, \'Coverage by Constituency\', \'All five constituencies are part of the Trans-Nzoia AHP.\', \'All Constituencies\', \'constituencies.php\'); ?>\\n      <div class=\\\"map-interactive-wrap\\\">\\n        <div class=\\\"map-canvas-wrap\\\">\\n          <svg viewBox=\\\"0 0 480 400\\\" class=\\\"county-map\\\" role=\\\"img\\\" aria-label=\\\"Interactive map of Trans-Nzoia County showing five constituencies\\\">\\n            <title>Trans-Nzoia County Constituency Map</title>\\n            <defs><filter id=\\\"mapGlow\\\"><feGaussianBlur stdDeviation=\\\"3\\\" result=\\\"blur\\\"/><feMerge><feMergeNode in=\\\"blur\\\"/><feMergeNode in=\\\"SourceGraphic\\\"/></feMerge></filter></defs>\\n<?php foreach (home_map_shapes() as $slug => $shape): ?>\\n            <?php $c = home_constituency($constituencies, $slug); $projects = (int)($c[\'live_project_count\'] ?? 0); $pct = (int)round((float)($c[\'live_avg_completion\'] ?? 0)); ?>\\n            <g class=\\\"map-constituency\\\" data-id=\\\"<?= Security::e($slug) ?>\\\" data-name=\\\"<?= Security::e($c[\'name\'] ?? $shape[\'name\']) ?>\\\" data-projects=\\\"<?= $projects ?>\\\" data-status=\\\"<?= Security::e($pct > 0 ? \'active\' : \'planning\') ?>\\\" data-units=\\\"<?= (int)($c[\'live_total_units\'] ?? 0) ?>\\\" data-pct=\\\"<?= $pct ?>\\\" data-link=\\\"constituency-detail.php?id=<?= Security::e($slug) ?>\\\" tabindex=\\\"0\\\" role=\\\"button\\\" aria-label=\\\"<?= Security::e(($c[\'name\'] ?? $shape[\'name\']) . \' - \' . $projects . \' projects\') ?>\\\">\\n              <path d=\\\"<?= Security::e($shape[\'path\']) ?>\\\" class=\\\"map-path\\\"/>\\n              <text class=\\\"map-label\\\" x=\\\"<?= Security::e($shape[\'x\']) ?>\\\" y=\\\"<?= Security::e($shape[\'y\']) ?>\\\"><?= Security::e($c[\'name\'] ?? $shape[\'name\']) ?></text>\\n            </g>\\n<?php endforeach; ?>\\n            <g class=\\\"map-sites\\\" aria-hidden=\\\"true\\\">\\n              <circle class=\\\"map-site-dot site-active\\\" cx=\\\"178\\\" cy=\\\"255\\\" r=\\\"6\\\"/><circle class=\\\"map-site-pulse\\\" cx=\\\"178\\\" cy=\\\"255\\\" r=\\\"6\\\"/>\\n              <circle class=\\\"map-site-dot site-active\\\" cx=\\\"304\\\" cy=\\\"125\\\" r=\\\"6\\\"/><circle class=\\\"map-site-pulse\\\" cx=\\\"304\\\" cy=\\\"125\\\" r=\\\"6\\\"/>\\n              <circle class=\\\"map-site-dot site-planning\\\" cx=\\\"88\\\" cy=\\\"82\\\" r=\\\"5\\\"/>\\n            </g>\\n          </svg>\\n          <div class=\\\"map-compass\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid fa-location-crosshairs\\\"></i><span>N</span></div>\\n          <div class=\\\"map-legend\\\" aria-hidden=\\\"true\\\">\\n            <span class=\\\"map-legend-item\\\"><span class=\\\"map-legend-dot map-legend-active\\\"></span><?= Security::e(CmsLoader::text($coverage, \'legend_active\', \'Active\')) ?></span>\\n            <span class=\\\"map-legend-item\\\"><span class=\\\"map-legend-dot map-legend-plan\\\"></span><?= Security::e(CmsLoader::text($coverage, \'legend_planning\', \'Planning\')) ?></span>\\n            <span class=\\\"map-legend-item\\\"><i class=\\\"fa-solid fa-location-dot\\\" style=\\\"color:var(--lime-muted);font-size:11px\\\"></i> <?= Security::e(CmsLoader::text($coverage, \'legend_site\', \'Project site\')) ?></span>\\n          </div>\\n        </div>\\n        <aside class=\\\"map-side-panel\\\" id=\\\"mapPanel\\\" aria-live=\\\"polite\\\">\\n          <div class=\\\"map-panel-default\\\" id=\\\"mapPanelDefault\\\">\\n            <i class=\\\"fa-solid fa-map-location-dot map-panel-icon\\\" aria-hidden=\\\"true\\\"></i>\\n            <p class=\\\"map-panel-hint\\\"><?= Security::e(CmsLoader::text($coverage, \'panel_hint\', \'Click a constituency on the map to see project data\')) ?></p>\\n            <div class=\\\"map-panel-overview\\\">\\n              <div class=\\\"map-ov-item\\\"><span class=\\\"map-ov-val\\\"><?= Security::e(format_number(count($constituencies))) ?></span><span class=\\\"map-ov-lbl\\\">Constituencies</span></div>\\n              <div class=\\\"map-ov-item\\\"><span class=\\\"map-ov-val\\\"><?= Security::e(format_number((int)($projectStats[\'active_projects\'] ?? 0))) ?></span><span class=\\\"map-ov-lbl\\\">Active Projects</span></div>\\n              <div class=\\\"map-ov-item\\\"><span class=\\\"map-ov-val\\\"><?= Security::e(format_number((int)($projectStats[\'total_units\'] ?? 0))) ?>+</span><span class=\\\"map-ov-lbl\\\">Units Planned</span></div>\\n            </div>\\n          </div>\\n          <div class=\\\"map-panel-detail\\\" id=\\\"mapPanelDetail\\\"></div>\\n        </aside>\\n      </div>\\n    </div>\\n  </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($homePage, \'ground_reports\')): ?>\\n  <section class=\\\"section news-section\\\" aria-labelledby=\\\"news-heading\\\">\\n    <div class=\\\"container\\\">\\n      <?php home_section_header(\'news-heading\', $reports, \'From the Ground\', \'Project milestones, tender notices, and official clearances.\', \'All Reports\', \'news.php\'); ?>\\n      <div class=\\\"news-asymmetric\\\">\\n<?php if ($newsItems): ?>\\n        <?php home_news_card($newsItems[0], true); ?>\\n        <div class=\\\"news-stack\\\">\\n<?php foreach (array_slice($newsItems, 1, max(0, (int)($reports[\'compact_count\'] ?? 2))) as $item): ?>\\n          <?php home_news_card($item, false); ?>\\n<?php endforeach; ?>\\n        </div>\\n        <aside class=\\\"news-alerts-sidebar\\\" aria-label=\\\"Latest programme alerts\\\">\\n          <div class=\\\"nas-header\\\"><i class=\\\"fa-solid fa-bolt nas-icon\\\" aria-hidden=\\\"true\\\"></i><span class=\\\"nas-title\\\"><?= Security::e(CmsLoader::text($reports, \'alerts_title\', \'Latest Alerts\')) ?></span></div>\\n          <ul class=\\\"nas-list\\\">\\n<?php foreach (array_slice($newsItems, 0, max(1, (int)($reports[\'alert_count\'] ?? 6))) as $index => $item): ?>\\n            <li class=\\\"nas-item <?= $index === 0 ? \'nas-item--urgent\' : \'\' ?>\\\">\\n              <span class=\\\"nas-dot\\\" aria-hidden=\\\"true\\\"></span>\\n              <div class=\\\"nas-content\\\">\\n                <span class=\\\"nas-tag\\\"><?= Security::e($item[\'category_name\'] ?? \'Report\') ?></span>\\n                <a href=\\\"news-article.php?id=<?= Security::e($item[\'slug\']) ?>\\\" class=\\\"nas-headline\\\"><?= Security::e($item[\'title\']) ?></a>\\n                <time class=\\\"nas-time\\\" datetime=\\\"<?= Security::e(substr((string)$item[\'published_at\'], 0, 10)) ?>\\\"><?= Security::e(format_date($item[\'published_at\'] ?? null, \'d M Y\')) ?></time>\\n              </div>\\n            </li>\\n<?php endforeach; ?>\\n          </ul>\\n        </aside>\\n<?php else: ?>\\n        <div class=\\\"empty-state\\\">\\n          <strong><?= Security::e(CmsLoader::text($reports, \'empty_title\', \'Reports will appear here\')) ?></strong>\\n          <p><?= Security::e(CmsLoader::text($reports, \'empty_text\', \'Published news and alerts will populate this live section.\')) ?></p>\\n        </div>\\n<?php endif; ?>\\n      </div>\\n    </div>\\n  </section>\\n<?php endif; ?>\\n\\n<?php if (CmsLoader::visible($homePage, \'ecitizen_cta\')): ?>\\n  <section class=\\\"ecitizen-cta\\\" aria-labelledby=\\\"ecitizen-heading\\\">\\n    <div class=\\\"ecitizen-cta-bg\\\" aria-hidden=\\\"true\\\">\\n      <img <?= public_image_attrs(CmsLoader::text($cta, \'background_image\', \'uploads/site-photos/maili-tatu-2.jpg\'), \'\', [\'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>>\\n      <div class=\\\"ecitizen-cta-overlay\\\"></div>\\n    </div>\\n    <div class=\\\"container\\\">\\n      <div class=\\\"ecitizen-inner fade-up\\\">\\n        <div class=\\\"ecitizen-left\\\">\\n          <div class=\\\"ecitizen-eyebrow\\\">\\n            <img <?= public_image_attrs(CmsLoader::text($cta, \'logo_image\', \'uploads/logos/BomaYanguLogo.png\'), \'Boma Yangu\', [\'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>>\\n            <span><?= Security::e(CmsLoader::text($cta, \'eyebrow\', \'Boma Yangu - eCitizen\')) ?></span>\\n          </div>\\n          <h2 id=\\\"ecitizen-heading\\\" class=\\\"ecitizen-headline\\\"><?= nl2br(Security::e(CmsLoader::text($cta, \'title\', \\\"Your Home.\\\\nApplied Online.\\\")), false) ?></h2>\\n          <p class=\\\"ecitizen-sub\\\"><?= Security::e(CmsLoader::text($cta, \'subtitle\', \'Register on the national Boma Yangu portal via eCitizen.\')) ?></p>\\n          <div class=\\\"ecitizen-actions\\\">\\n            <a href=\\\"<?= Security::e(CmsLoader::text($cta, \'primary_url\', \'https://ecitizen.go.ke\')) ?>\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ecitizen-btn-main\\\">\\n              <?= Security::e(CmsLoader::text($cta, \'primary_label\', \'Apply via eCitizen\')) ?> <i class=\\\"fa-solid fa-arrow-up-right-from-square\\\" aria-hidden=\\\"true\\\"></i>\\n            </a>\\n            <a href=\\\"<?= Security::e(CmsLoader::text($cta, \'secondary_url\', \'about.php\')) ?>\\\" class=\\\"ecitizen-btn-ghost\\\">\\n              <?= Security::e(CmsLoader::text($cta, \'secondary_label\', \'About the programme\')) ?> <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i>\\n            </a>\\n          </div>\\n        </div>\\n        <div class=\\\"ecitizen-steps\\\" aria-label=\\\"How to apply via eCitizen\\\">\\n          <h3 class=\\\"ecitizen-steps-title\\\"><i class=\\\"fa-solid fa-list-check\\\" aria-hidden=\\\"true\\\"></i> How to Apply</h3>\\n          <div class=\\\"ecitizen-steps-grid\\\">\\n<?php for ($i = 1; $i <= 4; $i++): ?>\\n            <div class=\\\"ecitizen-step-card\\\">\\n              <div class=\\\"ecitizen-step-icon-wrap\\\">\\n                <i class=\\\"fa-solid <?= Security::e(CmsLoader::text($cta, \\\"step_{$i}_icon\\\", \'fa-circle-check\')) ?>\\\" aria-hidden=\\\"true\\\"></i>\\n                <span class=\\\"ecitizen-step-num\\\"><?= str_pad((string)$i, 2, \'0\', STR_PAD_LEFT) ?></span>\\n              </div>\\n              <strong><?= Security::e(CmsLoader::text($cta, \\\"step_{$i}_title\\\", \'Application step\')) ?></strong>\\n              <p><?= Security::e(CmsLoader::text($cta, \\\"step_{$i}_body\\\", \'Complete this step to continue.\')) ?></p>\\n            </div>\\n<?php endfor; ?>\\n          </div>\\n        </div>\\n      </div>\\n    </div>\\n  </section>\\n<?php endif; ?>\\n\\n</main>\\n\\n<?php include __DIR__ . \'/app/partials/footer.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/back-to-top.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/mobile-menu.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/scripts.php\'; ?>\\n</body>\\n</html>\\n\\n<?php\\nfunction home_defaults(string $key): array\\n{\\n    return match ($key) {\\n        \'home_hero\' => [\\n            \'eyebrow\' => \'Ongoing Projects - Trans-Nzoia County\',\\n            \'title\' => \\\"Affordable Housing\\\\nProject Tracker\\\",\\n            \'subtitle\' => \'Transparent, real-time monitoring of housing construction delivery across all five constituencies of Trans-Nzoia County.\',\\n            \'background_image\' => \'uploads/heroes/hero-main.jpg\',\\n            \'background_alt\' => \'Affordable housing construction site in Trans-Nzoia County, Kenya\',\\n            \'primary_label\' => \'View All Projects\',\\n            \'primary_url\' => \'projects.php\',\\n            \'primary_icon\' => \'fa-table-cells-large\',\\n            \'secondary_label\' => \'By Constituency\',\\n            \'secondary_url\' => \'constituencies.php\',\\n            \'secondary_icon\' => \'fa-map-location-dot\',\\n            \'show_kpis\' => \'1\',\\n        ],\\n        \'featured_projects\' => [\'title\' => \'Featured Projects\', \'subtitle\' => \'Track ongoing affordable housing construction across Trans-Nzoia County.\', \'button_label\' => \'Full Portfolio\', \'button_url\' => \'projects.php\'],\\n        \'constituency_coverage\' => [\'title\' => \'Coverage by Constituency\', \'subtitle\' => \'All five constituencies are part of the Trans-Nzoia AHP.\', \'button_label\' => \'All Constituencies\', \'button_url\' => \'constituencies.php\'],\\n        \'ground_reports\' => [\'title\' => \'From the Ground\', \'subtitle\' => \'Project milestones, tender notices, and official clearances.\', \'button_label\' => \'All Reports\', \'button_url\' => \'news.php\', \'alerts_title\' => \'Latest Alerts\'],\\n        \'ecitizen_cta\' => [\'title\' => \\\"Your Home.\\\\nApplied Online.\\\", \'subtitle\' => \'Register on the national Boma Yangu portal via eCitizen.\', \'primary_label\' => \'Apply via eCitizen\', \'primary_url\' => \'https://ecitizen.go.ke\'],\\n        default => [],\\n    };\\n}\\n\\nfunction home_kpi(string $label, int $value, string $suffix = \'\'): void\\n{\\n    ?>\\n    <div class=\\\"hero-kpi-item\\\">\\n      <span class=\\\"hero-kpi-number\\\" data-count=\\\"<?= $value ?>\\\" data-suffix=\\\"<?= Security::e($suffix) ?>\\\" aria-label=\\\"<?= Security::e(format_number($value) . $suffix . \' \' . $label) ?>\\\">0</span>\\n      <span class=\\\"hero-kpi-label\\\"><?= Security::e($label) ?></span>\\n    </div>\\n    <?php\\n}\\n\\nfunction home_section_header(string $id, array $content, string $fallbackTitle, string $fallbackSubtitle, string $fallbackButton, string $fallbackUrl): void\\n{\\n    ?>\\n    <div class=\\\"split-section-header fade-up\\\">\\n      <div class=\\\"split-section-left\\\">\\n        <span class=\\\"accent-line\\\"></span>\\n        <h2 id=\\\"<?= Security::e($id) ?>\\\" class=\\\"section-title\\\"><?= Security::e(CmsLoader::text($content, \'title\', $fallbackTitle)) ?></h2>\\n        <p class=\\\"section-subtitle\\\" style=\\\"margin-bottom:0\\\"><?= Security::e(CmsLoader::text($content, \'subtitle\', $fallbackSubtitle)) ?></p>\\n      </div>\\n      <div class=\\\"split-section-right\\\">\\n        <a href=\\\"<?= Security::e(CmsLoader::text($content, \'button_url\', $fallbackUrl)) ?>\\\" class=\\\"btn btn-outline\\\">\\n          <?= Security::e(CmsLoader::text($content, \'button_label\', $fallbackButton)) ?> <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i>\\n        </a>\\n      </div>\\n    </div>\\n    <?php\\n}\\n\\nfunction home_project_card(array $project): void\\n{\\n    $image = home_project_image($project);\\n    $status = status_label($project[\'status\'] ?? \'planning\');\\n    $pct = (int)($project[\'pct_complete\'] ?? 0);\\n    ?>\\n    <article class=\\\"ptc\\\">\\n      <div class=\\\"ptc-image\\\">\\n        <img <?= public_image_attrs($image, ($project[\'name\'] ?? \'Project\') . \' construction site\', [\'onerror\' => \\\"this.parentElement.classList.add(\'ptc-img-fallback\')\\\"]) ?>>\\n        <div class=\\\"ptc-image-overlay\\\" aria-hidden=\\\"true\\\"></div>\\n        <div class=\\\"ptc-badges\\\">\\n          <span class=\\\"badge <?= ($project[\'status\'] ?? \'\') === \'active\' ? \'badge-ongoing\' : \'badge-warning\' ?>\\\"><?= Security::e($status) ?></span>\\n          <span class=\\\"ptc-category-tag\\\"><?= Security::e($project[\'category_name\'] ?? \'AHP\') ?></span>\\n        </div>\\n      </div>\\n      <div class=\\\"ptc-body\\\">\\n        <div class=\\\"ptc-location\\\"><i class=\\\"fa-solid fa-location-dot\\\" aria-hidden=\\\"true\\\"></i> <?= Security::e(($project[\'constituency_name\'] ?? \'Trans-Nzoia\') . \' Constituency - \' . ($project[\'ward_name\'] ?? $project[\'location_label\'] ?? \'\')) ?></div>\\n        <h3 class=\\\"ptc-title\\\"><?= Security::e($project[\'name\'] ?? \'Project\') ?></h3>\\n        <div class=\\\"ptc-stats-row\\\">\\n          <div class=\\\"ptc-stat\\\"><span class=\\\"ptc-stat-val\\\"><?= Security::e(format_number((int)($project[\'units\'] ?? 0))) ?></span><span class=\\\"ptc-stat-lbl\\\">Units</span></div>\\n          <div class=\\\"ptc-stat-sep\\\" aria-hidden=\\\"true\\\"></div>\\n          <div class=\\\"ptc-stat\\\"><span class=\\\"ptc-stat-val ptc-stat-pct\\\"><?= $pct ?>%</span><span class=\\\"ptc-stat-lbl\\\">Complete</span></div>\\n          <div class=\\\"ptc-stat-sep\\\" aria-hidden=\\\"true\\\"></div>\\n          <div class=\\\"ptc-stat\\\"><span class=\\\"ptc-stat-val\\\"><?= Security::e(home_delivery_year($project[\'est_delivery\'] ?? null)) ?></span><span class=\\\"ptc-stat-lbl\\\">Est. Delivery</span></div>\\n        </div>\\n        <div class=\\\"ptc-progress\\\" role=\\\"progressbar\\\" aria-valuenow=\\\"<?= $pct ?>\\\" aria-valuemin=\\\"0\\\" aria-valuemax=\\\"100\\\" aria-label=\\\"Construction <?= $pct ?>% complete\\\">\\n          <div class=\\\"ptc-progress-track\\\"><div class=\\\"ptc-progress-fill\\\" data-progress=\\\"<?= $pct ?>\\\"></div></div>\\n          <span class=\\\"ptc-progress-label\\\"><?= $pct ?>% Completed</span>\\n        </div>\\n        <div class=\\\"ptc-actions\\\">\\n          <a href=\\\"project-detail.php?id=<?= Security::e($project[\'slug\'] ?? \'\') ?>\\\" class=\\\"btn btn-primary btn-sm\\\">View Details</a>\\n          <a href=\\\"https://ecitizen.go.ke\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"btn btn-outline btn-sm\\\">Apply on eCitizen <i class=\\\"fa-solid fa-arrow-up-right-from-square\\\" aria-hidden=\\\"true\\\"></i></a>\\n        </div>\\n      </div>\\n    </article>\\n    <?php\\n}\\n\\nfunction home_project_image(array $project): string\\n{\\n    if (!empty($project[\'hero_image\'])) {\\n        return (string)$project[\'hero_image\'];\\n    }\\n\\n    $images = json_decode((string)($project[\'images_json\'] ?? \'\'), true);\\n    return is_array($images) && !empty($images[0]) ? (string)$images[0] : \'uploads/heroes/hero-main.jpg\';\\n}\\n\\nfunction home_delivery_year(mixed $date): string\\n{\\n    if (!$date) {\\n        return \'TBD\';\\n    }\\n\\n    $timestamp = strtotime((string)$date);\\n    return $timestamp ? date(\'Y\', $timestamp) : (string)$date;\\n}\\n\\nfunction home_constituency(array $rows, string $slug): array\\n{\\n    foreach ($rows as $row) {\\n        if (($row[\'slug\'] ?? \'\') === $slug) {\\n            return $row;\\n        }\\n    }\\n\\n    return [];\\n}\\n\\nfunction home_map_shapes(): array\\n{\\n    return [\\n        \'endebess\' => [\'name\' => \'Endebess\', \'path\' => \'M 20,20 L 220,20 L 220,180 L 120,200 L 20,160 Z\', \'x\' => \'112\', \'y\' => \'98\'],\\n        \'cherangany\' => [\'name\' => \'Cherangany\', \'path\' => \'M 220,20 L 460,20 L 460,230 L 260,230 L 220,180 Z\', \'x\' => \'348\', \'y\' => \'112\'],\\n        \'kiminini\' => [\'name\' => \'Kiminini\', \'path\' => \'M 20,160 L 120,200 L 120,380 L 20,380 Z\', \'x\' => \'62\', \'y\' => \'290\'],\\n        \'saboti\' => [\'name\' => \'Saboti\', \'path\' => \'M 120,200 L 220,180 L 260,230 L 260,380 L 120,380 Z\', \'x\' => \'186\', \'y\' => \'305\'],\\n        \'kwanza\' => [\'name\' => \'Kwanza\', \'path\' => \'M 260,230 L 460,230 L 460,380 L 260,380 Z\', \'x\' => \'362\', \'y\' => \'310\'],\\n    ];\\n}\\n\\nfunction home_news_items(int $limit): array\\n{\\n    try {\\n        return Database::fetchAll(\\\"\\n            SELECT na.*, nc.name AS category_name, nc.slug AS category_slug, ml.path AS image_path\\n            FROM news_articles na\\n            LEFT JOIN news_categories nc ON nc.id = na.category_id\\n            LEFT JOIN media_library ml ON ml.id = na.featured_image_id\\n            WHERE na.status = \'published\'\\n            ORDER BY COALESCE(na.published_at, na.created_at) DESC, na.id DESC\\n            LIMIT {$limit}\\n        \\\");\\n    } catch (Throwable $e) {\\n        return [];\\n    }\\n}\\n\\nfunction home_news_card(array $item, bool $feature): void\\n{\\n    $image = (string)($item[\'image_path\'] ?? \'uploads/news/modern-market.jpg\');\\n    $class = $feature ? \'news-card news-card--feature\' : \'news-card news-card--compact\';\\n    ?>\\n    <article class=\\\"<?= $class ?>\\\">\\n      <div class=\\\"news-card-img\\\">\\n        <img <?= public_image_attrs($image, $item[\'title\'] ?? \'Programme report\', [\'onerror\' => \\\"this.parentElement.classList.add(\'news-img-fallback\')\\\"]) ?>>\\n        <span class=\\\"news-cat-badge news-cat-milestone\\\"><i class=\\\"fa-solid fa-flag-checkered\\\" aria-hidden=\\\"true\\\"></i> <?= Security::e($item[\'category_name\'] ?? \'Report\') ?></span>\\n      </div>\\n      <div class=\\\"news-card-body\\\">\\n        <time class=\\\"news-date\\\" datetime=\\\"<?= Security::e(substr((string)($item[\'published_at\'] ?? $item[\'created_at\'] ?? \'\'), 0, 10)) ?>\\\"><i class=\\\"fa-regular fa-calendar\\\" aria-hidden=\\\"true\\\"></i> <?= Security::e(format_date($item[\'published_at\'] ?? $item[\'created_at\'] ?? null, \'d M Y\')) ?></time>\\n        <h3 class=\\\"news-card-title\\\"><?= Security::e($item[\'title\'] ?? \'Programme report\') ?></h3>\\n        <p class=\\\"news-card-text <?= $feature ? \'\' : \'line-clamp-2\' ?>\\\"><?= Security::e($item[\'excerpt\'] ?? \'\') ?></p>\\n<?php if ($feature): ?>\\n        <a href=\\\"news-article.php?id=<?= Security::e($item[\'slug\'] ?? \'\') ?>\\\" class=\\\"news-read-link\\\">Read full report <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i></a>\\n<?php endif; ?>\\n      </div>\\n    </article>\\n    <?php\\n}\\n\"}', '2026-06-24 18:05:13', '2026-06-24 18:05:13');
INSERT INTO `public_frontend_content_snapshots` (`id`, `page_slug`, `page_label`, `file_path`, `source_hash`, `raw_source`, `extracted_text`, `extracted_json`, `seeded_at`, `updated_at`) VALUES
(2, 'about', 'About', 'about.php', '0fbe9e275b5cfb7f10c736d6c8f40d3edfafeeea8cd82c961ad50908c220bb0b', '<?php\nrequire_once __DIR__ . \'/app/core/bootstrap.php\';\n\n$basePath = \'\';\n$activePage = \'about\';\n$aboutPage = CmsLoader::page(\'about\');\n$projectStats = Project::stats();\n$constituencies = Constituency::withProjectCounts();\n\n$hero = CmsLoader::content($aboutPage, \'about_hero\', about_defaults(\'about_hero\'));\n$overview = CmsLoader::content($aboutPage, \'programme_overview\', about_defaults(\'programme_overview\'));\n$pillars = CmsLoader::content($aboutPage, \'core_commitments\', about_defaults(\'core_commitments\'));\n$history = CmsLoader::content($aboutPage, \'programme_history\', about_defaults(\'programme_history\'));\n$legal = CmsLoader::content($aboutPage, \'legal_framework\', about_defaults(\'legal_framework\'));\n$partners = CmsLoader::content($aboutPage, \'partners_teaser\', about_defaults(\'partners_teaser\'));\n$faqTeaser = CmsLoader::content($aboutPage, \'faq_teaser\', about_defaults(\'faq_teaser\'));\n$leadership = CmsLoader::content($aboutPage, \'leadership_contact\', about_defaults(\'leadership_contact\'));\n$applyCta = CmsLoader::content($aboutPage, \'apply_cta\', about_defaults(\'apply_cta\'));\n\n$pageTitle = (string)($aboutPage[\'seo_title\'] ?? \'About the Programme | Trans-Nzoia AHP Tracker\');\n$pageDescription = (string)($aboutPage[\'seo_description\'] ?? \'Learn about the Trans-Nzoia County Affordable Housing Programme - mandate, partners, legal framework and how to apply.\');\n$pageKeywords = (string)($aboutPage[\'seo_keywords\'] ?? \'Trans-Nzoia affordable housing, AHP Kenya, housing programme, Boma Yangu, county housing policy\');\n$pageAuthor = \'Trans-Nzoia County Government - Department of Land, Housing & Physical Planning\';\n$pageRobots = \'index, follow\';\n$themeColor = \'#163300\';\n$canonicalUrl = (string)($aboutPage[\'canonical_url\'] ?? \'https://housing.transnzoia.go.ke/about.php\');\n$heroImage = CmsLoader::text($hero, \'background_image\', (string)($aboutPage[\'hero_image\'] ?? \'uploads/gallery/maili-tatu-2.jpg\'));\n$pageStyles = [\n    \'assets/css/global.css\',\n    \'assets/css/pages/about.css\',\n];\n$pageScripts = [\n    \'assets/js/global.js\',\n    \'assets/js/pages/about.js\',\n];\n$headMeta = [\n    \'<meta name=\"geo.region\" content=\"KE-36\">\',\n    \'<meta name=\"geo.placename\" content=\"Trans-Nzoia County, Kenya\">\',\n    \'<meta property=\"og:title\" content=\"\' . Security::e($pageTitle) . \'\">\',\n    \'<meta property=\"og:description\" content=\"\' . Security::e($pageDescription) . \'\">\',\n    \'<meta property=\"og:type\" content=\"website\">\',\n    \'<meta property=\"og:url\" content=\"\' . Security::e($canonicalUrl) . \'\">\',\n    \'<meta property=\"og:image\" content=\"\' . Security::e($heroImage) . \'\">\',\n    \'<meta property=\"og:locale\" content=\"en_KE\">\',\n    \'<meta property=\"og:site_name\" content=\"Trans-Nzoia AHP Tracker\">\',\n    \'<meta name=\"twitter:card\" content=\"summary_large_image\">\',\n    \'<meta name=\"twitter:title\" content=\"\' . Security::e($pageTitle) . \'\">\',\n    \'<meta name=\"twitter:description\" content=\"\' . Security::e($pageDescription) . \'\">\',\n    \'<meta name=\"twitter:image\" content=\"\' . Security::e($heroImage) . \'\">\',\n];\ninclude __DIR__ . \'/app/partials/head.php\';\n?>\n<body>\n<?php include __DIR__ . \'/app/partials/cursor.php\'; ?>\n<?php include __DIR__ . \'/app/partials/skip-link.php\'; ?>\n<?php include __DIR__ . \'/app/partials/navbar.php\'; ?>\n<main id=\"main-content\">\n\n<?php if (CmsLoader::visible($aboutPage, \'about_hero\')): ?>\n    <section class=\"ab-hero\" aria-label=\"About the programme\">\n      <div class=\"ab-hero-bg\" aria-hidden=\"true\">\n        <img <?= public_image_attrs($heroImage, CmsLoader::text($hero, \'background_alt\', \'Affordable housing construction works in Trans-Nzoia County\'), [\'loading\' => \'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \"this.style.display=\'none\'\"]) ?>>\n        <div class=\"ab-hero-overlay\"></div>\n      </div>\n      <div class=\"container\">\n        <nav class=\"breadcrumb\" aria-label=\"Breadcrumb\">\n          <a href=\"index.php\" class=\"breadcrumb-link\">Home</a>\n          <span class=\"breadcrumb-sep\" aria-hidden=\"true\"><i class=\"fa-solid fa-chevron-right\"></i></span>\n          <span class=\"breadcrumb-current\" aria-current=\"page\">About</span>\n        </nav>\n        <div class=\"ab-hero-body\">\n          <div class=\"ab-hero-eyebrow\">\n            <i class=\"fa-solid fa-circle-info\" aria-hidden=\"true\"></i>\n            <?= Security::e(CmsLoader::text($hero, \'eyebrow\', \'National Affordable Housing Programme - Trans-Nzoia County\')) ?>\n          </div>\n          <h1 class=\"ab-hero-title\"><?= nl2br(Security::e(CmsLoader::text($hero, \'title\', \'Delivering Affordable Homes for Trans-Nzoia County Residents\')), false) ?></h1>\n          <p class=\"ab-hero-desc\"><?= Security::e(CmsLoader::text($hero, \'subtitle\', \'A government-led initiative to provide quality, subsidised housing to low-to-middle-income earners across all five constituencies - tracked transparently for every resident.\')) ?></p>\n          <div class=\"ab-hero-ctas\">\n            <a href=\"<?= Security::e(CmsLoader::text($hero, \'primary_url\', \'projects.php\')) ?>\" class=\"ab-btn-lime\">\n              <i class=\"fa-solid fa-building-columns\" aria-hidden=\"true\"></i> <?= Security::e(CmsLoader::text($hero, \'primary_label\', \'View All Projects\')) ?>\n            </a>\n            <a href=\"<?= Security::e(CmsLoader::text($hero, \'secondary_url\', \'https://bomayangu.go.ke\')) ?>\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ab-btn-outline\">\n              <?= Security::e(CmsLoader::text($hero, \'secondary_label\', \'Apply on Boma Yangu\')) ?> <i class=\"fa-solid fa-arrow-up-right-from-square\" aria-hidden=\"true\"></i>\n            </a>\n          </div>\n        </div>\n        <div class=\"ab-hero-kpis\" aria-label=\"Programme key figures\">\n          <?php about_kpi(\'fa-map-location-dot\', count($constituencies), \'Constituencies\'); ?>\n          <?php about_kpi(\'fa-building-columns\', (int)($projectStats[\'total_projects\'] ?? 0), \'Projects\'); ?>\n          <?php about_kpi(\'fa-house-chimney\', (int)($projectStats[\'total_units\'] ?? 0), \'Units Planned\'); ?>\n          <?php about_kpi(\'fa-calendar-days\', CmsLoader::text($hero, \'launch_year\', \'2024\'), CmsLoader::text($hero, \'launch_label\', \'Programme Launch\')); ?>\n        </div>\n      </div>\n    </section>\n<?php endif; ?>\n\n<?php if (CmsLoader::visible($aboutPage, \'programme_overview\')): ?>\n    <section class=\"ab-overview fade-up\" aria-label=\"Programme overview\">\n      <div class=\"container\">\n        <div class=\"ab-overview-inner\">\n          <div class=\"ab-overview-copy\">\n            <div class=\"ab-section-eyebrow\"><?= Security::e(CmsLoader::text($overview, \'eyebrow\', \'Programme Overview\')) ?></div>\n            <h2 class=\"ab-section-title\"><?= Security::e(CmsLoader::text($overview, \'title\', \'What Is the Affordable Housing Programme?\')) ?></h2>\n            <p class=\"ab-overview-lead\"><?= Security::e(CmsLoader::text($overview, \'lead\', about_defaults(\'programme_overview\')[\'lead\'])) ?></p>\n            <?php about_paragraph($overview, \'body_1\'); ?>\n            <?php about_paragraph($overview, \'body_2\'); ?>\n            <a href=\"<?= Security::e(CmsLoader::text($overview, \'link_url\', \'projects.php\')) ?>\" class=\"ab-text-link\">\n              <?= Security::e(CmsLoader::text($overview, \'link_label\', \'Explore all active projects\')) ?> <i class=\"fa-solid fa-arrow-right\" aria-hidden=\"true\"></i>\n            </a>\n          </div>\n          <div class=\"ab-snapshot\">\n            <div class=\"ab-snapshot-header\">\n              <i class=\"fa-solid fa-chart-pie\" aria-hidden=\"true\"></i>\n              <?= Security::e(CmsLoader::text($overview, \'snapshot_title\', \'Programme at a Glance\')) ?>\n            </div>\n            <ul class=\"ab-snapshot-list\">\n              <?php foreach (about_series($overview, \'glance\', 6, [\'label\', \'value\', \'url\']) as $row): ?>\n                <?php if (($row[\'label\'] ?? \'\') !== \'\' || ($row[\'value\'] ?? \'\') !== \'\'): ?>\n              <li>\n                <span class=\"ab-snap-label\"><?= Security::e($row[\'label\'] ?? \'\') ?></span>\n                <span class=\"ab-snap-value\">\n                  <?php if (!empty($row[\'url\'])): ?>\n                    <a href=\"<?= Security::e($row[\'url\']) ?>\" target=\"_blank\" rel=\"noopener noreferrer\"><?= Security::e($row[\'value\'] ?? \'\') ?> <i class=\"fa-solid fa-arrow-up-right-from-square\" style=\"font-size:9px\"></i></a>\n                  <?php else: ?>\n                    <?= Security::e($row[\'value\'] ?? \'\') ?>\n                  <?php endif; ?>\n                </span>\n              </li>\n                <?php endif; ?>\n              <?php endforeach; ?>\n            </ul>\n          </div>\n        </div>\n      </div>\n    </section>\n<?php endif; ?>\n\n<?php if (CmsLoader::visible($aboutPage, \'core_commitments\')): ?>\n    <section class=\"ab-pillars fade-up\" aria-label=\"Programme pillars\">\n      <div class=\"container\">\n        <div class=\"ab-pillars-header\">\n          <div class=\"ab-section-eyebrow ab-section-eyebrow--light\"><?= Security::e(CmsLoader::text($pillars, \'eyebrow\', \'Our Pillars\')) ?></div>\n          <h2 class=\"ab-section-title ab-section-title--light\"><?= Security::e(CmsLoader::text($pillars, \'title\', \'Built on Four Core Commitments\')) ?></h2>\n          <p class=\"ab-section-sub ab-section-sub--light\"><?= Security::e(CmsLoader::text($pillars, \'subtitle\', \'Every decision, project and process is guided by four foundational principles.\')) ?></p>\n        </div>\n        <div class=\"ab-pillars-grid\">\n          <?php foreach (about_series($pillars, \'pillar\', 4, [\'icon\', \'title\', \'body\']) as $pillar): ?>\n            <?php if (($pillar[\'title\'] ?? \'\') !== \'\'): ?>\n          <div class=\"ab-pillar-card\">\n            <div class=\"ab-pillar-icon-wrap\" aria-hidden=\"true\"><i class=\"fa-solid <?= Security::e(about_icon($pillar[\'icon\'] ?? \'fa-circle-check\')) ?>\"></i></div>\n            <h3 class=\"ab-pillar-title\"><?= Security::e($pillar[\'title\']) ?></h3>\n            <p class=\"ab-pillar-desc\"><?= Security::e($pillar[\'body\'] ?? \'\') ?></p>\n          </div>\n            <?php endif; ?>\n          <?php endforeach; ?>\n        </div>\n      </div>\n    </section>\n\n    <div class=\"ab-stats-strip\" aria-label=\"Programme statistics\">\n      <div class=\"container\">\n        <div class=\"ab-stats-inner\">\n          <?php about_stat((string)count($constituencies), \'Constituencies\'); ?>\n          <div class=\"ab-stat-divider\" aria-hidden=\"true\"></div>\n          <?php about_stat((string)(int)($projectStats[\'total_projects\'] ?? 0), \'Projects\'); ?>\n          <div class=\"ab-stat-divider\" aria-hidden=\"true\"></div>\n          <?php about_stat((string)(int)($projectStats[\'total_units\'] ?? 0), \'Units Planned\'); ?>\n          <div class=\"ab-stat-divider\" aria-hidden=\"true\"></div>\n          <?php about_stat(CmsLoader::text($pillars, \'families_target\', \'8650\'), \'Families to Benefit\'); ?>\n          <div class=\"ab-stat-divider\" aria-hidden=\"true\"></div>\n          <?php about_stat(CmsLoader::text($hero, \'launch_year\', \'2024\'), \'Year Launched\', true); ?>\n        </div>\n      </div>\n    </div>\n<?php endif; ?>\n\n<?php if (CmsLoader::visible($aboutPage, \'programme_history\')): ?>\n    <section class=\"ab-timeline fade-up\" aria-label=\"Programme timeline\">\n      <div class=\"container\">\n        <div class=\"ab-timeline-header\">\n          <div class=\"ab-section-eyebrow ab-section-eyebrow--light\"><?= Security::e(CmsLoader::text($history, \'eyebrow\', \'Programme History\')) ?></div>\n          <h2 class=\"ab-section-title ab-section-title--light\"><?= Security::e(CmsLoader::text($history, \'title\', \'From Announcement to Active Construction\')) ?></h2>\n          <p class=\"ab-section-sub ab-section-sub--light\"><?= Security::e(CmsLoader::text($history, \'subtitle\', \'A chronological record of how affordable housing came to life in Trans-Nzoia County.\')) ?></p>\n        </div>\n        <ol class=\"ab-tl-track\">\n          <?php foreach (about_series($history, \'item\', 6, [\'period\', \'icon\', \'title\', \'body\', \'status\']) as $item): ?>\n            <?php if (($item[\'title\'] ?? \'\') !== \'\'): ?>\n          <li class=\"ab-tl-item <?= Security::e(about_timeline_class($item[\'status\'] ?? \'\')) ?>\">\n            <span class=\"ab-tl-year\"><?= Security::e($item[\'period\'] ?? \'\') ?></span>\n            <div class=\"ab-tl-node\" aria-hidden=\"true\">\n              <div class=\"ab-tl-dot\"><i class=\"fa-solid <?= Security::e(about_icon($item[\'icon\'] ?? \'fa-circle\')) ?>\"></i></div>\n              <div class=\"ab-tl-connector\"></div>\n            </div>\n            <div class=\"ab-tl-content\">\n              <h3 class=\"ab-tl-title\"><?= Security::e($item[\'title\']) ?></h3>\n              <p class=\"ab-tl-desc\"><?= Security::e($item[\'body\'] ?? \'\') ?></p>\n              <span class=\"ab-tl-badge <?= Security::e(about_timeline_badge_class($item[\'status\'] ?? \'\')) ?>\"><i class=\"fa-solid <?= Security::e(about_timeline_icon($item[\'status\'] ?? \'\')) ?>\" aria-hidden=\"true\"></i> <?= Security::e($item[\'status\'] ?: \'Upcoming\') ?></span>\n            </div>\n          </li>\n            <?php endif; ?>\n          <?php endforeach; ?>\n        </ol>\n      </div>\n    </section>\n<?php endif; ?>\n\n<?php if (CmsLoader::visible($aboutPage, \'legal_framework\')): ?>\n    <section class=\"ab-legal fade-up\" aria-label=\"Legal and regulatory framework\">\n      <div class=\"container\">\n        <div class=\"ab-legal-header\">\n          <div class=\"ab-section-eyebrow\"><?= Security::e(CmsLoader::text($legal, \'eyebrow\', \'Legal Framework\')) ?></div>\n          <h2 class=\"ab-section-title\"><?= Security::e(CmsLoader::text($legal, \'title\', \'Backed by Law & Policy\')) ?></h2>\n          <p class=\"ab-section-sub\"><?= Security::e(CmsLoader::text($legal, \'subtitle\', \'A robust legal and regulatory framework ensures compliance, accountability and environmental responsibility across every project site.\')) ?></p>\n        </div>\n        <div class=\"ab-legal-grid\">\n          <?php foreach (about_series($legal, \'card\', 6, [\'icon\', \'title\', \'body\', \'link_label\', \'url\']) as $card): ?>\n            <?php if (($card[\'title\'] ?? \'\') !== \'\'): ?>\n          <div class=\"ab-legal-card\">\n            <div class=\"ab-legal-icon\" aria-hidden=\"true\"><i class=\"fa-solid <?= Security::e(about_icon($card[\'icon\'] ?? \'fa-book\')) ?>\"></i></div>\n            <h3 class=\"ab-legal-title\"><?= Security::e($card[\'title\']) ?></h3>\n            <p class=\"ab-legal-desc\"><?= Security::e($card[\'body\'] ?? \'\') ?></p>\n            <?php if (!empty($card[\'url\'])): ?>\n            <a href=\"<?= Security::e($card[\'url\']) ?>\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ab-legal-link\"><?= Security::e($card[\'link_label\'] ?: \'Read more\') ?> <i class=\"fa-solid fa-arrow-up-right-from-square\" aria-hidden=\"true\"></i></a>\n            <?php endif; ?>\n          </div>\n            <?php endif; ?>\n          <?php endforeach; ?>\n        </div>\n      </div>\n    </section>\n<?php endif; ?>\n\n<?php if (CmsLoader::visible($aboutPage, \'partners_teaser\')): ?>\n    <section class=\"ab-partners fade-up\" aria-label=\"Implementing partners\">\n      <div class=\"container\">\n        <div class=\"ab-partners-header\">\n          <div class=\"ab-section-eyebrow ab-section-eyebrow--light\"><?= Security::e(CmsLoader::text($partners, \'eyebrow\', \'Partners\')) ?></div>\n          <h2 class=\"ab-section-title ab-section-title--light\"><?= Security::e(CmsLoader::text($partners, \'title\', \'Implementing Partners & Stakeholders\')) ?></h2>\n          <p class=\"ab-section-sub ab-section-sub--light\"><?= Security::e(CmsLoader::text($partners, \'subtitle\', \'Delivered through collaboration between national and county government agencies, financial institutions and regulatory bodies.\')) ?></p>\n        </div>\n        <div class=\"ab-partners-grid\">\n          <?php foreach (about_partner_rows((int)($partners[\'display_count\'] ?? 5)) as $partner): ?>\n          <div class=\"ab-partner-card\">\n            <div class=\"ab-partner-icon\" aria-hidden=\"true\"><i class=\"fa-solid <?= Security::e(about_icon($partner[\'icon\'] ?? \'fa-handshake\')) ?>\"></i></div>\n            <h3 class=\"ab-partner-name\"><?= Security::e($partner[\'name\']) ?></h3>\n            <p class=\"ab-partner-role\"><?= Security::e($partner[\'description\']) ?></p>\n          </div>\n          <?php endforeach; ?>\n        </div>\n      </div>\n    </section>\n<?php endif; ?>\n\n<?php if (CmsLoader::visible($aboutPage, \'faq_teaser\')): ?>\n    <section class=\"ab-faq fade-up\" aria-label=\"Frequently asked questions\">\n      <div class=\"container\">\n        <div class=\"ab-faq-wrap\">\n          <div class=\"ab-faq-header\">\n            <div class=\"ab-section-eyebrow\"><?= Security::e(CmsLoader::text($faqTeaser, \'eyebrow\', \'Common Questions\')) ?></div>\n            <h2 class=\"ab-section-title\"><?= Security::e(CmsLoader::text($faqTeaser, \'title\', \'Frequently Asked Questions\')) ?></h2>\n            <p class=\"ab-section-sub\"><?= Security::e(CmsLoader::text($faqTeaser, \'subtitle\', \'Quick answers to the most common questions about the programme.\')) ?></p>\n          </div>\n          <div class=\"ab-faq-list\">\n            <?php foreach (about_faq_rows((int)($faqTeaser[\'display_count\'] ?? 4)) as $index => $faq): ?>\n            <div class=\"ab-faq-item\">\n              <button class=\"ab-faq-trigger\" aria-expanded=\"false\" aria-controls=\"faq-<?= (int)$index + 1 ?>\" id=\"faq-trigger-<?= (int)$index + 1 ?>\">\n                <span><?= Security::e($faq[\'question\']) ?></span>\n                <i class=\"fa-solid fa-chevron-down ab-faq-chevron\" aria-hidden=\"true\"></i>\n              </button>\n              <div class=\"ab-faq-body\" id=\"faq-<?= (int)$index + 1 ?>\" role=\"region\" aria-labelledby=\"faq-trigger-<?= (int)$index + 1 ?>\">\n                <p><?= Security::e($faq[\'answer\']) ?></p>\n              </div>\n            </div>\n            <?php endforeach; ?>\n          </div>\n          <div class=\"ab-faq-footer\">\n            <a href=\"<?= Security::e(CmsLoader::text($faqTeaser, \'link_url\', \'faq.php\')) ?>\" class=\"ab-text-link\">\n              <?= Security::e(CmsLoader::text($faqTeaser, \'link_label\', \'Read all frequently asked questions\')) ?> <i class=\"fa-solid fa-arrow-right\" aria-hidden=\"true\"></i>\n            </a>\n          </div>\n        </div>\n      </div>\n    </section>\n<?php endif; ?>\n\n<?php if (CmsLoader::visible($aboutPage, \'leadership_contact\')): ?>\n    <section class=\"ab-leadership fade-up\" aria-label=\"Programme leadership and contact\">\n      <div class=\"container\">\n        <div class=\"ab-leadership-inner\">\n          <div class=\"ab-leadership-col\">\n            <div class=\"ab-section-eyebrow\"><?= Security::e(CmsLoader::text($leadership, \'eyebrow\', \'National Programme Leadership\')) ?></div>\n            <h2 class=\"ab-section-title\"><?= Security::e(CmsLoader::text($leadership, \'title\', \'Programme Leadership\')) ?></h2>\n            <p class=\"ab-leadership-sub\"><?= Security::e(CmsLoader::text($leadership, \'subtitle\', about_defaults(\'leadership_contact\')[\'subtitle\'])) ?></p>\n            <div class=\"ab-leaders-grid\">\n              <?php foreach (about_leadership_rows() as $leader): ?>\n              <div class=\"ab-leader-card\">\n                <div class=\"ab-leader-avatar\" aria-hidden=\"true\"><i class=\"fa-solid <?= Security::e(about_icon($leader[\'icon\'] ?? \'fa-user-tie\')) ?>\"></i></div>\n                <div class=\"ab-leader-info\">\n                  <span class=\"ab-leader-role\"><?= Security::e($leader[\'title\']) ?></span>\n                  <h3 class=\"ab-leader-name\"><?= Security::e($leader[\'name\']) ?></h3>\n                  <span class=\"ab-leader-dept\"><?= Security::e($leader[\'organisation\']) ?></span>\n                </div>\n              </div>\n              <?php endforeach; ?>\n            </div>\n            <a href=\"<?= Security::e(CmsLoader::text($leadership, \'link_url\', \'leadership.php\')) ?>\" class=\"ab-text-link\" style=\"margin-top:var(--space-6);display:inline-flex;align-items:center;gap:var(--space-2)\">\n              <?= Security::e(CmsLoader::text($leadership, \'link_label\', \'Meet the full leadership team\')) ?> <i class=\"fa-solid fa-arrow-right\" aria-hidden=\"true\"></i>\n            </a>\n          </div>\n          <div class=\"ab-contact-col\">\n            <div class=\"ab-contact-card\">\n              <div class=\"ab-contact-header\">\n                <div class=\"ab-contact-header-icon\" aria-hidden=\"true\"><i class=\"fa-solid fa-envelope-open-text\"></i></div>\n                <h3><?= Security::e(CmsLoader::text($leadership, \'contact_title\', \'Get In Touch\')) ?></h3>\n                <p><?= Security::e(CmsLoader::text($leadership, \'contact_intro\', \'Have a question about the programme or your application? Reach the housing department directly.\')) ?></p>\n              </div>\n              <ul class=\"ab-contact-list\">\n                <?php about_contact_item(\'fa-location-dot\', \'Physical Address\', (string)(CmsLoader::setting(\'contact_address\') ?? \'Trans-Nzoia County Government Offices, Kitale\')); ?>\n                <?php about_contact_item(\'fa-phone\', \'Phone\', (string)(CmsLoader::setting(\'contact_phone\') ?? \'+254 53 000 0000\'), \'tel:\'); ?>\n                <?php about_contact_item(\'fa-envelope\', \'Email\', (string)(CmsLoader::setting(\'contact_email\') ?? \'housing@transnzoia.go.ke\'), \'mailto:\'); ?>\n                <?php about_contact_item(\'fa-clock\', \'Office Hours\', CmsLoader::text($leadership, \'office_hours\', \'Monday - Friday, 8:00 AM - 5:00 PM\')); ?>\n              </ul>\n              <a href=\"<?= Security::e(CmsLoader::text($leadership, \'contact_button_url\', \'contact.php\')) ?>\" class=\"ab-contact-cta\">\n                <?= Security::e(CmsLoader::text($leadership, \'contact_button_label\', \'Send a Message\')) ?> <i class=\"fa-solid fa-arrow-right\" aria-hidden=\"true\"></i>\n              </a>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n<?php endif; ?>\n\n</main>\n\n<?php if (CmsLoader::visible($aboutPage, \'apply_cta\')): ?>\n  <div class=\"ab-apply-banner\" role=\"complementary\" aria-label=\"Apply for affordable housing\">\n    <div class=\"container\">\n      <div class=\"ab-apply-inner\">\n        <div class=\"ab-apply-icon\" aria-hidden=\"true\"><i class=\"fa-solid fa-house-circle-check\"></i></div>\n        <div class=\"ab-apply-copy\">\n          <h3 class=\"ab-apply-title\"><?= Security::e(CmsLoader::text($applyCta, \'title\', \'Ready to Apply for Affordable Housing in Trans-Nzoia?\')) ?></h3>\n          <p class=\"ab-apply-sub\"><?= Security::e(CmsLoader::text($applyCta, \'subtitle\', \'Register on the national Boma Yangu portal, save your monthly deposit and select Trans-Nzoia as your allocation preference to join the housing ballot.\')) ?></p>\n        </div>\n        <div class=\"ab-apply-ctas\">\n          <a href=\"<?= Security::e(CmsLoader::text($applyCta, \'primary_url\', \'https://bomayangu.go.ke\')) ?>\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ab-btn-lime\">\n            <i class=\"fa-solid fa-arrow-up-right-from-square\" aria-hidden=\"true\"></i> <?= Security::e(CmsLoader::text($applyCta, \'primary_label\', \'Apply on Boma Yangu\')) ?>\n          </a>\n          <a href=\"<?= Security::e(CmsLoader::text($applyCta, \'secondary_url\', \'projects.php\')) ?>\" class=\"ab-btn-outline-dark\">\n            <?= Security::e(CmsLoader::text($applyCta, \'secondary_label\', \'View All Projects\')) ?> <i class=\"fa-solid fa-arrow-right\" aria-hidden=\"true\"></i>\n          </a>\n        </div>\n      </div>\n    </div>\n  </div>\n<?php endif; ?>\n\n<?php include __DIR__ . \'/app/partials/footer.php\'; ?>\n<?php include __DIR__ . \'/app/partials/back-to-top.php\'; ?>\n<?php include __DIR__ . \'/app/partials/mobile-menu.php\'; ?>\n<?php include __DIR__ . \'/app/partials/scripts.php\'; ?>\n</body>\n</html>\n\n<?php\nfunction about_defaults(string $section): array\n{\n    $defaults = [\n        \'about_hero\' => [\n            \'background_image\' => \'uploads/gallery/maili-tatu-2.jpg\',\n            \'background_alt\' => \'Affordable housing construction works in Trans-Nzoia County\',\n            \'eyebrow\' => \'National Affordable Housing Programme - Trans-Nzoia County\',\n            \'title\' => \'Delivering Affordable Homes for Trans-Nzoia County Residents\',\n            \'subtitle\' => \'A government-led initiative to provide quality, subsidised housing to low-to-middle-income earners across all five constituencies - tracked transparently for every resident.\',\n            \'primary_label\' => \'View All Projects\',\n            \'primary_url\' => \'projects.php\',\n            \'secondary_label\' => \'Apply on Boma Yangu\',\n            \'secondary_url\' => \'https://bomayangu.go.ke\',\n            \'launch_year\' => \'2024\',\n            \'launch_label\' => \'Programme Launch\',\n        ],\n        \'programme_overview\' => [\n            \'lead\' => \"The National Affordable Housing Programme (AHP) is a flagship initiative of the Kenya Kwanza Administration, aimed at bridging the nation\'s housing deficit by delivering quality, affordable units to low-to-middle-income earners.\",\n            \'body_1\' => \'In Trans-Nzoia County, the programme is implemented jointly by the State Department of Housing & Urban Development and the Trans-Nzoia County Government - Department of Land, Housing & Physical Planning. Projects span all five constituencies.\',\n            \'body_2\' => \'Units are allocated exclusively through the Boma Yangu Portal, using a transparent ballot to ensure equitable access for all registered applicants across Trans-Nzoia County.\',\n        ],\n        \'core_commitments\' => [],\n        \'programme_history\' => [],\n        \'legal_framework\' => [],\n        \'partners_teaser\' => [],\n        \'faq_teaser\' => [],\n        \'leadership_contact\' => [\n            \'subtitle\' => \'This is a national government initiative delivered through the State Department of Housing & Urban Development. The Trans-Nzoia field office coordinates local programme delivery and public support.\',\n        ],\n        \'apply_cta\' => [],\n    ];\n\n    return $defaults[$section] ?? [];\n}\n\nfunction about_kpi(string $icon, string|int|float $value, string $label): void\n{\n    ?>\n    <div class=\"ab-kpi\">\n      <i class=\"fa-solid <?= Security::e($icon) ?> ab-kpi-icon\" aria-hidden=\"true\"></i>\n      <span class=\"ab-kpi-val\"><?= Security::e(is_numeric($value) ? format_number($value) : (string)$value) ?></span>\n      <span class=\"ab-kpi-lbl\"><?= Security::e($label) ?></span>\n    </div>\n    <?php\n}\n\nfunction about_stat(string $value, string $label, bool $static = false): void\n{\n    $numeric = preg_replace(\'/[^0-9.]/\', \'\', $value);\n    ?>\n    <div class=\"ab-stat-item\">\n      <span class=\"ab-stat-val<?= $static ? \' ab-stat-static\' : \'\' ?>\"<?= !$static && $numeric !== \'\' ? \' data-target=\"\' . Security::e($numeric) . \'\"\' : \'\' ?>><?= Security::e($static ? $value : \'0\') ?></span>\n      <span class=\"ab-stat-lbl\"><?= Security::e($label) ?></span>\n    </div>\n    <?php\n}\n\nfunction about_paragraph(array $content, string $key): void\n{\n    $text = trim((string)($content[$key] ?? \'\'));\n    if ($text === \'\') {\n        return;\n    }\n    echo \'<p class=\"ab-overview-body\">\' . Security::e($text) . \'</p>\';\n}\n\nfunction about_series(array $content, string $prefix, int $count, array $keys): array\n{\n    $rows = [];\n    for ($i = 1; $i <= $count; $i++) {\n        $row = [];\n        foreach ($keys as $key) {\n            $row[$key] = trim((string)($content[$prefix . \'_\' . $i . \'_\' . $key] ?? \'\'));\n        }\n        $rows[] = $row;\n    }\n\n    return $rows;\n}\n\nfunction about_icon(string $icon): string\n{\n    $icon = trim($icon);\n    if ($icon === \'\') {\n        return \'fa-circle-check\';\n    }\n    return preg_match(\'/^fa-[a-z0-9-]+$/\', $icon) ? $icon : \'fa-circle-check\';\n}\n\nfunction about_timeline_class(string $status): string\n{\n    $status = strtolower($status);\n    if (str_contains($status, \'progress\')) {\n        return \'ab-tl-current\';\n    }\n    if (str_contains($status, \'complete\') || str_contains($status, \'done\')) {\n        return \'ab-tl-done\';\n    }\n    return \'\';\n}\n\nfunction about_timeline_badge_class(string $status): string\n{\n    $status = strtolower($status);\n    if (str_contains($status, \'progress\')) {\n        return \'ab-tl-badge--current\';\n    }\n    if (str_contains($status, \'complete\') || str_contains($status, \'done\')) {\n        return \'ab-tl-badge--done\';\n    }\n    return \'\';\n}\n\nfunction about_timeline_icon(string $status): string\n{\n    $status = strtolower($status);\n    if (str_contains($status, \'progress\')) {\n        return \'fa-rotate\';\n    }\n    if (str_contains($status, \'complete\') || str_contains($status, \'done\')) {\n        return \'fa-check\';\n    }\n    return \'fa-clock\';\n}\n\nfunction about_partner_rows(int $limit): array\n{\n    try {\n        $rows = Database::fetchAll(\n            \'SELECT organisation, role, description, category\n             FROM stakeholders\n             WHERE is_visible = 1\n             ORDER BY sort_order ASC, id ASC\n             LIMIT \' . max(1, $limit)\n        );\n    } catch (Throwable $e) {\n        $rows = [];\n    }\n\n    if ($rows) {\n        return array_map(static function (array $row): array {\n            return [\n                \'icon\' => match (strtolower((string)($row[\'category\'] ?? \'\'))) {\n                    \'government\' => \'fa-building-columns\',\n                    \'finance\', \'financial\' => \'fa-hand-holding-dollar\',\n                    \'regulator\', \'regulatory\' => \'fa-helmet-safety\',\n                    default => \'fa-handshake\',\n                },\n                \'name\' => (string)($row[\'organisation\'] ?? \'\'),\n                \'description\' => (string)($row[\'description\'] ?: ($row[\'role\'] ?? \'Programme partner\')),\n            ];\n        }, $rows);\n    }\n\n    return [\n        [\'icon\' => \'fa-building-columns\', \'name\' => \'State Dept. of Housing\', \'description\' => \'Lead implementing agency for project oversight, contractor management and national housing policy direction.\'],\n        [\'icon\' => \'fa-landmark-flag\', \'name\' => \'Trans-Nzoia County Government\', \'description\' => \'Land allocation, community engagement, site coordination and county-level programme support.\'],\n        [\'icon\' => \'fa-hand-holding-dollar\', \'name\' => \'Kenya Mortgage Refinance Company\', \'description\' => \'Long-term mortgage financing that supports affordable repayments for eligible beneficiaries.\'],\n        [\'icon\' => \'fa-house-circle-check\', \'name\' => \'Boma Yangu Portal\', \'description\' => \'National beneficiary registration, savings tracking and transparent unit allocation ballot.\'],\n        [\'icon\' => \'fa-helmet-safety\', \'name\' => \'National Construction Authority\', \'description\' => \'Contractor registration, site inspection compliance and occupational safety oversight.\'],\n    ];\n}\n\nfunction about_faq_rows(int $limit): array\n{\n    try {\n        $rows = Database::fetchAll(\n            \'SELECT question, answer\n             FROM faq_items\n             WHERE is_visible = 1\n             ORDER BY sort_order ASC, id ASC\n             LIMIT \' . max(1, $limit)\n        );\n    } catch (Throwable $e) {\n        $rows = [];\n    }\n\n    return $rows ?: [\n        [\'question\' => \'What is the Affordable Housing Programme?\', \'answer\' => \'The Affordable Housing Programme is a government initiative to deliver subsidised homes for low-to-middle-income earners.\'],\n        [\'question\' => \'Who qualifies to apply for a unit?\', \'answer\' => \'Eligible Kenyan citizens can apply through the Boma Yangu portal and follow the national allocation process.\'],\n        [\'question\' => \'How are units allocated?\', \'answer\' => \'Units are allocated through the official Boma Yangu process using transparent eligibility and ballot controls.\'],\n        [\'question\' => \'Where can I apply?\', \'answer\' => \'Applications are submitted through the national Boma Yangu portal.\'],\n    ];\n}\n\nfunction about_leadership_rows(): array\n{\n    try {\n        $rows = Database::fetchAll(\n            \'SELECT name, title, organisation\n             FROM leadership_profiles\n             WHERE is_visible = 1\n             ORDER BY sort_order ASC, id ASC\n             LIMIT 2\'\n        );\n    } catch (Throwable $e) {\n        $rows = [];\n    }\n\n    if ($rows) {\n        return array_map(static fn (array $row): array => [\n            \'icon\' => \'fa-user-tie\',\n            \'name\' => (string)($row[\'name\'] ?? \'\'),\n            \'title\' => (string)($row[\'title\'] ?? \'Programme Leadership\'),\n            \'organisation\' => (string)($row[\'organisation\'] ?? \'\'),\n        ], $rows);\n    }\n\n    return [\n        [\'icon\' => \'fa-user-tie\', \'title\' => \'County Director\', \'name\' => \'Moses Owuor\', \'organisation\' => \'State Dept. of Housing & Urban Development - Trans-Nzoia Representative\'],\n        [\'icon\' => \'fa-building-columns\', \'title\' => \'Lead National Agency\', \'name\' => \'State Dept. of Housing & Urban Development\', \'organisation\' => \'Ministry of Lands, Housing & Urban Development - National Government\'],\n    ];\n}\n\nfunction about_contact_item(string $icon, string $label, string $value, string $scheme = \'\'): void\n{\n    $value = trim($value);\n    if ($value === \'\') {\n        return;\n    }\n\n    $href = \'\';\n    if ($scheme === \'tel:\') {\n        $href = \'tel:\' . preg_replace(\'/[^0-9+]/\', \'\', $value);\n    } elseif ($scheme === \'mailto:\') {\n        $href = \'mailto:\' . $value;\n    }\n    ?>\n    <li>\n      <div class=\"ab-contact-icon\" aria-hidden=\"true\"><i class=\"fa-solid <?= Security::e($icon) ?>\"></i></div>\n      <div>\n        <strong><?= Security::e($label) ?></strong>\n        <span>\n          <?php if ($href !== \'\'): ?>\n            <a href=\"<?= Security::e($href) ?>\"><?= Security::e($value) ?></a>\n          <?php else: ?>\n            <?= nl2br(Security::e($value), false) ?>\n          <?php endif; ?>\n        </span>\n      </div>\n    </li>\n    <?php\n}\n', '\'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \"this.style.display=\'none\'\"]) ?>> Home About \" class=\"ab-btn-lime\"> \" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ab-btn-outline\"> \" class=\"ab-text-link\"> \" target=\"_blank\" rel=\"noopener noreferrer\"> \"> \"> \"> \"> \" aria-hidden=\"true\"> \"> \" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ab-legal-link\"> \"> \" id=\"faq-trigger- \"> \" role=\"region\" aria-labelledby=\"faq-trigger- \"> \" class=\"ab-text-link\"> \"> \" class=\"ab-text-link\" style=\"margin-top:var(--space-6);display:inline-flex;align-items:center;gap:var(--space-2)\"> \" class=\"ab-contact-cta\"> \" target=\"_blank\" rel=\"noopener noreferrer\" class=\"ab-btn-lime\"> \" class=\"ab-btn-outline-dark\"> ab-kpi-icon\" aria-hidden=\"true\"> \" > \"> \"> <?php }', '{\"page_slug\":\"about\",\"page_label\":\"About\",\"file_path\":\"about.php\",\"source_hash\":\"0fbe9e275b5cfb7f10c736d6c8f40d3edfafeeea8cd82c961ad50908c220bb0b\",\"title\":\"\",\"meta_description\":\"\",\"headings\":[],\"links\":[{\"href\":\"index.php\",\"text\":\"Home\"},{\"href\":\"<?= Security::e(CmsLoader::text($hero,\",\"text\":\"\\\" class=\\\"ab-btn-lime\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($hero,\",\"text\":\"\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-btn-outline\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($overview,\",\"text\":\"\\\" class=\\\"ab-text-link\\\">\"},{\"href\":\"<?= Security::e($row[\",\"text\":\"\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">\"},{\"href\":\"<?= Security::e($card[\",\"text\":\"\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-legal-link\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($faqTeaser,\",\"text\":\"\\\" class=\\\"ab-text-link\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($leadership,\",\"text\":\"\\\" class=\\\"ab-text-link\\\" style=\\\"margin-top:var(--space-6);display:inline-flex;align-items:center;gap:var(--space-2)\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($leadership,\",\"text\":\"\\\" class=\\\"ab-contact-cta\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($applyCta,\",\"text\":\"\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-btn-lime\\\">\"},{\"href\":\"<?= Security::e(CmsLoader::text($applyCta,\",\"text\":\"\\\" class=\\\"ab-btn-outline-dark\\\">\"},{\"href\":\"<?= Security::e($href) ?>\",\"text\":\"\"}],\"images\":[{\"src\":\"\",\"alt\":\"\"}],\"forms\":[],\"cms_keys\":[\"about_hero\",\"programme_overview\",\"core_commitments\",\"programme_history\",\"legal_framework\",\"partners_teaser\",\"faq_teaser\",\"leadership_contact\",\"apply_cta\"],\"text_content\":\"\'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>> Home About \\\" class=\\\"ab-btn-lime\\\"> \\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-btn-outline\\\"> \\\" class=\\\"ab-text-link\\\"> \\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\"> \\\"> \\\"> \\\"> \\\"> \\\" aria-hidden=\\\"true\\\"> \\\"> \\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-legal-link\\\"> \\\"> \\\" id=\\\"faq-trigger- \\\"> \\\" role=\\\"region\\\" aria-labelledby=\\\"faq-trigger- \\\"> \\\" class=\\\"ab-text-link\\\"> \\\"> \\\" class=\\\"ab-text-link\\\" style=\\\"margin-top:var(--space-6);display:inline-flex;align-items:center;gap:var(--space-2)\\\"> \\\" class=\\\"ab-contact-cta\\\"> \\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"ab-btn-lime\\\"> \\\" class=\\\"ab-btn-outline-dark\\\"> ab-kpi-icon\\\" aria-hidden=\\\"true\\\"> \\\" > \\\"> \\\"> <?php }\",\"raw_source\":\"<?php\\nrequire_once __DIR__ . \'/app/core/bootstrap.php\';\\n\\n$basePath = \'\';\\n$activePage = \'about\';\\n$aboutPage = CmsLoader::page(\'about\');\\n$projectStats = Project::stats();\\n$constituencies = Constituency::withProjectCounts();\\n\\n$hero = CmsLoader::content($aboutPage, \'about_hero\', about_defaults(\'about_hero\'));\\n$overview = CmsLoader::content($aboutPage, \'programme_overview\', about_defaults(\'programme_overview\'));\\n$pillars = CmsLoader::content($aboutPage, \'core_commitments\', about_defaults(\'core_commitments\'));\\n$history = CmsLoader::content($aboutPage, \'programme_history\', about_defaults(\'programme_history\'));\\n$legal = CmsLoader::content($aboutPage, \'legal_framework\', about_defaults(\'legal_framework\'));\\n$partners = CmsLoader::content($aboutPage, \'partners_teaser\', about_defaults(\'partners_teaser\'));\\n$faqTeaser = CmsLoader::content($aboutPage, \'faq_teaser\', about_defaults(\'faq_teaser\'));\\n$leadership = CmsLoader::content($aboutPage, \'leadership_contact\', about_defaults(\'leadership_contact\'));\\n$applyCta = CmsLoader::content($aboutPage, \'apply_cta\', about_defaults(\'apply_cta\'));\\n\\n$pageTitle = (string)($aboutPage[\'seo_title\'] ?? \'About the Programme | Trans-Nzoia AHP Tracker\');\\n$pageDescription = (string)($aboutPage[\'seo_description\'] ?? \'Learn about the Trans-Nzoia County Affordable Housing Programme - mandate, partners, legal framework and how to apply.\');\\n$pageKeywords = (string)($aboutPage[\'seo_keywords\'] ?? \'Trans-Nzoia affordable housing, AHP Kenya, housing programme, Boma Yangu, county housing policy\');\\n$pageAuthor = \'Trans-Nzoia County Government - Department of Land, Housing & Physical Planning\';\\n$pageRobots = \'index, follow\';\\n$themeColor = \'#163300\';\\n$canonicalUrl = (string)($aboutPage[\'canonical_url\'] ?? \'https://housing.transnzoia.go.ke/about.php\');\\n$heroImage = CmsLoader::text($hero, \'background_image\', (string)($aboutPage[\'hero_image\'] ?? \'uploads/gallery/maili-tatu-2.jpg\'));\\n$pageStyles = [\\n    \'assets/css/global.css\',\\n    \'assets/css/pages/about.css\',\\n];\\n$pageScripts = [\\n    \'assets/js/global.js\',\\n    \'assets/js/pages/about.js\',\\n];\\n$headMeta = [\\n    \'<meta name=\\\"geo.region\\\" content=\\\"KE-36\\\">\',\\n    \'<meta name=\\\"geo.placename\\\" content=\\\"Trans-Nzoia County, Kenya\\\">\',\\n    \'<meta property=\\\"og:title\\\" content=\\\"\' . Security::e($pageTitle) . \'\\\">\',\\n    \'<meta property=\\\"og:description\\\" content=\\\"\' . Security::e($pageDescription) . \'\\\">\',\\n    \'<meta property=\\\"og:type\\\" content=\\\"website\\\">\',\\n    \'<meta property=\\\"og:url\\\" content=\\\"\' . Security::e($canonicalUrl) . \'\\\">\',\\n    \'<meta property=\\\"og:image\\\" content=\\\"\' . Security::e($heroImage) . \'\\\">\',\\n    \'<meta property=\\\"og:locale\\\