_plain\' => \'Housing Projects\',\\n    \'title_highlight\' => \'Directory\',\\n    \'subtitle\' => \'Track every affordable housing project across Trans-Nzoia County - construction progress, contractor details, timelines and unit counts in real time.\',\\n    \'total_projects_label\' => \'Total Projects\',\\n    \'units_label\' => \'Units Planned\',\\n    \'active_label\' => \'Active\',\\n    \'constituencies_label\' => \'Constituencies\',\\n]);\\n$filters = CmsLoader::content($cmsPage, \'projects_filters\', [\\n    \'search_placeholder\' => \'Search projects...\',\\n    \'status_label\' => \'Status:\',\\n    \'all_label\' => \'All\',\\n    \'active_label\' => \'Active\',\\n    \'planning_label\' => \'Planning\',\\n    \'category_label\' => \'Category:\',\\n    \'constituency_label\' => \'Constituency:\',\\n    \'sort_label\' => \'Sort:\',\\n    \'sort_completion_desc\' => \'Completion high to low\',\\n    \'sort_completion_asc\' => \'Completion low to high\',\\n    \'sort_units_desc\' => \'Most units\',\\n    \'sort_name_asc\' => \'Name A-Z\',\\n    \'reset_label\' => \'Clear filters\',\\n]);\\n$listing = CmsLoader::content($cmsPage, \'projects_listing\', [\\n    \'results_prefix\' => \'Showing\',\\n    \'project_single\' => \'project\',\\n    \'project_plural\' => \'projects\',\\n    \'units_label\' => \'Units\',\\n    \'complete_label\' => \'Complete\',\\n    \'view_label\' => \'View Project\',\\n    \'pagination_showing_label\' => \'Showing\',\\n    \'pagination_of_label\' => \'of\',\\n    \'empty_title\' => \'No projects found\',\\n    \'empty_text\' => \'Try adjusting your filters or search term.\',\\n    \'empty_reset_label\' => \'Clear all filters\',\\n]);\\n\\n$initialFilters = [\\n    \'q\' => Security::cleanString((string)($_GET[\'search\'] ?? $_GET[\'q\'] ?? \'\')),\\n    \'status\' => Security::cleanString((string)($_GET[\'status\'] ?? \'\')),\\n    \'constituency\' => Security::cleanString((string)($_GET[\'constituency\'] ?? \'\')),\\n    \'category\' => Security::cleanString((string)($_GET[\'category\'] ?? \'\')),\\n    \'sort\' => Security::cleanString((string)($_GET[\'sort\'] ?? \'pct-desc\')),\\n];\\nforeach ([\'status\', \'constituency\', \'category\'] as $filterKey) {\\n    if (strtolower($initialFilters[$filterKey]) === \'all\') {\\n        $initialFilters[$filterKey] = \'\';\\n    }\\n}\\n$initialFilters[\'status\'] = in_array($initialFilters[\'status\'], [\'active\', \'planning\', \'completed\', \'on_hold\', \'stalled\'], true)\\n    ? $initialFilters[\'status\']\\n    : \'\';\\n$initialFilters[\'sort\'] = in_array($initialFilters[\'sort\'], [\'pct-desc\', \'pct-asc\', \'units-desc\', \'name-asc\', \'updated-desc\'], true)\\n    ? $initialFilters[\'sort\']\\n    : \'pct-desc\';\\n$hasInitialFilters = $initialFilters[\'q\'] !== \'\'\\n    || $initialFilters[\'status\'] !== \'\'\\n    || $initialFilters[\'constituency\'] !== \'\'\\n    || $initialFilters[\'category\'] !== \'\'\\n    || $initialFilters[\'sort\'] !== \'pct-desc\';\\n\\n$projects = Project::publicListing($initialFilters);\\n$constituencies = Project::publicConstituencies();\\n$categories = Project::publicCategories();\\n$projectStats = Project::publicStats($initialFilters);\\n$coverageConstituencies = class_exists(\'Constituency\') ? Constituency::publicList() : [];\\n$featuredProjects = array_slice($projects, 0, 3);\\n\\n$totalProjects = (int)($projectStats[\'total_projects\'] ?? count($projects));\\n$totalUnits = (int)($projectStats[\'total_units\'] ?? 0);\\n$activeProjects = (int)($projectStats[\'active_projects\'] ?? 0);\\n$coveredConstituencies = (int)($projectStats[\'constituencies\'] ?? 0);\\n$publicPayload = public_page_payload(\'projects\', [\\n    \'projects\' => $projects,\\n    \'constituencies\' => $constituencies,\\n    \'coverage_constituencies\' => $coverageConstituencies,\\n    \'featured_projects\' => $featuredProjects,\\n    \'categories\' => $categories,\\n    \'stats\' => $projectStats,\\n], [\\n    \'title\' => \'All Projects\',\\n    \'description\' => \'Browse affordable housing projects across Trans-Nzoia County.\',\\n]);\\n\\n$pageTitle = $cmsPage[\'seo_title\'] ?? \'All Projects | Trans-Nzoia County Affordable Housing Tracker\';\\n$pageDescription = $cmsPage[\'seo_description\'] ?? \'Browse all affordable housing projects in Trans-Nzoia County with live construction progress, contractor details and unit counts across all 5 constituencies.\';\\n$pageKeywords = $cmsPage[\'seo_keywords\'] ?? \'Trans-Nzoia affordable housing projects, AHP Kenya, Maili Tatu estate, Matunda estate, Saboti housing, Cherangany housing\';\\n$pageAuthor = \'Trans-Nzoia County Government - Department of Land, Housing & Physical Planning\';\\n$pageRobots = \'index, follow\';\\n$themeColor = \'#163300\';\\n$canonicalUrl = $cmsPage[\'canonical_url\'] ?? \'https://housing.transnzoia.go.ke/projects.php\';\\n$pageStyles = [\\n    \'assets/css/global.css\',\\n    \'assets/css/pages/projects.css\',\\n];\\n$pageScripts = [\\n    \'assets/js/global.js\',\\n    \'assets/js/pages/projects.js\',\\n];\\n\\n$e = static fn (mixed $value): string => Security::e($value);\\n$text = static fn (array $content, string $key, string $default = \'\'): string => CmsLoader::text($content, $key, $default);\\n$asset = static function (?string $path): string {\\n    $path = trim((string)$path);\\n    if ($path === \'\') {\\n        return \'\';\\n    }\\n    return preg_match(\'#^https?://#i\', $path) ? $path : $path;\\n};\\n$statusLabel = static function (string $status): string {\\n    return match ($status) {\\n        \'active\' => \'Active\',\\n        \'completed\' => \'Completed\',\\n        \'stalled\' => \'Stalled\',\\n        \'on_hold\' => \'On Hold\',\\n        \'cancelled\' => \'Cancelled\',\\n        default => \'Planning\',\\n    };\\n};\\n$publicStatus = static function (string $status): string {\\n    return $status === \'active\' || $status === \'completed\' ? \'active\' : \'planning\';\\n};\\n$isActiveFilter = static fn (string $current, string $value): string => $current === $value ? \' is-active\' : \'\';\\n$isSelected = static fn (string $current, string $value): string => $current === $value ? \' selected\' : \'\';\\n\\n$headMeta = [\\n    \'<meta property=\\\"og:title\\\" content=\\\"\' . $e($pageTitle) . \'\\\">\',\\n    \'<meta property=\\\"og:description\\\" content=\\\"\' . $e($pageDescription) . \'\\\">\',\\n    \'<meta property=\\\"og:type\\\" content=\\\"website\\\">\',\\n    \'<meta property=\\\"og:url\\\" content=\\\"\' . $e($canonicalUrl) . \'\\\">\',\\n    \'<meta property=\\\"og:image\\\" content=\\\"\' . $e($asset((string)($hero[\'background_image\'] ?? \'uploads/gallery/maili-tatu-2.jpg\'))) . \'\\\">\',\\n    \'<meta property=\\\"og:locale\\\" content=\\\"en_KE\\\">\',\\n    \'<meta property=\\\"og:site_name\\\" content=\\\"Trans-Nzoia AHP Tracker\\\">\',\\n    \'<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\">\',\\n    \'<meta name=\\\"twitter:title\\\" content=\\\"\' . $e($pageTitle) . \'\\\">\',\\n    \'<meta name=\\\"twitter:description\\\" content=\\\"\' . $e($pageDescription) . \'\\\">\',\\n    \'<meta name=\\\"twitter:image\\\" content=\\\"\' . $e($asset((string)($hero[\'background_image\'] ?? \'uploads/gallery/maili-tatu-2.jpg\'))) . \'\\\">\',\\n];\\n\\ninclude __DIR__ . \'/app/partials/head.php\';\\n?>\\n<body>\\n<?php include __DIR__ . \'/app/partials/cursor.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/skip-link.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/navbar.php\'; ?>\\n<main id=\\\"main-content\\\">\\n\\n    <section class=\\\"page-hero page-hero--projects\\\" aria-label=\\\"Projects directory\\\">\\n      <div class=\\\"page-hero-bg\\\" aria-hidden=\\\"true\\\">\\n        <?php $heroImage = $asset((string)($hero[\'background_image\'] ?? \'uploads/gallery/maili-tatu-2.jpg\')); ?>\\n        <?php if ($heroImage !== \'\'): ?>\\n          <img <?= public_image_attrs($heroImage, $text($hero, \'background_alt\', \'\'), [\'loading\' => \'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \\\"this.style.display=\'none\'\\\"]) ?>>\\n        <?php endif; ?>\\n        <div class=\\\"page-hero-overlay\\\"></div>\\n      </div>\\n      <div class=\\\"container\\\">\\n        <nav class=\\\"breadcrumb\\\" aria-label=\\\"Breadcrumb\\\">\\n          <a href=\\\"index.php\\\" class=\\\"breadcrumb-link\\\">Home</a>\\n          <i class=\\\"fa-solid fa-chevron-right breadcrumb-sep\\\" aria-hidden=\\\"true\\\"></i>\\n          <span class=\\\"breadcrumb-current\\\">All Projects</span>\\n        </nav>\\n        <div class=\\\"page-hero-body\\\">\\n          <div class=\\\"page-hero-eyebrow\\\">\\n            <span class=\\\"page-hero-tag\\\"><i class=\\\"fa-solid fa-building-columns\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($hero, \'eyebrow\', \'AHP Projects\')) ?></span>\\n          </div>\\n          <h1 class=\\\"page-hero-title\\\"><?= $e($text($hero, \'title_plain\', \'Housing Projects\')) ?><br><span class=\\\"text-lime\\\"><?= $e($text($hero, \'title_highlight\', \'Directory\')) ?></span></h1>\\n          <p class=\\\"page-hero-sub\\\"><?= $e($text($hero, \'subtitle\', \'Track every affordable housing project across Trans-Nzoia County - construction progress, contractor details, timelines and unit counts in real time.\')) ?></p>\\n        </div>\\n        <div class=\\\"projects-hero-stats\\\" role=\\\"region\\\" aria-label=\\\"Programme statistics\\\">\\n          <div class=\\\"phs-item\\\">\\n            <span class=\\\"phs-val\\\" id=\\\"statTotalProjects\\\"><?= $e(format_number($totalProjects)) ?></span>\\n            <span class=\\\"phs-lbl\\\"><?= $e($text($hero, \'total_projects_label\', \'Total Projects\')) ?></span>\\n          </div>\\n          <div class=\\\"phs-divider\\\" aria-hidden=\\\"true\\\"></div>\\n          <div class=\\\"phs-item\\\">\\n            <span class=\\\"phs-val\\\" id=\\\"statTotalUnits\\\"><?= $e(format_number($totalUnits)) ?></span>\\n            <span class=\\\"phs-lbl\\\"><?= $e($text($hero, \'units_label\', \'Units Planned\')) ?></span>\\n          </div>\\n          <div class=\\\"phs-divider\\\" aria-hidden=\\\"true\\\"></div>\\n          <div class=\\\"phs-item\\\">\\n            <span class=\\\"phs-val\\\" id=\\\"statActiveProjects\\\"><?= $e(format_number($activeProjects)) ?></span>\\n            <span class=\\\"phs-lbl\\\"><?= $e($text($hero, \'active_label\', \'Active\')) ?></span>\\n          </div>\\n          <div class=\\\"phs-divider\\\" aria-hidden=\\\"true\\\"></div>\\n          <div class=\\\"phs-item\\\">\\n            <span class=\\\"phs-val\\\" id=\\\"statConstituencies\\\"><?= $e(format_number($coveredConstituencies)) ?></span>\\n            <span class=\\\"phs-lbl\\\"><?= $e($text($hero, \'constituencies_label\', \'Constituencies\')) ?></span>\\n          </div>\\n        </div>\\n      </div>\\n    </section>\\n\\n    <section class=\\\"projects-coverage-section\\\" aria-label=\\\"Project coverage summary\\\">\\n      <div class=\\\"container\\\">\\n        <div class=\\\"projects-coverage-grid\\\">\\n          <div class=\\\"projects-coverage-map\\\">\\n            <div class=\\\"pcv-section-label\\\">County Coverage</div>\\n            <h2 class=\\\"pcv-title\\\">Projects Across Trans-Nzoia</h2>\\n            <p class=\\\"pcv-subtitle\\\">Browse active and planned housing works by constituency, progress and unit count.</p>\\n            <div class=\\\"pcv-map-wrap\\\" aria-label=\\\"Trans-Nzoia constituencies map\\\">\\n              <svg viewBox=\\\"0 0 480 400\\\" xmlns=\\\"http://www.w3.org/2000/svg\\\" role=\\\"img\\\" aria-label=\\\"Public project coverage map\\\">\\n<?php foreach (Constituency::mapShapes() as $slug => $shape): ?>\\n<?php\\n    $coverageItem = null;\\n    foreach ($coverageConstituencies as $candidate) {\\n        if ((string)$candidate[\'slug\'] === $slug) {\\n            $coverageItem = $candidate;\\n            break;\\n        }\\n    }\\n    $coverageName = $coverageItem[\'name\'] ?? ucwords($slug);\\n    $coverageCount = (int)($coverageItem[\'projectCount\'] ?? 0);\\n?>\\n                <g class=\\\"pcv-map-region<?= $coverageCount > 0 ? \' has-projects\' : \'\' ?>\\\">\\n                  <path d=\\\"<?= $e($shape[\'path\']) ?>\\\"></path>\\n                  <text x=\\\"<?= (int)$shape[\'label_x\'] ?>\\\" y=\\\"<?= (int)$shape[\'label_y\'] ?>\\\"><?= $e($coverageName) ?></text>\\n                  <text class=\\\"pcv-map-sub\\\" x=\\\"<?= (int)$shape[\'label_x\'] ?>\\\" y=\\\"<?= (int)$shape[\'sub_y\'] ?>\\\"><?= $e($coverageCount . \' \' . ($coverageCount === 1 ? \'project\' : \'projects\')) ?></text>\\n                </g>\\n<?php endforeach; ?>\\n              </svg>\\n            </div>\\n          </div>\\n          <div class=\\\"projects-coverage-list\\\">\\n            <div class=\\\"pcv-list-head\\\">\\n              <div>\\n                <div class=\\\"pcv-section-label\\\">Constituency Snapshot</div>\\n                <h2 class=\\\"pcv-title\\\">Where Work Is Happening</h2>\\n              </div>\\n              <a href=\\\"constituencies.php\\\" class=\\\"pcv-link\\\">View constituencies <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i></a>\\n            </div>\\n            <div class=\\\"pcv-constituency-cards\\\">\\n<?php foreach ($coverageConstituencies as $item): ?>\\n              <?php $constituencySlug = (string)$item[\'slug\']; ?>\\n              <a href=\\\"constituency-detail.php?id=<?= $e(rawurlencode($constituencySlug)) ?>\\\" class=\\\"pcv-card\\\">\\n                <div>\\n                  <h3><?= $e($item[\'name\']) ?></h3>\\n                  <p><?= $e(implode(\' / \', array_slice($item[\'wards\'], 0, 3))) ?></p>\\n                </div>\\n                <div class=\\\"pcv-card-stats\\\">\\n                  <span><strong><?= $e((string)$item[\'projectCount\']) ?></strong> projects</span>\\n                  <span><strong><?= $e(format_number((int)$item[\'totalUnits\'])) ?></strong> units</span>\\n                  <span><strong><?= $e((string)$item[\'avgCompletion\']) ?>%</strong> complete</span>\\n                </div>\\n              </a>\\n<?php endforeach; ?>\\n            </div>\\n          </div>\\n        </div>\\n      </div>\\n    </section>\\n\\n    <section class=\\\"projects-main\\\" aria-label=\\\"Project listings\\\">\\n      <div class=\\\"container\\\">\\n        <div class=\\\"projects-filter-bar\\\" role=\\\"search\\\" aria-label=\\\"Filter projects\\\">\\n          <div class=\\\"pfb-search-wrap\\\">\\n            <i class=\\\"fa-solid fa-magnifying-glass pfb-search-icon\\\" aria-hidden=\\\"true\\\"></i>\\n            <input type=\\\"search\\\" class=\\\"pfb-search-input\\\" id=\\\"projectSearch\\\" value=\\\"<?= $e($initialFilters[\'q\']) ?>\\\" placeholder=\\\"<?= $e($text($filters, \'search_placeholder\', \'Search projects...\')) ?>\\\" aria-label=\\\"Search projects by name or location\\\">\\n          </div>\\n          <div class=\\\"pfb-filters\\\" role=\\\"group\\\" aria-label=\\\"Filter by status\\\">\\n            <span class=\\\"pfb-label\\\"><?= $e($text($filters, \'status_label\', \'Status:\')) ?></span>\\n            <button class=\\\"pfb-chip<?= $initialFilters[\'status\'] === \'\' ? \' is-active\' : \'\' ?>\\\" type=\\\"button\\\" data-filter-status=\\\"all\\\"><?= $e($text($filters, \'all_label\', \'All\')) ?></button>\\n            <button class=\\\"pfb-chip<?= $isActiveFilter($initialFilters[\'status\'], \'active\') ?>\\\" type=\\\"button\\\" data-filter-status=\\\"active\\\">\\n              <span class=\\\"pfb-chip-dot pfb-chip-dot--active\\\" aria-hidden=\\\"true\\\"></span><?= $e($text($filters, \'active_label\', \'Active\')) ?>\\n            </button>\\n            <button class=\\\"pfb-chip<?= $isActiveFilter($initialFilters[\'status\'], \'planning\') ?>\\\" type=\\\"button\\\" data-filter-status=\\\"planning\\\">\\n              <span class=\\\"pfb-chip-dot pfb-chip-dot--planning\\\" aria-hidden=\\\"true\\\"></span><?= $e($text($filters, \'planning_label\', \'Planning\')) ?>\\n            </button>\\n          </div>\\n          <div class=\\\"pfb-filters\\\" role=\\\"group\\\" aria-label=\\\"Filter by constituency\\\">\\n            <span class=\\\"pfb-label\\\"><?= $e($text($filters, \'constituency_label\', \'Constituency:\')) ?></span>\\n            <button class=\\\"pfb-chip<?= $initialFilters[\'constituency\'] === \'\' ? \' is-active\' : \'\' ?>\\\" type=\\\"button\\\" data-filter-con=\\\"all\\\"><?= $e($text($filters, \'all_label\', \'All\')) ?></button>\\n<?php foreach ($constituencies as $constituency): ?>\\n            <button class=\\\"pfb-chip<?= $isActiveFilter($initialFilters[\'constituency\'], (string)$constituency[\'slug\']) ?>\\\" type=\\\"button\\\" data-filter-con=\\\"<?= $e($constituency[\'slug\']) ?>\\\"><?= $e($constituency[\'name\']) ?></button>\\n<?php endforeach; ?>\\n          </div>\\n<?php if ($categories): ?>\\n          <div class=\\\"pfb-filters\\\" role=\\\"group\\\" aria-label=\\\"Filter by project category\\\">\\n            <span class=\\\"pfb-label\\\"><?= $e($text($filters, \'category_label\', \'Category:\')) ?></span>\\n            <button class=\\\"pfb-chip<?= $initialFilters[\'category\'] === \'\' ? \' is-active\' : \'\' ?>\\\" type=\\\"button\\\" data-filter-category=\\\"all\\\"><?= $e($text($filters, \'all_label\', \'All\')) ?></button>\\n<?php foreach ($categories as $category): ?>\\n            <button class=\\\"pfb-chip<?= $isActiveFilter($initialFilters[\'category\'], (string)$category[\'slug\']) ?>\\\" type=\\\"button\\\" data-filter-category=\\\"<?= $e($category[\'slug\']) ?>\\\"><?= $e($category[\'name\']) ?></button>\\n<?php endforeach; ?>\\n          </div>\\n<?php endif; ?>\\n          <div class=\\\"pfb-sort-wrap\\\">\\n            <label for=\\\"projectSort\\\" class=\\\"pfb-label\\\"><?= $e($text($filters, \'sort_label\', \'Sort:\')) ?></label>\\n            <select id=\\\"projectSort\\\" class=\\\"pfb-sort-select\\\" aria-label=\\\"Sort projects\\\">\\n              <option value=\\\"pct-desc\\\"<?= $isSelected($initialFilters[\'sort\'], \'pct-desc\') ?>><?= $e($text($filters, \'sort_completion_desc\', \'Completion high to low\')) ?></option>\\n              <option value=\\\"pct-asc\\\"<?= $isSelected($initialFilters[\'sort\'], \'pct-asc\') ?>><?= $e($text($filters, \'sort_completion_asc\', \'Completion low to high\')) ?></option>\\n              <option value=\\\"units-desc\\\"<?= $isSelected($initialFilters[\'sort\'], \'units-desc\') ?>><?= $e($text($filters, \'sort_units_desc\', \'Most units\')) ?></option>\\n              <option value=\\\"name-asc\\\"<?= $isSelected($initialFilters[\'sort\'], \'name-asc\') ?>><?= $e($text($filters, \'sort_name_asc\', \'Name A-Z\')) ?></option>\\n            </select>\\n          </div>\\n        </div>\\n\\n        <div class=\\\"projects-results-meta\\\" aria-live=\\\"polite\\\" aria-atomic=\\\"true\\\">\\n          <span id=\\\"resultsCount\\\"><?= $e($text($listing, \'results_prefix\', \'Showing\')) ?> <?= $e(format_number($totalProjects)) ?> <?= $e($totalProjects === 1 ? $text($listing, \'project_single\', \'project\') : $text($listing, \'project_plural\', \'projects\')) ?></span>\\n          <button class=\\\"pfb-reset\\\" type=\\\"button\\\" id=\\\"resetFilters\\\"<?= $hasInitialFilters ? \'\' : \' hidden\' ?>>\\n            <i class=\\\"fa-solid fa-xmark\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($filters, \'reset_label\', \'Clear filters\')) ?>\\n          </button>\\n        </div>\\n\\n        <div class=\\\"projects-grid\\\"\\n             id=\\\"projectsGrid\\\"\\n             role=\\\"list\\\"\\n             data-api-url=\\\"<?= $e(public_url(\'api/public/projects.php\')) ?>\\\"\\n             data-results-prefix=\\\"<?= $e($text($listing, \'results_prefix\', \'Showing\')) ?>\\\"\\n             data-project-single=\\\"<?= $e($text($listing, \'project_single\', \'project\')) ?>\\\"\\n             data-project-plural=\\\"<?= $e($text($listing, \'project_plural\', \'projects\')) ?>\\\"\\n             data-units-label=\\\"<?= $e($text($listing, \'units_label\', \'Units\')) ?>\\\"\\n             data-complete-label=\\\"<?= $e($text($listing, \'complete_label\', \'Complete\')) ?>\\\"\\n             data-view-label=\\\"<?= $e($text($listing, \'view_label\', \'View Project\')) ?>\\\"\\n             data-pagination-showing=\\\"<?= $e($text($listing, \'pagination_showing_label\', \'Showing\')) ?>\\\"\\n             data-pagination-of=\\\"<?= $e($text($listing, \'pagination_of_label\', \'of\')) ?>\\\">\\n<?php foreach ($projects as $index => $project): ?>\\n          <?php\\n            $status = (string)($project[\'status\'] ?? \'planning\');\\n            $displayStatus = $publicStatus($status);\\n            $pct = max(0, min(100, (int)($project[\'pct_complete\'] ?? 0)));\\n            $image = $asset((string)($project[\'hero_image\'] ?? \'\'));\\n            $name = (string)($project[\'name\'] ?? \'Project\');\\n            $search = strtolower(trim(implode(\' \', [\\n                $name,\\n                $project[\'constituency_name\'] ?? \'\',\\n                $project[\'ward_name\'] ?? \'\',\\n                $project[\'contractor_name\'] ?? \'\',\\n                $project[\'current_milestone\'] ?? \'\',\\n            ])));\\n          ?>\\n          <article class=\\\"proj-card is-visible\\\"\\n                   role=\\\"listitem\\\"\\n                   style=\\\"animation-delay:<?= (int)($index % 6) * 55 ?>ms\\\"\\n                   data-status=\\\"<?= $e($displayStatus) ?>\\\"\\n                   data-constituency=\\\"<?= $e($project[\'constituency_slug\'] ?? \'\') ?>\\\"\\n                   data-category=\\\"<?= $e($project[\'category_slug\'] ?? \'\') ?>\\\"\\n                   data-name=\\\"<?= $e(strtolower($name)) ?>\\\"\\n                   data-units=\\\"<?= (int)($project[\'units\'] ?? 0) ?>\\\"\\n                   data-pct=\\\"<?= $pct ?>\\\"\\n                   data-search=\\\"<?= $e($search) ?>\\\">\\n            <div class=\\\"proj-card-img\\\">\\n<?php if ($image !== \'\'): ?>\\n              <img <?= public_image_attrs($image, $name, [\'onerror\' => \\\"this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\'\\\"]) ?>>\\n              <div class=\\\"proj-card-img-placeholder\\\" style=\\\"display:none\\\"><i class=\\\"fa-solid fa-building\\\" aria-hidden=\\\"true\\\"></i></div>\\n<?php else: ?>\\n              <div class=\\\"proj-card-img-placeholder\\\"><i class=\\\"fa-solid fa-building\\\" aria-hidden=\\\"true\\\"></i></div>\\n<?php endif; ?>\\n              <span class=\\\"proj-status-badge proj-status-badge--<?= $e($displayStatus) ?>\\\" aria-label=\\\"Status: <?= $e($statusLabel($status)) ?>\\\"><?= $e($statusLabel($status)) ?></span>\\n              <span class=\\\"proj-con-tag\\\"><?= $e($project[\'constituency_name\'] ?? \'\') ?></span>\\n            </div>\\n            <div class=\\\"proj-card-body\\\">\\n              <div class=\\\"proj-card-meta\\\">\\n                <span class=\\\"proj-ward\\\"><?= $e($project[\'ward_name\'] ?? $project[\'location_label\'] ?? \'\') ?></span>\\n              </div>\\n              <h3 class=\\\"proj-card-title\\\"><?= $e($name) ?></h3>\\n              <div class=\\\"proj-card-stats\\\">\\n                <div class=\\\"proj-stat\\\">\\n                  <span class=\\\"proj-stat-val\\\"><?= $e(format_number((int)($project[\'units\'] ?? 0))) ?></span>\\n                  <span class=\\\"proj-stat-lbl\\\"><?= $e($text($listing, \'units_label\', \'Units\')) ?></span>\\n                </div>\\n                <div class=\\\"proj-stat\\\">\\n                  <span class=\\\"proj-stat-val\\\"><?= $pct ?>%</span>\\n                  <span class=\\\"proj-stat-lbl\\\"><?= $e($text($listing, \'complete_label\', \'Complete\')) ?></span>\\n                </div>\\n              </div>\\n              <div class=\\\"proj-progress\\\" role=\\\"progressbar\\\" aria-valuenow=\\\"<?= $pct ?>\\\" aria-valuemin=\\\"0\\\" aria-valuemax=\\\"100\\\" aria-label=\\\"<?= $pct ?>% complete\\\">\\n                <div class=\\\"proj-progress-fill\\\" data-target=\\\"<?= $pct ?>\\\"></div>\\n              </div>\\n              <div class=\\\"proj-milestone\\\">\\n                <i class=\\\"fa-solid fa-hard-hat\\\" aria-hidden=\\\"true\\\"></i>\\n                <span><?= $e($project[\'current_milestone\'] ?? \'Project details pending\') ?></span>\\n              </div>\\n              <div class=\\\"proj-card-footer\\\">\\n                <span class=\\\"proj-contractor\\\" title=\\\"<?= $e($project[\'contractor_name\'] ?? \'\') ?>\\\"><?= $e($project[\'contractor_name\'] ?? \'\') ?></span>\\n                <a href=\\\"project-detail.php?id=<?= $e(rawurlencode((string)($project[\'slug\'] ?? \'\'))) ?>\\\" class=\\\"proj-cta\\\" aria-label=\\\"View details for <?= $e($name) ?>\\\">\\n                  <?= $e($text($listing, \'view_label\', \'View Project\')) ?> <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i>\\n                </a>\\n              </div>\\n            </div>\\n          </article>\\n<?php endforeach; ?>\\n        </div>\\n\\n        <nav class=\\\"projects-pagination\\\" id=\\\"projectsPagination\\\" aria-label=\\\"Project pages\\\" hidden></nav>\\n\\n        <div class=\\\"projects-empty\\\" id=\\\"projectsEmpty\\\" hidden aria-live=\\\"polite\\\">\\n          <div class=\\\"projects-empty-icon\\\" aria-hidden=\\\"true\\\">\\n            <i class=\\\"fa-solid fa-building-circle-xmark\\\"></i>\\n          </div>\\n          <h3><?= $e($text($listing, \'empty_title\', \'No projects found\')) ?></h3>\\n          <p><?= $e($text($listing, \'empty_text\', \'Try adjusting your filters or search term.\')) ?></p>\\n          <button class=\\\"btn btn-primary\\\" type=\\\"button\\\" id=\\\"emptyReset\\\"><?= $e($text($listing, \'empty_reset_label\', \'Clear all filters\')) ?></button>\\n        </div>\\n      </div>\\n    </section>\\n\\n  </main>\\n\\n<?php include __DIR__ . \'/app/partials/footer.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/back-to-top.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/mobile-menu.php\'; ?>\\n<?= public_json_script(\'ahp-page-data\', $publicPayload) ?>\\n<?php include __DIR__ . \'/app/partials/scripts.php\'; ?>\\n</body>\\n</html>\\n\"}', '2026-06-24 18:05:14', '2026-06-24 18:05:14');
INSERT INTO `public_frontend_content_snapshots` (`id`, `page_slug`, `page_label`, `file_path`, `source_hash`, `raw_source`, `extracted_text`, `extracted_json`, `seeded_at`, `updated_at`) VALUES
(4, 'project-detail', 'Project Detail', 'project-detail.php', '043ddeba617c3a34432e2158455771392e66989b02467645901504decb989e73', '<?php\nrequire_once __DIR__ . \'/app/core/bootstrap.php\';\n\n$basePath = \'\';\n$activePage = \'projects\';\n$cmsPage = CmsLoader::publicPage(\'project-detail\');\n$labels = CmsLoader::content($cmsPage, \'project_detail_labels\', []);\n$overview = CmsLoader::content($cmsPage, \'project_detail_overview\', []);\n$sidebar = CmsLoader::content($cmsPage, \'project_detail_sidebar\', []);\n$applyCta = CmsLoader::content($cmsPage, \'project_detail_apply_cta\', []);\n$notFound = CmsLoader::content($cmsPage, \'project_detail_not_found\', []);\n$text = static fn (array $content, string $key, string $default = \'\'): string => CmsLoader::text($content, $key, $default);\n$e = static fn (mixed $value): string => Security::e($value);\n\n$lookup = trim((string)($_GET[\'id\'] ?? $_GET[\'slug\'] ?? \'\'));\n$project = $lookup !== \'\' ? Project::publicDetail($lookup) : null;\n$isFound = is_array($project);\n\nif (!$isFound) {\n    http_response_code(404);\n}\n\nif (!function_exists(\'pd_asset_url\')) {\n    function pd_asset_url(?string $path): string\n    {\n        $path = trim((string)$path);\n        if ($path === \'\') {\n            return \'\';\n        }\n        if (preg_match(\'#^(?:[a-z][a-z0-9+.-]*:)?//#i\', $path) || str_starts_with($path, \'data:\')) {\n            return $path;\n        }\n        return Url::asset($path);\n    }\n}\n\nif (!function_exists(\'pd_images\')) {\n    function pd_images(array $project): array\n    {\n        $images = [];\n        $hero = trim((string)($project[\'hero_image\'] ?? \'\'));\n        if ($hero !== \'\') {\n            $images[] = $hero;\n        }\n\n        $decoded = json_decode((string)($project[\'images_json\'] ?? \'[]\'), true);\n        if (is_array($decoded)) {\n            foreach ($decoded as $image) {\n                $image = trim((string)$image);\n                if ($image !== \'\') {\n                    $images[] = $image;\n                }\n            }\n        }\n\n        $unique = [];\n        foreach ($images as $image) {\n            if (!in_array($image, $unique, true)) {\n                $unique[] = $image;\n            }\n        }\n\n        return $unique;\n    }\n}\n\nif (!function_exists(\'pd_quarter_label\')) {\n    function pd_quarter_label(?string $date, string $fallback = \'\'): string\n    {\n        $date = trim((string)$date);\n        if ($date === \'\' || $date === \'0000-00-00\') {\n            return $fallback;\n        }\n        $timestamp = strtotime($date);\n        if (!$timestamp) {\n            return $date;\n        }\n        return \'Q\' . (int)ceil((int)date(\'n\', $timestamp) / 3) . \' \' . date(\'Y\', $timestamp);\n    }\n}\n\nif (!function_exists(\'pd_date_label\')) {\n    function pd_date_label(?string $date, string $fallback = \'\'): string\n    {\n        $date = trim((string)$date);\n        if ($date === \'\' || $date === \'0000-00-00\') {\n            return $fallback;\n        }\n        $timestamp = strtotime($date);\n        return $timestamp ? date(\'j M Y\', $timestamp) : $date;\n    }\n}\n\nif (!function_exists(\'pd_number\')) {\n    function pd_number(mixed $value): string\n    {\n        return number_format((float)$value, 0);\n    }\n}\n\nif (!function_exists(\'pd_status_class\')) {\n    function pd_status_class(string $status): string\n    {\n        return match ($status) {\n            \'active\' => \'active\',\n            \'completed\' => \'completed\',\n            \'on_hold\', \'stalled\' => \'watch\',\n            default => \'planning\',\n        };\n    }\n}\n\nif (!function_exists(\'pd_status_label\')) {\n    function pd_status_label(string $status, array $labels): string\n    {\n        return match ($status) {\n            \'active\' => CmsLoader::text($labels, \'active_status_label\', \'Active\'),\n            \'completed\' => CmsLoader::text($labels, \'completed_status_label\', \'Completed\'),\n            \'on_hold\', \'stalled\' => CmsLoader::text($labels, \'watch_status_label\', \'On Hold\'),\n            default => CmsLoader::text($labels, \'planning_status_label\', \'Planning\'),\n        };\n    }\n}\n\nif (!function_exists(\'pd_icon_for_status\')) {\n    function pd_icon_for_status(string $status): string\n    {\n        return match ($status) {\n            \'active\' => \'fa-circle-dot\',\n            \'completed\' => \'fa-circle-check\',\n            \'on_hold\', \'stalled\' => \'fa-triangle-exclamation\',\n            default => \'fa-clock\',\n        };\n    }\n}\n\n$images = $isFound ? pd_images($project) : [];\n$projectName = $isFound ? (string)($project[\'name\'] ?? \'Project Detail\') : $text($notFound, \'title\', \'Project Not Found\');\n$projectDescription = $isFound\n    ? trim((string)($project[\'full_description\'] ?? $project[\'description\'] ?? \'\'))\n    : $text($notFound, \'text\', \"The project you\'re looking for doesn\'t exist or the URL is incorrect.\");\n$pageTitle = $isFound\n    ? $projectName . \' | Trans-Nzoia County Affordable Housing Tracker\'\n    : $text($notFound, \'title\', \'Project Not Found\') . \' | Trans-Nzoia County Affordable Housing Tracker\';\n$pageDescription = $isFound && $projectDescription !== \'\'\n    ? substr(strip_tags($projectDescription), 0, 160)\n    : ($cmsPage[\'seo_description\'] ?? \'Detailed construction progress, contractor information, milestones and site photos for an affordable housing project in Trans-Nzoia County.\');\n$pageKeywords = $cmsPage[\'seo_keywords\'] ?? \'Trans-Nzoia AHP project detail, affordable housing Kenya, construction progress\';\n$pageAuthor = \'Trans-Nzoia County Government - Department of Land, Housing & Physical Planning\';\n$pageRobots = $isFound ? \'index, follow\' : \'noindex, follow\';\n$themeColor = \'#163300\';\n$canonicalUrl = $isFound\n    ? \'https://housing.transnzoia.go.ke/project-detail.php?id=\' . rawurlencode((string)($project[\'slug\'] ?? $lookup))\n    : \'https://housing.transnzoia.go.ke/project-detail.php\';\n$pageStyles = [\n    \'assets/css/global.css\',\n    \'assets/css/pages/project-detail.css\',\n];\n$pageScripts = [\n    \'assets/js/global.js\',\n    \'assets/js/pages/project-detail.js\',\n];\n$milestones = [];\n$programmeSummary = [];\n$galleryMedia = [];\n$relatedProjects = [];\n$publicPayload = public_page_payload(\'project-detail\', [], [\n    \'title\' => $projectName,\n    \'description\' => $pageDescription,\n]);\nif ($isFound) {\n    $milestones = Milestone::publicForProject((int)$project[\'id\']);\n    $programmeSummary = ProgrammeTask::publicSummaryForProject((int)$project[\'id\']);\n    $galleryMedia = GalleryImage::publicForProject((int)$project[\'id\'], 48);\n    foreach ($galleryMedia as $galleryItem) {\n        $image = (string)($galleryItem[\'full_url\'] ?: $galleryItem[\'url\'] ?? \'\');\n        if ($image !== \'\' && !in_array($image, $images, true)) {\n            $images[] = $image;\n        }\n    }\n    $relatedProjects = Project::publicRelated($project, 4);\n    $publicPayload = public_page_payload(\'project-detail\', [\n        \'project\' => $project,\n        \'milestones\' => $milestones,\n        \'programme\' => $programmeSummary,\n        \'gallery\' => $galleryMedia,\n        \'related_projects\' => $relatedProjects,\n    ], [\n        \'title\' => $projectName,\n        \'description\' => $pageDescription,\n    ]);\n}\n$heroImage = $images[0] ?? \'\';\n$headMeta = [\n    \'<meta property=\"og:title\" content=\"\' . $e($pageTitle) . \'\">\',\n    \'<meta property=\"og:type\" content=\"website\">\',\n    \'<meta property=\"og:locale\" content=\"en_KE\">\',\n    \'<meta property=\"og:site_name\" content=\"Trans-Nzoia AHP Tracker\">\',\n    \'<meta name=\"twitter:card\" content=\"summary_large_image\">\',\n];\nif ($heroImage !== \'\') {\n    $headMeta[] = \'<meta property=\"og:image\" content=\"\' . $e(pd_asset_url($heroImage)) . \'\">\';\n}\n\ninclude __DIR__ . \'/app/partials/head.php\';\n?>\n<body>\n<?php include __DIR__ . \'/app/partials/cursor.php\'; ?>\n<?php include __DIR__ . \'/app/partials/skip-link.php\'; ?>\n<?php include __DIR__ . \'/app/partials/navbar.php\'; ?>\n<main id=\"main-content\">\n\n<?php if (!$isFound): ?>\n  <section class=\"pd-not-found\" id=\"pdNotFound\">\n    <div class=\"container\">\n      <div class=\"pd-not-found-inner\">\n        <i class=\"fa-solid fa-building-circle-xmark pd-not-found-icon\" aria-hidden=\"true\"></i>\n        <h1><?= $e($text($notFound, \'title\', \'Project Not Found\')) ?></h1>\n        <p><?= $e($text($notFound, \'text\', \"The project you\'re looking for doesn\'t exist or the URL is incorrect.\")) ?></p>\n        <a href=\"projects.php\" class=\"btn btn-primary\">\n          <i class=\"fa-solid fa-arrow-left\" aria-hidden=\"true\"></i> <?= $e($text($notFound, \'button_label\', \'Back to All Projects\')) ?>\n        </a>\n      </div>\n    </div>\n  </section>\n<?php else:\n    $status = (string)($project[\'status\'] ?? \'planning\');\n    $statusClass = pd_status_class($status);\n    $statusLabel = pd_status_label($status, $labels);\n    $pct = max(0, min(100, (int)($project[\'pct_complete\'] ?? 0)));\n    $units = (int)($project[\'units\'] ?? 0);\n    $unitsInProgress = (int)round($units * $pct / 100);\n    $constituencyName = (string)($project[\'constituency_name\'] ?? \'Trans-Nzoia\');\n    $constituencySlug = (string)($project[\'constituency_slug\'] ?? \'\');\n    $wardName = trim((string)($project[\'ward_name\'] ?? $project[\'location_label\'] ?? \'\'));\n    $location = trim(($wardName !== \'\' ? $wardName . \', \' : \'\') . $constituencyName);\n    $contractor = trim((string)($project[\'contractor_name\'] ?? \'\'));\n    $siteEngineer = trim((string)($project[\'site_engineer\'] ?? \'\'));\n    $leadAgency = trim((string)($project[\'lead_agency\'] ?? \'State Dept. of Housing\'));\n    $funding = trim((string)($project[\'funding_source\'] ?? \'National AHP Fund\'));\n    $currentMilestone = trim((string)($project[\'current_milestone\'] ?? \'\'));\n    $startDate = pd_quarter_label($project[\'start_date\'] ?? null);\n    $deliveryDate = pd_quarter_label($project[\'est_delivery\'] ?? null);\n    $detailUrl = \'project-detail.php?id=\' . rawurlencode((string)$project[\'slug\']);\n?>\n  <section class=\"pd-hero\" id=\"pdHero\" aria-label=\"Project overview\">\n    <div class=\"pd-hero-bg\" id=\"pdHeroBg\" aria-hidden=\"true\">\n<?php if ($heroImage !== \'\'): ?>\n      <img <?= public_image_attrs($heroImage, \'\', [\'loading\' => \'eager\', \'fetchpriority\' => \'high\']) ?>>\n<?php endif; ?>\n      <div class=\"pd-hero-overlay\"></div>\n    </div>\n    <div class=\"container\">\n      <nav class=\"breadcrumb\" aria-label=\"Breadcrumb\">\n        <a href=\"index.php\" class=\"breadcrumb-link\">Home</a>\n        <i class=\"fa-solid fa-chevron-right breadcrumb-sep\" aria-hidden=\"true\"></i>\n        <a href=\"projects.php\" class=\"breadcrumb-link\"><?= $e($text($labels, \'projects_breadcrumb_label\', \'Projects\')) ?></a>\n        <i class=\"fa-solid fa-chevron-right breadcrumb-sep\" aria-hidden=\"true\"></i>\n        <span class=\"breadcrumb-current\"><?= $e($projectName) ?></span>\n      </nav>\n\n      <div class=\"pd-hero-content\" id=\"pdHeroContent\">\n        <div class=\"pd-hero-badges\">\n          <span class=\"pd-badge pd-badge--<?= $e($statusClass) ?>\">\n            <i class=\"fa-solid <?= $e(pd_icon_for_status($status)) ?>\" aria-hidden=\"true\"></i> <?= $e($statusLabel) ?>\n          </span>\n          <span class=\"pd-badge pd-badge--con\">\n            <i class=\"fa-solid fa-map-location-dot\" aria-hidden=\"true\"></i> <?= $e($constituencyName) ?>\n          </span>\n<?php if ($startDate !== \'\'): ?>\n          <span class=\"pd-badge pd-badge--date\"><i class=\"fa-solid fa-calendar-days\" aria-hidden=\"true\"></i> <?= $e($text($labels, \'started_label\', \'Started\')) ?> <?= $e($startDate) ?></span>\n<?php endif; ?>\n<?php if ($deliveryDate !== \'\'): ?>\n          <span class=\"pd-badge pd-badge--date\"><i class=\"fa-solid fa-flag-checkered\" aria-hidden=\"true\"></i> <?= $e($text($labels, \'delivery_label\', \'Est. Delivery\')) ?> <?= $e($deliveryDate) ?></span>\n<?php endif; ?>\n        </div>\n        <h1 class=\"pd-hero-title\"><?= $e($projectName) ?></h1>\n        <div class=\"pd-hero-meta\">\n<?php if ($location !== \'\'): ?>\n          <span class=\"pd-hero-meta-item\"><i class=\"fa-solid fa-map-pin\" aria-hidden=\"true\"></i> <?= $e($location) ?></span>\n<?php endif; ?>\n<?php if ($currentMilestone !== \'\'): ?>\n          <span class=\"pd-hero-meta-item\"><i class=\"fa-solid fa-hard-hat\" aria-hidden=\"true\"></i> <?= $e($currentMilestone) ?></span>\n<?php endif; ?>\n<?php if ($contractor !== \'\'): ?>\n          <span class=\"pd-hero-meta-item\"><i class=\"fa-solid fa-person-digging\" aria-hidden=\"true\"></i> <?= $e($contractor) ?></span>\n<?php endif; ?>\n        </div>\n        <div class=\"pd-hero-pct-wrap\">\n          <div class=\"pd-hero-pct\">\n            <span class=\"pd-hero-pct-num\"><?= $e($pct) ?><span class=\"pd-hero-pct-sign\">%</span></span>\n            <span class=\"pd-hero-pct-lbl\"><?= $e($text($labels, \'construction_complete_label\', \'Construction Complete\')) ?></span>\n          </div>\n          <div class=\"pd-hero-pct-bar\" aria-hidden=\"true\">\n            <div class=\"pd-hero-pct-bar-fill\" data-target=\"<?= $e($pct) ?>\" style=\"width:0%\"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <div class=\"pd-body\" id=\"pdBody\">\n    <div class=\"container\">\n      <div class=\"pd-body-inner\">\n        <div class=\"pd-main\" id=\"pdMain\">\n          <div class=\"pd-facts-strip\" id=\"pdFactsStrip\">\n<?php\n    $facts = [\n        [\'fa-house-chimney\', $text($labels, \'units_label\', \'Units Planned\'), pd_number($units)],\n        [\'fa-map-pin\', $text($labels, \'ward_label\', \'Ward\'), $wardName !== \'\' ? $wardName : \'-\'],\n        [\'fa-person-digging\', $text($labels, \'contractor_label\', \'Contractor\'), $contractor !== \'\' ? $contractor : \'TBD\'],\n        [\'fa-coins\', $text($labels, \'funding_label\', \'Funding Source\'), $funding !== \'\' ? $funding : \'-\'],\n        [\'fa-calendar-plus\', $text($labels, \'start_date_label\', \'Start Date\'), $startDate !== \'\' ? $startDate : \'-\'],\n        [\'fa-flag-checkered\', $text($labels, \'est_delivery_label\', \'Est. Delivery\'), $deliveryDate !== \'\' ? $deliveryDate : \'-\'],\n    ];\n?>\n<?php foreach ($facts as [$icon, $label, $value]): ?>\n            <div class=\"pd-fact\">\n              <div class=\"pd-fact-icon-wrap\" aria-hidden=\"true\"><i class=\"fa-solid <?= $e($icon) ?>\"></i></div>\n              <span class=\"pd-fact-lbl\"><?= $e($label) ?></span>\n              <span class=\"pd-fact-val\"><?= $e($value) ?></span>\n            </div>\n<?php endforeach; ?>\n          </div>\n\n          <section class=\"pd-description pd-card\" id=\"pdDescription\">\n            <p class=\"pd-section-label\"><?= $e($text($overview, \'section_label\', \'About This Project\')) ?></p>\n            <h2 class=\"pd-section-title\"><?= $e($text($overview, \'title\', \'Project Overview\')) ?></h2>\n            <p class=\"pd-description-text\"><?= nl2br($e($projectDescription)) ?></p>\n            <div class=\"pd-desc-meta-strip\">\n<?php if ($leadAgency !== \'\'): ?>\n              <div class=\"pd-desc-meta-item\"><i class=\"fa-solid fa-building-government\" aria-hidden=\"true\"></i><span><strong><?= $e($text($overview, \'lead_agency_label\', \'Lead Agency\')) ?></strong><?= $e($leadAgency) ?></span></div>\n<?php endif; ?>\n<?php if ($siteEngineer !== \'\' && strtolower($siteEngineer) !== \'tbd\'): ?>\n              <div class=\"pd-desc-meta-item\"><i class=\"fa-solid fa-helmet-safety\" aria-hidden=\"true\"></i><span><strong><?= $e($text($overview, \'site_engineer_label\', \'Site Engineer\')) ?></strong><?= $e($siteEngineer) ?></span></div>\n<?php endif; ?>\n<?php if ($funding !== \'\'): ?>\n              <div class=\"pd-desc-meta-item\"><i class=\"fa-solid fa-coins\" aria-hidden=\"true\"></i><span><strong><?= $e($text($overview, \'funding_label\', \'Funding\')) ?></strong><?= $e($funding) ?></span></div>\n<?php endif; ?>\n            </div>\n<?php if ($currentMilestone !== \'\'): ?>\n            <div class=\"pd-current-milestone\">\n              <i class=\"fa-solid fa-hard-hat\" aria-hidden=\"true\"></i>\n              <span><strong><?= $e($text($overview, \'current_activity_label\', \'Current Activity\')) ?>:</strong> <?= $e($currentMilestone) ?></span>\n            </div>\n<?php endif; ?>\n          </section>\n\n          <section class=\"pd-progress-section pd-card\" id=\"pdProgressSection\">\n            <p class=\"pd-section-label\"><?= $e($text($overview, \'progress_label\', \'Construction Progress\')) ?></p>\n            <h2 class=\"pd-section-title\"><?= $e($text($overview, \'progress_title\', \'Live Progress Tracker\')) ?></h2>\n            <div class=\"pd-progress-bar-wrap\">\n              <div class=\"pd-progress-meta\">\n                <span class=\"pd-progress-lbl\"><?= $e($text($overview, \'overall_completion_label\', \'Overall Completion\')) ?></span>\n                <span class=\"pd-progress-pct\"><?= $e($pct) ?>%</span>\n              </div>\n              <div class=\"pd-progress-track\" role=\"progressbar\" aria-valuenow=\"<?= $e($pct) ?>\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-label=\"<?= $e($pct) ?>% construction complete\">\n                <div class=\"pd-progress-fill\" data-target=\"<?= $e($pct) ?>\"></div>\n              </div>\n              <p class=\"pd-progress-note\"><i class=\"fa-regular fa-clock\" aria-hidden=\"true\"></i> <?= $e($text($overview, \'progress_note\', \'Data updated regularly by the Trans-Nzoia County Housing Department.\')) ?></p>\n            </div>\n            <div class=\"pd-mini-stats\">\n              <div class=\"pd-mini-stat\"><span class=\"pd-mini-stat-val\"><?= $e(pd_number($units)) ?></span><span class=\"pd-mini-stat-lbl\"><?= $e($text($labels, \'units_label\', \'Units Planned\')) ?></span></div>\n              <div class=\"pd-mini-stat\"><span class=\"pd-mini-stat-val\"><?= $e(pd_number($unitsInProgress)) ?></span><span class=\"pd-mini-stat-lbl\"><?= $e($text($overview, \'units_in_progress_label\', \'Units In Progress\')) ?></span></div>\n              <div class=\"pd-mini-stat\"><span class=\"pd-mini-stat-val\"><?= $e($deliveryDate !== \'\' ? $deliveryDate : \'-\') ?></span><span class=\"pd-mini-stat-lbl\"><?= $e($text($overview, \'target_delivery_label\', \'Target Delivery\')) ?></span></div>\n              <div class=\"pd-mini-stat\"><span class=\"pd-mini-stat-val\"><?= $e(format_percentage($programmeSummary[\'average_progress\'] ?? $pct)) ?></span><span class=\"pd-mini-stat-lbl\"><?= $e($text($overview, \'programme_progress_label\', \'Programme Progress\')) ?></span></div>\n              <div class=\"pd-mini-stat\"><span class=\"pd-mini-stat-val\"><?= $e(pd_number($programmeSummary[\'complete\'] ?? 0)) ?></span><span class=\"pd-mini-stat-lbl\"><?= $e($text($overview, \'completed_tasks_label\', \'Completed Tasks\')) ?></span></div>\n              <div class=\"pd-mini-stat\"><span class=\"pd-mini-stat-val\"><?= $e(pd_number($programmeSummary[\'needs_attention\'] ?? 0)) ?></span><span class=\"pd-mini-stat-lbl\"><?= $e($text($overview, \'attention_items_label\', \'Needs Attention\')) ?></span></div>\n            </div>\n          </section>\n\n          <section class=\"pd-timeline-section pd-card\" id=\"pdTimelineSection\">\n            <p class=\"pd-section-label\"><?= $e($text($overview, \'timeline_label\', \'Key Milestones\')) ?></p>\n            <h2 class=\"pd-section-title\"><?= $e($text($overview, \'timeline_title\', \'Construction Timeline\')) ?></h2>\n<?php if ($milestones): ?>\n            <div class=\"pd-timeline\">\n<?php foreach ($milestones as $milestone):\n        $milestoneStatus = (string)($milestone[\'status\'] ?? \'pending\');\n        $itemClass = $milestoneStatus === \'done\' ? \'is-done\' : ($milestoneStatus === \'current\' ? \'is-current\' : \'\');\n        $milestoneDate = pd_date_label($milestone[\'actual_date\'] ?: ($milestone[\'target_date\'] ?? \'\'), (string)($milestone[\'target_date\'] ?? \'\'));\n?>\n              <div class=\"pd-tl-item <?= $e($itemClass) ?>\">\n                <div class=\"pd-tl-spine\" aria-hidden=\"true\">\n                  <div class=\"pd-tl-dot\"><?php if ($milestoneStatus === \'done\'): ?><i class=\"fa-solid fa-check\" aria-hidden=\"true\"></i><?php elseif ($milestoneStatus === \'current\'): ?><i class=\"fa-solid fa-circle-half-stroke\" aria-hidden=\"true\"></i><?php endif; ?></div>\n                </div>\n                <div class=\"pd-tl-content\">\n                  <span class=\"pd-tl-date\"><?= $e($milestoneDate !== \'\' ? $milestoneDate : \'Pending\') ?></span>\n                  <p class=\"pd-tl-label\"><?= $e($milestone[\'label\'] ?? \'\') ?><?php if ($milestoneStatus === \'current\'): ?> <span class=\"pd-tl-badge\">CURRENT</span><?php endif; ?></p>\n                </div>\n              </div>\n<?php endforeach; ?>\n            </div>\n<?php else: ?>\n            <div class=\"pd-timeline-empty\">\n              <i class=\"fa-solid fa-list-check\" aria-hidden=\"true\"></i>\n              <p><?= $e($text($overview, \'timeline_empty_text\', \'Milestones will appear after they are added to this project.\')) ?></p>\n            </div>\n<?php endif; ?>\n          </section>\n\n          <section class=\"pd-gallery-section pd-card\" id=\"pdGallerySection\">\n            <p class=\"pd-section-label\"><?= $e($text($overview, \'gallery_label\', \'Site Photography\')) ?></p>\n            <h2 class=\"pd-section-title\"><?= $e($text($overview, \'gallery_title\', \'Photo Gallery\')) ?></h2>\n<?php if ($images): ?>\n            <div class=\"pd-gallery\">\n<?php foreach ($images as $index => $image): ?>\n<?php if ($index === 1): ?>\n              <div class=\"pd-gallery-grid\">\n<?php endif; ?>\n              <button class=\"<?= $index === 0 ? \'pd-gallery-featured\' : \'pd-gallery-item\' ?>\" type=\"button\" data-gallery-index=\"<?= $e($index) ?>\" data-gallery-src=\"<?= $e(pd_asset_url($image)) ?>\" data-gallery-alt=\"<?= $e($projectName . \' site photo \' . ($index + 1)) ?>\" aria-label=\"View photo <?= $e($index + 1) ?>\">\n                <img <?= public_image_attrs($image, $projectName . \' site photo \' . ($index + 1), [\'loading\' => $index === 0 ? \'eager\' : \'lazy\', \'fetchpriority\' => $index === 0 ? \'high\' : \'auto\']) ?>>\n                <div class=\"pd-gallery-item-overlay\"><i class=\"fa-solid fa-magnifying-glass-plus\" aria-hidden=\"true\"></i></div>\n              </button>\n<?php endforeach; ?>\n<?php if (count($images) > 1): ?>\n              </div>\n<?php endif; ?>\n            </div>\n<?php else: ?>\n            <div class=\"pd-gallery-empty\">\n              <i class=\"fa-solid fa-camera-slash\" aria-hidden=\"true\"></i>\n              <p><?= $e($text($overview, \'gallery_empty_text\', \'Site photography will be added as construction progresses.\')) ?></p>\n            </div>\n<?php endif; ?>\n          </section>\n        </div>\n\n        <aside class=\"pd-sidebar\" id=\"pdSidebar\" aria-label=\"Project quick facts\">\n          <div class=\"pd-sidebar-card pd-sb-contractor\">\n            <div class=\"pd-sb-con-avatar\" aria-hidden=\"true\"><i class=\"fa-solid fa-helmet-safety\"></i></div>\n            <div class=\"pd-sb-con-info\">\n              <p class=\"pd-sidebar-card-title\"><?= $e($text($sidebar, \'contractor_title\', \'Contractor\')) ?></p>\n              <p class=\"pd-contractor-name\"><?= $e($contractor !== \'\' ? $contractor : \'TBD\') ?></p>\n              <span class=\"pd-contractor-role-badge\"><?= $e($text($sidebar, \'contractor_role_label\', \'Principal Contractor\')) ?></span>\n            </div>\n<?php if ($leadAgency !== \'\'): ?>\n            <div class=\"pd-sb-agency\"><i class=\"fa-solid fa-building-government\" aria-hidden=\"true\"></i><span><?= $e($leadAgency) ?></span></div>\n<?php endif; ?>\n          </div>\n\n          <div class=\"pd-sidebar-card\">\n            <p class=\"pd-sidebar-card-title\"><?= $e($text($sidebar, \'project_info_title\', \'Project Info\')) ?></p>\n            <div class=\"pd-sidebar-list\">\n<?php\n    $infoRows = [\n        [$text($sidebar, \'constituency_label\', \'Constituency\'), $constituencySlug !== \'\' ? \'<a href=\"constituency-detail.php?id=\' . $e(rawurlencode($constituencySlug)) . \'\" class=\"pd-sb-link\">\' . $e($constituencyName) . \'</a>\' : $e($constituencyName), true],\n        [$text($labels, \'ward_label\', \'Ward\'), $e($wardName !== \'\' ? $wardName : \'-\') , true],\n        [$text($sidebar, \'status_label\', \'Status\'), \'<span class=\"pd-sb-status pd-sb-status--\' . $e($statusClass) . \'\">\' . $e($statusLabel) . \'</span>\', true],\n        [$text($sidebar, \'target_units_label\', \'Target Units\'), $e(pd_number($units)), true],\n        [$text($labels, \'start_date_label\', \'Start Date\'), $e($startDate !== \'\' ? $startDate : \'-\'), true],\n        [$text($labels, \'est_delivery_label\', \'Est. Delivery\'), $e($deliveryDate !== \'\' ? $deliveryDate : \'-\'), true],\n        [$text($sidebar, \'completion_label\', \'Completion\'), \'<span class=\"pd-sb-pct\">\' . $e($pct) . \'%</span><div class=\"pd-sb-mini-bar\"><div class=\"pd-sb-mini-fill\" style=\"width:\' . $e($pct) . \'%\"></div></div>\', true],\n    ];\n?>\n<?php foreach ($infoRows as $index => [$label, $value, $raw]): ?>\n              <div class=\"pd-sidebar-row<?= $index % 2 === 1 ? \' is-alt\' : \'\' ?>\">\n                <span class=\"pd-sidebar-row-lbl\"><?= $e($label) ?></span>\n                <span class=\"pd-sidebar-row-val\"><?= $raw ? $value : $e($value) ?></span>\n              </div>\n<?php endforeach; ?>\n            </div>\n          </div>\n\n          <div class=\"pd-sidebar-card pd-apply-card\">\n            <div class=\"pd-apply-icon-wrap\" aria-hidden=\"true\"><i class=\"fa-solid fa-house-chimney-user\"></i></div>\n            <p class=\"pd-apply-title\"><?= $e($text($applyCta, \'title\', \'Interested in a Unit?\')) ?></p>\n            <p class=\"pd-apply-sub\"><?= $e($text($applyCta, \'subtitle\', \'Register on the national Boma Yangu portal to apply for affordable housing in Trans-Nzoia County.\')) ?></p>\n            <a href=\"<?= $e($text($applyCta, \'button_url\', \'https://app.bomayangu.go.ke\')) ?>\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"pd-apply-btn\">\n              <i class=\"fa-solid fa-arrow-up-right-from-square\" aria-hidden=\"true\"></i> <?= $e($text($applyCta, \'button_label\', \'Apply on Boma Yangu\')) ?>\n            </a>\n          </div>\n\n          <div class=\"pd-sidebar-card\">\n            <p class=\"pd-sidebar-card-title\"><?= $e($text($sidebar, \'related_title\', \'Related\')) ?></p>\n            <div class=\"pd-related-links\">\n<?php if ($constituencySlug !== \'\'): ?>\n              <a href=\"constituency-detail.php?id=<?= $e(rawurlencode($constituencySlug)) ?>\" class=\"pd-related-link\">\n                <div class=\"pd-related-icon\"><i class=\"fa-solid fa-map-location-dot\" aria-hidden=\"true\"></i></div>\n                <span><?= $e($constituencyName . \' \' . $text($sidebar, \'constituency_link_suffix\', \'Constituency\')) ?></span>\n                <i class=\"fa-solid fa-chevron-right pd-related-arrow\" aria-hidden=\"true\"></i>\n              </a>\n              <a href=\"projects.php?constituency=<?= $e(rawurlencode($constituencySlug)) ?>\" class=\"pd-related-link\">\n                <div class=\"pd-related-icon\"><i class=\"fa-solid fa-building-columns\" aria-hidden=\"true\"></i></div>\n                <span><?= $e($text($sidebar, \'all_projects_prefix\', \'All\') . \' \' . $constituencyName . \' Projects\') ?></span>\n                <i class=\"fa-solid fa-chevron-right pd-related-arrow\" aria-hidden=\"true\"></i>\n              </a>\n<?php endif; ?>\n              <a href=\"projects.php\" class=\"pd-related-link\">\n                <div class=\"pd-related-icon\"><i class=\"fa-solid fa-arrow-left\" aria-hidden=\"true\"></i></div>\n                <span><?= $e($text($sidebar, \'back_projects_label\', \'Back to All Projects\')) ?></span>\n                <i class=\"fa-solid fa-chevron-right pd-related-arrow\" aria-hidden=\"true\"></i>\n              </a>\n            </div>\n          </div>\n<?php if ($relatedProjects): ?>\n          <div class=\"pd-sidebar-card\">\n            <p class=\"pd-sidebar-card-title\"><?= $e($text($sidebar, \'nearby_projects_title\', \'Nearby Projects\')) ?></p>\n            <div class=\"pd-related-projects\">\n<?php foreach ($relatedProjects as $related): ?>\n              <a href=\"project-detail.php?id=<?= $e(rawurlencode((string)$related[\'slug\'])) ?>\" class=\"pd-related-project\">\n                <span class=\"pd-related-project-name\"><?= $e($related[\'name\']) ?></span>\n                <span class=\"pd-related-project-meta\"><?= $e($related[\'constituency_name\']) ?> / <?= $e(format_percentage($related[\'pct_complete\'])) ?></span>\n              </a>\n<?php endforeach; ?>\n            </div>\n          </div>\n<?php endif; ?>\n        </aside>\n      </div>\n    </div>\n  </div>\n<?php endif; ?>\n</main>\n<?php include __DIR__ . \'/app/partials/footer.php\'; ?>\n<?php include __DIR__ . \'/app/partials/back-to-top.php\'; ?>\n<?php include __DIR__ . \'/app/partials/mobile-menu.php\'; ?>\n<?= public_json_script(\'ahp-page-data\', $publicPayload) ?>\n<?php include __DIR__ . \'/app/partials/scripts.php\'; ?>\n</body>\n</html>\n', '\'eager\', \'fetchpriority\' => \'high\']) ?>> Home \"> \" aria-hidden=\"true\"> % \" style=\"width:0%\"> \"> : % \" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-label=\" % construction complete\"> \"> \"> CURRENT \" type=\"button\" data-gallery-index=\" \" data-gallery-src=\" \" data-gallery-alt=\" \" aria-label=\"View photo \"> $index === 0 ? \'eager\' : \'lazy\', \'fetchpriority\' => $index === 0 ? \'high\' : \'auto\']) ?>> \"> \" target=\"_blank\" rel=\"noopener noreferrer\" class=\"pd-apply-btn\"> \" class=\"pd-related-link\"> \" class=\"pd-related-link\"> \" class=\"pd-related-project\"> /', '{\"page_slug\":\"project-detail\",\"page_label\":\"Project Detail\",\"file_path\":\"project-detail.php\",\"source_hash\":\"043ddeba617c3a34432e2158455771392e66989b02467645901504decb989e73\",\"title\":\"\",\"meta_description\":\"\",\"headings\":[],\"links\":[{\"href\":\"projects.php\",\"text\":\"\"},{\"href\":\"index.php\",\"text\":\"Home\"},{\"href\":\"projects.php\",\"text\":\"\"},{\"href\":\"<?= $e($text($applyCta,\",\"text\":\"\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"pd-apply-btn\\\">\"},{\"href\":\"constituency-detail.php?id=<?= $e(rawurlencode($constituencySlug)) ?>\",\"text\":\"\"},{\"href\":\"projects.php?constituency=<?= $e(rawurlencode($constituencySlug)) ?>\",\"text\":\"\"},{\"href\":\"projects.php\",\"text\":\"\"},{\"href\":\"project-detail.php?id=<?= $e(rawurlencode((string)$related[\",\"text\":\"\\\" class=\\\"pd-related-project\\\"> /\"}],\"images\":[{\"src\":\"\",\"alt\":\"\"},{\"src\":\"\",\"alt\":\"\"}],\"forms\":[],\"cms_keys\":[\"project_detail_labels\",\"project_detail_overview\",\"project_detail_sidebar\",\"project_detail_apply_cta\",\"project_detail_not_found\"],\"text_content\":\"\'eager\', \'fetchpriority\' => \'high\']) ?>> Home \\\"> \\\" aria-hidden=\\\"true\\\"> % \\\" style=\\\"width:0%\\\"> \\\"> : % \\\" aria-valuemin=\\\"0\\\" aria-valuemax=\\\"100\\\" aria-label=\\\" % construction complete\\\"> \\\"> \\\"> CURRENT \\\" type=\\\"button\\\" data-gallery-index=\\\" \\\" data-gallery-src=\\\" \\\" data-gallery-alt=\\\" \\\" aria-label=\\\"View photo \\\"> $index === 0 ? \'eager\' : \'lazy\', \'fetchpriority\' => $index === 0 ? \'high\' : \'auto\']) ?>> \\\"> \\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"pd-apply-btn\\\"> \\\" class=\\\"pd-related-link\\\"> \\\" class=\\\"pd-related-link\\\"> \\\" class=\\\"pd-related-project\\\"> /\",\"raw_source\":\"<?php\\nrequire_once __DIR__ . \'/app/core/bootstrap.php\';\\n\\n$basePath = \'\';\\n$activePage = \'projects\';\\n$cmsPage = CmsLoader::publicPage(\'project-detail\');\\n$labels = CmsLoader::content($cmsPage, \'project_detail_labels\', []);\\n$overview = CmsLoader::content($cmsPage, \'project_detail_overview\', []);\\n$sidebar = CmsLoader::content($cmsPage, \'project_detail_sidebar\', []);\\n$applyCta = CmsLoader::content($cmsPage, \'project_detail_apply_cta\', []);\\n$notFound = CmsLoader::content($cmsPage, \'project_detail_not_found\', []);\\n$text = static fn (array $content, string $key, string $default = \'\'): string => CmsLoader::text($content, $key, $default);\\n$e = static fn (mixed $value): string => Security::e($value);\\n\\n$lookup = trim((string)($_GET[\'id\'] ?? $_GET[\'slug\'] ?? \'\'));\\n$project = $lookup !== \'\' ? Project::publicDetail($lookup) : null;\\n$isFound = is_array($project);\\n\\nif (!$isFound) {\\n    http_response_code(404);\\n}\\n\\nif (!function_exists(\'pd_asset_url\')) {\\n    function pd_asset_url(?string $path): string\\n    {\\n        $path = trim((string)$path);\\n        if ($path === \'\') {\\n            return \'\';\\n        }\\n        if (preg_match(\'#^(?:[a-z][a-z0-9+.-]*:)?//#i\', $path) || str_starts_with($path, \'data:\')) {\\n            return $path;\\n        }\\n        return Url::asset($path);\\n    }\\n}\\n\\nif (!function_exists(\'pd_images\')) {\\n    function pd_images(array $project): array\\n    {\\n        $images = [];\\n        $hero = trim((string)($project[\'hero_image\'] ?? \'\'));\\n        if ($hero !== \'\') {\\n            $images[] = $hero;\\n        }\\n\\n        $decoded = json_decode((string)($project[\'images_json\'] ?? \'[]\'), true);\\n        if (is_array($decoded)) {\\n            foreach ($decoded as $image) {\\n                $image = trim((string)$image);\\n                if ($image !== \'\') {\\n                    $images[] = $image;\\n                }\\n            }\\n        }\\n\\n        $unique = [];\\n        foreach ($images as $image) {\\n            if (!in_array($image, $unique, true)) {\\n                $unique[] = $image;\\n            }\\n        }\\n\\n        return $unique;\\n    }\\n}\\n\\nif (!function_exists(\'pd_quarter_label\')) {\\n    function pd_quarter_label(?string $date, string $fallback = \'\'): string\\n    {\\n        $date = trim((string)$date);\\n        if ($date === \'\' || $date === \'0000-00-00\') {\\n            return $fallback;\\n        }\\n        $timestamp = strtotime($date);\\n        if (!$timestamp) {\\n            return $date;\\n        }\\n        return \'Q\' . (int)ceil((int)date(\'n\', $timestamp) / 3) . \' \' . date(\'Y\', $timestamp);\\n    }\\n}\\n\\nif (!function_exists(\'pd_date_label\')) {\\n    function pd_date_label(?string $date, string $fallback = \'\'): string\\n    {\\n        $date = trim((string)$date);\\n        if ($date === \'\' || $date === \'0000-00-00\') {\\n            return $fallback;\\n        }\\n        $timestamp = strtotime($date);\\n        return $timestamp ? date(\'j M Y\', $timestamp) : $date;\\n    }\\n}\\n\\nif (!function_exists(\'pd_number\')) {\\n    function pd_number(mixed $value): string\\n    {\\n        return number_format((float)$value, 0);\\n    }\\n}\\n\\nif (!function_exists(\'pd_status_class\')) {\\n    function pd_status_class(string $status): string\\n    {\\n        return match ($status) {\\n            \'active\' => \'active\',\\n            \'completed\' => \'completed\',\\n            \'on_hold\', \'stalled\' => \'watch\',\\n            default => \'planning\',\\n        };\\n    }\\n}\\n\\nif (!function_exists(\'pd_status_label\')) {\\n    function pd_status_label(string $status, array $labels): string\\n    {\\n        return match ($status) {\\n            \'active\' => CmsLoader::text($labels, \'active_status_label\', \'Active\'),\\n            \'completed\' => CmsLoader::text($labels, \'completed_status_label\', \'Completed\'),\\n            \'on_hold\', \'stalled\' => CmsLoader::text($labels, \'watch_status_label\', \'On Hold\'),\\n            default => CmsLoader::text($labels, \'planning_status_label\', \'Planning\'),\\n        };\\n    }\\n}\\n\\nif (!function_exists(\'pd_icon_for_status\')) {\\n    function pd_icon_for_status(string $status): string\\n    {\\n        return match ($status) {\\n            \'active\' => \'fa-circle-dot\',\\n            \'completed\' => \'fa-circle-check\',\\n            \'on_hold\', \'stalled\' => \'fa-triangle-exclamation\',\\n            default => \'fa-clock\',\\n        };\\n    }\\n}\\n\\n$images = $isFound ? pd_images($project) : [];\\n$projectName = $isFound ? (string)($project[\'name\'] ?? \'Project Detail\') : $text($notFound, \'title\', \'Project Not Found\');\\n$projectDescription = $isFound\\n    ? trim((string)($project[\'full_description\'] ?? $project[\'description\'] ?? \'\'))\\n    : $text($notFound, \'text\', \\\"The project you\'re looking for doesn\'t exist or the URL is incorrect.\\\");\\n$pageTitle = $isFound\\n    ? $projectName . \' | Trans-Nzoia County Affordable Housing Tracker\'\\n    : $text($notFound, \'title\', \'Project Not Found\') . \' | Trans-Nzoia County Affordable Housing Tracker\';\\n$pageDescription = $isFound && $projectDescription !== \'\'\\n    ? substr(strip_tags($projectDescription), 0, 160)\\n    : ($cmsPage[\'seo_description\'] ?? \'Detailed construction progress, contractor information, milestones and site photos for an affordable housing project in Trans-Nzoia County.\');\\n$pageKeywords = $cmsPage[\'seo_keywords\'] ?? \'Trans-Nzoia AHP project detail, affordable housing Kenya, construction progress\';\\n$pageAuthor = \'Trans-Nzoia County Government - Department of Land, Housing & Physical Planning\';\\n$pageRobots = $isFound ? \'index, follow\' : \'noindex, follow\';\\n$themeColor = \'#163300\';\\n$canonicalUrl = $isFound\\n    ? \'https://housing.transnzoia.go.ke/project-detail.php?id=\' . rawurlencode((string)($project[\'slug\'] ?? $lookup))\\n    : \'https://housing.transnzoia.go.ke/project-detail.php\';\\n$pageStyles = [\\n    \'assets/css/global.css\',\\n    \'assets/css/pages/project-detail.css\',\\n];\\n$pageScripts = [\\n    \'assets/js/global.js\',\\n    \'assets/js/pages/project-detail.js\',\\n];\\n$milestones = [];\\n$programmeSummary = [];\\n$galleryMedia = [];\\n$relatedProjects = [];\\n$publicPayload = public_page_payload(\'project-detail\', [], [\\n    \'title\' => $projectName,\\n    \'description\' => $pageDescription,\\n]);\\nif ($isFound) {\\n    $milestones = Milestone::publicForProject((int)$project[\'id\']);\\n    $programmeSummary = ProgrammeTask::publicSummaryForProject((int)$project[\'id\']);\\n    $galleryMedia = GalleryImage::publicForProject((int)$project[\'id\'], 48);\\n    foreach ($galleryMedia as $galleryItem) {\\n        $image = (string)($galleryItem[\'full_url\'] ?: $galleryItem[\'url\'] ?? \'\');\\n        if ($image !== \'\' && !in_array($image, $images, true)) {\\n            $images[] = $image;\\n        }\\n    }\\n    $relatedProjects = Project::publicRelated($project, 4);\\n    $publicPayload = public_page_payload(\'project-detail\', [\\n        \'project\' => $project,\\n        \'milestones\' => $milestones,\\n        \'programme\' => $programmeSummary,\\n        \'gallery\' => $galleryMedia,\\n        \'related_projects\' => $relatedProjects,\\n    ], [\\n        \'title\' => $projectName,\\n        \'description\' => $pageDescription,\\n    ]);\\n}\\n$heroImage = $images[0] ?? \'\';\\n$headMeta = [\\n    \'<meta property=\\\"og:title\\\" content=\\\"\' . $e($pageTitle) . \'\\\">\',\\n    \'<meta property=\\\"og:type\\\" content=\\\"website\\\">\',\\n    \'<meta property=\\\"og:locale\\\" content=\\\"en_KE\\\">\',\\n    \'<meta property=\\\"og:site_name\\\" content=\\\"Trans-Nzoia AHP Tracker\\\">\',\\n    \'<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\">\',\\n];\\nif ($heroImage !== \'\') {\\n    $headMeta[] = \'<meta property=\\\"og:image\\\" content=\\\"\' . $e(pd_asset_url($heroImage)) . \'\\\">\';\\n}\\n\\ninclude __DIR__ . \'/app/partials/head.php\';\\n?>\\n<body>\\n<?php include __DIR__ . \'/app/partials/cursor.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/skip-link.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/navbar.php\'; ?>\\n<main id=\\\"main-content\\\">\\n\\n<?php if (!$isFound): ?>\\n  <section class=\\\"pd-not-found\\\" id=\\\"pdNotFound\\\">\\n    <div class=\\\"container\\\">\\n      <div class=\\\"pd-not-found-inner\\\">\\n        <i class=\\\"fa-solid fa-building-circle-xmark pd-not-found-icon\\\" aria-hidden=\\\"true\\\"></i>\\n        <h1><?= $e($text($notFound, \'title\', \'Project Not Found\')) ?></h1>\\n        <p><?= $e($text($notFound, \'text\', \\\"The project you\'re looking for doesn\'t exist or the URL is incorrect.\\\")) ?></p>\\n        <a href=\\\"projects.php\\\" class=\\\"btn btn-primary\\\">\\n          <i class=\\\"fa-solid fa-arrow-left\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($notFound, \'button_label\', \'Back to All Projects\')) ?>\\n        </a>\\n      </div>\\n    </div>\\n  </section>\\n<?php else:\\n    $status = (string)($project[\'status\'] ?? \'planning\');\\n    $statusClass = pd_status_class($status);\\n    $statusLabel = pd_status_label($status, $labels);\\n    $pct = max(0, min(100, (int)($project[\'pct_complete\'] ?? 0)));\\n    $units = (int)($project[\'units\'] ?? 0);\\n    $unitsInProgress = (int)round($units * $pct / 100);\\n    $constituencyName = (string)($project[\'constituency_name\'] ?? \'Trans-Nzoia\');\\n    $constituencySlug = (string)($project[\'constituency_slug\'] ?? \'\');\\n    $wardName = trim((string)($project[\'ward_name\'] ?? $project[\'location_label\'] ?? \'\'));\\n    $location = trim(($wardName !== \'\' ? $wardName . \', \' : \'\') . $constituencyName);\\n    $contractor = trim((string)($project[\'contractor_name\'] ?? \'\'));\\n    $siteEngineer = trim((string)($project[\'site_engineer\'] ?? \'\'));\\n    $leadAgency = trim((string)($project[\'lead_agency\'] ?? \'State Dept. of Housing\'));\\n    $funding = trim((string)($project[\'funding_source\'] ?? \'National AHP Fund\'));\\n    $currentMilestone = trim((string)($project[\'current_milestone\'] ?? \'\'));\\n    $startDate = pd_quarter_label($project[\'start_date\'] ?? null);\\n    $deliveryDate = pd_quarter_label($project[\'est_delivery\'] ?? null);\\n    $detailUrl = \'project-detail.php?id=\' . rawurlencode((string)$project[\'slug\']);\\n?>\\n  <section class=\\\"pd-hero\\\" id=\\\"pdHero\\\" aria-label=\\\"Project overview\\\">\\n    <div class=\\\"pd-hero-bg\\\" id=\\\"pdHeroBg\\\" aria-hidden=\\\"true\\\">\\n<?php if ($heroImage !== \'\'): ?>\\n      <img <?= public_image_attrs($heroImage, \'\', [\'loading\' => \'eager\', \'fetchpriority\' => \'high\']) ?>>\\n<?php endif; ?>\\n      <div class=\\\"pd-hero-overlay\\\"></div>\\n    </div>\\n    <div class=\\\"container\\\">\\n      <nav class=\\\"breadcrumb\\\" aria-label=\\\"Breadcrumb\\\">\\n        <a href=\\\"index.php\\\" class=\\\"breadcrumb-link\\\">Home</a>\\n        <i class=\\\"fa-solid fa-chevron-right breadcrumb-sep\\\" aria-hidden=\\\"true\\\"></i>\\n        <a href=\\\"projects.php\\\" class=\\\"breadcrumb-link\\\"><?= $e($text($labels, \'projects_breadcrumb_label\', \'Projects\')) ?></a>\\n        <i class=\\\"fa-solid fa-chevron-right breadcrumb-sep\\\" aria-hidden=\\\"true\\\"></i>\\n        <span class=\\\"breadcrumb-current\\\"><?= $e($projectName) ?></span>\\n      </nav>\\n\\n      <div class=\\\"pd-hero-content\\\" id=\\\"pdHeroContent\\\">\\n        <div class=\\\"pd-hero-badges\\\">\\n          <span class=\\\"pd-badge pd-badge--<?= $e($statusClass) ?>\\\">\\n            <i class=\\\"fa-solid <?= $e(pd_icon_for_status($status)) ?>\\\" aria-hidden=\\\"true\\\"></i> <?= $e($statusLabel) ?>\\n          </span>\\n          <span class=\\\"pd-badge pd-badge--con\\\">\\n            <i class=\\\"fa-solid fa-map-location-dot\\\" aria-hidden=\\\"true\\\"></i> <?= $e($constituencyName) ?>\\n          </span>\\n<?php if ($startDate !== \'\'): ?>\\n          <span class=\\\"pd-badge pd-badge--date\\\"><i class=\\\"fa-solid fa-calendar-days\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($labels, \'started_label\', \'Started\')) ?> <?= $e($startDate) ?></span>\\n<?php endif; ?>\\n<?php if ($deliveryDate !== \'\'): ?>\\n          <span class=\\\"pd-badge pd-badge--date\\\"><i class=\\\"fa-solid fa-flag-checkered\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($labels, \'delivery_label\', \'Est. Delivery\')) ?> <?= $e($deliveryDate) ?></span>\\n<?php endif; ?>\\n        </div>\\n        <h1 class=\\\"pd-hero-title\\\"><?= $e($projectName) ?></h1>\\n        <div class=\\\"pd-hero-meta\\\">\\n<?php if ($location !== \'\'): ?>\\n          <span class=\\\"pd-hero-meta-item\\\"><i class=\\\"fa-solid fa-map-pin\\\" aria-hidden=\\\"true\\\"></i> <?= $e($location) ?></span>\\n<?php endif; ?>\\n<?php if ($currentMilestone !== \'\'): ?>\\n          <span class=\\\"pd-hero-meta-item\\\"><i class=\\\"fa-solid fa-hard-hat\\\" aria-hidden=\\\"true\\\"></i> <?= $e($currentMilestone) ?></span>\\n<?php endif; ?>\\n<?php if ($contractor !== \'\'): ?>\\n          <span class=\\\"pd-hero-meta-item\\\"><i class=\\\"fa-solid fa-person-digging\\\" aria-hidden=\\\"true\\\"></i> <?= $e($contractor) ?></span>\\n<?php endif; ?>\\n        </div>\\n        <div class=\\\"pd-hero-pct-wrap\\\">\\n          <div class=\\\"pd-hero-pct\\\">\\n            <span class=\\\"pd-hero-pct-num\\\"><?= $e($pct) ?><span class=\\\"pd-hero-pct-sign\\\">%</span></span>\\n            <span class=\\\"pd-hero-pct-lbl\\\"><?= $e($text($labels, \'construction_complete_label\', \'Construction Complete\')) ?></span>\\n          </div>\\n          <div class=\\\"pd-hero-pct-bar\\\" aria-hidden=\\\"true\\\">\\n            <div class=\\\"pd-hero-pct-bar-fill\\\" data-target=\\\"<?= $e($pct) ?>\\\" style=\\\"width:0%\\\"></div>\\n          </div>\\n        </div>\\n      </div>\\n    </div>\\n  </section>\\n\\n  <div class=\\\"pd-body\\\" id=\\\"pdBody\\\">\\n    <div class=\\\"container\\\">\\n      <div class=\\\"pd-body-inner\\\">\\n        <div class=\\\"pd-main\\\" id=\\\"pdMain\\\">\\n          <div class=\\\"pd-facts-strip\\\" id=\\\"pdFactsStrip\\\">\\n<?php\\n    $facts = [\\n        [\'fa-house-chimney\', $text($labels, \'units_label\', \'Units Planned\'), pd_number($units)],\\n        [\'fa-map-pin\', $text($labels, \'ward_label\', \'Ward\'), $wardName !== \'\' ? $wardName : \'-\'],\\n        [\'fa-person-digging\', $text($labels, \'contractor_label\', \'Contractor\'), $contractor !== \'\' ? $contractor : \'TBD\'],\\n        [\'fa-coins\', $text($labels, \'funding_label\', \'Funding Source\'), $funding !== \'\' ? $funding : \'-\'],\\n        [\'fa-calendar-plus\', $text($labels, \'start_date_label\', \'Start Date\'), $startDate !== \'\' ? $startDate : \'-\'],\\n        [\'fa-flag-checkered\', $text($labels, \'est_delivery_label\', \'Est. Delivery\'), $deliveryDate !== \'\' ? $deliveryDate : \'-\'],\\n    ];\\n?>\\n<?php foreach ($facts as [$icon, $label, $value]): ?>\\n            <div class=\\\"pd-fact\\\">\\n              <div class=\\\"pd-fact-icon-wrap\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid <?= $e($icon) ?>\\\"></i></div>\\n              <span class=\\\"pd-fact-lbl\\\"><?= $e($label) ?></span>\\n              <span class=\\\"pd-fact-val\\\"><?= $e($value) ?></span>\\n            </div>\\n<?php endforeach; ?>\\n          </div>\\n\\n          <section class=\\\"pd-description pd-card\\\" id=\\\"pdDescription\\\">\\n            <p class=\\\"pd-section-label\\\"><?= $e($text($overview, \'section_label\', \'About This Project\')) ?></p>\\n            <h2 class=\\\"pd-section-title\\\"><?= $e($text($overview, \'title\', \'Project Overview\')) ?></h2>\\n            <p class=\\\"pd-description-text\\\"><?= nl2br($e($projectDescription)) ?></p>\\n            <div class=\\\"pd-desc-meta-strip\\\">\\n<?php if ($leadAgency !== \'\'): ?>\\n              <div class=\\\"pd-desc-meta-item\\\"><i class=\\\"fa-solid fa-building-government\\\" aria-hidden=\\\"true\\\"></i><span><strong><?= $e($text($overview, \'lead_agency_label\', \'Lead Agency\')) ?></strong><?= $e($leadAgency) ?></span></div>\\n<?php endif; ?>\\n<?php if ($siteEngineer !== \'\' && strtolower($siteEngineer) !== \'tbd\'): ?>\\n              <div class=\\\"pd-desc-meta-item\\\"><i class=\\\"fa-solid fa-helmet-safety\\\" aria-hidden=\\\"true\\\"></i><span><strong><?= $e($text($overview, \'site_engineer_label\', \'Site Engineer\')) ?></strong><?= $e($siteEngineer) ?></span></div>\\n<?php endif; ?>\\n<?php if ($funding !== \'\'): ?>\\n              <div class=\\\"pd-desc-meta-item\\\"><i class=\\\"fa-solid fa-coins\\\" aria-hidden=\\\"true\\\"></i><span><strong><?= $e($text($overview, \'funding_label\', \'Funding\')) ?></strong><?= $e($funding) ?></span></div>\\n<?php endif; ?>\\n            </div>\\n<?php if ($currentMilestone !== \'\'): ?>\\n            <div class=\\\"pd-current-milestone\\\">\\n              <i class=\\\"fa-solid fa-hard-hat\\\" aria-hidden=\\\"true\\\"></i>\\n              <span><strong><?= $e($text($overview, \'current_activity_label\', \'Current Activity\')) ?>:</strong> <?= $e($currentMilestone) ?></span>\\n            </div>\\n<?php endif; ?>\\n          </section>\\n\\n          <section class=\\\"pd-progress-section pd-card\\\" id=\\\"pdProgressSection\\\">\\n            <p class=\\\"pd-section-label\\\"><?= $e($text($overview, \'progress_label\', \'Construction Progress\')) ?></p>\\n            <h2 class=\\\"pd-section-title\\\"><?= $e($text($overview, \'progress_title\', \'Live Progress Tracker\')) ?></h2>\\n            <div class=\\\"pd-progress-bar-wrap\\\">\\n              <div class=\\\"pd-progress-meta\\\">\\n                <span class=\\\"pd-progress-lbl\\\"><?= $e($text($overview, \'overall_completion_label\', \'Overall Completion\')) ?></span>\\n                <span class=\\\"pd-progress-pct\\\"><?= $e($pct) ?>%</span>\\n              </div>\\n              <div class=\\\"pd-progress-track\\\" role=\\\"progressbar\\\" aria-valuenow=\\\"<?= $e($pct) ?>\\\" aria-valuemin=\\\"0\\\" aria-valuemax=\\\"100\\\" aria-label=\\\"<?= $e($pct) ?>% construction complete\\\">\\n                <div class=\\\"pd-progress-fill\\\" data-target=\\\"<?= $e($pct) ?>\\\"></div>\\n              </div>\\n              <p class=\\\"pd-progress-note\\\"><i class=\\\"fa-regular fa-clock\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($overview, \'progress_note\', \'Data updated regularly by the Trans-Nzoia County Housing Department.\')) ?></p>\\n            </div>\\n            <div class=\\\"pd-mini-stats\\\">\\n              <div class=\\\"pd-mini-stat\\\"><span class=\\\"pd-mini-stat-val\\\"><?= $e(pd_number($units)) ?></span><span class=\\\"pd-mini-stat-lbl\\\"><?= $e($text($labels, \'units_label\', \'Units Planned\')) ?></span></div>\\n              <div class=\\\"pd-mini-stat\\\"><span class=\\\"pd-mini-stat-val\\\"><?= $e(pd_number($unitsInProgress)) ?></span><span class=\\\"pd-mini-stat-lbl\\\"><?= $e($text($overview, \'units_in_progress_label\', \'Units In Progress\')) ?></span></div>\\n              <div class=\\\"pd-mini-stat\\\"><span class=\\\"pd-mini-stat-val\\\"><?= $e($deliveryDate !== \'\' ? $deliveryDate : \'-\') ?></span><span class=\\\"pd-mini-stat-lbl\\\"><?= $e($text($overview, \'target_delivery_label\', \'Target Delivery\')) ?></span></div>\\n              <div class=\\\"pd-mini-stat\\\"><span class=\\\"pd-mini-stat-val\\\"><?= $e(format_percentage($programmeSummary[\'average_progress\'] ?? $pct)) ?></span><span class=\\\"pd-mini-stat-lbl\\\"><?= $e($text($overview, \'programme_progress_label\', \'Programme Progress\')) ?></span></div>\\n              <div class=\\\"pd-mini-stat\\\"><span class=\\\"pd-mini-stat-val\\\"><?= $e(pd_number($programmeSummary[\'complete\'] ?? 0)) ?></span><span class=\\\"pd-mini-stat-lbl\\\"><?= $e($text($overview, \'completed_tasks_label\', \'Completed Tasks\')) ?></span></div>\\n              <div class=\\\"pd-mini-stat\\\"><span class=\\\"pd-mini-stat-val\\\"><?= $e(pd_number($programmeSummary[\'needs_attention\'] ?? 0)) ?></span><span class=\\\"pd-mini-stat-lbl\\\"><?= $e($text($overview, \'attention_items_label\', \'Needs Attention\')) ?></span></div>\\n            </div>\\n          </section>\\n\\n          <section class=\\\"pd-timeline-section pd-card\\\" id=\\\"pdTimelineSection\\\">\\n            <p class=\\\"pd-section-label\\\"><?= $e($text($overview, \'timeline_label\', \'Key Milestones\')) ?></p>\\n            <h2 class=\\\"pd-section-title\\\"><?= $e($text($overview, \'timeline_title\', \'Construction Timeline\')) ?></h2>\\n<?php if ($milestones): ?>\\n            <div class=\\\"pd-timeline\\\">\\n<?php foreach ($milestones as $milestone):\\n        $milestoneStatus = (string)($milestone[\'status\'] ?? \'pending\');\\n        $itemClass = $milestoneStatus === \'done\' ? \'is-done\' : ($milestoneStatus === \'current\' ? \'is-current\' : \'\');\\n        $milestoneDate = pd_date_label($milestone[\'actual_date\'] ?: ($milestone[\'target_date\'] ?? \'\'), (string)($milestone[\'target_date\'] ?? \'\'));\\n?>\\n              <div class=\\\"pd-tl-item <?= $e($itemClass) ?>\\\">\\n                <div class=\\\"pd-tl-spine\\\" aria-hidden=\\\"true\\\">\\n                  <div class=\\\"pd-tl-dot\\\"><?php if ($milestoneStatus === \'done\'): ?><i class=\\\"fa-solid fa-check\\\" aria-hidden=\\\"true\\\"></i><?php elseif ($milestoneStatus === \'current\'): ?><i class=\\\"fa-solid fa-circle-half-stroke\\\" aria-hidden=\\\"true\\\"></i><?php endif; ?></div>\\n                </div>\\n                <div class=\\\"pd-tl-content\\\">\\n                  <span class=\\\"pd-tl-date\\\"><?= $e($milestoneDate !== \'\' ? $milestoneDate : \'Pending\') ?></span>\\n                  <p class=\\\"pd-tl-label\\\"><?= $e($milestone[\'label\'] ?? \'\') ?><?php if ($milestoneStatus === \'current\'): ?> <span class=\\\"pd-tl-badge\\\">CURRENT</span><?php endif; ?></p>\\n                </div>\\n              </div>\\n<?php endforeach; ?>\\n            </div>\\n<?php else: ?>\\n            <div class=\\\"pd-timeline-empty\\\">\\n              <i class=\\\"fa-solid fa-list-check\\\" aria-hidden=\\\"true\\\"></i>\\n              <p><?= $e($text($overview, \'timeline_empty_text\', \'Milestones will appear after they are added to this project.\')) ?></p>\\n            </div>\\n<?php endif; ?>\\n          </section>\\n\\n          <section class=\\\"pd-gallery-section pd-card\\\" id=\\\"pdGallerySection\\\">\\n            <p class=\\\"pd-section-label\\\"><?= $e($text($overview, \'gallery_label\', \'Site Photography\')) ?></p>\\n            <h2 class=\\\"pd-section-title\\\"><?= $e($text($overview, \'gallery_title\', \'Photo Gallery\')) ?></h2>\\n<?php if ($images): ?>\\n            <div class=\\\"pd-gallery\\\">\\n<?php foreach ($images as $index => $image): ?>\\n<?php if ($index === 1): ?>\\n              <div class=\\\"pd-gallery-grid\\\">\\n<?php endif; ?>\\n              <button class=\\\"<?= $index === 0 ? \'pd-gallery-featured\' : \'pd-gallery-item\' ?>\\\" type=\\\"button\\\" data-gallery-index=\\\"<?= $e($index) ?>\\\" data-gallery-src=\\\"<?= $e(pd_asset_url($image)) ?>\\\" data-gallery-alt=\\\"<?= $e($projectName . \' site photo \' . ($index + 1)) ?>\\\" aria-label=\\\"View photo <?= $e($index + 1) ?>\\\">\\n                <img <?= public_image_attrs($image, $projectName . \' site photo \' . ($index + 1), [\'loading\' => $index === 0 ? \'eager\' : \'lazy\', \'fetchpriority\' => $index === 0 ? \'high\' : \'auto\']) ?>>\\n                <div class=\\\"pd-gallery-item-overlay\\\"><i class=\\\"fa-solid fa-magnifying-glass-plus\\\" aria-hidden=\\\"true\\\"></i></div>\\n              </button>\\n<?php endforeach; ?>\\n<?php if (count($images) > 1): ?>\\n              </div>\\n<?php endif; ?>\\n            </div>\\n<?php else: ?>\\n            <div class=\\\"pd-gallery-empty\\\">\\n              <i class=\\\"fa-solid fa-camera-slash\\\" aria-hidden=\\\"true\\\"></i>\\n              <p><?= $e($text($overview, \'gallery_empty_text\', \'Site photography will be added as construction progresses.\')) ?></p>\\n            </div>\\n<?php endif; ?>\\n          </section>\\n        </div>\\n\\n        <aside class=\\\"pd-sidebar\\\" id=\\\"pdSidebar\\\" aria-label=\\\"Project quick facts\\\">\\n          <div class=\\\"pd-sidebar-card pd-sb-contractor\\\">\\n            <div class=\\\"pd-sb-con-avatar\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid fa-helmet-safety\\\"></i></div>\\n            <div class=\\\"pd-sb-con-info\\\">\\n              <p class=\\\"pd-sidebar-card-title\\\"><?= $e($text($sidebar, \'contractor_title\', \'Contractor\')) ?></p>\\n              <p class=\\\"pd-contractor-name\\\"><?= $e($contractor !== \'\' ? $contractor : \'TBD\') ?></p>\\n              <span class=\\\"pd-contractor-role-badge\\\"><?= $e($text($sidebar, \'contractor_role_label\', \'Principal Contractor\')) ?></span>\\n            </div>\\n<?php if ($leadAgency !== \'\'): ?>\\n            <div class=\\\"pd-sb-agency\\\"><i class=\\\"fa-solid fa-building-government\\\" aria-hidden=\\\"true\\\"></i><span><?= $e($leadAgency) ?></span></div>\\n<?php endif; ?>\\n          </div>\\n\\n          <div class=\\\"pd-sidebar-card\\\">\\n            <p class=\\\"pd-sidebar-card-title\\\"><?= $e($text($sidebar, \'project_info_title\', \'Project Info\')) ?></p>\\n            <div class=\\\"pd-sidebar-list\\\">\\n<?php\\n    $infoRows = [\\n        [$text($sidebar, \'constituency_label\', \'Constituency\'), $constituencySlug !== \'\' ? \'<a href=\\\"constituency-detail.php?id=\' . $e(rawurlencode($constituencySlug)) . \'\\\" class=\\\"pd-sb-link\\\">\' . $e($constituencyName) . \'</a>\' : $e($constituencyName), true],\\n        [$text($labels, \'ward_label\', \'Ward\'), $e($wardName !== \'\' ? $wardName : \'-\') , true],\\n        [$text($sidebar, \'status_label\', \'Status\'), \'<span class=\\\"pd-sb-status pd-sb-status--\' . $e($statusClass) . \'\\\">\' . $e($statusLabel) . \'</span>\', true],\\n        [$text($sidebar, \'target_units_label\', \'Target Units\'), $e(pd_number($units)), true],\\n        [$text($labels, \'start_date_label\', \'Start Date\'), $e($startDate !== \'\' ? $startDate : \'-\'), true],\\n        [$text($labels, \'est_delivery_label\', \'Est. Delivery\'), $e($deliveryDate !== \'\' ? $deliveryDate : \'-\'), true],\\n        [$text($sidebar, \'completion_label\', \'Completion\'), \'<span class=\\\"pd-sb-pct\\\">\' . $e($pct) . \'%</span><div class=\\\"pd-sb-mini-bar\\\"><div class=\\\"pd-sb-mini-fill\\\" style=\\\"width:\' . $e($pct) . \'%\\\"></div></div>\', true],\\n    ];\\n?>\\n<?php foreach ($infoRows as $index => [$label, $value, $raw]): ?>\\n              <div class=\\\"pd-sidebar-row<?= $index % 2 === 1 ? \' is-alt\' : \'\' ?>\\\">\\n                <span class=\\\"pd-sidebar-row-lbl\\\"><?= $e($label) ?></span>\\n                <span class=\\\"pd-sidebar-row-val\\\"><?= $raw ? $value : $e($value) ?></span>\\n              </div>\\n<?php endforeach; ?>\\n            </div>\\n          </div>\\n\\n          <div class=\\\"pd-sidebar-card pd-apply-card\\\">\\n            <div class=\\\"pd-apply-icon-wrap\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid fa-house-chimney-user\\\"></i></div>\\n            <p class=\\\"pd-apply-title\\\"><?= $e($text($applyCta, \'title\', \'Interested in a Unit?\')) ?></p>\\n            <p class=\\\"pd-apply-sub\\\"><?= $e($text($applyCta, \'subtitle\', \'Register on the national Boma Yangu portal to apply for affordable housing in Trans-Nzoia County.\')) ?></p>\\n            <a href=\\\"<?= $e($text($applyCta, \'button_url\', \'https://app.bomayangu.go.ke\')) ?>\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" class=\\\"pd-apply-btn\\\">\\n              <i class=\\\"fa-solid fa-arrow-up-right-from-square\\\" aria-hidden=\\\"true\\\"></i> <?= $e($text($applyCta, \'button_label\', \'Apply on Boma Yangu\')) ?>\\n            </a>\\n          </div>\\n\\n          <div class=\\\"pd-sidebar-card\\\">\\n            <p class=\\\"pd-sidebar-card-title\\\"><?= $e($text($sidebar, \'related_title\', \'Related\')) ?></p>\\n            <div class=\\\"pd-related-links\\\">\\n<?php if ($constituencySlug !== \'\'): ?>\\n              <a href=\\\"constituency-detail.php?id=<?= $e(rawurlencode($constituencySlug)) ?>\\\" class=\\\"pd-related-link\\\">\\n                <div class=\\\"pd-related-icon\\\"><i class=\\\"fa-solid fa-map-location-dot\\\" aria-hidden=\\\"true\\\"></i></div>\\n                <span><?= $e($constituencyName . \' \' . $text($sidebar, \'constituency_link_suffix\', \'Constituency\')) ?></span>\\n                <i class=\\\"fa-solid fa-chevron-right pd-related-arrow\\\" aria-hidden=\\\"true\\\"></i>\\n              </a>\\n              <a href=\\\"projects.php?constituency=<?= $e(rawurlencode($constituencySlug)) ?>\\\" class=\\\"pd-related-link\\\">\\n                <div class=\\\"pd-related-icon\\\"><i class=\\\"fa-solid fa-building-columns\\\" aria-hidden=\\\"true\\\"></i></div>\\n                <span><?= $e($text($sidebar, \'all_projects_prefix\', \'All\') . \' \' . $constituencyName . \' Projects\') ?></span>\\n                <i class=\\\"fa-solid fa-chevron-right pd-related-arrow\\\" aria-hidden=\\\"true\\\"></i>\\n              </a>\\n<?php endif; ?>\\n              <a href=\\\"projects.php\\\" class=\\\"pd-related-link\\\">\\n                <div class=\\\"pd-related-icon\\\"><i class=\\\"fa-solid fa-arrow-left\\\" aria-hidden=\\\"true\\\"></i></div>\\n                <span><?= $e($text($sidebar, \'back_projects_label\', \'Back to All Projects\')) ?></span>\\n                <i class=\\\"fa-solid fa-chevron-right pd-related-arrow\\\" aria-hidden=\\\"true\\\"></i>\\n              </a>\\n            </div>\\n          </div>\\n<?php if ($relatedProjects): ?>\\n          <div class=\\\"pd-sidebar-card\\\">\\n            <p class=\\\"pd-sidebar-card-title\\\"><?= $e($text($sidebar, \'nearby_projects_title\', \'Nearby Projects\')) ?></p>\\n            <div class=\\\"pd-related-projects\\\">\\n<?php foreach ($relatedProjects as $related): ?>\\n              <a href=\\\"project-detail.php?id=<?= $e(rawurlencode((string)$related[\'slug\'])) ?>\\\" class=\\\"pd-related-project\\\">\\n                <span class=\\\"pd-related-project-name\\\"><?= $e($related[\'name\']) ?></span>\\n                <span class=\\\"pd-related-project-meta\\\"><?= $e($related[\'constituency_name\']) ?> / <?= $e(format_percentage($related[\'pct_complete\'])) ?></span>\\n              </a>\\n<?php endforeach; ?>\\n            </div>\\n          </div>\\n<?php endif; ?>\\n        </aside>\\n      </div>\\n    </div>\\n  </div>\\n<?php endif; ?>\\n</main>\\n<?php include __DIR__ . \'/app/partials/footer.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/back-to-top.php\'; ?>\\n<?php include __DIR__ . \'/app/partials/mobile-menu.php\'; ?>\\n<?= public_json_script(\'ahp-page-data\', $publicPayload) ?>\\n<?php include __DIR__ . \'/app/partials/scripts.php\'; ?>\\n</body>\\n</html>\\n\"}', '2026-06-24 18:05:14', '2026-06-24 18:05:14');
INSERT INTO `public_frontend_content_snapshots` (`id`, `page_slug`, `page_label`, `file_path`, `source_hash`, `raw_source`, `extracted_text`, `extracted_json`, `seeded_at`, `updated_at`) VALUES
(5, 'constituencies', 'Constituencies', 'constituencies.php', 'f4056c27dcf26fa9bdf27d280fa2acea6e22b34688f68e976d86c48d4fadd2ef', '<?php\nrequire_once __DIR__ . \'/app/core/bootstrap.php\';\n\n$basePath = \'\';\n$activePage = \'constituencies\';\n$cmsPage = CmsLoader::publicPage(\'constituencies\');\n\nif (!function_exists(\'constituencies_content\')) {\nfunction constituencies_content(array $page, string $key, array $defaults): array\n{\n    return CmsLoader::content($page, $key, $defaults);\n}\n}\n\nif (!function_exists(\'constituencies_number\')) {\nfunction constituencies_number(int|float $value): string\n{\n    return number_format((float)$value, 0);\n}\n}\n\nif (!function_exists(\'constituencies_short_number\')) {\nfunction constituencies_short_number(int|float $value): string\n{\n    $value = (float)$value;\n    if ($value >= 1000000) {\n        return rtrim(rtrim(number_format($value / 1000000, 1), \'0\'), \'.\') . \'M\';\n    }\n    if ($value >= 1000) {\n        return rtrim(rtrim(number_format($value / 1000, 1), \'0\'), \'.\') . \'K\';\n    }\n    return number_format($value, 0);\n}\n}\n\nif (!function_exists(\'constituencies_plural\')) {\nfunction constituencies_plural(int $count, string $singular, string $plural): string\n{\n    return $count === 1 ? $singular : $plural;\n}\n}\n\nif (!function_exists(\'constituencies_replace_stats\')) {\nfunction constituencies_replace_stats(string $text, array $stats): string\n{\n    return strtr($text, [\n        \'{constituencies}\' => (string)$stats[\'constituencies\'],\n        \'{projects}\' => (string)$stats[\'projects\'],\n        \'{units}\' => constituencies_number((int)$stats[\'units\']),\n        \'{residents}\' => constituencies_short_number((int)$stats[\'residents\']),\n    ]);\n}\n}\n\n$hero = constituencies_content($cmsPage, \'constituencies_hero\', [\n    \'background_image\' => \'uploads/gallery/maili-tatu-3.jpg\',\n    \'background_alt\' => \'Affordable housing construction site in Trans-Nzoia County\',\n    \'eyebrow\' => \'Coverage Map\',\n    \'title_prefix\' => \'All\',\n    \'title_highlight\' => \'5 Constituencies\',\n    \'subtitle\' => \'Explore how the Affordable Housing Programme reaches every corner of Trans-Nzoia County - from Endebess on the Uganda border to Kwanza in the south.\',\n    \'constituencies_label\' => \'Constituencies\',\n    \'projects_label\' => \'Projects\',\n    \'units_label\' => \'Units Planned\',\n    \'residents_label\' => \'Residents Served\',\n]);\n$mapCopy = constituencies_content($cmsPage, \'constituencies_map\', [\n    \'title\' => \'Trans-Nzoia County\',\n    \'subtitle\' => \'Click a constituency to explore its housing projects\',\n    \'active_label\' => \'Active construction\',\n    \'planning_label\' => \'Planning stage\',\n    \'selected_label\' => \'Selected\',\n    \'empty_text\' => \'Constituency data will appear after projects and wards are added to the registry.\',\n]);\n$progressCopy = constituencies_content($cmsPage, \'constituencies_progress\', [\n    \'title\' => \"County-Wide\\nProgramme\\nProgress\",\n    \'subtitle\' => \'Across all {constituencies} constituencies, the programme is delivering {units} affordable housing units - targeting Kenyans registered on the national Boma Yangu portal.\',\n    \'button_label\' => \'Browse All Projects\',\n    \'button_url\' => \'projects.php\',\n]);\n$gridCopy = constituencies_content($cmsPage, \'constituencies_grid\', [\n    \'eyebrow\' => \'Browse by Constituency\',\n    \'title_prefix\' => \'All\',\n    \'title_highlight\' => \'5 Constituencies\',\n    \'sort_label\' => \'Sort:\',\n    \'default_label\' => \'Default\',\n    \'progress_label\' => \'Highest Progress\',\n    \'units_label\' => \'Most Units\',\n    \'alpha_label\' => \'A - Z\',\n]);\n$ctaCopy = constituencies_content($cmsPage, \'constituencies_apply_cta\', [\n    \'title\' => \'Ready to Apply for Affordable Housing?\',\n    \'subtitle\' => \'Register on the national Boma Yangu portal to join the Trans-Nzoia County AHP allocation list.\',\n    \'primary_label\' => \'Apply on Boma Yangu\',\n    \'primary_url\' => \'https://bomayangu.go.ke\',\n    \'secondary_label\' => \'View All Projects\',\n    \'secondary_url\' => \'projects.php\',\n]);\n\n$constituencies = Constituency::publicList();\n$stats = Constituency::publicStats();\n$constituenciesBySlug = [];\nforeach ($constituencies as $item) {\n    $constituenciesBySlug[$item[\'id\']] = $item;\n}\n$clientLabels = [\n    \'active\' => \'Active\',\n    \'planning\' => \'Planning\',\n    \'residents\' => \'residents\',\n    \'projects\' => CmsLoader::text($hero, \'projects_label\', \'Projects\'),\n    \'units\' => \'Units\',\n    \'wards\' => \'Wards\',\n    \'completion\' => \'Avg. Completion\',\n    \'explore\' => \'Explore\',\n    \'previous\' => \'Prev\',\n    \'next\' => \'Next\',\n    \'showing\' => \'Showing\',\n    \'of\' => \'of\',\n];\n$pagePayload = public_page_payload(\'constituencies\', [\n    \'constituencies\' => $constituencies,\n    \'stats\' => $stats,\n    \'labels\' => $clientLabels,\n]);\n\n$pageTitle = $cmsPage[\'seo_title\'] ?? \'Constituencies | Trans-Nzoia County Affordable Housing Tracker\';\n$pageDescription = $cmsPage[\'seo_description\'] ?? \'Explore affordable housing coverage across all 5 constituencies in Trans-Nzoia County - Saboti, Cherangany, Endebess, Kiminini and Kwanza.\';\n$pageKeywords = $cmsPage[\'seo_keywords\'] ?? \'Trans-Nzoia constituencies, Saboti housing, Cherangany AHP, Endebess housing, Kiminini housing, Kwanza housing\';\n$pageAuthor = \'Trans-Nzoia County Government - Department of Land, Housing & Physical Planning\';\n$pageRobots = \'index, follow\';\n$themeColor = \'#163300\';\n$canonicalUrl = $cmsPage[\'canonical_url\'] ?? \'https://housing.transnzoia.go.ke/constituencies.php\';\n$heroImage = CmsLoader::text($hero, \'background_image\', (string)($cmsPage[\'hero_image\'] ?? \'uploads/gallery/maili-tatu-3.jpg\'));\n$pageStyles = [\'assets/css/global.css\', \'assets/css/pages/constituencies.css\'];\n$pageScripts = [\'assets/js/global.js\', \'assets/js/pages/constituencies.js\'];\n$headMeta = [\n    \'<meta property=\"og:title\" content=\"\' . Security::e($pageTitle) . \'\">\',\n    \'<meta property=\"og:description\" content=\"\' . Security::e($pageDescription) . \'\">\',\n    \'<meta property=\"og:type\" content=\"website\">\',\n    \'<meta property=\"og:url\" content=\"\' . Security::e($canonicalUrl) . \'\">\',\n    \'<meta property=\"og:image\" content=\"\' . Security::e($heroImage) . \'\">\',\n    \'<meta property=\"og:locale\" content=\"en_KE\">\',\n    \'<meta property=\"og:site_name\" content=\"Trans-Nzoia AHP Tracker\">\',\n    \'<meta name=\"twitter:card\" content=\"summary_large_image\">\',\n    \'<meta name=\"twitter:title\" content=\"\' . Security::e($pageTitle) . \'\">\',\n    \'<meta name=\"twitter:description\" content=\"\' . Security::e($pageDescription) . \'\">\',\n    \'<meta name=\"twitter:image\" content=\"\' . Security::e($heroImage) . \'\">\',\n];\ninclude __DIR__ . \'/app/partials/head.php\';\n?>\n<body>\n<?php include __DIR__ . \'/app/partials/cursor.php\'; ?>\n<?php include __DIR__ . \'/app/partials/skip-link.php\'; ?>\n<?php include __DIR__ . \'/app/partials/navbar.php\'; ?><main id=\"main-content\">\n\n    <section class=\"page-hero page-hero--constituencies\" aria-label=\"Constituencies overview\">\n      <div class=\"page-hero-bg\" aria-hidden=\"true\">\n        <img <?= public_image_attrs($heroImage, \'\', [\'loading\' => \'eager\', \'fetchpriority\' => \'high\', \'onerror\' => \"this.style.display=\'none\'\"]) ?>>\n        <div class=\"page-hero-overlay\"></div>\n      </div>\n      <div class=\"container\">\n        <nav class=\"breadcrumb\" aria-label=\"Breadcrumb\">\n          <a href=\"index.php\" class=\"breadcrumb-link\">Home</a>\n          <i class=\"fa-solid fa-chevron-right breadcrumb-sep\" aria-hidden=\"true\"></i>\n          <span class=\"breadcrumb-current\">Constituencies</span>\n        </nav>\n        <div class=\"page-hero-body\">\n          <div class=\"page-hero-eyebrow\">\n            <span class=\"page-hero-tag\"><i class=\"fa-solid fa-map-location-dot\" aria-hidden=\"true\"></i> <?= Security::e(CmsLoader::text($hero, \'eyebrow\', \'Coverage Map\')) ?></span>\n          </div>\n          <h1 class=\"page-hero-title\"><?= Security::e(CmsLoader::text($hero, \'title_prefix\', \'All\')) ?> <span class=\"text-lime\"><?= Security::e(CmsLoader::text($hero, \'title_highlight\', $stats[\'constituencies\'] . \' Constituencies\')) ?></span></h1>\n          <p class=\"page-hero-sub\"><?= Security::e(CmsLoader::text($hero, \'subtitle\', \'Explore how the Affordable Housing Programme reaches every corner of Trans-Nzoia County.\')) ?></p>\n        </div>\n        <div class=\"projects-hero-stats\" role=\"region\" aria-label=\"County-wide statistics\">\n          <div class=\"phs-item\"><span class=\"phs-val\"><?= Security::e((string)$stats[\'constituencies\']) ?></span><span class=\"phs-lbl\"><?= Security::e(CmsLoader::text($hero, \'constituencies_label\', \'Constituencies\')) ?></span></div>\n          <div class=\"phs-divider\" aria-hidden=\"true\"></div>\n          <div class=\"phs-item\"><span class=\"phs-val\"><?= Security::e((string)$stats[\'projects\']) ?></span><span class=\"phs-lbl\"><?= Security::e(CmsLoader::text($hero, \'projects_label\', \'Projects\')) ?></span></div>\n          <div class=\"phs-divider\" aria-hidden=\"true\"></div>\n          <div class=\"phs-item\"><span class=\"phs-val\"><?= Security::e(constituencies_number($stats[\'units\'])) ?></span><span class=\"phs-lbl\"><?= Security::e(CmsLoader::text($hero, \'units_label\', \'Units Planned\')) ?></span></div>\n          <div class=\"phs-divider\" aria-hidden=\"true\"></div>\n          <div class=\"phs-item\"><span class=\"phs-val\"><?= Security::e(constituencies_short_number($stats[\'residents\'])) ?></span><span class=\"phs-lbl\"><?= Security::e(CmsLoader::text($hero, \'residents_label\', \'Residents Served\')) ?></span></div>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"constituencies-split\" aria-label=\"Constituency map and listings\">\n      <div class=\"constituencies-split-inner\">\n        <div class=\"con-map-panel\" aria-label=\"Interactive constituency map\">\n          <div class=\"con-map-sticky\">\n            <div class=\"con-map-header\">\n              <h2 class=\"con-map-title\"><?= Security::e(CmsLoader::text($mapCopy, \'title\', \'Trans-Nzoia County\')) ?></h2>\n              <p class=\"con-map-hint\"><?= Security::e(CmsLoader::text($mapCopy, \'subtitle\', \'Click a constituency to explore its housing projects\')) ?></p>\n            </div>\n            <div class=\"con-map-wrap\">\n              <svg id=\"countyMap\" viewBox=\"0 0 480 400\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Trans-Nzoia County map showing constituencies\">\n                <defs>\n                  <filter id=\"shadow\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\">\n                    <feDropShadow dx=\"0\" dy=\"2\" stdDeviation=\"3\" flood-color=\"rgba(10,31,5,0.25)\"/>\n                  </filter>\n                </defs>\n<?php foreach (Constituency::mapShapes() as $slug => $shape): ?>\n<?php $item = $constituenciesBySlug[$slug] ?? [\'name\' => ucwords($slug), \'projectCount\' => 0, \'avgCompletion\' => 0]; ?>\n                <g class=\"con-path-group\" data-id=\"<?= Security::e($slug) ?>\" tabindex=\"0\" role=\"button\" aria-label=\"<?= Security::e($item[\'name\'] . \' - \' . $item[\'projectCount\'] . \' \' . constituencies_plural((int)$item[\'projectCount\'], \'project\', \'projects\') . \', \' . $item[\'avgCompletion\'] . \'% average completion\') ?>\">\n                  <path d=\"<?= Security::e($shape[\'path\']) ?>\" class=\"con-path\"/>\n                  <text class=\"con-path-label\" x=\"<?= (int)$shape[\'label_x\'] ?>\" y=\"<?= (int)$shape[\'label_y\'] ?>\"><?= Security::e($item[\'name\']) ?></text>\n                  <text class=\"con-path-sub\" x=\"<?= (int)$shape[\'label_x\'] ?>\" y=\"<?= (int)$shape[\'sub_y\'] ?>\"><?= Security::e($item[\'projectCount\'] . \' \' . constituencies_plural((int)$item[\'projectCount\'], \'project\', \'projects\')) ?></text>\n                </g>\n<?php endforeach; ?>\n              </svg>\n            </div>\n            <div class=\"con-map-legend\" aria-label=\"Map legend\">\n              <div class=\"con-legend-item\"><span class=\"con-legend-dot con-legend-dot--active\"></span><span><?= Security::e(CmsLoader::text($mapCopy, \'active_label\', \'Active construction\')) ?></span></div>\n              <div class=\"con-legend-item\"><span class=\"con-legend-dot con-legend-dot--planning\"></span><span><?= Security::e(CmsLoader::text($mapCopy, \'planning_label\', \'Planning stage\')) ?></span></div>\n              <div class=\"con-legend-item\"><span class=\"con-legend-dot con-legend-dot--selected\"></span><span><?= Security::e(CmsLoader::text($mapCopy, \'selected_label\', \'Selected\')) ?></span></div>\n            </div>\n          </div>\n        </div>\n        <div class=\"con-cards-panel\" id=\"conCardsPanel\" aria-label=\"Constituency listings\">\n<?php if ($constituencies): ?>\n<?php foreach ($constituencies as $item): ?>\n          <article class=\"con-card\" data-id=\"<?= Security::e($item[\'id\']) ?>\" tabindex=\"0\" aria-label=\"Explore <?= Security::e($item[\'name\']) ?>\">\n            <div class=\"con-card-header\">\n              <div class=\"con-card-name-wrap\">\n                <h3 class=\"con-card-name\"><?= Security::e($item[\'name\']) ?></h3>\n                <span class=\"con-card-pop\"><?= Security::e($item[\'population\']) ?> residents</span>\n              </div>\n              <span class=\"con-card-status con-card-status--<?= Security::e($item[\'status\']) ?>\"><?= Security::e($item[\'status\'] === \'active\' ? \'Active\' : \'Planning\') ?></span>\n            </div>\n            <div class=\"con-card-stats\">\n              <div class=\"con-card-stat\"><span class=\"con-card-stat-val\"><?= Security::e((string)$item[\'projectCount\']) ?></span><span class=\"con-card-stat-lbl\">Projects</span></div>\n              <div class=\"con-card-stat\"><span class=\"con-card-stat-val\"><?= Security::e(format_number((int)$item[\'totalUnits\'])) ?></span><span class=\"con-card-stat-lbl\">Units</span></div>\n              <div class=\"con-card-stat\"><span class=\"con-card-stat-val\"><?= Security::e((string)count($item[\'wards\'])) ?></span><span class=\"con-card-stat-lbl\">Wards</span></div>\n            </div>\n            <div class=\"con-card-progress-wrap\">\n              <div class=\"con-card-progress-meta\">\n                <span class=\"con-card-progress-label\">Avg. Completion</span>\n                <span class=\"con-card-progress-pct\"><?= Security::e((string)$item[\'avgCompletion\']) ?>%</span>\n              </div>\n              <div class=\"con-card-progress-bar\" role=\"progressbar\" aria-valuenow=\"<?= (int)$item[\'avgCompletion\'] ?>\" aria-valuemin=\"0\" aria-valuemax=\"100\">\n                <div class=\"con-card-progress-fill\" data-target=\"<?= (int)$item[\'avgCompletion\'] ?>\" style=\"width:<?= (int)$item[\'avgCompletion\'] ?>%\"></div>\n              </div>\n            </div>\n            <div class=\"con-card-footer\">\n              <span class=\"con-card-wards\"><?= Security::e(implode(\', \', $item[\'wards\'])) ?></span>\n              <a href=\"<?= Security::e($item[\'link\']) ?>\" class=\"con-card-cta\" aria-label=\"Explore <?= Security::e($item[\'name\']) ?>\">\n                Explore <i class=\"fa-solid fa-arrow-right\" aria-hidden=\"true\"></i>\n              </a>\n            </div>\n          </article>\n<?php endforeach; ?>\n<?php else: ?>\n          <p class=\"con-map-hint\"><?= Security::e(CmsLoader::text($mapCopy, \'empty_text\', \'Constituency data will appear after projects and wards are added to the registry.\')) ?></p>\n<?php endif; ?>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"county-total-section\" aria-label=\"County-wide programme totals\">\n      <div class=\"container\">\n        <div class=\"county-total-inner\">\n          <div class=\"county-total-left\">\n            <h2 class=\"county-total-title\"><?= nl2br(Security::e(CmsLoader::text($progressCopy, \'title\', \"County-Wide\\nProgramme\\nProgress\"))) ?></h2>\n            <p class=\"county-total-sub\"><?= Security::e(constituencies_replace_stats(CmsLoader::text($progressCopy, \'subtitle\', \'Across all {constituencies} constituencies, the programme is delivering {units} affordable housing units.\'), $stats)) ?></p>\n            <a href=\"<?= Security::e(CmsLoader::text($progressCopy, \'button_url\', \'projects.php\')) ?>\" class=\"btn btn-primary\">\n              <i class=\"fa-solid fa-building-columns\" aria-hidden=\"true\"></i> <?= Security::e(CmsLoader::text($progressCopy, \'button_label\', \'Browse All Projects\')) ?>\n            </a>\n          </div>\n          <div class=\"county-total-right\" id=\"countyTotalsChart\" aria-label=\"Constituency progress comparison\">\n            <div class=\"county-bar-row\">\n<?php foreach ($constituencies as $item): ?>\n              <div class=\"county-bar-item\">\n                <span class=\"county-bar-name\"><?= Security::e($item[\'name\']) ?></span>\n                <div class=\"county-bar-track\">\n                  <div class=\"county-bar-fill\" data-target=\"<?= (int)$item[\'avgCompletion\'] ?>\" style=\"width:<?= (int)$item[\'avgCompletion\'] ?>%\"></div>\n                </div>\n                <span class=\"county-bar-pct\"><?= Security::e((string)$item[\'avgCompletion\']) ?>%</span>\n              </div>\n<?php endforeach; ?>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"con-grid-section\" aria-label=\"All constituencies overview\">\n      <div class=\"container\">\n        <div class=\"con-grid-header\">\n          <div class=\"con-grid-header-left\">\n            <p class=\"con-grid-eyebrow\"><?= Security::e(CmsLoader::text($gridCopy, \'eyebrow\', \'Browse by Constituency\')) ?></p>\n            <h2 class=\"con-grid-title\"><?= Security::e(CmsLoader::text($gridCopy, \'title_prefix\', \'All\')) ?> <span class=\"text-lime\"><?= Security::e(CmsLoader::text($gridCopy, \'title_highlight\', $stats[\'constituencies\'] . \' Constituencies\')) ?></span></h2>\n          </div>\n          <div class=\"con-grid-sort\" id=\"conGridSort\">\n            <span class=\"con-sort-label\"><?= Security::e(CmsLoader::text($gridCopy, \'sort_label\', \'Sort:\')) ?></span>\n            <button class=\"con-sort-btn is-active\" data-sort=\"default\"><?= Security::e(CmsLoader::text($gridCopy, \'default_label\', \'Default\')) ?></button>\n            <button class=\"con-sort-btn\" data-sort=\"progress\"><?= Security::e(CmsLoader::text($gridCopy, \'progress_label\', \'Highest Progress\')) ?></button>\n            <button class=\"con-sort-btn\" data-sort=\"units\"><?= Security::e(CmsLoader::text($gridCopy, \'units_label\', \'Most Units\')) ?></button>\n            <button class=\"con-sort-btn\" data-sort=\"alpha\"><?= Security::e(CmsLoader::text($gridCopy, \'alpha_label\', \'A - Z\')) ?></button>\n          </div>\n        </div>\n        <div class=\"con-grid\" id=\"conBrowseGrid\">\n<?php foreach ($constituencies as $item): ?>\n          <article class=\"con-browse-card\">\n            <div class=\"con-browse-card-top\">\n              <div>\n                <h3 class=\"con-browse-card-name\"><?= Security::e($item[\'name\']) ?></h3>\n                <div class=\"con-browse-card-pop\"><?= Security::e($item[\'population\']) ?> residents</div>\n              </div>\n              <span class=\"con-browse-status con-browse-status--<?= Security::e($item[\'status\']) ?>\"><?= Security::e($item[\'status\'] === \'active\' ? \'Active\' : \'Planning\') ?></span>\n            </div>\n            <div class=\"con-browse-stats\">\n              <div class=\"con-browse-stat\"><span class=\"con-browse-stat-val\"><?= Security::e((string)$item[\'projectCount\']) ?></span><span class=\"con-browse-stat-lbl\">Projects</span></div>\n              <div class=\"con-browse-stat\"><span class=\"con-browse-stat-val\"><?= Security::e(format_number((int)$item[\'totalUnits\'])) ?></span><span class=\"con-browse-stat-lbl\">Units</span></div>\n              <div class=\"con-browse-stat\"><span class=\"con-browse-stat-val\"><?= Security::e((string)count($item[\'wards\'])) ?></span><span class=\"con-browse-stat-lbl\">Wards</span></div>\n            </div>\n            <div class=\"con-browse-progress\">\n              <div class=\"con-browse-progress-meta\"><span>Avg. Completion</span><span><?= Security::e((string)$item[\'avgCompletion\']) ?>%</span></div>\n              <div class=\"con-browse-bar-track\"><div class=\"con-browse-bar-fill\" data-target=\"<?= (int)$item[\'avgCompletion\'] ?>\" style=\"width:<?= (int)$item[\'avgCompletion\'] ?>%\"></div></div>\n            </div>\n            <div class=\"con-browse-wards\"><?= Security::e(implode(\' / \', $item[\'wards\'])) ?></div>\n            <a href=\"<?= Security::e($item[\'link\']) ?>\" class=\"con-browse-cta\">\n              Explore <?= Security::e($item[\'name\']) ?> <i class=\"fa-solid fa-arrow-right\" aria-hidden=\"true\"></i>\n            </a>\n          </article>\n<?php endforeach; ?>\n        </div>\n      </div>\n    </section>\n\n  </main>\n\n  <div class=\"con-apply-banner\" role=\"complementary\" aria-label=\"Apply for housing\">\n    <div class=\"container\">\n      <div class=\"con-apply-inner\">\n        <div class=\"con-apply-icon\"><i class=\"fa-solid fa-house-circle-check\" aria-hidden=\"true\"></i></div>\n        <div class=\"con-apply-copy\">\n          <h3 class=\"con-apply-title\"><?= Security::e(CmsLoader::text($ctaCopy, \'title\', \'Ready to Apply for Affordable Housi