(1, 1, '2022-06-01', 'June 2022', 'Presidential Directive - AHP Launch', 'H.E. the President directs immediate rollout of affordable housing nationwide, including Trans-Nzoia allocation.', 'fa-flag', 'National Govt', 'published', 10, '2026-05-30 10:09:22', '2026-05-30 10:09:22'),
(2, 4, '2023-01-01', 'Jan 2023', 'Housing Levy Activation', 'Housing levy takes effect, enabling collection through national payroll channels and beneficiary registration.', 'fa-coins', 'Financial', 'published', 20, '2026-05-30 10:09:22', '2026-05-30 10:09:22'),
(3, 2, '2023-03-01', 'Mar 2023', 'Trans-Nzoia Land Allocation MoU', 'County signs memorandum for allocation of strategic sites across the five constituencies.', 'fa-map-location-dot', 'County Govt', 'published', 30, '2026-05-30 10:09:22', '2026-05-30 10:09:22'),
(4, 5, '2023-07-01', 'Jul 2023', 'NEMA EIAs Completed', 'Environmental assessments completed for priority sites and mitigation requirements issued.', 'fa-leaf', 'Oversight', 'published', 40, '2026-05-30 10:09:22', '2026-05-30 10:09:22'),
(5, 6, '2023-09-01', 'Sep 2023', 'Ward Baraza Series - 5 Constituencies', 'Public participation barazas held in every constituency to gather residents feedback and design concerns.', 'fa-people-group', 'Community', 'published', 50, '2026-05-30 10:09:22', '2026-05-30 10:09:22'),
(6, 3, '2023-12-01', 'Dec 2023', 'First 4 Contracts Awarded', 'Procurement concludes for first wave of implementing contractors.', 'fa-helmet-safety', 'Contractors', 'published', 60, '2026-05-30 10:09:22', '2026-05-30 10:09:22'),
(7, 1, '2024-02-01', 'Feb 2024', 'Trans-Nzoia Groundbreaking Ceremony', 'Programme formally enters site mobilisation and construction preparation.', 'fa-shovel', 'National Govt', 'published', 70, '2026-05-30 10:09:22', '2026-05-30 10:09:22'),
(8, 5, '2024-06-01', 'Jun 2024', 'NCA Q1 Site Audit - All Sites Pass', 'Quality and safety inspections confirm active sites meet minimum compliance requirements.', 'fa-clipboard-check', 'Oversight', 'published', 80, '2026-05-30 10:09:22', '2026-05-30 10:09:22'),
(9, 6, '2025-01-01', 'Jan 2025', 'Beneficiary Balloting - Phase 1', 'First beneficiary allocation communication begins for qualifying registered applicants.', 'fa-ticket', 'Community', 'published', 90, '2026-05-30 10:09:22', '2026-05-30 10:09:22'),
(10, 3, NULL, 'Present', '8 Sites Active - 1,730 Units Underway', 'Active construction and procurement continue across the county pipeline.', 'fa-person-digging', 'Contractors', 'published', 100, '2026-05-30 10:09:22', '2026-05-30 10:09:22');

