INSERT INTO `stakeholder_testimonials` (`id`, `group_id`, `name`, `role`, `initials`, `photo_path`, `rating`, `quote`, `tags_json`, `status`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 6, 'Margaret Wanjiku', 'Registered Beneficiary - Kitale Township Ward', 'MW', NULL, 5, 'I have been a Boma Yangu applicant since 2023. When I attended the baraza in our ward, I could ask questions directly to the Field Director. They told us exactly when to expect our units. That kind of transparency gives me confidence.', '[\"Beneficiary\",\"Ward Baraza\"]', 'published', 10, '2026-05-30 10:09:22', '2026-05-30 10:09:22'),
(2, 6, 'James Omwange', 'Ward Rep - Saboti Constituency Development Committee', 'JO', NULL, 5, 'As a ward representative I attended all five site-selection meetings. The community was genuinely heard and the Matunda site was repositioned based on drainage concerns. That is real stakeholder engagement.', '[\"Ward Rep\",\"Site Selection\"]', 'published', 20, '2026-05-30 10:09:22', '2026-05-30 10:09:22'),
(3, 6, 'Fatuma Koech', 'Trans-Nzoia Women Housing Network - Chairperson', 'FK', NULL, 4, 'Our network lobbied for unit allocation to single mothers and women-headed households. The AHP listened and committed to this in the balloting criteria. We are seeing it being honoured.', '[\"Women\'s Group\",\"Advocacy\"]', 'published', 30, '2026-05-30 10:09:22', '2026-05-30 10:09:22'),
(4, 6, 'David Mutai', 'Youth Cohort Rep - Cherangany & Tuwani Ward', 'DM', NULL, 5, 'As a 28-year-old teacher, I could never afford to own a home under normal circumstances. The Boma Yangu process was straightforward. I applied, attended the baraza, and I am ballot number 114. Progress is real.', '[\"Beneficiary\",\"Youth Cohort\"]', 'published', 40, '2026-05-30 10:09:22', '2026-05-30 10:09:22');

